def _get_setting(key: str, default: str = "") -> str:
    """Get a config value from app_settings with 5-minute cache. Falls back to default."""
    import time as _st
    now = _st.time()
    cached = _SETTING_CACHE.get(key)
    if cached and cached["ts"] > now - 300:
        return cached["val"]
    try:
        with get_db() as conn, conn.cursor() as cur:
            cur.execute("SELECT value FROM app_settings WHERE key = %s AND category = 'config'", (key,))
            row = cur.fetchone()
            if row and row[0]:
                _SETTING_CACHE[key] = {"val": row[0], "ts": now}
                return row[0]
    except Exception:
        pass
    _SETTING_CACHE[key] = {"val": default, "ts": now}
    return default


_DDG_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
           "(KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36")


def _ddg_parse_html(text: str, max_results: int) -> list:
    """Parse the html.duckduckgo.com/html/ result page -> [{title,url,snippet}]."""
    out, seen = [], set()
    # Each result: <a class="result__a" href="URL">TITLE</a> ... <a class="result__snippet">SNIPPET</a>
    anchors = _re_module.findall(
        r'result__a[^>]*href="([^"]+)"[^>]*>(.*?)</a>', text, _re_module.DOTALL)
    snippets = [_re_module.sub(r'<[^>]+>', '', s).strip()
                for s in _re_module.findall(r'result__snippet[^>]*>(.*?)</a>', text, _re_module.DOTALL)]
    for i, (href, title_html) in enumerate(anchors[:max_results]):
        # DDG wraps external URLs as //duckduckgo.com/l/?uddg=ENCODED
        url = href
        if "uddg=" in href:
            u = href if "://" in href else "https:" + href
            url = _unquote(_parse_qs(_urlparse_fn(u).query).get("uddg", [href])[0])
        if url in seen:
            continue
        seen.add(url)
        title = _re_module.sub(r'<[^>]+>', '', title_html).strip()
        snippet = (snippets[i][:300] if i < len(snippets) else "")
        out.append({"title": title, "url": url, "snippet": snippet})
    return out


def ddg_search(query: str, max_results: int = 15, timeout: float = 10.0, proxy: str = None) -> list:
    """Search DuckDuckGo. Returns list of {title, url, snippet}.

    Uses the html.duckduckgo.com/html/ POST endpoint (returns 200 with parseable
    result__a/result__snippet blocks). The old lite endpoint now answers 202 with
    an anti-bot interstitial and no parseable links, so it silently returned
    nothing — every web-search consumer (CVE research, default-cred lookup) got an
    empty list. The lite GET is kept as a fallback."""
    # Proxy is a configurable OPSEC option: an explicit arg wins, else the
    # operator setting `web_research.proxy` (Settings), else the DDG_PROXY env,
    # else direct. Empty = search egresses from this host's own IP, which reveals
    # what products/targets are being researched — set a SOCKS proxy to avoid that.
    proxy_url = proxy or _get_setting("web_research.proxy", DDG_PROXY)
    proxies = {"https": proxy_url, "http": proxy_url} if proxy_url else None
    headers = {"User-Agent": _DDG_UA}
    # Primary: HTML POST endpoint.
    try:
        resp = requests.post("https://html.duckduckgo.com/html/",
                             data={"q": query}, headers=headers,
                             timeout=timeout, verify=False, proxies=proxies)
        if resp.status_code == 200:
            parsed = _ddg_parse_html(resp.text, max_results)
            if parsed:
                return parsed
    except Exception:  # noqa: BLE001
        pass
    # Fallback: lite endpoint (older format), accept 200/202.
    try:
        resp = requests.get("https://lite.duckduckgo.com/lite/",
            params={"q": query}, headers=headers,
            timeout=timeout, verify=False, proxies=proxies)
        if resp.status_code not in (200, 202):
            return []
        raw_links = _re_module.findall(r'href="(//duckduckgo\.com/l/\?uddg=[^"]+)"', resp.text)
        title_matches = _re_module.findall(
            r'<a[^>]*rel="nofollow"[^>]*>(.*?)</a>', resp.text, _re_module.DOTALL)
        snippet_matches = _re_module.findall(
            r'class="result-snippet"[^>]*>(.*?)</td>', resp.text, _re_module.DOTALL)
        results, seen = [], set()
        for i, raw_url in enumerate(raw_links[:max_results]):
            url = "https:" + raw_url
            actual_url = _unquote(_parse_qs(_urlparse_fn(url).query).get("uddg", [url])[0])
            if actual_url in seen:
                continue
            seen.add(actual_url)
            title = _re_module.sub(r'<[^>]+>', '', title_matches[i]).strip() if i < len(title_matches) else ""
            snippet = _re_module.sub(r'<[^>]+>', '', snippet_matches[i]).strip()[:300] if i < len(snippet_matches) else ""
            results.append({"title": title, "url": actual_url, "snippet": snippet})
        return results
    except Exception:  # noqa: BLE001
        return []


# ── LLM call helper with automatic metrics logging ──
OLLAMA_BASE = os.environ.get("OLLAMA_BASE_URL", "http://host.docker.internal:11434")
LLM_MODEL = os.environ.get("LLM_MODEL", "gemma4:31b")
if "llm_query" not in OLLAMA_BASE:
    # The router (llm_query:8002) is where task routing + fallback live. A base
    # that points elsewhere (the legacy host.docker.internal default, or a stray
    # OLLAMA_URL) silently bypasses all of it and dials a host that may not even
    # exist. Log it loudly at startup rather than failing mysteriously later
    # (Docs/OPEN_ITEMS.md "OLLAMA_BASE falls back to a host that does not exist").
    logging.warning(
        "OLLAMA_BASE=%s does not point at the llm_query router (:8002) — task "
        "routing and fallback are BYPASSED for direct Ollama calls.", OLLAMA_BASE)


def llm_generate(prompt: str, caller: str, model: str = None, think: bool = False,
                 temperature: float = 0.1, num_predict: int = 1024, timeout: int = 120,
                 task: str = "analyze") -> dict:
    """Call the LLM (via llm_query) and log metrics to llm_request_metrics.

    Routes by `task` (default "analyze") so llm_query picks the model the
    operator configured for that task on the ACTIVE backend. An explicit `model`
    still wins; without one we send NO model, because a forced default
    (LLM_MODEL=gemma4:31b, an ollama tag) is a deployment name the Azure backend
    404s on. `model` in the returned dict / metrics is whatever actually answered.

    Returns dict with: response, eval_count, tokens_per_sec, latency_ms, ok, error
    """
    import time as _t
    result = {"response": "", "eval_count": 0, "tokens_per_sec": 0, "latency_ms": 0, "ok": False, "error": None}

    t0 = _t.time()
    payload = {"prompt": prompt, "stream": False, "think": think, "task": task,
               "options": {"temperature": temperature, "num_predict": num_predict}}
    if model:
        payload["model"] = model
    try:
        resp = requests.post(
            f"{OLLAMA_BASE}/api/generate", json=payload,
            timeout=timeout, verify=False,
        )
        latency_ms = round((_t.time() - t0) * 1000, 1)
        result["latency_ms"] = latency_ms

        if resp.status_code == 200:
            data = resp.json()
            # The model that actually answered (the task route may have chosen
            # it); fall back to the caller's model or the task name for logging.
            model = data.get("model") or model or task
            result["response"] = data.get("response", "")
            result["eval_count"] = data.get("eval_count", 0)
            eval_dur = data.get("eval_duration", 0)
            result["tokens_per_sec"] = round(result["eval_count"] / (eval_dur / 1e9), 1) if eval_dur else 0
            result["prompt_tokens"] = data.get("prompt_eval_count", 0)
            result["ok"] = True
            result["model"] = model
            logger.info("[llm:%s] %s: %d tokens, %.1f tok/s, %dms",
                        caller, model, result["eval_count"], result["tokens_per_sec"], latency_ms)
        else:
            result["error"] = f"HTTP {resp.status_code}"
            logger.warning("[llm:%s] HTTP %s from Ollama", caller, resp.status_code)
    except Exception as e:
        latency_ms = round((_t.time() - t0) * 1000, 1)
        result["latency_ms"] = latency_ms
        result["error"] = f"{type(e).__name__}: {e}"
        logger.warning("[llm:%s] error: %s", caller, result["error"])

    # Log to database (fire-and-forget)
    try:
        with get_db(autocommit=True) as conn, conn.cursor() as cur:
            cur.execute("""INSERT INTO llm_request_metrics
                (caller, model_name, prompt_tokens, completion_tokens, total_tokens, tokens_per_sec,
                 latency_ms, is_error, error_message, request_params)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s)""",
                (caller, model or task, result.get("prompt_tokens", 0), result["eval_count"],
                 result.get("prompt_tokens", 0) + result["eval_count"], result["tokens_per_sec"],
                 result["latency_ms"], not result["ok"], result.get("error"),
                 Json({"temperature": temperature, "num_predict": num_predict, "prompt_len": len(prompt),
                       "prompt": prompt[:8000], "response": result["response"][:8000]})))
    except Exception:
        pass

    return result


def _embed_texts(texts: list[str]) -> list[list[float]]:
    """Call the embedder microservice to get vectors."""
    resp = requests.post(f"{EMBEDDER_URL}/embed", json={"texts": texts}, verify=False, timeout=30)
    resp.raise_for_status()
    return resp.json()["embeddings"]


def _embed_text(text: str) -> list[float]:
    """Convenience wrapper for a single text."""
    return _embed_texts([text])[0]

