# Keep legacy /health endpoint for backward compatibility
@app.get("/health")
def health():
    """
    Legacy health check endpoint with enhanced details.

    Returns:
    - ok: Boolean indicating if service is operational
    - service: Service name
    - database: Database connection status and table count
    - dependencies: Status of critical dependencies (Ollama, scan-recommender)
    - timestamp: ISO 8601 timestamp

    Maintains backward compatibility - always returns {"ok": true/false} at minimum.
    """
    import requests
    from datetime import datetime, timezone

    response = {
        "ok": True,
        "service": "rag-api",
        "version": os.environ.get("BUILD_VERSION", "dev"),
        "timestamp": datetime.now(timezone.utc).isoformat()
    }

    # Check database
    try:
        with get_db() as conn, conn.cursor() as cursor:
            cursor.execute("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = 'public' AND table_type = 'BASE TABLE'")
            table_count = cursor.fetchone()[0]

        response["database"] = {
            "connected": True,
            "tables_found": table_count,
            "tables_expected": 34
        }
    except Exception as e:
        response["ok"] = False
        response["database"] = {
            "connected": False,
            "error": str(e)
        }

    # Check critical dependencies
    dependencies = {}

    # Check the LLM backend, THROUGH THE ROUTER.
    #
    # This probed a hard-coded http://ollama:11434 — a host that does not exist
    # in this stack and never has (the same nonexistent daemon that meant news
    # enrichment had never once run). Two consequences, both measured:
    #
    #   * 4.00s of this endpoint's 4.2s was this one probe. `timeout=3` does not
    #     bound it, because requests retries the connection; the caller sees ~4s.
    #     That is why the dashboard's aggregate /api/health took 8.6s and
    #     reported `rag_api: ConnectTimeout (timeout=8s)` under load.
    #   * it set response["ok"] = False, so rag-api reported UNHEALTHY
    #     permanently — `docker ps` showed "Up 15 hours (unhealthy)" — because an
    #     optional dependency that is not part of this deployment was missing.
    #     A health check that is always red says nothing when something is
    #     actually wrong.
    #
    # OLLAMA_BASE is the same variable the rag-api agents already dial, and it
    # points at llm_query, which serves an ollama-compatible /api/tags. Measured
    # from inside this container: 0.00s vs 4.00s.
    #
    # An unreachable LLM backend is reported, but does NOT flip `ok`: this
    # endpoint's `ok` is about whether rag-api itself can serve, and the backend
    # has its own entry for anyone who needs it.
    try:
        llm_resp = requests.get(f"{OLLAMA_BASE}/api/tags", verify=False, timeout=3)
        if llm_resp.status_code == 200:
            models = llm_resp.json().get("models", [])
            dependencies["ollama"] = {
                "healthy": True,
                "models": len(models),
                "endpoint": OLLAMA_BASE,
            }
        else:
            dependencies["ollama"] = {"healthy": False, "endpoint": OLLAMA_BASE,
                                      "code": llm_resp.status_code}
    except Exception as e:  # noqa: BLE001
        dependencies["ollama"] = {"healthy": False, "endpoint": OLLAMA_BASE,
                                  "error": type(e).__name__}

    # Check scan-recommender
    try:
        scan_rec_resp = requests.get("https://scan-recommender:8013/health", verify=False, timeout=3)
        dependencies["scan_recommender"] = {
            "healthy": scan_rec_resp.status_code == 200
        }
    except Exception:
        dependencies["scan_recommender"] = {"healthy": False}

    response["dependencies"] = dependencies

    # Check ExploitDB / searchsploit data
    try:
        from rule_engine import _load_exploitdb, _EXPLOITDB_INDEX
        _load_exploitdb()
        response["exploitdb"] = {
            "loaded": len(_EXPLOITDB_INDEX) > 0,
            "count": len(_EXPLOITDB_INDEX),
        }
    except Exception:
        response["exploitdb"] = {"loaded": False, "count": 0}

    return response

api_router = APIRouter()

@app.get("/scans/{job_id}", tags=["Scans"])
async def get_scan_results(job_id: str, x_api_key: str = Header(...), db_dsn=DB_DSN):
    if x_api_key != API_KEY:
        raise HTTPException(status_code=401, detail="Invalid X-API-Key")

    # The scan runs recorded under this job. This used to query `scan_results`,
    # a table that has never existed in db_init — so every call 500'd with
    # `relation "scan_results" does not exist`. The real per-job record is
    # `scan_runs` (one row per tool run, keyed by job_id), with its findings in
    # `scan_run_findings` (run_id -> finding). Returned shape is unchanged
    # ({job_id, results}) so any consumer of the documented contract still works.
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cursor:
            cursor.execute(
                """SELECT id, tool, target, job_id, profile, started_at,
                          finished_at, finding_count, metadata
                     FROM scan_runs
                    WHERE job_id = %s
                    ORDER BY started_at DESC""",
                (job_id,),
            )
            results = cursor.fetchall()
        return {"job_id": job_id, "results": results}
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

app.include_router(api_router)

