@app.get("/ports/open")
def get_open_ports(
    ip: Optional[str] = Query(None, description="Optional IP filter, e.g., 192.168.1.5"),
    service: Optional[str] = Query(None, description="Optional service filter (e.g. ssh, http)"),
    search: Optional[str] = Query(None, description="Substring match on service / product / banner (case-insensitive)"),
    limit: int = Query(200, ge=1, le=5000),
    offset: int = Query(0, ge=0, description="Pagination offset for retrieving > limit rows"),
    authorized: bool = Depends(auth),
):
    # Return normalized open ports, optionally filtered by IP
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        where = ["COALESCE(p.is_open, true)"]
        params: list = []
        # Scope to the active engagement (via the joined asset — ports has no
        # engagement_id) so the global port list isn't cross-engagement.
        _eid = _validate_engagement_uuid(_resolve_engagement_id())
        if _eid:
            where.append("a.engagement_id = %s::uuid")
            params.append(_eid)
        if ip:
            # Accept an IP, hostname, or URL — a scan target is often a hostname
            # ('demo.testfire.net') while ports are keyed by the resolved IP, so
            # match either the address or the asset hostname (scheme/port stripped).
            _h = _target_host(ip)
            where.append("(host(a.ip)=%s OR lower(a.hostname)=%s)")
            params.extend([_h, _h])
        if service:
            where.append("p.service ILIKE %s")
            params.append(service)
        if search:
            where.append("(p.service ILIKE %s OR p.product ILIKE %s OR p.banner ILIKE %s)")
            params.extend([f"%{search}%", f"%{search}%", f"%{search}%"])
        where_sql = "WHERE " + " AND ".join(where)
        # Count total matching rows (independent of LIMIT/OFFSET) for pagination.
        cur.execute(
            f"SELECT count(DISTINCT (p.id)) AS n FROM ports p JOIN assets a ON p.asset_id = a.id {where_sql}",
            params,
        )
        total = cur.fetchone()["n"]
        sql = f"""
            SELECT host(a.ip)::text AS ip,
                   p.proto, p.port,
                   COALESCE(p.service,'?') AS service,
                   p.product, p.version, p.banner,
                   a.os,
                   COALESCE(COUNT(DISTINCT v.id), 0)::int AS finding_count,
                   -- how many distinct tools have run against this exact port,
                   -- and whether there is enumeration data (a held shell, an
                   -- executed exploit, or a finding) worth opening for it.
                   (SELECT COUNT(DISTINCT te.tool) FROM tool_executions te
                     WHERE te.target = host(a.ip) AND te.port = p.port)::int AS tools_run,
                   (SELECT COUNT(DISTINCT pe2.exploit_id) FROM pending_exploits pe2
                     WHERE host(pe2.target_ip) = host(a.ip)
                       AND pe2.target_port = p.port)::int AS exploits_attempted,
                   (COUNT(DISTINCT v.id) > 0
                    OR EXISTS (SELECT 1 FROM obtained_access oa
                                WHERE oa.target = host(a.ip) AND oa.port = p.port
                                  AND oa.status <> 'rejected')
                    OR EXISTS (SELECT 1 FROM pending_exploits pe
                                 JOIN exploit_results er ON er.pending_exploit_id = pe.id
                                WHERE host(pe.target_ip) = host(a.ip)
                                  AND pe.target_port = p.port)) AS has_enum,
                   -- proven COMMAND EXECUTION on this port: an exploit-success
                   -- finding (record_exploit_success_finding writes script
                   -- 'exploit:<kind>') OR a held shell/session on the port.
                   (EXISTS (SELECT 1 FROM vulns vex
                             WHERE vex.port_id = p.id AND vex.script LIKE 'exploit:%%')
                    OR EXISTS (SELECT 1 FROM obtained_access oa2
                                WHERE oa2.target = host(a.ip) AND oa2.port = p.port
                                  AND oa2.kind IN ('bind_shell','msf_session',
                                                   'webshell','listener_callback')
                                  AND oa2.status <> 'rejected')) AS has_command_exec,
                   -- public.severity_rank() — one scale for the whole stack
                   -- (etl/severity.py). This was a hand-written descending CASE.
                   CASE MAX(
                       CASE v.severity
                           WHEN 'critical' THEN 5
                           WHEN 'high' THEN 4
                           WHEN 'medium' THEN 3
                           WHEN 'low' THEN 2
                           WHEN 'info' THEN 1
                           ELSE 0
                       END
                   )
                       WHEN 5 THEN 'critical'
                       WHEN 4 THEN 'high'
                       WHEN 3 THEN 'medium'
                       WHEN 2 THEN 'low'
                       WHEN 1 THEN 'info'
                       ELSE NULL
                   END AS max_severity
            FROM ports p
            JOIN assets a ON p.asset_id = a.id
            LEFT JOIN vulns v ON v.port_id = p.id
            {where_sql}
            GROUP BY a.ip, p.id, p.proto, p.port, p.service, p.product, p.version, p.banner, a.os
            ORDER BY a.ip, p.port
            LIMIT %s OFFSET %s
        """
        cur.execute(sql, (*params, limit, offset))
        rows = cur.fetchall()
    return {"count": len(rows), "total": total, "limit": limit, "offset": offset, "items": rows}

# Upload archiving cap. Scan uploads are normally KBs to a few MB; this exists
# so a pathological file cannot be read into memory whole. Exceeding it is
# logged loudly and marked in the stored content rather than passing silently,
# because this table is meant to be the source of truth.
ARTIFACT_MAX_BYTES = int(os.environ.get("ARTIFACT_MAX_BYTES", str(64 * 1024 * 1024)))


def _count_items(content: str, fmt: str) -> int:
    """How many records THIS file holds — the honest per-artifact item count.

    A job-wide findings join over-counts badly: tools share a job_id, so a 514-byte
    crtsh file inherited a sibling dnsx run's 1996 hosts. The file itself is the
    source of truth: JSONL lines, a JSON array's length (or a wrapped list), else
    non-blank lines. Computed once at ingest so the list never rescans 64 MB rows."""
    s = content or ""
    if not s.strip():
        return 0
    if fmt == "jsonl":
        return sum(1 for ln in s.splitlines() if ln.strip())
    if fmt == "json":
        try:
            v = json.loads(s)
        except Exception:
            v = None
        if isinstance(v, list):
            return len(v)
        if isinstance(v, dict):
            for k in ("results", "data", "findings", "hosts", "subdomains",
                      "ports", "urls", "items"):
                if isinstance(v.get(k), list):
                    return len(v[k])
            return 1
    return sum(1 for ln in s.splitlines() if ln.strip())


def _store_artifact_row(*, tool: str, content: str, command: str = None,
                        target: str = None, port: int = None, service: str = None,
                        exec_id: str = None, job_id: str = None, scan_id: str = None,
                        source: str = "unknown", content_format: str = None,
                        native_json: bool = False, engagement_id: str = None,
                        note: str = None) -> dict:
    """Insert or dedupe one artifact. Shared by the HTTP endpoint and the
    upload chokepoint so the two paths cannot drift apart."""
    sha = hashlib.sha256(content.encode("utf-8", "replace")).hexdigest()
    fmt = content_format or _detect_content_format(content)
    item_count = _count_items(content, fmt)
    with get_db() as conn, conn.cursor() as cur:
        cur.execute(
            """
            INSERT INTO raw_artifacts
                (engagement_id, tool, command, target, port, service, exec_id,
                 job_id, scan_id, source, note, item_count, content_format,
                 native_json, content, content_sha256, byte_size)
            VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            ON CONFLICT (tool, COALESCE(target,''), content_sha256) DO UPDATE
               SET last_seen    = now(),
                   occurrences  = raw_artifacts.occurrences + 1,
                   exec_id      = COALESCE(EXCLUDED.exec_id, raw_artifacts.exec_id),
                   job_id       = COALESCE(EXCLUDED.job_id, raw_artifacts.job_id),
                   scan_id      = COALESCE(EXCLUDED.scan_id, raw_artifacts.scan_id),
                   command      = COALESCE(EXCLUDED.command, raw_artifacts.command),
                   note         = COALESCE(EXCLUDED.note, raw_artifacts.note),
                   item_count   = EXCLUDED.item_count
            RETURNING id, (xmax = 0) AS inserted, occurrences
            """,
            (engagement_id, tool, command, target, port, service, exec_id, job_id,
             scan_id, source, note, item_count, fmt, native_json, content, sha,
             len(content.encode("utf-8", "replace"))),
        )
        row = cur.fetchone()
    return {"artifact_id": str(row[0]), "inserted": bool(row[1]),
            "occurrences": row[2], "content_format": fmt, "sha256": sha}


def _archive_upload(path: str, tool: str, job_id: str = None,
                    engagement_id: str = None) -> None:
    """Archive an uploaded scan file verbatim.

    This is where the SCANNER SERVICES get covered. pd_runner, nmap_scanner,
    osint_runner and brutus_runner all deliver results by POSTing a file to
    /ingest/<tool>, so their output never passed through the kali-listener path
    that archived stdout — it was parsed into findings and the original file
    deleted. Archiving here catches every one of them at a single point rather
    than editing each service.

    Never raises: the parse that follows is what the caller asked for, and
    losing the archive copy must not fail an otherwise good ingest.
    """
    try:
        size = os.path.getsize(path)
        with open(path, "rb") as fh:
            raw = fh.read(ARTIFACT_MAX_BYTES)
        content = raw.decode("utf-8", "replace")
        if size > ARTIFACT_MAX_BYTES:
            logger.warning("artifact %s from %s is %d bytes; archived first %d",
                           os.path.basename(path), tool, size, ARTIFACT_MAX_BYTES)
            content += (f"\n\n=== TRUNCATED BY ARTIFACT_MAX_BYTES: stored "
                        f"{ARTIFACT_MAX_BYTES} of {size} bytes ===\n")
        res = _store_artifact_row(tool=tool, content=content, source="upload",
                                  job_id=job_id, engagement_id=engagement_id,
                                  command=f"upload:{os.path.basename(path)}")
        logger.info("archived %s upload (%d bytes) -> %s new=%s",
                    tool, size, res["artifact_id"], res["inserted"])
    except Exception as e:
        logger.warning("upload archive failed for tool=%s: %s", tool, e)


def _save_upload_to_tmp(file: UploadFile, tool: str = None, job_id: str = None,
                        engagement_id: str = None) -> str:
    """Persist an upload to a private temp path.

    The filename is attacker-controlled (it comes from the multipart headers),
    so it is reduced to a basename and scrubbed to a safe charset: a crafted
    name like "../../etc/cron.d/x" would otherwise let the uploader choose the
    write destination. The uuid prefix additionally stops two concurrent
    uploads that share a filename from clobbering each other.
    """
    raw = os.path.basename(file.filename or "upload.bin")
    safe = _re_module.sub(r"[^A-Za-z0-9._-]", "_", raw).lstrip(".") or "upload.bin"
    tmp_path = f"/tmp/{uuid.uuid4().hex}_{safe[:120]}"
    with open(tmp_path, "wb") as buffer:
        buffer.write(file.file.read())
    # Archive before parsing. Callers that name their tool get the complete
    # uploaded file preserved; the parse below is lossy and the temp file is
    # unlinked immediately after it.
    if tool:
        _archive_upload(tmp_path, tool, job_id=job_id, engagement_id=engagement_id)
    return tmp_path

def _parse_targets_text(content: str, whitelist: Optional[List[str]], blacklist: Optional[List[str]]) -> List[str]:
    targets = []
    lines = content.splitlines()
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        targets.append(line)

    # Apply whitelist and blacklist
    if whitelist:
        targets = [target for target in targets if any(ipaddress.ip_address(target) in ipaddress.ip_network(wl) for wl in whitelist)]
    if blacklist:
        targets = [target for target in targets if not any(ipaddress.ip_address(target) in ipaddress.ip_network(bl) for bl in blacklist)]

    return targets

def _create_nmap_tasks_from_recent(job_id: str, since_ts: datetime) -> int:
    base = os.environ.get("NMAP_SCANNER_URL", "https://nmap_scanner:8012")
    _eid = None
    try:
        with get_db() as conn, conn.cursor() as cur:
            cur.execute("SELECT engagement_id FROM jobs WHERE id=%s::uuid", (job_id,))
            row = cur.fetchone()
            if row and row[0]:
                _eid = str(row[0])
    except Exception:
        pass
    try:
        r = requests.post(
            f"{base}/jobs/masscan-results-since/{since_ts.isoformat()}",
            headers=_outgoing_runner_headers(engagement_id=_eid),
            verify=False,
        )
        r.raise_for_status()
        results = r.json().get("results", [])
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            for result in results:
                ip = result.get("ip")
                ports = result.get("ports", [])
                for port_info in ports:
                    port = port_info.get("port")
                    proto = port_info.get("proto", "tcp")
                    cur.execute(
                        """
                        INSERT INTO tasks (job_id, type, target_host, target_port, proto, status)
                        VALUES (%s::uuid, 'nmap', %s, %s, %s, 'queued')
                        ON CONFLICT DO NOTHING
                        """,
                        (job_id, ip, port, proto),
                    )
            cur.execute("UPDATE jobs SET total_tasks = GREATEST(total_tasks, finished_tasks + 1) WHERE id=%s::uuid", (job_id,))
            conn.commit()
        return len(results)
    except requests.RequestException as e:
        raise HTTPException(status_code=502, detail=f"scanner unavailable: {e}")

def _background_run_masscan_nmap(job_id: str, targets: List[str], ports: str, rate: int, interface: Optional[str]) -> None:
    base = os.environ.get("NMAP_SCANNER_URL", "https://nmap_scanner:8012")
    since_ts = datetime.now(timezone.utc)
    # Resolve engagement_id from the jobs row we already stamped at launch.
    # The contextvar isn't reliable in background tasks; DB lookup is.
    _bg_eid: Optional[str] = None
    try:
        with get_db() as conn, conn.cursor() as cur:
            cur.execute("SELECT engagement_id FROM jobs WHERE id=%s::uuid", (job_id,))
            row = cur.fetchone()
            if row and row[0]:
                _bg_eid = str(row[0])
    except Exception:
        pass
    # transition job/tasks to running if queued
    try:
        with get_db() as conn, conn.cursor() as cur:
            cur.execute("UPDATE jobs SET status='running', started_at=COALESCE(started_at, now()) WHERE id=%s::uuid", (job_id,))
            cur.execute("""
                        INSERT INTO tasks (job_id, type, status, started_at)
                        VALUES (%s::uuid,'pipeline','running',now())
                        ON CONFLICT DO NOTHING
                        """, (job_id,))
            # If already existed queued, mark running
            cur.execute("UPDATE tasks SET status='running', started_at=COALESCE(started_at, now()) WHERE job_id=%s::uuid AND type='pipeline' AND status='queued'", (job_id,))
            cur.execute("UPDATE jobs SET total_tasks = GREATEST(total_tasks, 1) WHERE id=%s::uuid", (job_id,))
            conn.commit()
    except Exception:
        pass

    # call scanner
    ok = False
    resp: Dict[str, Any] = {}
    try:
        payload: Dict[str, Any] = {"targets": targets, "ports": ports, "rate": rate}
        if interface:
            payload["interface"] = interface
        r = requests.post(
            f"{base}/jobs/masscan-then-nmap",
            json=payload,
            headers=_outgoing_runner_headers(engagement_id=_bg_eid),
            verify=False, timeout=3600,
        )
        r.raise_for_status()
        resp = r.json() if r.headers.get("content-type","").startswith("application/json") else {"ok": True}
        ok = bool(resp.get("ok", True))
    except requests.RequestException as e:
        err = f"scanner unavailable: {e}"
        with get_db() as conn, conn.cursor() as cur:
            cur.execute("UPDATE tasks SET status='failed', finished_at=now(), last_error=%s WHERE job_id=%s::uuid AND type='pipeline'", (err, job_id))
            cur.execute("UPDATE jobs SET status='failed', finished_at=now(), error=%s WHERE id=%s::uuid", (err, job_id))
            conn.commit()
        return

    # enqueue Nmap tasks from recent results
    try:
        _create_nmap_tasks_from_recent(job_id, since_ts)
    except Exception:
        pass

    # finalize pipeline task and job
    with get_db() as conn, conn.cursor() as cur:
        if ok:
            cur.execute("UPDATE tasks SET status='finished', finished_at=now() WHERE job_id=%s::uuid AND type='pipeline'", (job_id,))
            cur.execute("UPDATE jobs SET finished_tasks = LEAST(total_tasks, finished_tasks + 1), status='finished', finished_at=now(), error=NULL WHERE id=%s::uuid", (job_id,))
        else:
            err = resp.get("error", "unknown error")
            cur.execute("UPDATE tasks SET status='failed', finished_at=now(), last_error=%s WHERE job_id=%s::uuid AND type='pipeline'", (err, job_id))
            cur.execute("UPDATE jobs SET status='failed', finished_at=now(), error=%s WHERE id=%s::uuid", (err, job_id))
        conn.commit()

# Service-discovery sources whose ingest produces new (ip, service, banner)
# tuples that the local-LLM scan_recommender can usefully reason about.
# Sources NOT in this set (burp, subfinder, dnsx, tlsx, crtsh, brutus,
# trufflehog, amass, gau, waybackurls, …) don't produce service-centric
# output, so calling /next_scan for them would be a no-op or wasted call —
# exploit_watcher's existing periodic poll picks up findings from them.
_RECOMMENDER_TRIGGER_SOURCES = {
    "nmap", "masscan", "naabu", "nessus", "nuclei",
    "whatweb", "wafw00f", "httpx", "zap",
}


def _emit_ingest_event(source: str, stats: dict = None):
    """Emit ingest_completed webhook, and — for service-discovery sources —
    fire the local-LLM scan recommender for every freshly-touched open port
    that doesn't yet have a recommendation.  Together these make prioritized
    follow-ups appear as soon as scan results land, instead of waiting for the
    exploit_watcher's polling cycle."""
    try:
        from webhooks import emit_webhook
        emit_webhook("ingest_completed", source, {"stats": stats or {}})
    except Exception:
        pass  # Non-critical — dashboard will still poll
    # Detection -> exploit bridge: promote scanner-confirmed CVEs into
    # software_known_cve follow-ups so they FLAG in the Software tab (and can drive
    # the exploit pipeline) as soon as results land. Idempotent; CVE-producing
    # scanners only.
    if source in ("nuclei", "zap", "nessus", "vulnx", "web", "tool-output", "playwright"):
        try:
            from etl.cve_exploit_bridge import promote_scanner_cves
            _bid = _validate_engagement_uuid(_resolve_engagement_id())
            with get_db() as _c, _c.cursor() as _cur:
                _r = promote_scanner_cves(_cur, _bid); _c.commit()
            if _r.get("created"):
                logging.info("cve bridge: flagged %s scanner-confirmed CVE(s) after %s ingest",
                             _r["created"], source)
        except Exception as _e:  # noqa: BLE001
            logging.debug("cve bridge on %s ingest failed: %s", source, _e)
        # Auto-resolve targeted exploits for the freshly-flagged CVEs (MSF -> EDB ->
        # synth), bounded + idempotent + approval-gated.
        try:
            if _bid:
                _auto_resolve_flagged_cves(_bid, limit=5)
        except Exception as _e2:  # noqa: BLE001
            logging.debug("auto-resolve on %s ingest failed: %s", source, _e2)
    # Generic output-vs-findings reconciliation for EVERY scan type. The parser
    # already reported records it could not ingest (errors / non-dedup skips);
    # surface that instead of letting it pass silently — dedup and scope filters
    # are NOT counted as loss (see etl/reconcile). This is the credential-check
    # reconciliation generalised to the shared ingest chokepoint.
    try:
        from etl.reconcile import reconcile_ingest
        rec = reconcile_ingest(source, stats or {})
        if not rec["matched"]:
            logger.warning("[ingest:%s] RECONCILIATION MISMATCH: %s (seen=%s "
                           "stored=%s dropped=%s deduped=%s)",
                           source, "; ".join(rec["reasons"]), rec["seen"],
                           rec["stored"], rec["dropped"], rec["deduped"])
            try:
                from webhooks import emit_webhook as _emit
                _emit("scan_count_mismatch", source, {
                    "tool": source,
                    "job_id": (stats or {}).get("job_id"),
                    "target": (stats or {}).get("target"),
                    **{k: rec[k] for k in ("seen", "stored", "dropped",
                                           "deduped", "drop_detail", "reasons")},
                })
            except Exception:
                pass
    except Exception as e:
        logger.warning("ingest reconciliation failed for source=%s: %s", source, e)
    try:
        _trigger_recommendations_for(source, stats)
    except Exception as e:
        logger.warning("recommender trigger failed for source=%s: %s", source, e)


def _select_open_ports_without_recs(window_minutes: int = None, limit: int = 200,
                                    ip: str = None):
    """Return open ports that don't yet have a scan recommendation.

    LEFT JOIN + IS NULL keeps this idempotent: ports already recommended are
    filtered out, so running again over the same data is a no-op.

    window_minutes: if set, only consider ports touched within that many
    minutes (the reactive ingest path uses 10). If None, consider ALL current
    open ports — used by on-demand generation for targets scanned earlier.
    """
    clauses = ["COALESCE(p.is_open, true)", "sr.id IS NULL"]
    params: dict = {"limit": limit}
    if window_minutes is not None:
        clauses.append("p.last_seen >= now() - make_interval(mins => %(mins)s)")
        params["mins"] = window_minutes
    if ip:
        clauses.append("host(a.ip)::text = %(ip)s")
        params["ip"] = ip
    where_sql = " AND ".join(clauses)
    with get_db() as c, c.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(f"""
            SELECT host(a.ip)::text AS ip,
                   p.port,
                   p.service,
                   COALESCE(NULLIF(p.banner, ''),
                            NULLIF(CONCAT_WS(' ', p.product, p.version), '')
                   ) AS banner
            FROM public.ports p
            JOIN public.assets a ON a.id = p.asset_id
            LEFT JOIN public.scan_recommendations sr
              ON sr.ip = a.ip
             AND COALESCE(sr.service, '') = COALESCE(p.service, '')
            WHERE {where_sql}
            ORDER BY p.last_seen DESC
            LIMIT %(limit)s
        """, params)
        return cur.fetchall()


def _dispatch_recommender_for_ports(rows) -> int:
    """Call the scan_recommender's /next_scan (persist=true) for each port row,
    generating + persisting recommendations. Returns the number dispatched.

    Must run inside a copy_context() (or a request scope) so
    _outgoing_runner_headers() resolves the engagement_id contextvar.
    """
    scan_rec_url = os.environ.get("SCAN_RECOMMENDER_URL",
                                  "https://scan-recommender:8013")
    dispatched = 0
    for row in rows:
        params = {
            "ip": row["ip"],
            "port": str(row["port"]),
            "persist": "true",
        }
        if row.get("service"):
            params["service"] = row["service"]
        if row.get("banner"):
            params["banner"] = row["banner"]
        try:
            _resp = requests.get(
                f"{scan_rec_url}/next_scan",
                params=params,
                headers=_outgoing_runner_headers(),
                timeout=60,
                verify=False,
            )
            # 429 = the recommender shed this deliberately because it is at
            # capacity. Continuing the loop would queue dozens more requests
            # into a service that just said "not now", which is how it got
            # saturated in the first place. Stop this pass; these ports keep
            # their "no recommendation yet" state and the next ingest (or
            # exploit_watcher's poll) picks them up.
            if _resp is not None and _resp.status_code == 429:
                logger.info(
                    "recommender at capacity — stopping this pass after %d of %d "
                    "port(s); remaining ports will be retried on a later cycle",
                    dispatched, len(rows))
                break
            dispatched += 1
        except Exception as e:
            logger.debug(
                "recommender call failed for %s:%s — %s",
                row["ip"], row["port"], e,
            )
    return dispatched


def _trigger_recommendations_for(source: str, stats: dict = None):
    """Fire-and-forget: ask the local-LLM scan_recommender to recommend next
    probes for every recently-touched open port without a recommendation yet.

    Runs in a daemon thread so the ingest response isn't blocked by LLM
    inference.  Only fires for sources in `_RECOMMENDER_TRIGGER_SOURCES`;
    everything else is a no-op (no shape match, no value)."""
    if source not in _RECOMMENDER_TRIGGER_SOURCES:
        return

    def _worker():
        try:
            # Pull the most-recently-touched open ports that haven't been
            # recommended on yet (10-minute reactive window for ingest).
            rows = _select_open_ports_without_recs(window_minutes=10)
            dispatched = _dispatch_recommender_for_ports(rows)

            if dispatched:
                logger.info(
                    "scan_recommender dispatched: source=%s dispatched=%d",
                    source, dispatched,
                )
                # Surface this on the webhook bus so external tools / the
                # OPSEC timeline can see that follow-ups were generated
                # reactively in response to this ingest.
                try:
                    from webhooks import emit_webhook
                    emit_webhook("recommendations_generated", source, {
                        "source": source,
                        "dispatched": dispatched,
                    })
                except Exception:
                    pass
        except Exception as e:
            logger.warning(
                "recommender trigger worker failed: source=%s err=%s",
                source, e,
            )

    # Propagate the request's contextvars (including current_engagement_id)
    # into the worker thread.  `threading.Thread` does NOT inherit contextvars
    # by default -- without this the worker runs with default (None) values
    # for any contextvar set by the HTTP middleware, which would silently
    # break engagement-scoped lookups added in future worker code paths.
    # See: https://docs.python.org/3/library/contextvars.html#contextvars.copy_context
    ctx = contextvars.copy_context()
    threading.Thread(
        target=ctx.run, args=(_worker,),
        daemon=True, name=f"reco-trigger-{source}",
    ).start()

@app.post("/ingest/nmap")
def ingest_nmap(
    file: UploadFile = File(...),
    job_id: str = None,
    target: str = None,
    authorized: bool = Depends(auth)
):
    path = _save_upload_to_tmp(file, tool="nmap", job_id=job_id)
    try:
        from etl.parse_nmap import parse_nmap
        stats = parse_nmap(path, profile="api-upload", job_id=job_id, target=target)
        _emit_ingest_event("nmap", stats)
        return {"ok": True, "stats": stats}
    finally:
        os.remove(path)

