@app.post("/ingest/masscan/dedupe")
def dedupe_masscan(file: UploadFile = File(...), authorized: bool = Depends(auth)):
    """
    Accept a Masscan -oJ JSON file and return a deduplicated list of host:port pairs.
    """
    path = _save_upload_to_tmp(file, tool="dedupe")
    try:
        items: List[Dict[str, Any]] = []
        pairs = set()
        with open(path, "r", encoding="utf-8", errors="ignore") as fh:
            try:
                data = json.load(fh)
            except json.JSONDecodeError:
                # Fallback: attempt to parse line-delimited JSON entries
                fh.seek(0)
                data = []
                for line in fh:
                    s = line.strip()
                    if not s or s in ("[", "]", ","):
                        continue
                    if s.endswith(","):
                        s = s[:-1]
                    try:
                        obj = json.loads(s)
                        data.append(obj)
                    except Exception:
                        pass
        if isinstance(data, list):
            for rec in data:
                if not isinstance(rec, dict):
                    continue
                ip = rec.get("ip")
                for p in rec.get("ports", []) or []:
                    port = p.get("port")
                    proto = p.get("proto", "tcp")
                    if ip and isinstance(port, int):
                        key = (ip, port, proto)
                        if key not in pairs:
                            pairs.add(key)
                            items.append({"host": ip, "port": port, "proto": proto})
        return {"count": len(items), "items": items}
    finally:
        os.remove(path)

