@app.get("/news/items", tags=["News"])
def news_items_list(
    status: Optional[str] = Query(None),
    hide_statuses: Optional[str] = Query(None, description="CSV of statuses to hide (applied IN ADDITION to other filters)"),
    cve: Optional[str] = Query(None),
    kev_listed: Optional[bool] = Query(None),
    rce: Optional[bool] = Query(None),
    red_team_only: bool = Query(False, description="Only items with at least one offensive flag (kev/rce/easy/itw/malware)"),
    affects_engagement: bool = Query(False, description="Only items with a cached match against the current engagement (any confidence tier). Requires X-Engagement-Id."),
    strong_only: bool = Query(False, description="Secondary filter — restrict affects_engagement hits to confidence='strong'. Ignored when affects_engagement is false."),
    q: Optional[str] = Query(None, description="Substring on title/summary"),
    since: Optional[str] = Query(None, description="ISO timestamp; only items with last_seen >= since"),
    published_since: Optional[str] = Query(None, description="ISO timestamp; only items PUBLISHED at or after this (items with no published_at are excluded)"),
    sort: str = Query("relevance", description="relevance (offensive flags first, then last_seen) | published (newest publication date first) | last_seen"),
    include_deleted: bool = Query(False),
    limit: int = Query(100, ge=1, le=1000),
    offset: int = Query(0, ge=0),
    authorized: bool = Depends(auth),
):
    conds = []
    params: list = []
    if status:
        conds.append("status = %s"); params.append(status)
    elif not include_deleted:
        conds.append("status <> 'deleted'")
    if hide_statuses:
        wanted = [s.strip() for s in hide_statuses.split(",") if s.strip()]
        if wanted:
            conds.append("status <> ALL(%s::text[])")
            params.append(wanted)
    if cve:
        conds.append("(primary_cve = %s OR %s = ANY(all_cves))")
        params.extend([cve.upper(), cve.upper()])
    if kev_listed is not None:
        conds.append("kev_listed = %s"); params.append(kev_listed)
    if rce is not None:
        conds.append("rce = %s"); params.append(rce)
    if red_team_only:
        # An item is red-team relevant when at least one offensive flag is true.
        # Items still pending enrichment (all flags NULL) are excluded so the
        # default view doesn't show commentary/marketing pieces.
        conds.append(
            "(kev_listed IS TRUE OR rce IS TRUE OR easily_exploitable IS TRUE "
            "OR active_internet_breach IS TRUE OR malware_exploitable IS TRUE)"
        )
    # Engagement-match filter — matches items whose metadata.engagement_match
    # cache for the CURRENT engagement reports match_count > 0. strong_only
    # narrows to confidence='strong'.
    _eid_for_filter = _resolve_engagement_id() if affects_engagement else None
    if affects_engagement:
        if not _eid_for_filter:
            raise HTTPException(400, "affects_engagement requires X-Engagement-Id")
        conds.append("(metadata #> ARRAY['engagement_match', %s, 'match_count'])::text::int > 0")
        params.append(_eid_for_filter)
        if strong_only:
            conds.append("(metadata #>> ARRAY['engagement_match', %s, 'confidence']) = 'strong'")
            params.append(_eid_for_filter)
    if q:
        conds.append("(title ILIKE %s OR summary ILIKE %s)")
        params.extend([f"%{q}%", f"%{q}%"])
    if since:
        conds.append("last_seen >= %s::timestamptz"); params.append(since)
    if published_since:
        # An item with no published_at cannot be shown to satisfy "published
        # since X" — NULL means the feed never told us, not "recent".
        conds.append("published_at >= %s::timestamptz"); params.append(published_since)
    where = (" WHERE " + " AND ".join(conds)) if conds else ""

    if sort not in _NEWS_SORTS:
        raise HTTPException(400, f"sort must be one of {sorted(_NEWS_SORTS)}")
    order_by = _NEWS_SORTS[sort]

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(f"SELECT count(*) AS n FROM news_items{where}", params)
        total = cur.fetchone()["n"]
        # Red-team-relevant items rank higher (KEV → RCE → ITW → easy → malware)
        # so the default view bubbles dangerous items above commentary even
        # when red_team_only is off.
        cur.execute(
            f"""SELECT * FROM news_items {where}
                ORDER BY {order_by}
                LIMIT %s OFFSET %s""",
            list(params) + [limit, offset],
        )
        rows = cur.fetchall()
    _eid = _resolve_engagement_id()
    return {"total": total, "limit": limit, "offset": offset,
            "results": [_ser_news_item(r, engagement_id=_eid) for r in rows]}


