def _run_takeover_hunter_if_enabled(engagement_id: Optional[str] = None) -> None:
    """Post-recon hook. Fires automatically when the agent's auto toggle is
    on AND there's been a fresh recon ingest. Operator must opt in (default
    OFF) because this actively probes external resources via the configured
    proxy. Debounce in the agent itself ensures back-to-back ingests don't
    spam targets."""
    if not get_agent_auto_enabled("takeover_hunter_agent", default=False):
        return
    try:
        import takeover_hunter
        with get_db(autocommit=True) as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            engagement_ids = [engagement_id] if engagement_id else None
            result = takeover_hunter.hunt(
                cur, engagement_ids=engagement_ids, dry_run=False, force=False,
            )
        if result.get("debounced"):
            log.info("takeover_hunter auto-run debounced (next eligible in %ss)",
                     result.get("next_eligible_in_s"))
        else:
            log.info("takeover_hunter auto-run: candidates=%s confirmed=%s inserted=%s",
                     result.get("candidates_examined"),
                     result.get("confirmed"),
                     result.get("inserted"))
    except Exception as e:
        log.warning("takeover_hunter auto-run failed (non-fatal): %s", e)


_STUCK_JOB_TIMEOUT_S = int(os.environ.get("STUCK_JOB_TIMEOUT_S", "300"))   # 5 min default
_STUCK_JOB_SWEEP_S   = int(os.environ.get("STUCK_JOB_SWEEP_S", "600"))    # check every 10 min
_stuck_sweeper_task = None
# Holds the background task that keeps retrying default-webhook registration
# (None once registration has succeeded). Declared at module level so
# startup_event's `global` binding has something to bind.
_webhook_registration_task = None


def _sweep_stuck_jobs_once():
    """Mark running jobs as failed if their progress hasn't been bumped
    within _STUCK_JOB_TIMEOUT_S seconds. COALESCE to started_at so jobs
    that never wrote progress (parser died before first batch) still get
    detected. Returns the list of swept job ids for logging / webhook."""
    swept: list[tuple[str, str, str]] = []  # (id, type, last_bump_at)
    try:
        with get_db(autocommit=True) as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                UPDATE jobs
                SET status      = 'failed',
                    finished_at = now(),
                    error       = COALESCE(error || ' | ', '') ||
                                  'auto-sweeper: no progress in '
                                  || %s::int || 's (parser likely died)'
                WHERE status = 'running'
                  AND COALESCE(progress_updated_at, started_at)
                      < now() - (%s::int || ' seconds')::interval
                RETURNING id::text, type,
                    COALESCE(progress_updated_at, started_at)::text AS last_bump
            """, (_STUCK_JOB_TIMEOUT_S, _STUCK_JOB_TIMEOUT_S))
            swept = [(r["id"], r["type"], r["last_bump"]) for r in cur.fetchall()]
    except Exception as e:
        log.warning("stuck-job sweeper query failed: %s", e)
        return []

    if swept:
        log.warning("stuck-job sweeper marked %d job(s) failed: %s",
                    len(swept), [(jid[:8], jt) for jid, jt, _ in swept])
        try:
            from webhooks import emit_webhook
            for jid, jt, last in swept:
                emit_webhook("job_marked_stale", "stuck_job_sweeper", {
                    "job_id": jid, "job_type": jt,
                    "last_progress_at": last,
                    "timeout_s": _STUCK_JOB_TIMEOUT_S,
                })
        except Exception:
            pass
    return swept


async def _stuck_sweeper_loop():
    import asyncio as _asyncio
    log.info("stuck-job sweeper started — sweep every %ds, timeout %ds",
             _STUCK_JOB_SWEEP_S, _STUCK_JOB_TIMEOUT_S)
    while True:
        try:
            await _asyncio.sleep(_STUCK_JOB_SWEEP_S)
            _sweep_stuck_jobs_once()
        except _asyncio.CancelledError:
            raise
        except Exception:
            log.exception("stuck-job sweeper iteration failed")


async def _retry_default_webhooks(attempts: int = 30, delay: float = 10.0):
    """Keep trying to register the default webhooks until the schema exists.

    On a fresh install this service starts in phase 6 and the `webhooks` table
    is created in phase 7, so the startup attempt necessarily fails. It used to
    fail silently and never retry, leaving 'event-log' and 'dashboard-bff'
    unregistered for the life of the install — every emitted event answered 200
    and was dropped, so webhook_events stayed empty and so did the Agent
    Activity timeline.

    30 x 10s covers the gap between phases 6 and 7 with room to spare. Giving up
    is logged as an ERROR, because at that point events really are being lost.
    """
    import asyncio
    for n in range(1, attempts + 1):
        await asyncio.sleep(delay)
        if ensure_default_webhook():
            log.info("Default webhooks registered on retry %d", n)
            return
    log.error(
        "Default webhooks still unregistered after %d attempts (%.0fs). Events "
        "are being accepted and DISCARDED — check that the webhooks table "
        "exists (scripts/ensure_db_schema.sh) and restart this service.",
        attempts, attempts * delay,
    )


@app.on_event("startup")
async def startup_event():
    ensure_phase0_schema()
    # Start webhook retry worker for failed delivery retries
    start_retry_worker()
    # Sweep stuck/abandoned running jobs on startup, then every 60s
    import asyncio
    # Register default catch-all event-log webhook so all events are recorded.
    # Retried in the background when it cannot succeed yet: on a fresh install
    # the webhooks table does not exist until phase 7.
    global _webhook_registration_task
    if ensure_default_webhook():
        _webhook_registration_task = None
    else:
        log.warning("Default webhooks not registered yet — retrying in the background")
        _webhook_registration_task = asyncio.create_task(_retry_default_webhooks())
    global _stuck_sweeper_task
    try:
        _sweep_stuck_jobs_once()  # immediate sweep covers crashes pre-restart
    except Exception:
        log.exception("initial stuck-job sweep failed")
    _stuck_sweeper_task = asyncio.create_task(_stuck_sweeper_loop())
    # News intelligence — fetch + LLM enrichment now lives in the news-runner
    # container; trigger endpoints below proxy to it. The news-runner owns
    # its own scheduler.


@app.on_event("shutdown")
async def shutdown_event():
    # Stop webhook retry worker
    stop_retry_worker()
    global _stuck_sweeper_task
    if _stuck_sweeper_task is not None:
        _stuck_sweeper_task.cancel()
    # Cancelled alongside it — an un-cancelled retry task keeps sleeping through
    # shutdown and logs its give-up error into a process that is already gone.
    global _webhook_registration_task
    if _webhook_registration_task is not None:
        _webhook_registration_task.cancel()

class Job(BaseModel):
    id: str = Field(..., description="Unique identifier for the job")
    type: str = Field(..., description="Type of the job (e.g., masscan-nmap)")
    status: str = Field(..., description="Current status of the job (queued, running, finished, failed, canceled)")
    params: Dict[str, Any] = Field(..., description="Parameters for the job")
    total_tasks: int = Field(0, description="Total number of tasks for the job")
    finished_tasks: int = Field(0, description="Number of finished tasks for the job")
    error: Optional[str] = Field(None, description="Error message if applicable")
    created_at: datetime = Field(..., description="Creation timestamp of the job")
    started_at: Optional[datetime] = Field(None, description="Start timestamp of the job")
    finished_at: Optional[datetime] = Field(None, description="Completion timestamp of the job")

class JobListResponse(BaseModel):
    jobs: List[Job]

@app.get("/jobs/{job_id}")
def get_job_results(job_id: str, authorized: bool = Depends(auth)):
    # Check in-memory DDG jobs first (non-UUID IDs like ai-check-*)
    if job_id in _ddg_jobs:
        job = _ddg_jobs[job_id]
        return {"id": job_id, "status": job["status"], "stage": job.get("stage", ""),
                "stages_done": job.get("stages_done", []),
                "params": {"product": job.get("product"), "version": job.get("version")},
                "result": job.get("result"), "progress": {}}
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        try:
            cur.execute(
                # total_tasks/finished_tasks are maintained by
                # /jobs/nmap-from-masscan but were never returned, so a caller
                # could not see progress it was already recording.
                "SELECT id, type, params, result, progress, status, error, "
                "total_tasks, finished_tasks, "
                "started_at, finished_at, created_at "
                "FROM jobs WHERE id=%s::uuid",
                (job_id,),
            )
        except Exception:
            raise HTTPException(status_code=404, detail=f"Job not found: {job_id}")
        row = cur.fetchone()

        if not row:
            raise HTTPException(status_code=404, detail="Job not found")

    return {
        "id": str(row["id"]),
        "type": row["type"],
        "params": row["params"],
        "result": row["result"],
        "progress": row["progress"],
        "status": row["status"],
        "error": row["error"],
        "total_tasks": row["total_tasks"],
        "finished_tasks": row["finished_tasks"],
        "started_at": row["started_at"].isoformat() if row["started_at"] else None,
        "finished_at": row["finished_at"].isoformat() if row["finished_at"] else None,
        "created_at": row["created_at"].isoformat() if row["created_at"] else None,
    }

# added to get details on a specific job
router = APIRouter(prefix="/tasks", tags=["Tasks"])

class Task(BaseModel):
    id: str
    job_id: str
    type: str
    target_host: Optional[str]
    target_port: Optional[int]
    proto: Optional[str]
    status: str
    attempt: int
    last_error: Optional[str]
    created_at: datetime
    started_at: Optional[datetime]
    finished_at: Optional[datetime]

@router.get("/{job_id}", response_model=List[Task])
def get_tasks_for_job(job_id: str, authorized: bool = Depends(auth)):
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM tasks WHERE job_id=%s::uuid", (job_id,))
        rows = cur.fetchall()
    if not rows:
        raise HTTPException(status_code=404, detail="No tasks found for this job ID")
    return rows
# adding for vulns
class Vuln(BaseModel):
    id: str = Field(..., description="Unique identifier for the vulnerability")
    script: str = Field(..., description="Nmap script used to detect the vulnerability")
    output: str = Field(..., description="Detailed output from the NSE script")
    ip: Optional[str] = Field(None, description="IP address of the asset")
    port: Optional[int] = Field(None, description="Port number where the vulnerability was found")
    proto: Optional[str] = Field(None, description="Protocol (tcp/udp)")
    service: Optional[str] = Field(None, description="Service running on the port")
    product: Optional[str] = Field(None, description="Product name of the service")
    version: Optional[str] = Field(None, description="Version of the service")
    banner: Optional[str] = Field(None, description="Banner from the service")
    created_at: datetime = Field(..., description="Timestamp when the vulnerability was found")

class VulnListResponse(BaseModel):
    vulns: List[Vuln]

@app.get("/vulns")
def get_vulnerabilities(
    ip: Optional[str] = Query(None, description="Filter by IP address"),
    script_type: Optional[str] = Query(None, description="Filter by Nmap script type"),
    severity: Optional[str] = Query(None, description="Filter by severity (info/low/medium/high/critical)"),
    search: Optional[str] = Query(None, description="Substring match on script / output / banner (case-insensitive)"),
    limit: int = Query(200, ge=1, le=5000),
    offset: int = Query(0, ge=0, description="Pagination offset for retrieving > limit rows"),
    authorized: bool = Depends(auth)
):
    # Construct the SQL query with optional filters
    where = []
    params = []

    # Scope to the active engagement (X-Engagement-Id header); vulns carries
    # engagement_id, so a selected engagement must not list every engagement's
    # vulnerabilities.
    _eid = _validate_engagement_uuid(_resolve_engagement_id())
    if _eid:
        where.append("v.engagement_id = %s::uuid")
        params.append(_eid)

    if ip:
        where.append("host(a.ip)=%s")
        params.append(ip)

    if script_type:
        where.append("v.script=%s")
        params.append(script_type)

    if severity:
        where.append("v.severity=%s")
        params.append(severity)

    if search:
        where.append("(v.script ILIKE %s OR v.output ILIKE %s OR p.banner ILIKE %s)")
        params.extend([f"%{search}%", f"%{search}%", f"%{search}%"])

    where_sql = "WHERE " + " AND ".join(where) if where else ""

    # LEFT JOIN, not INNER. vulns.port_id is NULL for findings that belong to an
    # ASSET rather than a specific port — every nuclei/web finding, for one. An
    # inner join through ports silently discarded all of them: a high-severity
    # CVE-2012-1823 (PHP CGI RCE) sat ingested in the table while
    # /vulns?severity=high returned 0 results. Assets are reached via the port
    # when there is one and via vulns.asset_id when there is not.
    count_sql = f"""
        SELECT count(*) AS n FROM public.vulns v
        LEFT JOIN public.ports p ON v.port_id = p.id
        LEFT JOIN public.assets a ON a.id = COALESCE(p.asset_id, v.asset_id)
        {where_sql}
    """

    sql = f"""
        SELECT v.id,
               v.script, v.output,
               host(a.ip)::text AS ip,
               p.port, p.proto, p.service, p.product, p.version, p.banner,
               v.created_at
        FROM public.vulns v
        LEFT JOIN public.ports p ON v.port_id = p.id
        LEFT JOIN public.assets a ON a.id = COALESCE(p.asset_id, v.asset_id)
        {where_sql}
        ORDER BY v.created_at DESC
        LIMIT %s OFFSET %s
    """

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(count_sql, params)
        total = cur.fetchone()["n"]
        cur.execute(sql, params + [limit, offset])
        rows = cur.fetchall()

    # Vuln model expects an `id` (UUID); psycopg2 returns the UUID type which Pydantic
    # accepts. Stringify other UUIDs for downstream serializers if needed.
    vulns = [Vuln(**row) for row in rows]
    return {"vulns": vulns, "total": total, "count": len(vulns), "limit": limit, "offset": offset}


# --- Unified Findings Search ---

class UnifiedFinding(BaseModel):
    id: str = Field(..., description="Unique identifier")
    problem_id: Optional[str] = Field(None, description="Infrastructure problem group (shared across virtual hosts of one machine); null when the finding cannot be grouped")
    affects_hosts: int = Field(1, description="How many virtual hosts of this machine show the same problem. 1 means it was seen on this host only")
    source: str = Field(..., description="Source scanner (nmap, nuclei, zap, gobuster, playwright)")
    asset_id: Optional[str] = Field(None, description="Asset UUID")
    ip: Optional[str] = Field(None, description="IP address")
    hostname: Optional[str] = Field(None, description="DNS hostname")
    port: Optional[int] = Field(None, description="Port number")
    url: Optional[str] = Field(None, description="URL (for web findings)")
    severity: Optional[str] = Field(None, description="Severity level")
    title: str = Field(..., description="Finding title/name")
    evidence: Optional[str] = Field(None, description="Evidence or output")
    cve: List[str] = Field(default_factory=list, description="CVE identifiers")
    cwe: List[str] = Field(default_factory=list, description="CWE identifiers")
    cvss: Optional[float] = Field(None, description="CVSS score")
    method: Optional[str] = Field(None, description="HTTP method (for web findings)")
    description: Optional[str] = Field(None, description="Full description of the finding")
    solution: Optional[str] = Field(None, description="Remediation guidance")
    reference: Optional[str] = Field(None, description="External references")
    confidence: Optional[str] = Field(None, description="Confidence level (High, Medium, Low)")
    tags: Optional[list] = Field(None, description="User-assigned tags")
    created_at: datetime = Field(..., description="When the finding was created")


class SearchAggregations(BaseModel):
    """Two different questions, deliberately answered differently.

    GLOBAL, RAW (by_severity, by_source) — computed over the whole dataset,
    IGNORING the query filters, and counting rows. That is not a bug: the
    frontend uses by_source to render a filter chip for every source that
    exists, so chips do not vanish as you narrow the filter, and Dashboard.tsx /
    Reports.tsx want dataset totals. Changing these to respect the filter would
    break all three.

    FILTERED, PER-PROBLEM (problems_by_severity, distinct_problems,
    shared_problems) — computed over the rows the query actually matched, and
    collapsed so a server-level problem seen on six virtual hosts counts once.

    They differ on BOTH axes, so the names have to say so. `by_severity` next to
    a `by_severity_deduped` invited exactly the wrong reading — that the only
    difference was dedup.
    """

    # global, raw row counts
    by_severity: Dict[str, int] = Field(default_factory=dict, description="GLOBAL row counts by severity — ignores query filters")
    by_source: Dict[str, int] = Field(default_factory=dict, description="GLOBAL row counts by source — ignores query filters, so every source stays filterable")
    # filtered, one entry per underlying problem
    problems_by_severity: Dict[str, int] = Field(default_factory=dict, description="FILTERED counts by severity, one per underlying problem")
    problems_by_source: Dict[str, int] = Field(default_factory=dict, description="FILTERED counts by source, one per underlying problem. Use this when a breakdown must agree with the rows the filter actually matched; use by_source when every source must stay visible as a filter option.")
    distinct_problems: int = Field(0, description="FILTERED: matching rows collapsed to one per underlying problem")
    shared_problems: int = Field(0, description="FILTERED: of those, how many appear on more than one virtual host")


class UnifiedSearchResponse(BaseModel):
    findings: List[UnifiedFinding]
    total: int
    aggregations: SearchAggregations


@app.get("/findings/search", response_model=UnifiedSearchResponse, tags=["Findings"])
def search_findings(
    severity: Optional[List[str]] = Query(None, description="Filter by severity (critical, high, medium, low, info)"),
    source: Optional[List[str]] = Query(None, description="Filter by source (nmap, nuclei, zap, gobuster, playwright)"),
    ip: Optional[str] = Query(None, description="Filter by IP address"),
    asset_id: Optional[str] = Query(None, description="Filter by asset UUID"),
    cve: Optional[str] = Query(None, description="Search for CVE (e.g., CVE-2024)"),
    cwe: Optional[str] = Query(None, description="Search for CWE (e.g., CWE-79)"),
    search: Optional[str] = Query(None, description="Free-text search in title/evidence"),
    port: Optional[int] = Query(None, description="Filter by port number"),
    date_from: Optional[datetime] = Query(None, description="Created after this date"),
    date_to: Optional[datetime] = Query(None, description="Created before this date"),
    workflow_status: Optional[List[str]] = Query(None, description="Filter by workflow status (new, triaging, confirmed, false_positive, accepted_risk, in_report, deferred)"),
    engagement_id: Optional[str] = Query(None, description="Filter by engagement ID"),
    tags: Optional[List[str]] = Query(None, description="Filter by tags (findings must have ALL specified tags)"),
    problem_scope: Optional[str] = Query(None, description="Filter by how far a problem spreads: 'shared' (one problem seen on several virtual hosts of a machine), 'single' (observed on one host only), 'all'. NOT the engagement scope — see the `scope_name` concept elsewhere."),
    problem_id: Optional[str] = Query(None, description="Filter to one infrastructure problem group (infrastructure_fingerprint)"),
    collapse_problems: bool = Query(False, description="Return one row per underlying problem instead of one per virtual host"),
    include_inventory: bool = Query(False, description="Include crawl inventory — URLs a crawler merely discovered, with no name or issue type. Excluded by default because a crawled URL is not a finding: 746 of 779 rows in one deployment were katana output, which made every severity count meaningless"),
    limit: int = Query(100, ge=1, le=1000, description="Max results to return"),
    offset: int = Query(0, ge=0, description="Pagination offset"),
    authorized: bool = Depends(auth)
):
    """
    Search across all vulnerability and finding tables (vulns, web_findings, playwright_findings).
    Returns unified results with aggregations by severity and source.
    """
    # Build the base UNION query
    base_query = """
    WITH unified AS (
        -- From vulns table (nmap/nuclei/ssh-audit/sslscan/etc)
        SELECT
            v.id::text,
            CASE
                WHEN v.metadata->>'source' LIKE 'nuclei:%%' THEN 'nuclei'
                WHEN v.metadata->>'tool' IS NOT NULL THEN v.metadata->>'tool'
                WHEN v.script = 'vulnx' THEN 'vulnx'
                WHEN v.script LIKE 'ssh-audit:%%' THEN 'ssh-audit'
                WHEN v.script LIKE 'sslscan:%%' THEN 'sslscan'
                WHEN v.script LIKE 'testssl:%%' THEN 'testssl'
                WHEN v.script LIKE 'sslyze:%%' THEN 'sslyze'
                WHEN v.script LIKE 'nmap-%%' OR v.script LIKE 'nmap:%%' THEN 'nmap'
                WHEN v.script LIKE 'vulscan:%%' THEN 'vulscan'
                WHEN v.script LIKE 'vulners:%%' THEN 'vulners'
                WHEN v.script LIKE '%%:%%' THEN split_part(v.script, ':', 1)
                ELSE 'nmap'
            END as source,
            v.asset_id::text,
            COALESCE(host(a.ip)::text, '') as ip,
            a.hostname,
            COALESCE(p.port, (v.metadata->>'port')::int) as port,
            v.metadata->>'url' as url,
            v.severity,
            COALESCE(v.title, v.script) as title,
            LEFT(v.output, 500) as evidence,
            COALESCE(v.cve, ARRAY[]::text[]) as cve,
            ARRAY[]::text[] as cwe,
            v.cvss,
            NULL::text as method,
            NULL::text as description,
            NULL::text as solution,
            NULL::text as reference,
            NULL::text as confidence,
            COALESCE(v.tags, ARRAY[]::text[]) as tags,
            v.created_at,
            v.workflow_status,
            v.assigned_to,
            v.verified_by,
            v.verified_at,
            v.tester_notes,
            v.original_severity,
            v.report_ready,
            v.engagement_id::text,
            NULL::text as problem_id,
            1 as affects_hosts,
            'finding'::text as record_kind,
            'vuln' as finding_source
        FROM vulns v
        LEFT JOIN assets a ON a.id = v.asset_id
        LEFT JOIN ports p ON p.id = v.port_id

        UNION ALL

        -- From web_findings table (zap/gobuster)
        SELECT
            wf.id::text,
            wf.source,
            wf.asset_id::text,
            COALESCE(host(a.ip)::text, split_part(split_part(wf.url, '://', 2), '/', 1), split_part(split_part(wf.url, '://', 2), ':', 1)) as ip,
            a.hostname,
            wf.port,
            wf.url,
            wf.severity,
            wf.name as title,
            LEFT(wf.evidence, 500) as evidence,
            ARRAY[]::text[] as cve,
            COALESCE(wf.cwe, ARRAY[]::text[]) as cwe,
            NULL::float as cvss,
            wf.method,
            LEFT(wf.description, 1000) as description,
            LEFT(wf.solution, 1000) as solution,
            LEFT(wf.reference, 500) as reference,
            wf.confidence,
            -- Merge operator tags (user_tags, text[]) with SCANNER tags
            -- (wf.tags, jsonb — nuclei's rce/php/sqli/…). Surfacing only
            -- user_tags hid every scanner tag, so a WSTG matcher keyed on
            -- nuclei_tags matched nothing and CVE findings produced no tests.
            (COALESCE(wf.user_tags, ARRAY[]::text[]) ||
             CASE WHEN jsonb_typeof(wf.tags) = 'array'
                  THEN ARRAY(SELECT jsonb_array_elements_text(wf.tags))
                  ELSE ARRAY[]::text[] END) as tags,
            wf.created_at,
            wf.workflow_status,
            wf.assigned_to,
            wf.verified_by,
            wf.verified_at,
            wf.tester_notes,
            wf.original_severity,
            wf.report_ready,
            wf.engagement_id::text,
            wf.infrastructure_fingerprint as problem_id,
            COALESCE(ic.n, 1) as affects_hosts,
            wf.record_kind,
            'web' as finding_source
        FROM web_findings wf
        LEFT JOIN assets a ON a.id = wf.asset_id
        -- One aggregate scan, joined in, rather than a correlated subquery per
        -- row. affects_hosts > 1 is what makes a finding "shared": the same
        -- problem observed on several virtual hosts of one machine.
        LEFT JOIN (
            SELECT infrastructure_fingerprint AS fp,
                   count(DISTINCT asset_id)   AS n
              FROM web_findings
             WHERE infrastructure_fingerprint IS NOT NULL
             GROUP BY infrastructure_fingerprint
        ) ic ON ic.fp = wf.infrastructure_fingerprint

        UNION ALL

        -- From playwright_findings table
        SELECT
            pf.id::text,
            'playwright' as source,
            pf.asset_id::text,
            COALESCE(host(a.ip)::text, split_part(split_part(pf.url, '://', 2), '/', 1), split_part(split_part(pf.url, '://', 2), ':', 1)) as ip,
            a.hostname,
            COALESCE(
                (substring(pf.url from '://[^/:]+:(\d+)'))::int,
                CASE WHEN pf.url LIKE 'https://%%' THEN 443 WHEN pf.url LIKE 'http://%%' THEN 80 ELSE NULL END
            ) as port,
            pf.url,
            pf.severity,
            pf.title,
            LEFT(pf.evidence, 500) as evidence,
            ARRAY[]::text[] as cve,
            COALESCE(pf.cwe, ARRAY[]::text[]) as cwe,
            NULL::float as cvss,
            NULL::text as method,
            LEFT(pf.description, 1000) as description,
            pf.remediation as solution,
            NULL::text as reference,
            NULL::text as confidence,
            COALESCE(pf.tags, ARRAY[]::text[]) as tags,
            pf.created_at,
            pf.workflow_status,
            pf.assigned_to,
            pf.verified_by,
            pf.verified_at,
            pf.tester_notes,
            pf.original_severity,
            pf.report_ready,
            pf.engagement_id::text,
            NULL::text as problem_id,
            1 as affects_hosts,
            'finding'::text as record_kind,
            'playwright' as finding_source
        FROM playwright_findings pf
        LEFT JOIN assets a ON a.id = pf.asset_id

        UNION ALL

        -- From ports table (nmap/masscan port scans)
        SELECT
            pt.id::text,
            'portscan' as source,
            pt.asset_id::text,
            COALESCE(host(a.ip)::text, '') as ip,
            a.hostname,
            pt.port,
            NULL::text as url,
            -- Informational, not a separate 'recon' severity. The two were
            -- functionally identical: both mapped to SARIF 'note', both were
            -- ordinary severity chips, neither was filtered differently by any
            -- export or report. Only the sort rank differed. Collapsing them
            -- means one informational bucket instead of two names for it.
            'info'::text as severity,
            COALESCE(pt.service, '') || ' ' || COALESCE(pt.product, '') || ' ' || COALESCE(pt.version, '') as title,
            CASE WHEN pt.is_open THEN 'open' ELSE 'closed' END || '/' || pt.proto || ' ' || COALESCE(pt.service, '?') || COALESCE(' ' || pt.product || ' ' || pt.version, '') || COALESCE(' banner=' || LEFT(pt.banner, 100), '') as evidence,
            ARRAY[]::text[] as cve,
            ARRAY[]::text[] as cwe,
            NULL::float as cvss,
            NULL::text as method,
            NULL::text as description,
            NULL::text as solution,
            NULL::text as reference,
            NULL::text as confidence,
            ARRAY[]::text[] as tags,
            pt.created_at,
            NULL::text as workflow_status,
            NULL::text as assigned_to,
            NULL::text as verified_by,
            NULL::timestamptz as verified_at,
            NULL::text as tester_notes,
            NULL::text as original_severity,
            NULL::boolean as report_ready,
            NULL::text as engagement_id,
            NULL::text as problem_id,
            1 as affects_hosts,
            -- INVENTORY, not a finding. "port 2121 runs ProFTPD 1.3.1" is an
            -- observation about the target, not a weakness in it — the same
            -- distinction that moved 746 katana crawl rows out of this view.
            -- These 40 rows were the entire remaining gap between
            -- /findings/search (94) and /export/sarif (54): the same engagement
            -- described two ways depending on which artefact you opened.
            --
            -- Not hidden: include_inventory=true brings them back, the Ports and
            -- Assets views read the `ports` table directly, and CVE matching
            -- still consumes the service/product/version from it. They just stop
            -- padding a findings count and a severity facet.
            'inventory'::text as record_kind,
            'portscan' as finding_source
        FROM ports pt
        LEFT JOIN assets a ON a.id = pt.asset_id
        WHERE pt.is_open = true

        UNION ALL

        -- From credential_findings (brutus/hydra/medusa/ncrack, credential-check)
        --
        -- A working set of credentials is one of the highest-value results an
        -- engagement produces, and it was the only finding class not reachable
        -- from the findings list: it lived in its own table and had no branch
        -- here, so 7 valid credentials on a live engagement were invisible to
        -- every severity filter, export and report built on this endpoint.
        --
        -- valid_cred = true is the gate. Failed attempts are audit trail, not
        -- findings; surfacing them would bury the working credentials among the
        -- passwords that did NOT work.
        --
        -- The secret itself is NOT exposed here. credential_findings stores only
        -- a masked form (metadata.audit…password_masked) by design; the cleartext
        -- belongs in credential_vault behind its own access control. The evidence
        -- below is what an operator needs to act — which account, which service,
        -- proven working — without spraying passwords through every findings
        -- list, export and screenshot.
        SELECT
            cf.id::text,
            COALESCE(cf.source, 'credentials') as source,
            cf.asset_id::text,
            COALESCE(host(cf.ip)::text, host(a.ip)::text, '') as ip,
            a.hostname,
            cf.port,
            NULL::text as url,
            COALESCE(cf.severity, 'critical') as severity,
            'Valid credentials — ' || COALESCE(cf.username, '(unknown user)')
                || '@' || COALESCE(cf.protocol, 'service')
                || COALESCE(':' || cf.port::text, '') as title,
            'Authentication succeeded as user=' || COALESCE(cf.username, '?')
                || COALESCE(' auth_type=' || cf.auth_type, '')
                || COALESCE(' secret_type=' || cf.secret_type, '')
                || COALESCE(' proto=' || cf.protocol, '')
                || COALESCE(' [' || (cf.metadata->'audit'->>'summary') || ']', '')
                || ' — secret masked; see credential vault' as evidence,
            ARRAY[]::text[] as cve,
            -- CWE-798 Use of Hard-coded Credentials / CWE-521 Weak Password
            -- Requirements: the closest standard classification for a guessable
            -- or default account, so credential findings join CWE-filtered
            -- reporting instead of being uncategorised.
            ARRAY['CWE-521']::text[] as cwe,
            NULL::float as cvss,
            NULL::text as method,
            'Valid credentials were recovered for this service. Any account '
                || 'reachable with a guessed, default or reused password grants '
                || 'the access that account holds.' as description,
            'Rotate the credential, disable the account if unused, and enforce '
                || 'a password policy plus lockout on this service.' as solution,
            NULL::text as reference,
            'confirmed' as confidence,
            ARRAY[]::text[] as tags,
            cf.created_at,
            NULL::text as workflow_status,
            NULL::text as assigned_to,
            NULL::text as verified_by,
            cf.last_verified_at as verified_at,
            NULL::text as tester_notes,
            NULL::text as original_severity,
            NULL::boolean as report_ready,
            cf.engagement_id::text,
            NULL::text as problem_id,
            1 as affects_hosts,
            'finding'::text as record_kind,
            'credential' as finding_source
        FROM credential_findings cf
        LEFT JOIN assets a ON a.id = cf.asset_id
        WHERE cf.valid_cred = true

        UNION ALL

        -- Service-enum recon (email + DNS infrastructure: spf/dmarc/dkim,
        -- nameservers, dns_records). ONLY these finding sources — the bulk
        -- subdomain/dnsx enumeration stays in the Recon Explorer, not here.
        SELECT
            rf.id::text,
            rf.source,
            rf.asset_id::text,
            COALESCE(host(a.ip)::text, rf.target, '') as ip,
            COALESCE(a.hostname, rf.target) as hostname,
            NULL::int as port,
            NULL::text as url,
            rf.severity,
            rf.finding_type as title,
            LEFT(rf.data::text, 500) as evidence,
            ARRAY[]::text[] as cve,
            ARRAY[]::text[] as cwe,
            NULL::numeric as cvss,
            NULL::text as method,
            NULL::text as description,
            NULL::text as solution,
            NULL::text as reference,
            NULL::text as confidence,
            COALESCE(rf.tags, ARRAY[]::text[]) as tags,
            rf.created_at,
            NULL::text as workflow_status,
            NULL::text as assigned_to,
            NULL::text as verified_by,
            NULL::timestamptz as verified_at,
            NULL::text as tester_notes,
            NULL::text as original_severity,
            NULL::boolean as report_ready,
            rf.engagement_id::text,
            rf.fingerprint as problem_id,
            1 as affects_hosts,
            'finding'::text as record_kind,
            'recon' as finding_source
        FROM recon_findings rf
        LEFT JOIN assets a ON a.id = rf.asset_id
        WHERE rf.source IN ('email-enum', 'dns-enum')
    )
    SELECT * FROM unified
    """

    # Build WHERE clause with psycopg2 %s placeholders
    where_clauses_pg = []
    params_pg: List[Any] = []

    # Scope to the active engagement (explicit param or X-Engagement-Id header).
    # Every UNION arm selects engagement_id, so filtering the combined result
    # scopes findings across all source tables at once — without this the
    # Findings Explorer showed every engagement's findings.
    _eid = _validate_engagement_uuid(_resolve_engagement_id(engagement_id))
    if _eid:
        # The UNION selects engagement_id::text on every arm, so compare as text
        # (a bare `= %s::uuid` raises "operator does not exist: text = uuid").
        where_clauses_pg.append("engagement_id = %s")
        params_pg.append(_eid)

    if severity:
        where_clauses_pg.append("severity = ANY(%s::text[])")
        params_pg.append(list(severity))

    if source:
        where_clauses_pg.append("source = ANY(%s::text[])")
        params_pg.append(list(source))

    if ip:
        where_clauses_pg.append("ip = %s")
        params_pg.append(ip)

    if asset_id:
        where_clauses_pg.append("asset_id = %s")
        params_pg.append(asset_id)

    if port:
        where_clauses_pg.append("port = %s")
        params_pg.append(port)

    # Scope is derived, not declared: "shared" means the same problem was
    # actually observed on more than one virtual host of a machine. Deciding it
    # from the data avoids guessing whether a finding is server- or app-level.
    # Named problem_scope, not scope: in this codebase "scope" already means the
    # ENGAGEMENT scope — the named set of authorised targets that gates dispatch.
    # Reusing the word for something else in the same response would be a bad
    # collision in a tool where scope is a security boundary.
    if problem_scope:
        wanted = problem_scope.strip().lower()
        if wanted in ("shared", "infrastructure", "infra"):
            where_clauses_pg.append("affects_hosts > 1")
        elif wanted in ("single", "application", "app"):
            where_clauses_pg.append("affects_hosts <= 1")
        elif wanted not in ("all", ""):
            raise HTTPException(
                400,
                f"Unknown problem_scope {problem_scope!r}. "
                "Use 'shared', 'single' or 'all'.")

    if problem_id:
        where_clauses_pg.append("problem_id = %s")
        params_pg.append(problem_id)

    # Crawl inventory is excluded by DEFAULT. It is not deleted or moved —
    # /export/burp and /export/har read web_findings by URL to build the Burp
    # sitemap and the HAR file, so those rows are the crawl surface that makes
    # the tool's primary deliverable work. They just are not findings.
    if not include_inventory:
        where_clauses_pg.append("record_kind = 'finding'")

    if cve:
        where_clauses_pg.append("EXISTS (SELECT 1 FROM unnest(cve) c WHERE c ILIKE %s)")
        params_pg.append(f"%{cve}%")

    if cwe:
        where_clauses_pg.append("EXISTS (SELECT 1 FROM unnest(cwe) c WHERE c ILIKE %s)")
        params_pg.append(f"%{cwe}%")

    if search:
        where_clauses_pg.append(
            "(title ILIKE %s OR evidence ILIKE %s"
            " OR description ILIKE %s OR url ILIKE %s"
            " OR solution ILIKE %s OR reference ILIKE %s)"
        )
        for _ in range(6):
            params_pg.append(f"%{search}%")

    if date_from:
        where_clauses_pg.append("created_at >= %s")
        params_pg.append(date_from)

    if date_to:
        where_clauses_pg.append("created_at <= %s")
        params_pg.append(date_to)

    if workflow_status:
        where_clauses_pg.append("workflow_status = ANY(%s::text[])")
        params_pg.append(list(workflow_status))

    if engagement_id:
        # Match findings directly linked to the engagement OR whose IP is in its
        # scope.
        #
        # The scope side resolves scope_targets by its OWN engagement_id, which is
        # reliably populated. It previously joined by NAME —
        # scope_targets.name = engagements.scope_name — and that silently matched
        # nothing whenever the two strings disagreed: on a live engagement,
        # `engagements.scope_name` was EMPTY while its scope_targets rows were
        # named 'msf'. The subquery returned no targets, so the filter degraded to
        # `engagement_id = %s` alone, and every finding whose row had a NULL
        # engagement_id vanished from the engagement view — 49 nmap and 28,232
        # zap findings on that engagement, with no error to explain it. Only
        # sources that stamp engagement_id (e.g. nuclei) appeared, which made it
        # look like a per-tool ingestion problem rather than a filter bug.
        #
        # The name-based lookup is kept as a fallback so rows predating
        # scope_targets.engagement_id still resolve.
        where_clauses_pg.append(
            "(engagement_id = %s OR ip IN ("
            "  SELECT target FROM scope_targets"
            "   WHERE target_type = 'ip' AND target <> ''"
            "     AND (engagement_id = %s::uuid"
            "          OR name = NULLIF((SELECT scope_name FROM engagements"
            "                             WHERE id = %s::uuid), ''))"
            "))"
        )
        params_pg.append(engagement_id)
        params_pg.append(engagement_id)
        params_pg.append(engagement_id)

    if tags:
        where_clauses_pg.append("tags @> %s::text[]")
        params_pg.append(tags)

    where_sql = ""
    if where_clauses_pg:
        where_sql = "WHERE " + " AND ".join(where_clauses_pg)

    # Main query for results — order by severity rank then date
    # One scale for the whole stack: public.severity_rank() mirrors
    # etl/severity.py and the frontend's SEVERITY_RANK, pinned by
    # tests/test_severity_scale.py. DESC because higher = more severe, which also
    # puts unknown values LAST — the hand-written ascending CASE this replaces
    # used ELSE 7 to fake that, and got it wrong if anyone flipped the direction.
    severity_order = "public.severity_rank(severity) DESC"
    if collapse_problems:
        # One row per underlying problem. DISTINCT ON rather than a window
        # function so no helper column leaks into the result set.
        #
        # PARTITION/DISTINCT key is COALESCE(problem_id, id): partitioning on
        # problem_id alone would treat every ungroupable row (NULL) as ONE
        # group and collapse thousands of unrelated findings into a single row.
        main_sql = f"""
        SELECT * FROM (
            SELECT DISTINCT ON (COALESCE(problem_id, id)) *
            FROM (
                {base_query}
                {where_sql}
            ) filtered
            ORDER BY COALESCE(problem_id, id), {severity_order}, created_at DESC
        ) collapsed
        ORDER BY {severity_order}, created_at DESC
        LIMIT %s OFFSET %s
        """
    else:
        main_sql = f"""
        {base_query}
        {where_sql}
        ORDER BY {severity_order}, created_at DESC
        LIMIT %s OFFSET %s
        """
    params_pg.extend([limit, offset])

    # Count query
    count_sql = f"""
    {base_query}
    {where_sql}
    """

    # Aggregation query
    agg_sql = f"""
    WITH unified AS (
        SELECT
            CASE
                WHEN v.metadata->>'source' LIKE 'nuclei:%%' THEN 'nuclei'
                WHEN v.metadata->>'tool' IS NOT NULL THEN v.metadata->>'tool'
                WHEN v.script LIKE '%%:%%' THEN split_part(v.script, ':', 1)
                ELSE 'nmap'
            END as source,
            v.severity
        FROM vulns v
        UNION ALL
        -- Same inventory rule as the main query. If the global facet counted
        -- crawl inventory while the default view excluded it, the UI would
        -- render a `katana` chip with 746 that returns nothing when clicked.
        SELECT wf.source, wf.severity FROM web_findings wf
         WHERE (%(include_inventory)s OR wf.record_kind = 'finding')
        UNION ALL
        SELECT 'playwright' as source, pf.severity FROM playwright_findings pf
        UNION ALL
        -- recon_findings was MISSING from this union while the main query
        -- included it, so `dns-enum` (5) and `email-enum` (6) rows counted
        -- toward `total` but appeared in NO global facet. The frontend builds
        -- its source filter chips from by_source precisely so a chip never
        -- vanishes as you narrow the filter — so those 11 findings were listed
        -- but could not be filtered to, ever. Same WHERE as the main query's
        -- recon branch; if that gate changes, change it here too.
        SELECT rf.source, rf.severity FROM recon_findings rf
         WHERE rf.source IN ('email-enum', 'dns-enum')
        UNION ALL
        -- Mirrors the main query's ports branch, which is now inventory. Without
        -- the same gate the facet would render a `portscan` chip with 40 that
        -- returns nothing when clicked -- exactly the katana bug this comment
        -- block warns about two branches up.
        SELECT 'portscan' as source, 'info'::text as severity FROM ports
         WHERE is_open = true AND %(include_inventory)s
        UNION ALL
        -- Must mirror the credential branch in the main query above, including
        -- the valid_cred gate. If these two drift, the severity facet counts
        -- disagree with the rows actually returned.
        SELECT COALESCE(cf.source, 'credentials') as source,
               COALESCE(cf.severity, 'critical') as severity
          FROM credential_findings cf WHERE cf.valid_cred = true
    )
    SELECT
        COALESCE(severity, 'info') as severity,
        source,
        COUNT(*) as cnt
    FROM unified
    GROUP BY COALESCE(severity, 'info'), source
    """

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # Get results
        cur.execute(main_sql, params_pg)
        rows = cur.fetchall()

        # Get total count (without limit/offset)
        count_params = params_pg[:-2]  # Remove limit and offset
        cur.execute(f"SELECT COUNT(*) as total FROM ({count_sql}) sub", count_params)
        total = cur.fetchone()["total"]

        # Deduped counts over the same filtered set. `total` counts ROWS, which
        # double-counts a server-level problem once per virtual host — fine for
        # pagination, misleading as a headline. COALESCE(problem_id, id) keeps
        # every ungroupable row distinct; grouping on problem_id alone would
        # fold all NULLs into one.
        cur.execute(f"""
            SELECT
                COUNT(DISTINCT COALESCE(problem_id, id))                     AS distinct_problems,
                COUNT(DISTINCT problem_id) FILTER (WHERE affects_hosts > 1)  AS shared_problems
            FROM ({count_sql}) sub
        """, count_params)
        dedup_row = cur.fetchone()
        distinct_problems = dedup_row["distinct_problems"] or 0
        shared_problems = dedup_row["shared_problems"] or 0

        # Severity facets over the collapsed set, so a chart shows one bar per
        # problem rather than one per affected vhost.
        cur.execute(f"""
            SELECT severity, source, COUNT(*) AS cnt FROM (
                SELECT DISTINCT ON (COALESCE(problem_id, id))
                       COALESCE(severity, 'info') AS severity,
                       COALESCE(source, 'unknown') AS source
                FROM ({count_sql}) sub
                ORDER BY COALESCE(problem_id, id)
            ) collapsed
            GROUP BY severity, source
        """, count_params)
        problems_by_severity: Dict[str, int] = {}
        problems_by_source: Dict[str, int] = {}
        for r in cur.fetchall():
            problems_by_severity[r["severity"]] = problems_by_severity.get(r["severity"], 0) + r["cnt"]
            problems_by_source[r["source"]] = problems_by_source.get(r["source"], 0) + r["cnt"]

        # Get aggregations
        cur.execute(agg_sql, {"include_inventory": bool(include_inventory)})
        agg_rows = cur.fetchall()

    # Process aggregations
    by_severity: Dict[str, int] = {}
    by_source: Dict[str, int] = {}
    for row in agg_rows:
        sev = row["severity"] or "unknown"
        src = row["source"] or "unknown"
        cnt = row["cnt"]
        by_severity[sev] = by_severity.get(sev, 0) + cnt
        by_source[src] = by_source.get(src, 0) + cnt

    # Convert rows to UnifiedFinding objects
    findings = []
    for row in rows:
        findings.append(UnifiedFinding(
            id=row["id"],
            problem_id=row.get("problem_id"),
            affects_hosts=row.get("affects_hosts") or 1,
            source=row["source"],
            asset_id=row["asset_id"],
            ip=row["ip"],
            hostname=row.get("hostname"),
            port=row["port"],
            url=row["url"],
            severity=row["severity"],
            title=row["title"] or "Unknown",
            evidence=row["evidence"],
            cve=row["cve"] or [],
            cwe=row["cwe"] or [],
            cvss=row["cvss"],
            method=row.get("method"),
            description=row.get("description"),
            solution=row.get("solution"),
            reference=row.get("reference"),
            confidence=row.get("confidence"),
            tags=row.get("tags") or [],
            created_at=row["created_at"]
        ))

    return UnifiedSearchResponse(
        findings=findings,
        total=total,
        aggregations=SearchAggregations(
            by_severity=by_severity,
            by_source=by_source,
            problems_by_severity=problems_by_severity,
            problems_by_source=problems_by_source,
            distinct_problems=distinct_problems,
            shared_problems=shared_problems
        )
    )


class NoteRequest(BaseModel):
    source: str
    url: str
    name: str
    severity: str = "info"
    evidence: Optional[str] = None


@app.post("/findings/note", tags=["Findings"])
def create_finding_note(note: NoteRequest, authorized: bool = Depends(auth)):
    """
    Insert an informational finding into web_findings.

    Used to log scan executions so they appear in unified findings search and reports.
    """
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            """INSERT INTO web_findings (url, source, name, severity, evidence, issue_type)
               VALUES (%s, %s, %s, %s, %s, 'scan_execution')
               RETURNING id""",
            (note.url, note.source, note.name, note.severity, note.evidence),
        )
        row = cur.fetchone()
        # The web_findings dedup trigger skips the INSERT when this finding
        # already exists (it advances last_seen instead), and a skipped insert
        # returns NO row — `row["id"]` would raise TypeError on a perfectly
        # normal re-scan. Fall back to looking up the row it merged into so the
        # caller still gets the id of the finding it just recorded.
        if row is None:
            cur.execute(
                """SELECT id FROM web_findings
                    WHERE fingerprint = md5('web|' || rtrim(lower(btrim(%s)), '/')
                                             || '|' || lower(btrim(coalesce(%s, '')))
                                             || '|' || 'scan_execution')""",
                (note.url or "", note.name),
            )
            row = cur.fetchone()
        conn.commit()
    return {"ok": True, "id": str(row["id"]) if row else None}


@app.get("/last-completed-scan")
def get_last_completed_scan(authorized: bool = Depends(auth)):
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # Query the most recent completed job
        cur.execute(
            "SELECT id, params, results, status FROM jobs WHERE status='completed' ORDER BY created_at DESC LIMIT 1"
        )
        row = cur.fetchone()

        if not row:
            raise HTTPException(status_code=404, detail="No completed scan found")

    return {
        "id": str(row["id"]),
        "params": row["params"],
        "results": row["results"],
        "status": row["status"]
    }


class CleanupResponse(BaseModel):
    """Response from cleanup operation"""
    web_findings_deleted: int = 0
    playwright_findings_deleted: int = 0
    playwright_scans_deleted: int = 0
    vulns_deleted: int = 0
    dry_run: bool = False
    message: str = ""


@app.post("/cleanup/findings", response_model=CleanupResponse, tags=["Cleanup"])
def cleanup_findings(
    sources: str = Query(
        default="all",
        description="Comma-separated sources to clean: 'all', 'web', 'playwright', 'vulns', or specific sources like 'zap,gobuster'"
    ),
    older_than_hours: Optional[int] = Query(
        default=None,
        ge=1,
        description="Only delete findings older than this many hours (optional)"
    ),
    dry_run: bool = Query(
        default=False,
        description="If true, show what would be deleted without actually deleting"
    ),
    authorized: bool = Depends(auth)
):
    """
    Delete web findings, playwright findings, and/or vulnerability records.

    Sources:
    - 'all': Delete from all tables (web_findings, playwright_findings, vulns)
    - 'web': Delete from web_findings only (includes zap, gobuster)
    - 'playwright': Delete from playwright_findings and playwright_scans
    - 'vulns': Delete from vulns table only
    - Specific sources: 'zap', 'gobuster', etc. (filters web_findings by source)

    Use dry_run=true to preview what would be deleted.
    """
    result = CleanupResponse(dry_run=dry_run)
    source_list = [s.strip().lower() for s in sources.split(',') if s.strip()]

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # Build time filter if specified
        time_filter = ""
        time_params = []
        if older_than_hours:
            time_filter = " AND created_at < now() - interval '%s hours'"
            time_params = [older_than_hours]

        # Determine what to clean
        clean_web = 'all' in source_list or 'web' in source_list
        clean_playwright = 'all' in source_list or 'playwright' in source_list
        clean_vulns = 'all' in source_list or 'vulns' in source_list

        # Check for specific web sources (zap, gobuster, etc.)
        specific_sources = [s for s in source_list if s not in ('all', 'web', 'playwright', 'vulns')]

        if dry_run:
            # Count what would be deleted
            if clean_web or specific_sources:
                if specific_sources:
                    placeholders = ','.join(['%s'] * len(specific_sources))
                    cur.execute(
                        f"SELECT COUNT(*) as cnt FROM web_findings WHERE source IN ({placeholders})" +
                        (time_filter if time_filter else ""),
                        specific_sources + time_params
                    )
                else:
                    cur.execute(
                        "SELECT COUNT(*) as cnt FROM web_findings WHERE 1=1" + time_filter,
                        time_params if time_params else None
                    )
                result.web_findings_deleted = cur.fetchone()['cnt']

            if clean_playwright:
                cur.execute(
                    "SELECT COUNT(*) as cnt FROM playwright_findings WHERE 1=1" + time_filter,
                    time_params if time_params else None
                )
                result.playwright_findings_deleted = cur.fetchone()['cnt']

                cur.execute(
                    "SELECT COUNT(*) as cnt FROM playwright_scans WHERE 1=1" + time_filter,
                    time_params if time_params else None
                )
                result.playwright_scans_deleted = cur.fetchone()['cnt']

            if clean_vulns:
                cur.execute(
                    "SELECT COUNT(*) as cnt FROM vulns WHERE 1=1" + time_filter,
                    time_params if time_params else None
                )
                result.vulns_deleted = cur.fetchone()['cnt']

            total = (result.web_findings_deleted + result.playwright_findings_deleted +
                     result.playwright_scans_deleted + result.vulns_deleted)
            result.message = f"Dry run: would delete {total} total records"

        else:
            # Actually delete
            if clean_web or specific_sources:
                if specific_sources:
                    placeholders = ','.join(['%s'] * len(specific_sources))
                    cur.execute(
                        f"DELETE FROM web_findings WHERE source IN ({placeholders})" +
                        (time_filter if time_filter else ""),
                        specific_sources + time_params
                    )
                else:
                    cur.execute(
                        "DELETE FROM web_findings WHERE 1=1" + time_filter,
                        time_params if time_params else None
                    )
                result.web_findings_deleted = cur.rowcount

            if clean_playwright:
                # Delete findings first (FK constraint)
                cur.execute(
                    "DELETE FROM playwright_findings WHERE 1=1" + time_filter,
                    time_params if time_params else None
                )
                result.playwright_findings_deleted = cur.rowcount

                # Then delete scans
                cur.execute(
                    "DELETE FROM playwright_scans WHERE 1=1" + time_filter,
                    time_params if time_params else None
                )
                result.playwright_scans_deleted = cur.rowcount

            if clean_vulns:
                cur.execute(
                    "DELETE FROM vulns WHERE 1=1" + time_filter,
                    time_params if time_params else None
                )
                result.vulns_deleted = cur.rowcount

            conn.commit()

            total = (result.web_findings_deleted + result.playwright_findings_deleted +
                     result.playwright_scans_deleted + result.vulns_deleted)
            result.message = f"Deleted {total} total records"

    return result


# --- RAG/Exploit Search Proxy ---
# Proxy requests to the scan_recommender service which has ExploitDB access

SCAN_RECOMMENDER_URL = os.environ.get("SCAN_RECOMMENDER_URL", "https://scan-recommender:8013")
EXPLOIT_RUNNER_URL = os.environ.get("EXPLOIT_RUNNER_URL", "https://exploit-runner:8017")


class EnhancedExploitResult(BaseModel):
    """Individual exploit search result."""
    edb_id: Optional[int] = None
    module_path: Optional[str] = None
    title: str
    source: str  # "exploitdb" or "metasploit"
    confidence: float
    cve_match: bool = False
    service_match: bool = False
    version_match: bool = False
    snippet: Optional[str] = None
    path: Optional[str] = None
    platform: Optional[str] = None
    exploit_type: Optional[str] = None


class EnhancedExploitSearchResponse(BaseModel):
    """Response from enhanced exploit search."""
    query: Dict[str, Any]
    exploitdb: List[EnhancedExploitResult]
    metasploit: List[EnhancedExploitResult]
    total_matches: int
    exploitdb_count: int = 0
    metasploit_count: int = 0


@app.get("/rag/search/enhanced", response_model=EnhancedExploitSearchResponse, tags=["RAG/Exploits"])
def enhanced_exploit_search(
    cve: Optional[str] = Query(None, description="CVE ID to search for (e.g., CVE-2017-7494)"),
    service: Optional[str] = Query(None, description="Service name (e.g., samba, apache, openssh)"),
    version: Optional[str] = Query(None, description="Service version (e.g., 2.4.49, 7.4)"),
    port: Optional[int] = Query(None, description="Target port for context"),
    query: Optional[str] = Query(None, description="Additional search terms"),
    top_k: int = Query(10, ge=1, le=50, description="Max results per source"),
    min_confidence: float = Query(0.2, ge=0.0, le=1.0, description="Minimum confidence threshold"),
    authorized: bool = Depends(auth)
):
    """
    Search for exploits matching CVE, service, or version.

    Proxies to the scan_recommender service which has access to:
    - ExploitDB database (CSV and embedded vectors)
    - Metasploit module cache

    Returns matching exploits with confidence scores based on:
    - CVE exact match: +0.4
    - Service name match: +0.25
    - Version match: +0.2
    - Verified exploit: +0.05

    Used by ETL parsers to correlate findings with known exploits
    and trigger finding_exploitable webhooks.
    """
    try:
        # Build query params
        params = {}
        if cve:
            params["cve"] = cve
        if service:
            params["service"] = service
        if version:
            params["version"] = version
        if port:
            params["port"] = port
        if query:
            params["query"] = query
        params["top_k"] = top_k
        params["min_confidence"] = min_confidence

        # Forward to scan_recommender
        resp = requests.get(
            f"{SCAN_RECOMMENDER_URL}/rag/search/enhanced",
            params=params,
            timeout=30,
            verify=False
        )

        if resp.status_code == 200:
            data = resp.json()
            # Add convenience counts
            data["exploitdb_count"] = len(data.get("exploitdb", []))
            data["metasploit_count"] = len(data.get("metasploit", []))
            return data
        else:
            # Return empty results on error (don't fail the calling ETL)
            return EnhancedExploitSearchResponse(
                query={"cve": cve, "service": service, "version": version, "port": port, "query": query},
                exploitdb=[],
                metasploit=[],
                total_matches=0,
                exploitdb_count=0,
                metasploit_count=0
            )

    except requests.RequestException as e:
        # Log but don't fail - return empty results
        import logging
        logging.getLogger("rag-api").warning(f"Exploit search proxy failed: {e}")
        return EnhancedExploitSearchResponse(
            query={"cve": cve, "service": service, "version": version, "port": port, "query": query},
            exploitdb=[],
            metasploit=[],
            total_matches=0,
            exploitdb_count=0,
            metasploit_count=0
        )


## --- Maintenance endpoints ---

@app.get("/maintenance/stats", tags=["Maintenance"])
def maintenance_stats(authorized: bool = Depends(auth)):
    """Return row counts for key database tables."""
    tables = [
        "assets", "ports", "scans", "findings", "web_findings", "vulns",
        "playwright_findings", "playwright_scans", "jobs", "tasks",
        "agent_sessions", "agent_messages", "scan_recommendations",
        "recon_findings", "credential_findings",
    ]
    counts = {}
    with get_db() as conn, conn.cursor() as cur:
        for t in tables:
            try:
                cur.execute(f"SELECT COUNT(*) FROM {t}")
                counts[t] = cur.fetchone()[0]
            except Exception:
                conn.rollback()
                counts[t] = -1
    return counts


@app.post("/cleanup/tool-executions", tags=["Maintenance"])
def cleanup_tool_executions(
    stale_after_hours: int = Query(default=6, ge=1),
    delete_older_than_days: Optional[int] = Query(default=None, ge=1),
    dry_run: bool = Query(default=False),
    authorized: bool = Depends(auth),
):
    """Reconcile stuck tool executions, and optionally prune old ones.

    Two jobs, because the table had neither:

    1. RECONCILE — a row is set to 'running' before the subprocess starts and
       updated when it finishes. If the process dies in between (restart, OOM,
       wedged tool) the row stays 'running' for ever. 41 such rows accumulated
       here, the oldest three days stale.

       The activity view already *displayed* rows like these as 'lost' via a
       CASE expression, but never wrote it back — so the view looked correct
       while every other reader, every count and every export still saw
       'running'. Cosmetic fixes in one query are worse than none: they hide the
       problem from the place most likely to reveal it.

    2. PRUNE — optional age-based delete, off unless delete_older_than_days is
       given. Execution rows carry command lines and output, so they are worth
       keeping longer than the default suggests.

    kali-listener also reaps at startup, which is stricter and immediate: after
    a restart nothing it launched can still be alive. This endpoint covers what
    that cannot — a tool that wedged while the service stayed up — and puts the
    table on the same scheduled cleanup footing as jobs, scans and artifacts.
    """
    with get_db() as conn, conn.cursor() as cur:
        cur.execute(
            """
            SELECT count(*) FROM tool_executions
             WHERE status IN ('running','pending')
               AND started_at < now() - (%s || ' hours')::interval
            """,
            [stale_after_hours],
        )
        stale = cur.fetchone()[0]
        if not dry_run and stale:
            cur.execute(
                """
                UPDATE tool_executions
                   SET status = 'failed',
                       error = coalesce(nullif(error, ''), '') ||
                               'reconciled: no completion recorded after %s hours',
                       completed_at = now()
                 WHERE status IN ('running','pending')
                   AND started_at < now() - (%s || ' hours')::interval
                """,
                [stale_after_hours, stale_after_hours],
            )

        deleted = 0
        if delete_older_than_days:
            cur.execute(
                "SELECT count(*) FROM tool_executions WHERE started_at < now() - (%s || ' days')::interval",
                [delete_older_than_days],
            )
            deleted = cur.fetchone()[0]
            if not dry_run and deleted:
                cur.execute(
                    "DELETE FROM tool_executions WHERE started_at < now() - (%s || ' days')::interval",
                    [delete_older_than_days],
                )

        cur.execute("SELECT status, count(*) FROM tool_executions GROUP BY 1")
        remaining = {r[0]: r[1] for r in cur.fetchall()}

    result = {
        "dry_run": dry_run,
        "stale_after_hours": stale_after_hours,
        "reconciled": 0 if dry_run else stale,
        "reconcilable": stale,
        "deleted": 0 if dry_run else deleted,
        "by_status": remaining,
    }
    if not dry_run and (stale or deleted):
        logger.info("tool_executions cleanup: reconciled=%s deleted=%s", stale, deleted)
        try:
            from webhooks import emit_webhook
            emit_webhook("tool_executions_cleaned", "maintenance", result)
        except Exception:
            pass
    return result


@app.post("/cleanup/artifacts", tags=["Maintenance"])
def cleanup_artifacts(
    older_than_days: int = Query(default=90, ge=1),
    keep_unprocessed: bool = Query(default=True),
    keep_with_findings: bool = Query(default=True),
    dry_run: bool = Query(default=False),
    authorized: bool = Depends(auth),
):
    """Prune old raw artifacts.

    raw_artifacts stores every byte a tool produced and had NO retention at all:
    it only ever grew. That matters more than usual here because the content is
    kept verbatim, so a large share of it is credential material (see
    Docs/RAW_ARTIFACTS.md) — old data is both storage cost and standing
    exposure.

    Two safety rails, both on by default:

    * keep_unprocessed — never delete an artifact still queued for LLM
      processing. Pruning by age alone would silently discard work the queue was
      about to do, and the loss would be invisible.
    * keep_with_findings — never delete an artifact a finding still points at.
      Those are the evidence behind a report; deleting them turns a cited
      finding into an unverifiable claim.

    Run dry_run=true first: this is not recoverable.
    """
    where = ["created_at < now() - (%s || ' days')::interval"]
    params: list = [older_than_days]
    if keep_unprocessed:
        where.append("llm_status <> 'pending'")
        where.append("llm_status <> 'processing'")
    if keep_with_findings:
        # A finding referencing this artifact makes it evidence, not scratch.
        where.append("""NOT EXISTS (
            SELECT 1 FROM public.scan_recommendations r
             WHERE r.extra->>'artifact_id' = raw_artifacts.id::text)""")
    clause = " AND ".join(where)

    with get_db() as conn, conn.cursor() as cur:
        cur.execute(f"SELECT count(*), coalesce(sum(byte_size),0) FROM raw_artifacts WHERE {clause}",
                    params)
        count, freed = cur.fetchone()
        if not dry_run and count:
            cur.execute(f"DELETE FROM raw_artifacts WHERE {clause}", params)
        cur.execute("SELECT count(*), coalesce(sum(byte_size),0) FROM raw_artifacts")
        remaining, remaining_bytes = cur.fetchone()

    # Report what the safety rails held back. keep_unprocessed and an unfed LLM
    # queue compound: every artifact stays 'pending' forever, so age-based
    # pruning matches nothing and the store grows without bound. Silence here
    # would read as "nothing was old enough".
    with get_db() as conn, conn.cursor() as cur:
        cur.execute("""
            SELECT count(*) FROM raw_artifacts
             WHERE created_at < now() - (%s || ' days')::interval
               AND llm_status IN ('pending','processing')
        """, [older_than_days])
        held_unprocessed = cur.fetchone()[0]

    result = {
        "dry_run": dry_run,
        "older_than_days": older_than_days,
        "held_back_unprocessed": held_unprocessed,
        "kept_unprocessed": keep_unprocessed,
        "kept_with_findings": keep_with_findings,
        "artifacts_deleted": 0 if dry_run else count,
        "artifacts_matching": count,
        "bytes_freed": 0 if dry_run else int(freed or 0),
        "remaining": remaining,
        "remaining_bytes": int(remaining_bytes or 0),
    }
    if keep_unprocessed and held_unprocessed:
        result["note"] = (
            f"{held_unprocessed} artifact(s) old enough to prune were kept because "
            f"they are still queued for LLM processing. If nothing is consuming "
            f"/artifacts/claim, they will never age out — run a consumer, or "
            f"prune with keep_unprocessed=false once you accept losing that work.")
    if not dry_run and count:
        logger.info("pruned %d raw artifact(s), freed %d bytes", count, freed or 0)
        try:
            from webhooks import emit_webhook
            emit_webhook("artifacts_pruned", "maintenance", result)
        except Exception:
            pass
    return result


@app.post("/cleanup/jobs", tags=["Maintenance"])
def cleanup_jobs(
    older_than_hours: Optional[int] = Query(default=None, ge=1),
    dry_run: bool = Query(default=False),
    authorized: bool = Depends(auth),
):
    """Delete finished/failed/canceled jobs and their tasks."""
    time_filter = ""
    time_params: list = []
    if older_than_hours:
        time_filter = " AND j.finished_at < now() - interval '%s hours'"
        time_params = [older_than_hours]

    with get_db() as conn, conn.cursor() as cur:
        count_sql = (
            "SELECT COUNT(*) FROM jobs j WHERE j.status IN ('finished','failed','canceled')"
            + time_filter
        )
        cur.execute(count_sql, time_params or None)
        job_count = cur.fetchone()[0]

        task_sql = (
            "SELECT COUNT(*) FROM tasks t JOIN jobs j ON t.job_id = j.id"
            " WHERE j.status IN ('finished','failed','canceled')" + time_filter
        )
        cur.execute(task_sql, time_params or None)
        task_count = cur.fetchone()[0]

        if dry_run:
            return {"dry_run": True, "jobs": job_count, "tasks": task_count}

        # tasks first (FK), then jobs
        del_tasks = (
            "DELETE FROM tasks t USING jobs j WHERE t.job_id = j.id"
            " AND j.status IN ('finished','failed','canceled')" + time_filter
        )
        cur.execute(del_tasks, time_params or None)
        tasks_deleted = cur.rowcount

        del_jobs = (
            "DELETE FROM jobs j WHERE j.status IN ('finished','failed','canceled')"
            + time_filter
        )
        cur.execute(del_jobs, time_params or None)
        jobs_deleted = cur.rowcount
        conn.commit()

    return {"dry_run": False, "jobs": jobs_deleted, "tasks": tasks_deleted}


@app.post("/cleanup/sessions", tags=["Maintenance"])
def cleanup_sessions(
    older_than_hours: Optional[int] = Query(default=None, ge=1),
    dry_run: bool = Query(default=False),
    authorized: bool = Depends(auth),
):
    """Delete agent sessions and their messages."""
    time_filter = ""
    time_params: list = []
    if older_than_hours:
        time_filter = " WHERE created_at < now() - interval '%s hours'"
        time_params = [older_than_hours]

    with get_db() as conn, conn.cursor() as cur:
        cur.execute("SELECT COUNT(*) FROM agent_sessions" + time_filter, time_params or None)
        session_count = cur.fetchone()[0]

        if older_than_hours:
            msg_filter = " WHERE session_id IN (SELECT id FROM agent_sessions" + time_filter + ")"
            cur.execute("SELECT COUNT(*) FROM agent_messages" + msg_filter, time_params or None)
        else:
            cur.execute("SELECT COUNT(*) FROM agent_messages")
        message_count = cur.fetchone()[0]

        if dry_run:
            return {"dry_run": True, "sessions": session_count, "messages": message_count}

        # messages first (FK), then sessions
        if older_than_hours:
            cur.execute("DELETE FROM agent_messages" + msg_filter, time_params or None)
        else:
            cur.execute("DELETE FROM agent_messages")
        messages_deleted = cur.rowcount

        cur.execute("DELETE FROM agent_sessions" + time_filter, time_params or None)
        sessions_deleted = cur.rowcount
        conn.commit()

    return {"dry_run": False, "sessions": sessions_deleted, "messages": messages_deleted}


@app.post("/cleanup/scans", tags=["Maintenance"])
def cleanup_scans(
    older_than_hours: Optional[int] = Query(default=None, ge=1),
    dry_run: bool = Query(default=False),
    authorized: bool = Depends(auth),
):
    """Delete completed scan records."""
    time_filter = ""
    time_params: list = []
    base_where = " WHERE finished_at IS NOT NULL"
    if older_than_hours:
        time_filter = " AND finished_at < now() - interval '%s hours'"
        time_params = [older_than_hours]

    with get_db() as conn, conn.cursor() as cur:
        cur.execute("SELECT COUNT(*) FROM scans" + base_where + time_filter, time_params or None)
        scan_count = cur.fetchone()[0]

        if dry_run:
            return {"dry_run": True, "scans": scan_count}

        cur.execute("DELETE FROM scans" + base_where + time_filter, time_params or None)
        scans_deleted = cur.rowcount
        conn.commit()

    return {"dry_run": False, "scans": scans_deleted}


@app.post("/cleanup/assets", tags=["Maintenance"])
def cleanup_assets(
    dry_run: bool = Query(default=False),
    authorized: bool = Depends(auth),
):
    """Delete ALL data — assets, findings, scans, jobs, sessions, recommendations."""
    # Order matters: delete dependent rows before parent rows
    tables = [
        "agent_messages",
        "agent_sessions",
        "scan_recommendations",
        "recon_findings",
        "credential_findings",
        "tasks",
        "jobs",
        "playwright_findings",
        "playwright_scans",
        "web_findings",
        "vulns",
        "findings",
        "scans",
        "ports",
        "assets",
    ]
    counts = {}
    with get_db() as conn, conn.cursor() as cur:
        for t in tables:
            try:
                cur.execute(f"SELECT COUNT(*) FROM {t}")
                counts[t] = cur.fetchone()[0]
            except Exception:
                conn.rollback()
                counts[t] = 0

        if dry_run:
            return {"dry_run": True, **counts}

        deleted = {}
        for t in tables:
            try:
                cur.execute(f"DELETE FROM {t}")
                deleted[t] = cur.rowcount
            except Exception:
                conn.rollback()
                deleted[t] = 0
        conn.commit()

    return {"dry_run": False, **deleted}


@app.post("/cleanup/recommendations", tags=["Maintenance"])
def cleanup_recommendations(
    older_than_hours: Optional[int] = Query(default=None, ge=1),
    status: Optional[str] = Query(default=None),
    dry_run: bool = Query(default=False),
    authorized: bool = Depends(auth),
):
    """Delete scan recommendations."""
    where_parts = ["1=1"]
    params: list = []
    if older_than_hours:
        where_parts.append("created_at < now() - interval '%s hours'")
        params.append(older_than_hours)
    if status:
        where_parts.append("status = %s")
        params.append(status)

    where_sql = " WHERE " + " AND ".join(where_parts)

    with get_db() as conn, conn.cursor() as cur:
        cur.execute("SELECT COUNT(*) FROM scan_recommendations" + where_sql, params or None)
        rec_count = cur.fetchone()[0]

        if dry_run:
            return {"dry_run": True, "recommendations": rec_count}

        cur.execute("DELETE FROM scan_recommendations" + where_sql, params or None)
        recs_deleted = cur.rowcount
        conn.commit()

    return {"dry_run": False, "recommendations": recs_deleted}


@app.post("/recommendations/generate", tags=["Recommendations"])
def generate_recommendations(
    ip: Optional[str] = Query(default=None),
    authorized: bool = Depends(auth),
):
    """Generate scan recommendations for currently-detected open ports that
    don't have one yet — with NO time window.

    The reactive ingest path (`_trigger_recommendations_for`) only generates
    recs for ports touched in the last 10 minutes, so a target scanned earlier
    shows an empty Recommendations page ("run a port-discovery scan"). This
    endpoint lets the operator (re)populate recommendations on demand for all
    detected ports, so suggested scans can then be dispatched against them.

    Runs synchronously (one local-LLM call per port) and returns the count.
    Optionally scope to a single `ip`.
    """
    rows = _select_open_ports_without_recs(window_minutes=None, ip=ip)
    # Runs in a request scope, so _outgoing_runner_headers() resolves the
    # engagement contextvar set by middleware.
    generated = _dispatch_recommender_for_ports(rows)

    try:
        from webhooks import emit_webhook
        emit_webhook("recommendations_generated", "manual", {
            "source": "manual",
            "ip": ip,
            "ports_considered": len(rows),
            "dispatched": generated,
        })
    except Exception:
        pass

    return {"ok": True, "ports_considered": len(rows), "generated": generated}


