# ─── Exploit Store ────────────────────────────────────────────────────────────
# A first-class, editable library of PoCs/exploits. A converged PoC-builder result is
# saved here automatically; operators can also add/edit entries by hand. For WEB findings
# each entry carries BOTH a portable Python script AND a Burp-ready raw HTTP request
# (generated from the PoC command by common/exploit_artifacts). Entries are downloadable
# and can be pushed to an SSH remote node for execution there. Bonus provenance: the LLM
# that produced it and the build timestamp are stored per entry.

def _ensure_exploit_store():
    with get_db() as conn, conn.cursor() as cur:
        cur.execute("""CREATE TABLE IF NOT EXISTS public.exploit_store (
            id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
            name text NOT NULL, cve text, kind text NOT NULL DEFAULT 'cve_poc',
            target_host text, target_port integer, product text, version text,
            command text, assertion jsonb, python_code text, http_request text,
            rationale text, verified boolean DEFAULT false, source text DEFAULT 'exploit_store',
            security_test_id uuid, poc_log_path text, llm_model text, built_at timestamptz,
            engagement_id uuid, metadata jsonb DEFAULT '{}'::jsonb, created_by text,
            created_at timestamptz NOT NULL DEFAULT now(),
            updated_at timestamptz NOT NULL DEFAULT now())""")
        cur.execute("""CREATE TABLE IF NOT EXISTS public.exploit_store_versions (
            id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
            exploit_id uuid NOT NULL REFERENCES public.exploit_store(id) ON DELETE CASCADE,
            version integer NOT NULL, label text, name text, command text, assertion jsonb,
            python_code text, http_request text, rationale text, verified boolean DEFAULT false,
            llm_model text, metadata jsonb DEFAULT '{}'::jsonb, created_by text,
            created_at timestamptz NOT NULL DEFAULT now())""")
        cur.execute("""CREATE UNIQUE INDEX IF NOT EXISTS ux_exploit_versions_num
                       ON public.exploit_store_versions(exploit_id, version)""")
        conn.commit()


def _snapshot_exploit_version(cur, row, label, created_by="operator"):
    """Insert a snapshot of the entry's editable fields as the next version number.
    `row` is a dict of the current exploit_store row. Cursor-agnostic (works with a
    RealDictCursor or a plain cursor). Returns (version, version_id)."""
    def _one(r):  # first value regardless of dict/tuple cursor
        if r is None:
            return None
        return next(iter(r.values())) if isinstance(r, dict) else r[0]
    cur.execute("SELECT COALESCE(MAX(version), 0) + 1 AS nextver FROM exploit_store_versions WHERE exploit_id = %s",
                (row["id"],))
    ver = _one(cur.fetchone())
    cur.execute("""INSERT INTO exploit_store_versions
        (exploit_id, version, label, name, command, assertion, python_code, http_request,
         rationale, verified, llm_model, metadata, created_by)
        VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING id""",
        (row["id"], ver, label, row.get("name"), row.get("command"),
         Json(row.get("assertion") or {}), row.get("python_code"), row.get("http_request"),
         row.get("rationale"), row.get("verified"), row.get("llm_model"),
         Json(row.get("metadata") or {}), created_by))
    return ver, str(_one(cur.fetchone()))


_EXPLOIT_TOOLS_CACHE = None


def _load_exploitation_tools():
    """Load knowledge/exploitation_tools.yaml (cached) — the vuln-class →
    specialist-tool map used to derive which tool can take a PoC further."""
    global _EXPLOIT_TOOLS_CACHE
    if _EXPLOIT_TOOLS_CACHE is not None:
        return _EXPLOIT_TOOLS_CACHE
    import yaml as _yaml
    _kd = os.environ.get("KNOWLEDGE_DIR", "/knowledge")
    for p in (os.path.join(_kd, "exploitation_tools.yaml"),
              os.path.join(os.path.dirname(__file__), "..", "knowledge", "exploitation_tools.yaml"),
              "knowledge/exploitation_tools.yaml"):
        try:
            with open(p, encoding="utf-8") as f:
                _EXPLOIT_TOOLS_CACHE = (_yaml.safe_load(f) or {}).get("tools") or []
                return _EXPLOIT_TOOLS_CACHE
        except Exception:  # noqa: BLE001
            continue
    _EXPLOIT_TOOLS_CACHE = []
    return _EXPLOIT_TOOLS_CACHE


_TOOL_GENERATORS = {"curl_to_sqlmap": "curl_to_sqlmap"}


def _derive_tools_for_poc(command, assertion=None, product=None, cve=""):
    """Once a PoC exists, DERIVE which specialist tool(s) can exploit it further.

    Operator ask: "once we have a poc it should then look up what tools could do
    this — it should derive sqlmap and create that call."

    Matches the PoC command/assertion against knowledge/exploitation_tools.yaml
    (vuln-class markers) and, where a generator exists, builds the ready-to-run
    tool invocation (sqlmap via common.exploit_artifacts.curl_to_sqlmap). Returns
    a list of {class, tool, binary, command, confirm_markers, test_args, notes}."""
    import re as _re
    from urllib.parse import unquote as _unq
    out = []
    if not command:
        return out
    blob = _unq(str(command)).lower()
    akeys = set((assertion or {}).keys())
    try:
        from common import exploit_artifacts as _ea
    except Exception:  # noqa: BLE001
        _ea = None
    for t in _load_exploitation_tools():
        m = t.get("match") or {}
        hit = any(s in blob for s in (m.get("payload_contains") or [])) or \
            any(k in akeys for k in (m.get("assertion_has") or []))
        if not hit:
            continue
        invocation = ""
        gen = t.get("generator") or ""
        if gen == "curl_to_sqlmap" and _ea is not None:
            try:
                block = _ea.curl_to_sqlmap(command, assertion=assertion, cve=cve)
                # extract the actual command line (drop the leading # comments)
                invocation = next((ln for ln in block.splitlines()
                                   if ln.strip().startswith(t.get("tool", ""))), "")
            except Exception as e:  # noqa: BLE001
                logging.debug("tool gen %s failed: %s", gen, e)
        out.append({
            "class": t.get("class"), "tool": t.get("tool"),
            "binary": t.get("binary") or t.get("tool"),
            "command": invocation,
            "confirm_markers": t.get("confirm_markers") or [],
            "test_args": t.get("test_args") or "",
            "notes": (t.get("notes") or "").strip(),
        })
    return out


def _run_tool_validation(ip, port, tool_entry, eid=None, timeout=150):
    """TEST a derived tool call: run it (scope-gated, bounded) on the runner and
    report whether the tool CONFIRMS the finding. Operator ask: "create that call
    and test it." Returns {ran, available, confirmed, seconds, command, output,
    refusal}."""
    import httpx as _hx, time as _t
    res = {"tool": tool_entry.get("tool"), "ran": False, "available": None,
           "confirmed": False, "seconds": 0.0, "command": "", "output": "",
           "refusal": None}
    cmd = (tool_entry.get("command") or "").strip()
    if not cmd:
        res["refusal"] = "no generator produced a command for this tool"
        return res
    # confirm-only test args (fast; just prove the tool reproduces the finding)
    test_cmd = cmd + ((" " + tool_entry["test_args"]) if tool_entry.get("test_args") else "")
    res["command"] = test_cmd
    # Scope gate — fail closed (CLAUDE.md: every path that sends traffic is gated).
    try:
        from etl.scope_gate import enforce_target_scope
        refusal = enforce_target_scope(str(ip), test_cmd, engagement_id=eid)
    except Exception as e:  # noqa: BLE001
        refusal = f"scope check error: {e}"
    if refusal:
        res["refusal"] = refusal
        return res
    listener = os.environ.get("KALI_LISTENER_URL", "https://kali-listener:8019")
    # Is the tool present on the runner?
    try:
        chk = _hx.post(f"{listener.rstrip('/')}/vectors/run",
                       json={"command": f"command -v {tool_entry.get('binary','')} || echo __MISSING__",
                             "target": str(ip), "port": port, "timeout": 15},
                       headers={"x-api-key": API_KEY}, verify=False, timeout=30)
        cd = chk.json() if chk.status_code < 400 else {}
        res["available"] = "__MISSING__" not in ((cd.get("output") or "") if isinstance(cd, dict) else "")
    except Exception:  # noqa: BLE001
        res["available"] = None
    if res["available"] is False:
        res["refusal"] = f"{tool_entry.get('binary')} not installed on the runner"
        return res
    _t0 = _t.time()
    try:
        lr = _hx.post(f"{listener.rstrip('/')}/vectors/run",
                      json={"command": test_cmd, "target": str(ip), "port": port,
                            "timeout": timeout},
                      headers={"x-api-key": API_KEY}, verify=False, timeout=timeout + 60)
        d = lr.json() if lr.status_code < 400 else {}
        out = (d.get("output", "") if isinstance(d, dict) else "") or lr.text
        res["ran"] = True
        res["output"] = (out or "")[-4000:]
        low = (out or "").lower()
        res["confirmed"] = any(mk.lower() in low for mk in (tool_entry.get("confirm_markers") or []))
    except Exception as e:  # noqa: BLE001
        res["refusal"] = f"tool run error: {e}"
    res["seconds"] = round(_t.time() - _t0, 1)
    return res


def _exploit_store_artifacts(kind, command, name, cve, rationale, assertion):
    """Generate {python_code, http_request, sqlmap} for a web/curl PoC. `sqlmap`
    is a ready-to-run sqlmap command for SQLi PoCs (empty for non-SQLi) so the
    operator can hand the finding to sqlmap for exploitation. Best-effort; never
    raises."""
    if not command:
        return {"python_code": None, "http_request": None, "sqlmap": ""}
    try:
        from common import exploit_artifacts as _ea
        art = _ea.web_exploit_artifacts(command, name=name or "poc", cve=cve or "",
                                        rationale=rationale or "", assertion=assertion or {})
        return {"python_code": art.get("python_code"),
                "http_request": art.get("http_request"),
                "sqlmap": art.get("sqlmap") or ""}
    except Exception as e:  # noqa: BLE001
        logging.debug("exploit artifact gen failed: %s", e)
        return {"python_code": None, "http_request": None, "sqlmap": ""}


def _sanitize_poc_auth(text):
    """Redact SESSION-SPECIFIC auth material from a PoC before it is persisted or
    reused. Two operator rules converge here: "auth info should never be hard
    coded" and "do not assume anything" — a stored PoC that embeds a live session
    cookie or CSRF token (a) leaks a secret in plaintext (CLAUDE.md: use
    <placeholder> markers, plaintext stays in origin tables) and (b) poisons the
    NEXT build, which copies the dead token and assumes it still works (exactly
    how a stale sid=a6094b4f… propagated identically across separate builds).

    Replaces the value with a typed placeholder the re-run path re-establishes
    live (session from auth_establish, sid via precondition enumeration +
    _enforce_resolved_object_ids). Shell variable references ($VAR) are LEFT
    ALONE — they resolve live at run time and are not literals. Returns the text."""
    import re as _re
    if not text or not isinstance(text, str):
        return text

    def _ph(placeholder):
        def _sub(m):
            val = m.group(2)
            if val.startswith("$"):   # live shell var — not a literal secret
                return m.group(0)
            return m.group(1) + placeholder
        return _sub

    t = text
    # session cookies anywhere (Cookie header or body/param)
    t = _re.sub(r'((?:zbx_session|PHPSESSID|JSESSIONID|sessionid|_session|'
                r'laravel_session|csrftoken|session)=)([A-Za-z0-9%+/._=-]+)',
                _ph("<SESSION>"), t, flags=_re.I)
    # Zabbix sid / anti-CSRF token param (16+ hex)
    t = _re.sub(r'(sid=)([A-Fa-f0-9]{16,})', _ph("<SID>"), t)
    # named CSRF token params + header
    t = _re.sub(r'((?:csrf[_-]?token|_csrf_token|authenticity_token)=)'
                r'([A-Za-z0-9._%-]+)', _ph("<CSRF>"), t, flags=_re.I)
    t = _re.sub(r'(X-CSRF-Token:\s*)([A-Za-z0-9._-]+)', _ph("<CSRF>"), t, flags=_re.I)
    # bearer / api-key headers
    t = _re.sub(r'(Authorization:\s*Bearer\s+)([A-Za-z0-9._-]+)', _ph("<TOKEN>"),
                t, flags=_re.I)
    t = _re.sub(r'(x-api-key:\s*)([A-Za-z0-9._-]+)', _ph("<APIKEY>"), t, flags=_re.I)
    return t


def _extract_credentials_from_poc_output(output, context=None):
    """Scan a verified PoC's output for extracted creds/tokens/IDs. Operator ask:
    "when we get creds and ids from a PoC exploit they should go into the
    credentials captured part of the assets." Catches common exfil shapes:
      - SQL dump rows: username|password or username,password_hash
      - WordPress user_pass hashes ($P$B...), MySQL hashes (*ABC...)
      - API tokens / bearer tokens / JWT (eyJ...)
      - sessionid / cookie values the exploit leaked
      - plaintext password: X / pass: X
      - canonical id leaks (admin_id, user_id = N)
    Returns list of {username, secret, secret_type, auth_type, source_hint}
    (any field may be None; caller sets ip/port/engagement)."""
    import re as _re
    out = output or ""
    found = []
    if not out:
        return found
    seen = set()

    def _add(username=None, secret=None, secret_type="password", auth_type="form", hint=""):
        key = (username or "", secret or "", secret_type)
        if key in seen or not (username or secret):
            return
        seen.add(key)
        found.append({"username": username, "secret_value": secret,
                      "secret_type": secret_type, "auth_type": auth_type,
                      "source_hint": hint[:200]})

    # SQL dump rows: look for lines with |-separated or ,-separated identity+hash/pw
    # Common WP output: admin|$P$B...   or   1|admin|$P$B...|admin@...
    for m in _re.finditer(r"(?m)^[^\n|,]*[\s|,](?P<u>[A-Za-z][\w.@-]{2,32})[\s|,]+(?P<s>\$[APS12][\$B][A-Za-z0-9./]{20,}|\*[A-F0-9]{40}|[a-f0-9]{32,128})", out):
        _add(username=m.group("u"), secret=m.group("s"),
             secret_type=("mysql_hash" if m.group("s").startswith("*") else "wp_hash"),
             hint="sql dump row")
    # JWT bearer tokens
    for m in _re.finditer(r"\b(eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{5,})\b", out):
        _add(secret=m.group(1), secret_type="jwt", auth_type="bearer",
             hint="JWT leaked in response")
    # Bearer tokens / api keys / X-API-Key
    for m in _re.finditer(r"(?:bearer\s+|authorization:\s*bearer\s+|api[_-]?key[:=]\s*|x-api-key:\s*)([A-Za-z0-9._-]{16,})", out, _re.I):
        _add(secret=m.group(1), secret_type="api_token", auth_type="bearer",
             hint="bearer/api key in response")
    # Session cookies the exploit leaked (very common SQLi output)
    for m in _re.finditer(r"\b(PHPSESSID|JSESSIONID|sessionid|session_id|_session|wordpress_logged_in[\w]*|zbx_session|csrftoken)\s*[:=]\s*([A-Za-z0-9%+/._=-]{10,})", out, _re.I):
        _add(secret=f"{m.group(1)}={m.group(2)}", secret_type="session_cookie",
             auth_type="cookie", hint="session cookie leaked")
    # Plain "password: X" / "pass: X" (quoted or not)
    for m in _re.finditer(r"(?i)(?:^|\s)(?:password|pwd|passwd)\s*[:=]\s*[\"']?([^\s\"'<>,;]{3,64})[\"']?", out):
        _add(secret=m.group(1), secret_type="password", auth_type="form",
             hint="plaintext password mention")
    # username: X paired with a nearby password/hash (same line, within 80 chars)
    for m in _re.finditer(r"(?i)(?:username|user|login|email)\s*[:=]\s*[\"']?([A-Za-z][\w.@+-]{2,64})[\"']?", out):
        u = m.group(1)
        # look for a secret in the next 120 chars
        tail = out[m.end():m.end()+120]
        s = _re.search(r"(?i)(?:password|pwd|passwd|hash|token)\s*[:=]\s*[\"']?([^\s\"'<>,;]{3,120})", tail)
        if s:
            _add(username=u, secret=s.group(1),
                 secret_type=("hash" if _re.match(r"[a-f0-9]{32,}", s.group(1)) else "password"),
                 hint="username+secret pair")
        else:
            _add(username=u, hint="username only (id leak)")
    return found


def _store_captured_credentials(ip, port, engagement_id, creds, cve=None,
                                 asset_id=None, source="cve_poc_builder"):
    """Insert each captured cred into credential_findings so it shows up in the
    asset's Credentials section + export + spray surfaces. Idempotent via the
    existing uq_credential_findings_identity index. Returns count inserted."""
    if not creds:
        return 0
    try:
        n = 0
        with get_db() as c, c.cursor() as cur:
            if not asset_id:
                try:
                    cur.execute("SELECT id FROM public.assets WHERE host(ip) = %s "
                                "AND (engagement_id = %s OR engagement_id IS NULL) "
                                "ORDER BY engagement_id NULLS LAST LIMIT 1",
                                (str(ip), engagement_id))
                    r = cur.fetchone()
                    if r:
                        asset_id = r[0]
                except Exception:  # noqa: BLE001
                    pass
            for cr in creds:
                try:
                    cur.execute("""
                        INSERT INTO public.credential_findings
                          (asset_id, ip, port, protocol, username, secret_value,
                           secret_type, valid_cred, auth_type, severity, source,
                           status, engagement_id, metadata)
                        VALUES (%s,%s,%s,'http',%s,%s,%s,true,%s,'high',%s,
                                'captured',%s,%s)
                        ON CONFLICT DO NOTHING
                    """, (asset_id, str(ip), int(port or 80),
                          cr.get("username") or "(unknown)",
                          cr.get("secret_value"), cr.get("secret_type") or "password",
                          cr.get("auth_type") or "form", source, engagement_id,
                          Json({"cve": cve, "source_hint": cr.get("source_hint"),
                                 "captured_at": "poc_build", "via": source})))
                    n += 1
                except Exception as e:  # noqa: BLE001
                    logging.debug("captured-cred insert failed: %s", e)
                    try: c.rollback()
                    except Exception: pass
            c.commit()
        return n
    except Exception as e:  # noqa: BLE001
        logging.debug("_store_captured_credentials failed: %s", e)
        return 0


def _save_exploit_store(name, cve=None, kind="cve_poc", target_host=None, target_port=None,
                        product=None, version=None, command=None, assertion=None,
                        rationale=None, verified=False, source="exploit_store",
                        security_test_id=None, poc_log_path=None, llm_model=None,
                        built_at=None, eid=None, metadata=None, created_by="operator",
                        python_code=None, http_request=None):
    """Insert one exploit-store entry. Auto-generates the Python + raw-HTTP artifacts from
    the command when they are not supplied (web/curl PoCs). Session-specific auth
    (cookies, sid/CSRF tokens, bearer keys) is redacted to placeholders so a
    stored PoC never embeds a live secret or poisons the next build with a stale
    token. Returns the new id (or None)."""
    _ensure_exploit_store()
    _sqlmap = ""
    if command:
        art = _exploit_store_artifacts(kind, command, name, cve, rationale, assertion)
        if python_code is None:
            python_code = art["python_code"]
        if http_request is None:
            http_request = art["http_request"]
        _sqlmap = art.get("sqlmap") or ""
    # Redact auth material from every stored form of the PoC.
    command = _sanitize_poc_auth(command)
    http_request = _sanitize_poc_auth(http_request)
    python_code = _sanitize_poc_auth(python_code)
    # sqlmap hand-off command (SQLi PoCs) — stored in metadata so the operator can
    # pivot the finding into sqlmap for data extraction. Redact auth here too.
    if _sqlmap:
        metadata = dict(metadata or {})
        metadata["sqlmap_command"] = _sanitize_poc_auth(_sqlmap)
    try:
        with get_db() as conn, conn.cursor() as cur:
            cur.execute("""INSERT INTO exploit_store
                (name, cve, kind, target_host, target_port, product, version, command, assertion,
                 python_code, http_request, rationale, verified, source, security_test_id,
                 poc_log_path, llm_model, built_at, engagement_id, metadata, created_by)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING id""",
                (name, cve, kind, target_host, target_port, product, version, command,
                 Json(assertion or {}), python_code, http_request, rationale, verified, source,
                 security_test_id, poc_log_path, llm_model, built_at, eid,
                 Json(metadata or {}), created_by))
            new_id = str(cur.fetchone()[0]); conn.commit()
        try:
            emit_webhook("exploit_store_saved", "exploit_store",
                         {"id": new_id, "cve": cve, "kind": kind, "verified": verified,
                          "target": target_host, "engagement_id": eid})
        except Exception:  # noqa: BLE001
            pass
        # (2) Dedicated webhook for the CVE PoC-builder path — carries the rich
        # context an operator needs to decide whether to tweak-and-rerun or move
        # on: iterations, verification method, confidence, canary, and the final
        # command (truncated). Generic exploit_store_saved stays for other kinds.
        if (kind == "cve_poc" or source == "cve_poc_builder") and cve:
            try:
                _md = metadata or {}
                _m = (_md.get("metrics") or {}) if isinstance(_md, dict) else {}
                emit_webhook("poc_build_completed", "cve_poc_builder", {
                    "id": new_id, "cve": cve, "verified": bool(verified),
                    "target": target_host, "port": target_port,
                    "engagement_id": eid,
                    "verification_method": _md.get("verification_method"),
                    "verification_confidence": _md.get("verification_confidence"),
                    "iterations": _m.get("iterations") or _m.get("target_runs"),
                    "skipped_syntax": _m.get("skipped_runs_bad_syntax"),
                    "skipped_refusal": _m.get("skipped_runs_llm_refusal"),
                    "model": llm_model,
                    "build_seconds": _m.get("build_seconds"),
                    "needs_tweaking": not bool(verified),  # the trigger for review
                    "command_preview": (command or "")[:280],
                })
            except Exception:  # noqa: BLE001
                pass
        # (3) Mirror the PoC build as a raw_artifacts row so it surfaces on the
        # Scan Results page alongside tool scans. tool="cve_poc_builder" is a
        # new category — distinguishable from nmap/nuclei/zap so operators can
        # filter it. content is the human-readable build summary (verdict,
        # metrics, final command, how to tweak) — not the raw trace, which stays
        # at poc_log_path for deep forensics.
        if (kind == "cve_poc" or source == "cve_poc_builder") and cve and command:
            try:
                _md = metadata or {}
                _m = (_md.get("metrics") or {}) if isinstance(_md, dict) else {}
                verdict = "VERIFIED" if verified else "FAILED — needs tweaking"
                vmethod = _md.get("verification_method") or "n/a"
                iters = _m.get("iterations") or _m.get("target_runs") or 0
                skipped = ((_m.get("skipped_runs_bad_syntax") or 0)
                           + (_m.get("skipped_runs_llm_refusal") or 0))
                canary = (assertion or {}).get("canary") if isinstance(assertion, dict) else None
                _artifact_content = (
                    f"CVE PoC Build: {cve}\n"
                    f"Target: {target_host}:{target_port}\n"
                    f"Verdict: {verdict}\n"
                    f"Verification method: {vmethod}\n"
                    f"Iterations: {iters} (skipped-pre-dispatch: {skipped})\n"
                    f"Canary: {canary or 'n/a'}\n"
                    f"Model: {llm_model or 'n/a'}\n"
                    f"Build seconds: {_m.get('build_seconds', 'n/a')}\n"
                    f"Exploit Store id: {new_id}\n"
                    f"PoC log: {poc_log_path or 'n/a'}\n"
                    f"\n--- Final command ---\n{command}\n"
                    f"\n--- Rationale ---\n{rationale or '(none)'}\n"
                    f"\n--- Tweak-and-rerun ---\n"
                    f"Open /exploits → Exploit Store → id {new_id} to edit the "
                    f"command/assertion and re-run against the target."
                )
                _store_artifact_row(
                    tool="cve_poc_builder",
                    content=_artifact_content,
                    command=(command or "")[:4000],
                    target=target_host,
                    port=target_port,
                    service=product or "web",
                    source="cve_poc_builder",
                    engagement_id=eid,
                    note=f"{cve} — {verdict}",
                    content_format="text",
                )
            except Exception as e:  # noqa: BLE001
                logging.debug("mirror cve_poc to raw_artifacts failed: %s", e)
        # Live-embed technique into RAG. Verified rows go to verified_exploit_technique
        # (positive signal); unverified go to failed_technique (negative signal — stops
        # the strategist from re-exploring shapes we've seen fail).
        try:
            if verified:
                _load_verified_technique_into_rag({
                    "verified": True, "target_host": target_host, "cve": cve,
                    "product": product, "version": version, "command": command,
                    "engagement_id": eid}, engagement_id=eid)
            else:
                _load_failed_technique_into_rag({
                    "verified": False, "target_host": target_host, "cve": cve,
                    "product": product, "version": version, "command": command,
                    "engagement_id": eid, "metadata": metadata or {}},
                    engagement_id=eid)
        except Exception:  # noqa: BLE001
            pass
        return new_id
    except Exception as e:  # noqa: BLE001
        logging.warning("save exploit_store failed: %s", e)
        return None


class ExploitStoreBody(BaseModel):
    name: str
    cve: Optional[str] = None
    kind: str = "manual"                 # cve_poc | web | manual
    target_host: Optional[str] = None
    target_port: Optional[int] = None
    product: Optional[str] = None
    version: Optional[str] = None
    command: Optional[str] = None
    assertion: Optional[dict] = None
    rationale: Optional[str] = None
    python_code: Optional[str] = None    # supply to override the generated one
    http_request: Optional[str] = None
    metadata: Optional[dict] = None


class ExploitStoreUpdateBody(BaseModel):
    name: Optional[str] = None
    cve: Optional[str] = None
    kind: Optional[str] = None
    target_host: Optional[str] = None
    target_port: Optional[int] = None
    product: Optional[str] = None
    version: Optional[str] = None
    command: Optional[str] = None
    assertion: Optional[dict] = None
    rationale: Optional[str] = None
    python_code: Optional[str] = None
    http_request: Optional[str] = None
    verified: Optional[bool] = None
    metadata: Optional[dict] = None
    regenerate: bool = False             # re-derive python/http from the (edited) command


class ExploitPushBody(BaseModel):
    node_id: str
    dest_dir: Optional[str] = None       # default ~ on the node
    filename: Optional[str] = None


@app.get("/exploit-store", tags=["Exploit Store"])
def list_exploit_store(cve: Optional[str] = None, kind: Optional[str] = None,
                       verified: Optional[bool] = None, limit: int = 200,
                       engagement_id: Optional[str] = None,
                       all_engagements: bool = False,
                       scope_only: bool = False,
                       authorized: bool = Depends(auth)):
    """List saved exploits (Exploit Store). Filter by cve/kind/verified.

    ENGAGEMENT FILTERING (enforced read-time, matches the project's engagement-
    isolation rule in CLAUDE.md):
      - Resolves the current engagement from X-Engagement-Id (what every page
        in the dashboard already sends via apiFetch).
      - Returns ONLY exploits where engagement_id matches, PLUS rows where
        engagement_id IS NULL (legacy/global rows that pre-date the attribution
        rule — shown in every engagement so they remain reachable).
      - `?engagement_id=` overrides the header.
      - `?all_engagements=true` disables engagement filtering (operator-explicit
        global view). Primarily for cross-engagement audits.

    SCOPE FILTERING:
      - `?scope_only=true` additionally restricts to exploits whose target_host
        matches a scope_targets row for the current engagement — i.e. only
        exploits targeting hosts the operator is authorized to touch right
        now. Keeps the Exploit Workbench honest about what's actionable."""
    _ensure_exploit_store()
    where, args = [], []
    if cve:
        where.append("es.cve = %s"); args.append(cve.strip().upper())
    if kind:
        where.append("es.kind = %s"); args.append(kind)
    if verified is not None:
        where.append("es.verified = %s"); args.append(verified)
    eid = _resolve_engagement_id(engagement_id)
    if eid and not all_engagements:
        where.append("(es.engagement_id = %s OR es.engagement_id IS NULL)")
        args.append(eid)
    if scope_only and eid:
        # Join to scope_targets for the current engagement — keep only rows
        # whose target_host matches an in-scope entry. Uses the host(ip) +
        # text equality the dispatch gate itself uses.
        where.append(
            "EXISTS (SELECT 1 FROM scope_targets st "
            "WHERE (st.engagement_id = %s OR st.engagement_id IS NULL) "
            "AND es.target_host = st.target)"
        )
        args.append(eid)
    sql = ("SELECT es.id, es.name, es.cve, es.kind, es.target_host, es.target_port, "
           "es.product, es.version, es.verified, es.source, es.security_test_id, "
           "es.llm_model, es.built_at, es.engagement_id, es.created_by, es.created_at, "
           "es.updated_at, "
           "(es.python_code IS NOT NULL) AS has_python, (es.http_request IS NOT NULL) AS has_http "
           "FROM exploit_store es")
    if where:
        sql += " WHERE " + " AND ".join(where)
    sql += " ORDER BY es.updated_at DESC LIMIT %s"; args.append(max(1, min(1000, limit)))
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(sql, args)
        return {"exploits": [dict(r) for r in cur.fetchall()],
                "engagement_id": eid, "all_engagements": bool(all_engagements),
                "scope_only": bool(scope_only)}


@app.get("/exploit-store/{exploit_id}", tags=["Exploit Store"])
def get_exploit_store(exploit_id: str, authorized: bool = Depends(auth)):
    """Full detail for one saved exploit (command, assertion, python, http request)."""
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        r = cur.fetchone()
        if not r:
            raise HTTPException(404, "exploit not found")
        return dict(r)


@app.get("/exploit-store/{exploit_id}/derivation-intel", tags=["Exploit Store"])
def get_derivation_intel(exploit_id: str, authorized: bool = Depends(auth)):
    """DERIVATION INTEL for manual review — surfaces the full agent-driven
    derivation evidence an operator needs to decide whether a PoC can be trusted:
    - the derived_cve_specs row (status, attempts, last_failure, hints)
    - confirmed_facts for this target+product (session_valid, injection_vector,
      action_permitted, object_ids, etc.)
    - captured_credentials filed from the PoC output
    - sqlmap hand-off (if generated)
    - key trace entries from the PoC build log (cve_spec_derivation,
      synth_seeded_from_confirmed, enforced_resolved_ids, enforced_request_contract,
      challenge_building_blocks, readiness_gate, access_enumeration, poc_captured_credentials)
    Operator: "surface this key info in the exploit workbench for manual review."
    """
    _ensure_exploit_store()
    _ensure_derived_cve_specs_table()
    _ensure_confirmed_facts_table()
    out = {"exploit_id": exploit_id,
           "derived_spec": None, "confirmed_facts": [], "captured_credentials": [],
           "sqlmap_command": None, "key_trace": [],
           "footholds": [], "intel_summary": None}
    try:
        with get_db() as c, c.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SELECT cve, target_host, target_port, product, metadata, "
                        "poc_log_path FROM exploit_store WHERE id=%s", (exploit_id,))
            row = cur.fetchone()
            if not row:
                raise HTTPException(404, "exploit not found")
            cve = row["cve"]
            target_host = row["target_host"]
            target_port = row["target_port"] or 80
            product = row["product"]
            tgt = f"{target_host}:{target_port}"
            meta = row.get("metadata") or {}
            if isinstance(meta, dict):
                out["sqlmap_command"] = meta.get("sqlmap_command")
            # 1. derived_cve_specs
            if cve:
                cur.execute("SELECT cve, product, version, vuln_class, spec, verified, "
                            "status, verify_method, verify_evidence, source, attempts, "
                            "last_failure, refine_hints, derived_at, last_verified "
                            "FROM derived_cve_specs WHERE cve=%s", (cve.upper(),))
                r = cur.fetchone()
                if r:
                    out["derived_spec"] = dict(r)
                    # Promote the standardized brief to a top-level field so the
                    # frontend intel-summary tab doesn't have to dig into
                    # spec._intel_summary. Lives in spec jsonb since
                    # 2026-10-04 — see _summarize_intel_for_exploit.
                    try:
                        _spec_obj = r.get("spec") or {}
                        if isinstance(_spec_obj, dict):
                            out["intel_summary"] = _spec_obj.get("_intel_summary")
                    except Exception:  # noqa: BLE001
                        pass
            # 2. confirmed_facts (product-scoped target facts)
            cur.execute("SELECT claim_type, claim_key, claim_value, status, "
                        "evidence, method, confidence, ttl_seconds, last_checked_at, "
                        "cve, product "
                        "FROM confirmed_facts "
                        "WHERE target=%s AND (product IS NULL OR lower(product)=lower(%s)) "
                        "ORDER BY last_checked_at DESC LIMIT 50",
                        (tgt, product or ""))
            out["confirmed_facts"] = [dict(r) for r in cur.fetchall()]
            # 3. captured credentials
            cur.execute("SELECT username, secret_value, secret_type, auth_type, "
                        "severity, metadata, created_at "
                        "FROM credential_findings "
                        "WHERE host(ip)=%s AND port=%s AND source='cve_poc_builder' "
                        "ORDER BY created_at DESC LIMIT 25",
                        (str(target_host), int(target_port)))
            out["captured_credentials"] = [dict(r) for r in cur.fetchall()]
            # 4. foothold (web_session access that was registered)
            cur.execute("SELECT kind, handle, transport, whoami, status, score, "
                        "last_seen_at, metadata "
                        "FROM obtained_access "
                        "WHERE host(ip)=%s AND port=%s "
                        "ORDER BY last_seen_at DESC LIMIT 10",
                        (str(target_host), int(target_port)))
            out["footholds"] = [dict(r) for r in cur.fetchall()]
    except HTTPException:
        raise
    except Exception as e:  # noqa: BLE001
        logging.debug("derivation-intel db read failed: %s", e)
    # 5. key trace entries from the PoC log file
    try:
        log_path = row.get("poc_log_path") if row else None
        if log_path and os.path.exists(log_path):
            import json as _j
            key_phases = {
                "cve_spec_derivation", "synth_seeded_from_confirmed",
                "enforced_resolved_ids", "enforced_request_contract",
                "challenge_building_blocks", "readiness_gate",
                "recon:access_enumeration", "poc_captured_credentials",
                "cve_spec_hit", "tool_handoff", "sqlmap_handoff",
            }
            trace = []
            with open(log_path, encoding="utf-8") as f:
                for line in f:
                    try:
                        rec = _j.loads(line)
                    except Exception:  # noqa: BLE001
                        continue
                    phase = rec.get("phase")
                    if phase in key_phases:
                        trace.append({"phase": phase, "ts": rec.get("ts"),
                                      "iteration": rec.get("iteration"),
                                      "response": (rec.get("response") or "")[:600],
                                      "extra": rec.get("extra") or {}})
                        if len(trace) >= 40:
                            break
            out["key_trace"] = trace
    except Exception as e:  # noqa: BLE001
        logging.debug("key_trace read failed: %s", e)
    return out


@app.post("/exploit-store", tags=["Exploit Store"])
def create_exploit_store(body: ExploitStoreBody, authorized: bool = Depends(auth)):
    """Save a new exploit. For web/curl PoCs, the Python script + Burp raw HTTP request
    are generated from `command` automatically (unless supplied)."""
    eid = _validate_engagement_uuid(_resolve_engagement_id())
    new_id = _save_exploit_store(
        name=body.name, cve=(body.cve or None), kind=body.kind, target_host=body.target_host,
        target_port=body.target_port, product=body.product, version=body.version,
        command=body.command, assertion=body.assertion, rationale=body.rationale,
        source="manual", eid=eid, metadata=body.metadata, python_code=body.python_code,
        http_request=body.http_request)
    if not new_id:
        raise HTTPException(500, "could not save exploit")
    return get_exploit_store(new_id, authorized)


@app.put("/exploit-store/{exploit_id}", tags=["Exploit Store"])
def update_exploit_store(exploit_id: str, body: ExploitStoreUpdateBody,
                         authorized: bool = Depends(auth)):
    """Edit a saved exploit. `regenerate=true` (or editing the command) re-derives the
    Python + HTTP artifacts from the command."""
    _ensure_exploit_store()
    fields, args = [], []
    data = body.dict(exclude_unset=True)
    data.pop("regenerate", None)
    # regenerate artifacts if asked, or if the command changed and artifacts weren't given
    regen = body.regenerate or ("command" in data and "python_code" not in data
                                and "http_request" not in data)
    for k in ("name", "cve", "kind", "target_host", "target_port", "product", "version",
              "command", "rationale", "python_code", "http_request", "verified"):
        if k in data:
            val = data[k]
            if k == "cve" and val:
                val = str(val).strip().upper()
            fields.append(f"{k} = %s"); args.append(val)
    if "assertion" in data:
        fields.append("assertion = %s"); args.append(Json(data["assertion"] or {}))
    if "metadata" in data:
        fields.append("metadata = %s"); args.append(Json(data["metadata"] or {}))
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        cur_row = cur.fetchone()
        if not cur_row:
            raise HTTPException(404, "exploit not found")
        if regen:
            cmd = data.get("command", cur_row["command"])
            nm = data.get("name", cur_row["name"])
            cve_v = (data.get("cve") or cur_row["cve"])
            rat = data.get("rationale", cur_row["rationale"])
            asrt = data.get("assertion", cur_row["assertion"])
            art = _exploit_store_artifacts(cur_row["kind"], cmd, nm, cve_v, rat, asrt)
            if art["python_code"] is not None:
                fields.append("python_code = %s"); args.append(art["python_code"])
            if art["http_request"] is not None:
                fields.append("http_request = %s"); args.append(art["http_request"])
        if not fields:
            return dict(cur_row)
        # Auto-snapshot the PRIOR state so every edit keeps a restorable version.
        try:
            _snapshot_exploit_version(cur, dict(cur_row), label="auto (pre-edit)",
                                      created_by=(body.dict().get("created_by") or "operator"))
        except Exception as e:  # noqa: BLE001
            logging.debug("version snapshot failed: %s", e)
        fields.append("updated_at = now()")
        args.append(exploit_id)
        cur.execute(f"UPDATE exploit_store SET {', '.join(fields)} WHERE id = %s RETURNING *", args)
        row = cur.fetchone(); conn.commit()
    try:
        emit_webhook("exploit_store_updated", "exploit_store", {"id": exploit_id})
    except Exception:  # noqa: BLE001
        pass
    return dict(row)


@app.delete("/exploit-store/{exploit_id}", tags=["Exploit Store"])
def delete_exploit_store(exploit_id: str, authorized: bool = Depends(auth)):
    """Delete a saved exploit."""
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor() as cur:
        cur.execute("DELETE FROM exploit_store WHERE id = %s", (exploit_id,))
        n = cur.rowcount; conn.commit()
    if not n:
        raise HTTPException(404, "exploit not found")
    return {"ok": True, "deleted": n}


@app.post("/exploit-store/{exploit_id}/generate", tags=["Exploit Store"])
def regenerate_exploit_artifacts(exploit_id: str, authorized: bool = Depends(auth)):
    """(Re)generate the Python script + Burp raw HTTP request from the stored command."""
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "exploit not found")
        if not row["command"]:
            raise HTTPException(400, "entry has no command to generate from")
        art = _exploit_store_artifacts(row["kind"], row["command"], row["name"], row["cve"],
                                       row["rationale"], row["assertion"])
        cur.execute("""UPDATE exploit_store SET python_code=%s, http_request=%s, updated_at=now()
                        WHERE id=%s RETURNING *""",
                    (art["python_code"], art["http_request"], exploit_id))
        out = cur.fetchone(); conn.commit()
    return dict(out)


@app.post("/exploit-store/{exploit_id}/run", tags=["Exploit Store"])
def run_exploit(exploit_id: str, authorized: bool = Depends(auth)):
    """Run the stored PoC's shell command through the listener and return the output.
    Operator triggers this from the detail panel to confirm the exploit still works
    (targets change, WAFs get tuned) without leaving the UI. Reuses the same
    /vectors/run listener the build+refine loop already uses, so scope gate + timeout
    + logging behave identically."""
    import httpx as _hx
    import time as _t
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
    if not row:
        raise HTTPException(404, "exploit not found")
    if not row.get("command"):
        return {"ok": False, "reason": "no command on this exploit"}
    listener = os.environ.get("KALI_LISTENER_URL", "https://kali-listener:8019")
    vt = int(os.environ.get("VECTOR_RUN_TIMEOUT", "600"))
    t0 = _t.time()
    # response_time_ms captures the listener HTTP round-trip SEPARATELY from
    # total wall-clock (seconds) — in bulk runs the operator wants to spot
    # slow targets vs slow setup. httpx `elapsed` is None until the request
    # completes, so we read it off `lr` after the call. target_response_ms
    # is best-effort: when the command is a curl with `-w %{time_total}`,
    # we parse that line out — otherwise falls back to the listener RTT.
    response_time_ms = None
    target_response_ms = None
    try:
        lr = _hx.post(f"{listener.rstrip('/')}/vectors/run",
                       json={"command": row["command"], "target": str(row.get("target_host") or ""),
                              "port": row.get("target_port") or 80, "timeout": vt},
                       headers={"x-api-key": API_KEY}, verify=False, timeout=vt + 60)
        try: response_time_ms = int(lr.elapsed.total_seconds() * 1000)
        except Exception: pass  # noqa: BLE001
        d = lr.json() if lr.status_code < 400 else {}
        output = (d.get("output", "") if isinstance(d, dict) else "") or lr.text
        exit_code = d.get("exit_code") if isinstance(d, dict) else None
    except Exception as e:  # noqa: BLE001
        output, exit_code = f"listener error: {e}", None
    # Parse curl -w timing out of the output if the command emitted it
    try:
        target_response_ms = _parse_curl_time_total_ms(output)
    except Exception:  # noqa: BLE001
        pass
    # Check the stored assertion against the fresh output to answer "does it STILL work?"
    still_works = False
    try:
        still_works = _poc_assertion_passes(row.get("assertion") or {}, output, exit_code)
    except Exception:  # noqa: BLE001
        pass
    return {
        "ok": True, "exploit_id": exploit_id, "cve": row.get("cve"),
        "target": f"{row.get('target_host')}:{row.get('target_port')}",
        "command": row["command"], "output": output[:20000],
        "exit_code": exit_code, "still_works": still_works,
        "seconds": round(_t.time() - t0, 2),
        "response_time_ms": response_time_ms,
        "target_response_ms": target_response_ms,
        "asserted_verified": bool(row.get("verified")),
    }


@app.get("/exploit-store/{exploit_id}/download", tags=["Exploit Store"])
def download_exploit(exploit_id: str, fmt: str = "python", authorized: bool = Depends(auth)):
    """Download an artifact as a file: fmt=python | http | curl | json."""
    import re as _re
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "exploit not found")
    # Filename shape (operator ask): "<cve>_<host>_<port>_<kind>.<ext>" when CVE known,
    # else "<host>_<port>_<kind>.<ext>". Falls back to name/exploit if neither is set.
    def _clean(s):
        return _re.sub(r"[^A-Za-z0-9_.-]+", "_", str(s or "")).strip("_") or ""
    parts = []
    if row.get("cve"):     parts.append(_clean(row["cve"]))
    if row.get("target_host"): parts.append(_clean(row["target_host"]))
    if row.get("target_port"): parts.append(str(row["target_port"]))
    if row.get("kind"):    parts.append(_clean(row["kind"]))
    base = "_".join(p for p in parts if p) or _clean(row.get("name")) or "exploit"
    if fmt == "python":
        content = row["python_code"] or ""
        if not content and row["command"]:
            content = _exploit_store_artifacts(row["kind"], row["command"], row["name"],
                                               row["cve"], row["rationale"], row["assertion"])["python_code"] or ""
        media, fn = "text/x-python", f"{base}.py"
    elif fmt == "http":
        content = row["http_request"] or ""
        if not content and row["command"]:
            from common import exploit_artifacts as _ea
            content = _ea.curl_to_http_request(row["command"])
        media, fn = "text/plain", f"{base}.http"
    elif fmt == "curl":
        content, media, fn = (row["command"] or ""), "text/plain", f"{base}.sh"
    elif fmt == "json":
        content = json.dumps({k: (str(v) if isinstance(v, (uuid.UUID,)) else v)
                              for k, v in dict(row).items()
                              if k not in ("engagement_id",)}, default=str, indent=2)
        media, fn = "application/json", f"{base}.json"
    else:
        raise HTTPException(400, "fmt must be python|http|curl|json")
    return Response(content=content, media_type=media,
                    headers={"Content-Disposition": f'attachment; filename="{fn}"'})


@app.post("/exploit-store/{exploit_id}/push", tags=["Exploit Store"])
def push_exploit_to_node(exploit_id: str, body: ExploitPushBody, authorized: bool = Depends(auth)):
    """Push the Python PoC to an SSH remote node so it can be run there. Requires the node
    to be node_type='ssh' with connection info in metadata ({ssh_user, ssh_host|external_ip,
    ssh_key}). Non-SSH node types (sliver/chisel C2) are not supported by this path."""
    import re as _re
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "exploit not found")
        cur.execute("""SELECT id, name, node_type, external_ip, internal_ip, metadata
                        FROM remote_nodes WHERE id = %s::uuid""", (body.node_id,))
        node = cur.fetchone()
    if not node:
        raise HTTPException(404, "node not found")
    if node["node_type"] != "ssh":
        raise HTTPException(400, f"push supports ssh nodes only (node is {node['node_type']}); "
                                 f"download the artifact and deliver via your C2 instead")
    code = row["python_code"] or ""
    if not code and row["command"]:
        code = _exploit_store_artifacts(row["kind"], row["command"], row["name"], row["cve"],
                                        row["rationale"], row["assertion"])["python_code"] or ""
    if not code:
        raise HTTPException(400, "entry has no Python artifact to push")
    meta = node.get("metadata") or {}
    ssh_user = meta.get("ssh_user") or "root"
    ssh_host = meta.get("ssh_host") or str(node.get("external_ip") or node.get("internal_ip") or "")
    ssh_key = meta.get("ssh_key")     # filename under ssh-keys/
    if not ssh_host:
        raise HTTPException(400, "node has no reachable ssh_host/external_ip in metadata")
    dest_dir = (body.dest_dir or meta.get("dest_dir") or "~").rstrip("/")
    fn = body.filename or f"{_re.sub(r'[^A-Za-z0-9_.-]+','_', row['cve'] or row['name'] or 'exploit')}_poc.py"
    result = _push_python_over_ssh(code, ssh_user, ssh_host, ssh_key, dest_dir, fn)
    try:
        emit_webhook("exploit_store_pushed", "exploit_store",
                     {"id": exploit_id, "node_id": body.node_id, "ok": result.get("ok"),
                      "dest": result.get("dest")})
    except Exception:  # noqa: BLE001
        pass
    if not result.get("ok"):
        raise HTTPException(502, f"push failed: {result.get('error')}")
    return {"ok": True, "node": node["name"], **result}


def _push_python_over_ssh(code, user, host, key_file, dest_dir, filename):
    """Best-effort scp of the Python PoC to an ssh node. Uses ssh-keys/<key_file> when
    given. Never trusts host key blindly for prod, but this is an authorized-lab helper."""
    import subprocess, tempfile, os as _os
    key_path = None
    if key_file:
        for cand in (key_file, _os.path.join("ssh-keys", key_file),
                     _os.path.join("/app/ssh-keys", key_file)):
            if _os.path.exists(cand):
                key_path = cand; break
    tf = None
    try:
        tf = tempfile.NamedTemporaryFile("w", suffix=".py", delete=False)
        tf.write(code); tf.close()
        dest = f"{dest_dir}/{filename}"
        scp = ["scp", "-o", "StrictHostKeyChecking=no", "-o", "ConnectTimeout=15",
               "-o", "BatchMode=yes"]
        if key_path:
            scp += ["-i", key_path]
        scp += [tf.name, f"{user}@{host}:{dest}"]
        p = subprocess.run(scp, capture_output=True, text=True, timeout=60)
        if p.returncode != 0:
            return {"ok": False, "error": (p.stderr or p.stdout or "scp failed")[:500]}
        return {"ok": True, "dest": dest, "host": host}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "error": f"{type(e).__name__}: {e}"}
    finally:
        try:
            if tf:
                _os.unlink(tf.name)
        except Exception:  # noqa: BLE001
            pass


class ExploitFromPocBody(BaseModel):
    security_test_id: Optional[str] = None
    # or import directly from a build-poc result:
    cve: Optional[str] = None
    command: Optional[str] = None
    assertion: Optional[dict] = None
    target_host: Optional[str] = None
    target_port: Optional[int] = None
    rationale: Optional[str] = None
    llm_model: Optional[str] = None
    poc_log_path: Optional[str] = None
    verified: bool = False
    kind: str = "web"


@app.post("/exploit-store/from-poc", tags=["Exploit Store"])
def import_poc_to_store(body: ExploitFromPocBody, authorized: bool = Depends(auth)):
    """Import a converged PoC into the Exploit Store — from a stored security_test id, or
    directly from a build-poc result. Generates the Python + Burp HTTP artifacts."""
    eid = _validate_engagement_uuid(_resolve_engagement_id())
    st = None
    if body.security_test_id:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SELECT * FROM security_tests WHERE id = %s", (body.security_test_id,))
            st = cur.fetchone()
        if not st:
            raise HTTPException(404, "security_test not found")
    cve = (body.cve or (st and st.get("metadata", {}).get("cve")) or "").strip().upper() or None
    command = body.command or (st and st.get("command"))
    if not command:
        raise HTTPException(400, "no command to import")
    assertion = body.assertion or (st and st.get("assertion")) or {}
    md = (st and st.get("metadata")) or {}
    new_id = _save_exploit_store(
        name=(st["name"] if st else f"PoC {cve or 'exploit'}"),
        cve=cve, kind=body.kind,
        target_host=body.target_host or (st and st.get("target_host")),
        target_port=body.target_port or (st and st.get("target_port")),
        command=command, assertion=assertion, rationale=body.rationale or (st and st.get("description")),
        verified=bool(body.verified or md.get("verified")), source="cve_poc_builder",
        security_test_id=body.security_test_id, poc_log_path=body.poc_log_path or md.get("log"),
        llm_model=body.llm_model or md.get("llm_model"), built_at=md.get("built_at"),
        eid=eid, metadata=md)
    if not new_id:
        raise HTTPException(500, "could not import PoC")
    return get_exploit_store(new_id, authorized)


@app.post("/exploit-store/{exploit_id}/send-to-burp", tags=["Exploit Store"])
def send_exploit_to_burp(exploit_id: str, authorized: bool = Depends(auth)):
    """Queue this exploit's raw HTTP request into the Burp Follow-Up Queue (what the Burp
    extension imports into Repeater). Uses the stored Burp-ready request; generates it from
    the command if missing. This is the one-click 'Send to Burp' for the Exploit Store."""
    _ensure_exploit_store()
    eid = _validate_engagement_uuid(_resolve_engagement_id())
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "exploit not found")
    from common import exploit_artifacts as _ea
    req = row["http_request"]
    # Regenerate when missing OR a stale fallback comment (e.g. saved before a parser fix).
    if (not req or req.lstrip().startswith("#")) and row["command"]:
        req = _ea.curl_to_http_request(row["command"])
    if not req or req.lstrip().startswith("#"):
        raise HTTPException(400, "no HTTP request available to send (entry has no web command)")
    parsed = _ea.parse_curl(row["command"] or "")
    method = parsed.get("method") or (req.split(" ", 1)[0] if req else "GET")
    url = parsed.get("url") or ""
    if not url and row["target_host"]:
        url = f"http://{row['target_host']}:{row['target_port'] or 80}/"
    title = f"PoC {row['cve'] or ''} {row['name']}".strip()
    cves = [row["cve"]] if row["cve"] else []
    meta = {"exploit_store_id": exploit_id, "source": "exploit_store",
            "verified": row["verified"], "llm_model": row["llm_model"]}
    with get_db() as conn, conn.cursor() as cur:
        cur.execute("""INSERT INTO burp_followup_queue
            (follow_up_id, title, url, target, severity, finding_source, method,
             request_raw, description, cves, metadata, status)
            VALUES (NULL,%s,%s,%s,'high','exploit_store',%s,%s,%s,%s,%s::jsonb,'pending')
            RETURNING id""",
            (title, url, row["target_host"], method, req,
             row["rationale"] or "", cves, json.dumps(meta, default=str)))
        qid = str(cur.fetchone()[0]); conn.commit()
    try:
        emit_webhook("exploit_store_sent_to_burp", "exploit_store",
                     {"id": exploit_id, "queue_id": qid, "cve": row["cve"], "target": row["target_host"]})
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, "queue_id": qid, "method": method, "url": url}


