@app.get("/params", tags=["Params"])
def search_params(
    url_pattern: Optional[str] = Query(None, description="Filter by URL pattern (ILIKE)"),
    param_name: Optional[str] = Query(None, description="Filter by param name (ILIKE)"),
    param_type: Optional[str] = Query(None, description="Filter by param type"),
    min_occurrences: int = Query(1, ge=1, description="Minimum occurrence count"),
    limit: int = Query(200, ge=1, le=2000),
    offset: int = Query(0, ge=0),
    authorized: bool = Depends(auth),
):
    """Search discovered parameters from katana crawls."""
    where_clauses: list[str] = []
    params: list = []

    # Scope to the active engagement (X-Engagement-Id header). discovered_params
    # has no engagement_id column, so filter via the linked asset — otherwise the
    # OSINT Explorer Parameters tab shows every engagement's parameters.
    _eid = _validate_engagement_uuid(_resolve_engagement_id())
    if _eid:
        where_clauses.append("dp.asset_id IN (SELECT id FROM assets WHERE engagement_id = %s::uuid)")
        params.append(_eid)
    if url_pattern:
        where_clauses.append("dp.url_pattern ILIKE %s")
        params.append(f"%{url_pattern}%")
    if param_name:
        where_clauses.append("dp.param_name ILIKE %s")
        params.append(f"%{param_name}%")
    if param_type:
        where_clauses.append("dp.param_type = %s")
        params.append(param_type)
    if min_occurrences > 1:
        where_clauses.append("dp.occurrence_count >= %s")
        params.append(min_occurrences)

    where_sql = (" WHERE " + " AND ".join(where_clauses)) if where_clauses else ""

    data_sql = f"""
        SELECT dp.id::text, dp.asset_id::text, dp.url_pattern, dp.param_name,
               dp.param_type, dp.http_method, dp.param_location,
               dp.sample_values, dp.occurrence_count, dp.discovery_source,
               dp.first_seen, dp.last_seen
        FROM discovered_params dp
        {where_sql}
        ORDER BY dp.occurrence_count DESC, dp.last_seen DESC
        LIMIT %s OFFSET %s
    """
    count_sql = f"SELECT COUNT(*) FROM discovered_params dp {where_sql}"

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(data_sql, params + [limit, offset])
        rows = cur.fetchall()
        cur.execute(count_sql, params)
        total = cur.fetchone()["count"]

    results = []
    for r in rows:
        results.append({
            "id": r["id"],
            "asset_id": r["asset_id"],
            "url_pattern": r["url_pattern"],
            "param_name": r["param_name"],
            "param_type": r["param_type"] or "string",
            "http_method": r["http_method"] or "GET",
            "param_location": r["param_location"] or "query",
            "sample_values": r["sample_values"] or [],
            "occurrence_count": r["occurrence_count"] or 1,
            "discovery_source": r["discovery_source"] or "katana",
            "first_seen": r["first_seen"].isoformat() if r.get("first_seen") else "",
            "last_seen": r["last_seen"].isoformat() if r.get("last_seen") else "",
        })

    return {"params": results, "total": total}


@app.get("/params/summary", tags=["Params"])
def params_summary(
    min_occurrences: int = Query(1, ge=1),
    limit: int = Query(100, ge=1, le=1000),
    authorized: bool = Depends(auth),
):
    """Summarize discovered params grouped by name with total occurrences across all URLs."""
    # Scope to the active engagement via the linked asset (no engagement_id
    # column on discovered_params) so the counts match the engagement, not all.
    where_clauses: list = []
    where_params: list = []
    _eid = _validate_engagement_uuid(_resolve_engagement_id())
    if _eid:
        where_clauses.append("dp.asset_id IN (SELECT id FROM assets WHERE engagement_id = %s::uuid)")
        where_params.append(_eid)
    where_sql = (" WHERE " + " AND ".join(where_clauses)) if where_clauses else ""
    having_sql = ""
    having_params: list = []
    if min_occurrences > 1:
        having_sql = "HAVING SUM(dp.occurrence_count) >= %s"
        having_params.append(min_occurrences)

    sql = f"""
        SELECT dp.param_name,
               array_agg(DISTINCT dp.param_type) AS types,
               array_agg(DISTINCT dp.param_location) AS locations,
               SUM(dp.occurrence_count)::int AS total_occurrences,
               COUNT(DISTINCT dp.url_pattern)::int AS url_count
        FROM discovered_params dp
        {where_sql}
        GROUP BY dp.param_name
        {having_sql}
        ORDER BY total_occurrences DESC
        LIMIT %s
    """

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(sql, where_params + having_params + [limit])
        rows = cur.fetchall()

    return {
        "summary": [
            {
                "param_name": r["param_name"],
                "types": r["types"] or [],
                "locations": r["locations"] or [],
                "total_occurrences": r["total_occurrences"],
                "url_count": r["url_count"],
            }
            for r in rows
        ]
    }


# ── Scope Management ──────────────────────────────────────────────────────────

@app.get("/scope/names", tags=["Scope"])
def list_scope_names(authorized: bool = Depends(auth)):
    """List distinct scope names with target counts."""
    # Placeholder rows (empty target, source '__placeholder__') exist so a named
    # scope can be created before it has any targets. They are NOT targets and
    # must not be counted — the engagement-scoped endpoints below already filter
    # them with the same predicate; these global ones did not, so a scope holding
    # only a placeholder reported target_count=1 and looked populated.
    sql = """
        SELECT name,
               COUNT(*) FILTER (
                   WHERE target <> '' AND source IS DISTINCT FROM %s
               ) AS target_count,
               MAX(added_at) AS last_updated
        FROM scope_targets
        GROUP BY name
        ORDER BY last_updated DESC
    """
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(sql, (_SCOPE_PLACEHOLDER_SOURCE,))
        rows = cur.fetchall()
    return {
        "names": [
            {
                "name": r["name"],
                "target_count": r["target_count"],
                "last_updated": r["last_updated"].isoformat() if r.get("last_updated") else "",
            }
            for r in rows
        ]
    }


@app.get("/scope", tags=["Scope"])
def get_scope(
    name: str = Query("default", description="Scope name"),
    limit: int = Query(500, ge=1, le=5000),
    authorized: bool = Depends(auth),
):
    """List targets for a named scope. Match is case-insensitive so the
    operator (or LLM) can pass "Default" / "default" / "DEFAULT" interchangeably."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # Exclude placeholder rows — see list_scope_names. A caller treating this
        # response as "the scope" (the BFF scan gate does exactly that) would
        # otherwise enforce against a scope whose only entry matches nothing,
        # refusing every scan.
        cur.execute(
            "SELECT COUNT(*) FROM scope_targets "
            "WHERE LOWER(name) = LOWER(%s) AND target <> '' AND source IS DISTINCT FROM %s",
            [name, _SCOPE_PLACEHOLDER_SOURCE],
        )
        total = cur.fetchone()["count"]

        cur.execute(
            """SELECT id::text, name, target, target_type, source, added_at
               FROM scope_targets
               WHERE LOWER(name) = LOWER(%s)
                 AND target <> '' AND source IS DISTINCT FROM %s
               ORDER BY added_at DESC
               LIMIT %s""",
            [name, _SCOPE_PLACEHOLDER_SOURCE, limit],
        )
        rows = cur.fetchall()

    return {
        "name": name,
        "total": total,
        "targets": [
            {
                "id": r["id"],
                "name": r["name"],
                "target": r["target"],
                "target_type": r["target_type"] or "",
                "source": r["source"] or "",
                "added_at": r["added_at"].isoformat() if r.get("added_at") else "",
            }
            for r in rows
        ],
    }


def _infer_target_type(target: str) -> str:
    """Classify a bare scope target as ip | cidr | domain.

    Mirrors the auto-discovery path's rule so the two agree. A wrong-but-present
    type is still better than NULL, which the gate cannot match at all.
    """
    t = (target or "").strip()
    if "/" in t and any(c.isdigit() for c in t.split("/")[-1]):
        return "cidr"
    try:
        import ipaddress
        ipaddress.ip_address(t)
        return "ip"
    except ValueError:
        return "domain"


@app.get("/scope/conflicts", tags=["Scope"])
def list_scope_conflicts(include_resolved: bool = Query(False),
                         _: bool = Depends(auth)):
    """Targets claimed by MORE THAN ONE engagement's scope, worst/newest first.

    A target in two scopes cannot be attributed to an engagement (the resolver
    refuses to guess), so a scan on it runs unattached and loses its engagement's
    pre-approval. Each row names the conflicting engagements so the operator can
    remove the duplicate. Recorded at detection time by record_scope_conflict.
    """
    where = "" if include_resolved else "WHERE resolved = false"
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            f"""SELECT id::text, target, target_type,
                       array(SELECT x::text FROM unnest(engagement_ids) x) AS engagement_ids,
                       engagement_names, detections, last_detected_by,
                       last_session_id::text, resolved, first_seen, last_seen
                  FROM scope_conflicts
                  {where}
                 ORDER BY resolved ASC, last_seen DESC
                 LIMIT 500""")
        rows = [dict(r) for r in cur.fetchall()]
    return {"count": len(rows), "open": sum(1 for r in rows if not r["resolved"]),
            "conflicts": rows}


@app.post("/scope/conflicts/{conflict_id}/resolve", tags=["Scope"])
def resolve_scope_conflict(conflict_id: str,
                           x_operator: str = Header("operator", alias="X-Operator"),
                           _: bool = Depends(auth)):
    """Mark a scope conflict resolved (the operator fixed the duplicate).

    Durable only until the duplicate recurs: if a scan later resolves the same
    target and STILL finds two scopes, record_scope_conflict reopens it — so
    dismissing without actually fixing the scope brings it straight back.
    """
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("UPDATE scope_conflicts SET resolved = true "
                    " WHERE id = %s::uuid RETURNING id::text, target, resolved",
                    (conflict_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, f"scope conflict {conflict_id} not found")
        conn.commit()
    return {"ok": True, "actor": x_operator, **dict(row)}


@app.post("/scope/add", tags=["Scope"])
def add_to_scope(
    body: dict,
    authorized: bool = Depends(auth),
):
    """Add targets to a named scope. Body: {name, targets: [{target, target_type, source}]}"""
    name = body.get("name", "default")
    targets = body.get("targets", [])
    if not targets:
        raise HTTPException(status_code=400, detail="No targets provided")

    # Attach to the active engagement if one is set. Storing an engagement's
    # target under engagement_id IS NULL put it in the GLOBAL list only, so the
    # engagement-scoped gate (load_engagement_scope) never saw it — a target you
    # authorised for THIS engagement was invisible to the dispatcher for it.
    eid = _validate_engagement_uuid(_resolve_engagement_id(body.get("engagement_id")))

    added = 0
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        for t in targets:
            target_val = t.get("target", "").strip()
            if not target_val:
                continue
            # target_type is what the scope GATE matches on (is_in_scope keys off
            # it: 'ip' exact, 'cidr' network, 'domain'/'url' suffix). An INSERT
            # that left it NULL — which is what happened when a caller sent only
            # {"target": ...} — stored a row that matched no branch and was
            # therefore silently OUT of scope while looking present in the list.
            # Infer it when the caller did not supply it, using the same rule the
            # auto-discovery path uses below.
            ttype = (t.get("target_type") or "").strip().lower() or _infer_target_type(target_val)
            cur.execute(
                """INSERT INTO scope_targets (name, target, target_type, source, engagement_id)
                   SELECT %s, %s, %s, %s, %s
                   WHERE NOT EXISTS (
                       SELECT 1 FROM scope_targets
                       WHERE target = %s AND name = %s
                         AND engagement_id IS NOT DISTINCT FROM %s
                   )""",
                [name, target_val, ttype, t.get("source"), eid,
                 target_val, name, eid],
            )
            added += cur.rowcount
        conn.commit()
    return {"ok": True, "name": name, "added": added, "engagement_id": eid}


@app.post("/scope/{name}/purge-data", tags=["Scope"])
def purge_scope_data(name: str, body: dict = None,
                     dry_run: bool = Query(False),
                     authorized: bool = Depends(auth)):
    """Delete all findings, follow-ups, and recommendations for every target in a
    named scope — so a lab rerun regenerates fresh data from a clean baseline.

    Deliberately does NOT touch assets, ports, or scope membership: the next scan
    re-observes those, and keeping the scope means the rerun is still authorised.
    `dry_run=true` returns the counts it WOULD delete, so the operator can preview
    before committing. Findings are matched to the scope's targets by asset IP /
    exact hostname; follow-ups and recommendations by their target/ip column.
    """
    body = body or {}
    eid = _resolve_engagement_id(body.get("engagement_id"))
    with get_db() as conn, conn.cursor() as cur:
        if eid:
            cur.execute("SELECT DISTINCT target FROM scope_targets "
                        "WHERE name = %s AND (engagement_id = %s OR engagement_id IS NULL)",
                        (name, eid))
        else:
            cur.execute("SELECT DISTINCT target FROM scope_targets WHERE name = %s", (name,))
        targets = [r[0] for r in cur.fetchall() if r[0]]
        if not targets:
            return {"ok": True, "scope": name, "dry_run": dry_run, "targets": 0,
                    "total": 0, "deleted": {}, "note": "scope has no targets"}

        cur.execute("SELECT id::text FROM assets "
                    "WHERE host(ip)::text = ANY(%s) OR hostname = ANY(%s)",
                    (targets, targets))
        aids = [r[0] for r in cur.fetchall()]

        # (table, where, params). Dependents/finding tables + follow-ups + recs.
        plan = [
            ("follow_up_items",      "target = ANY(%s)",              (targets,)),
            ("scan_recommendations", "host(ip)::text = ANY(%s)",      (targets,)),
            ("vulns",                "asset_id = ANY(%s::uuid[])",    (aids,)),
            ("web_findings",         "asset_id = ANY(%s::uuid[])",    (aids,)),
            ("discovered_params",    "asset_id = ANY(%s::uuid[])",    (aids,)),
            ("attack_vectors",       "asset_id = ANY(%s::uuid[])",    (aids,)),
            ("credential_findings",  "asset_id = ANY(%s::uuid[])",    (aids,)),
            ("findings",             "asset_id = ANY(%s::uuid[])",    (aids,)),
            ("recon_findings",       "target = ANY(%s)",              (targets,)),
        ]
        result = {}
        for table, where, params in plan:
            try:
                cur.execute("SAVEPOINT purge_scope")
                if dry_run:
                    cur.execute(f"SELECT COUNT(*) FROM {table} WHERE {where}", params)
                    n = cur.fetchone()[0]
                else:
                    cur.execute(f"DELETE FROM {table} WHERE {where}", params)
                    n = cur.rowcount
                if n:
                    result[table] = n
                cur.execute("RELEASE SAVEPOINT purge_scope")
            except Exception:  # noqa: BLE001
                cur.execute("ROLLBACK TO SAVEPOINT purge_scope")
        if not dry_run:
            conn.commit()

    total = sum(result.values())
    if not dry_run:
        try:
            from webhooks import emit_webhook
            emit_webhook("scope_data_purged", "rag-api",
                         {"scope": name, "engagement_id": eid,
                          "targets": len(targets), "rows_deleted": total,
                          "tables": result})
        except Exception:  # noqa: BLE001
            pass
    return {"ok": True, "scope": name, "dry_run": dry_run,
            "targets": len(targets), "total": total, "deleted": result}


@app.delete("/scope/targets", tags=["Scope"])
def remove_from_scope(
    body: dict,
    authorized: bool = Depends(auth),
):
    """Remove targets from a scope. Body: {name, targets: [str]}"""
    name = body.get("name", "default")
    targets = body.get("targets", [])
    if not targets:
        raise HTTPException(status_code=400, detail="No targets provided")

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            "DELETE FROM scope_targets WHERE name = %s AND target = ANY(%s)",
            [name, targets],
        )
        removed = cur.rowcount
        conn.commit()
    return {"ok": True, "name": name, "removed": removed}


@app.post("/scope/auto-assign-unknown", tags=["Scope"])
def _scope_engagement(cur, scope_name, default=None):
    """The engagement that owns a scope NAME, from the rows already in it.

    A scope belongs to one engagement in practice, so a row joining that scope
    should land in the same engagement. Returns `default` for a scope with no
    attributed rows yet — and None is correct for the global `not_in_scope`
    deny-list, which is cross-engagement by design (CLAUDE.md).
    """
    try:
        cur.execute("""SELECT engagement_id::text AS eid FROM scope_targets
                        WHERE name = %s AND engagement_id IS NOT NULL
                        GROUP BY engagement_id
                        ORDER BY count(*) DESC LIMIT 1""", (scope_name,))
        row = cur.fetchone()
    except Exception:  # noqa: BLE001
        return default
    return (row or {}).get("eid") or default


def auto_assign_unknown_scope(authorized: bool = Depends(auth)):
    """Find all assets/hostnames not in any scope and assign them to 'unknown_scope'.

    This gives visibility into discovered items that haven't been explicitly triaged
    into a named scope. Items remain in unknown_scope until manually moved.
    """
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # Get all existing scope targets
        cur.execute("SELECT DISTINCT target FROM scope_targets")
        scoped = set(r["target"] for r in cur.fetchall())

        # Find unscoped hostnames from assets
        cur.execute("SELECT DISTINCT hostname FROM assets WHERE hostname IS NOT NULL")
        all_hosts = set(r["hostname"] for r in cur.fetchall())

        # Find unscoped IPs from assets
        cur.execute("SELECT DISTINCT host(ip)::text FROM assets WHERE ip IS NOT NULL")
        all_ips = set(r["host"] for r in cur.fetchall())

        # Find unscoped domains from recon_findings (subfinder targets)
        cur.execute("""
            SELECT DISTINCT target FROM recon_findings
            WHERE source IN ('subfinder', 'dnsx', 'httpx') AND target IS NOT NULL
        """)
        all_recon_targets = set(r["target"] for r in cur.fetchall())

        # Combine all discovered items
        all_discovered = all_hosts | all_ips | all_recon_targets
        unscoped = all_discovered - scoped

        if not unscoped:
            return {"ok": True, "added": 0, "message": "All items already in a scope"}

        # Which engagement owns each discovered target? A scope row with a NULL
        # engagement_id is an orphan a data-purge cannot claim, so resolve it from
        # the asset/recon row the target came from, falling back to whatever
        # engagement already owns unknown_scope.
        owner = {}
        cur.execute("""
            SELECT hostname AS t, engagement_id::text AS eid FROM assets
             WHERE hostname IS NOT NULL AND engagement_id IS NOT NULL
            UNION ALL
            SELECT host(ip)::text, engagement_id::text FROM assets
             WHERE ip IS NOT NULL AND engagement_id IS NOT NULL
            UNION ALL
            SELECT target, engagement_id::text FROM recon_findings
             WHERE target IS NOT NULL AND engagement_id IS NOT NULL
        """)
        for r in cur.fetchall():
            owner.setdefault(r["t"], r["eid"])
        scope_eid = _scope_engagement(cur, "unknown_scope")

        # Add to unknown_scope
        added = 0
        for target in unscoped:
            if not target or not target.strip():
                continue
            # Determine type
            target_type = "domain"
            t = target.strip()
            if t.replace(".", "").isdigit() or ":" in t:
                target_type = "ip"
            elif "/" in t and any(c.isdigit() for c in t.split("/")[-1]):
                target_type = "cidr"

            # ON CONFLICT must repeat the unique index EXACTLY, and the only one
            # is ux_scope_targets_eng_name_target (engagement_id, name, target).
            # Naming (name, target) matched no index, so every insert here raised
            # "no unique or exclusion constraint matching the ON CONFLICT
            # specification" and this endpoint could never add a row.
            cur.execute("""
                INSERT INTO scope_targets (id, engagement_id, name, target, target_type, source)
                VALUES (gen_random_uuid(), %s::uuid, 'unknown_scope', %s, %s, 'auto-discovery')
                ON CONFLICT (engagement_id, name, target) DO NOTHING
            """, [owner.get(t) or scope_eid, t, target_type])
            added += cur.rowcount
        conn.commit()

    return {"ok": True, "added": added, "total_unscoped": len(unscoped),
            "message": f"Added {added} items to unknown_scope"}


def _gather_target_context(target: str, cur) -> dict:
    """Gather all available recon context for a target (WHOIS, ASN, TLS, HTTP, DNS)."""
    ctx = {"target": target}
    try:
        # WHOIS
        cur.execute("""
            SELECT data FROM recon_findings
            WHERE (target = %s OR target ILIKE %s) AND (finding_type = 'whois_record' OR source = 'whois')
            ORDER BY created_at DESC LIMIT 1
        """, (target, f"%.{target}"))
        row = cur.fetchone()
        if row and row[0]:
            d = row[0] if isinstance(row[0], dict) else {}
            ctx["whois_org"] = d.get("org") or d.get("registrant_org") or ""
            ctx["whois_registrant"] = d.get("registrant_name") or ""
            ctx["whois_country"] = d.get("registrant_country") or ""

        # ASN
        cur.execute("""
            SELECT data FROM recon_findings
            WHERE (target = %s OR target ILIKE %s) AND (finding_type = 'asn_mapping' OR source = 'asnmap')
            ORDER BY created_at DESC LIMIT 1
        """, (target, f"%.{target}"))
        row = cur.fetchone()
        if row and row[0]:
            d = row[0] if isinstance(row[0], dict) else {}
            ctx["asn_number"] = d.get("as_number") or ""
            ctx["asn_name"] = d.get("as_name") or ""

        # TLS
        cur.execute("""
            SELECT data FROM recon_findings
            WHERE (target = %s OR target ILIKE %s) AND (finding_type = 'tls_cert' OR source = 'tlsx')
            ORDER BY created_at DESC LIMIT 1
        """, (target, f"%.{target}"))
        row = cur.fetchone()
        if row and row[0]:
            d = row[0] if isinstance(row[0], dict) else {}
            ctx["tls_issuer"] = d.get("issuer_org") or d.get("issuer") or ""
            ctx["tls_subject"] = d.get("subject_cn") or ""

        # HTTP
        cur.execute("""
            SELECT data FROM recon_findings
            WHERE (target = %s OR target ILIKE %s) AND (finding_type = 'web_service' OR source = 'httpx')
            ORDER BY created_at DESC LIMIT 1
        """, (target, f"%.{target}"))
        row = cur.fetchone()
        if row and row[0]:
            d = row[0] if isinstance(row[0], dict) else {}
            ctx["http_title"] = d.get("title") or ""
            ctx["http_server"] = d.get("webserver") or d.get("server") or ""
            ctx["http_tech"] = d.get("tech") or []
            ctx["http_status"] = d.get("status_code") or ""

        # DNS
        cur.execute("""
            SELECT finding_type, data FROM recon_findings
            WHERE (target = %s OR target ILIKE %s) AND finding_type LIKE 'dns_%%'
            ORDER BY created_at DESC LIMIT 5
        """, (target, f"%.{target}"))
        dns = {}
        for row in cur.fetchall():
            dns[row[0]] = row[1] if isinstance(row[1], dict) else {}
        if dns:
            ctx["dns"] = dns

    except Exception as e:
        ctx["_gather_error"] = str(e)
    return ctx


def _build_context_text(ctx: dict) -> str:
    """Flatten context dict into a text string for embedding."""
    parts = [f"target={ctx.get('target', '')}"]
    for key in ("whois_org", "whois_registrant", "whois_country",
                "asn_number", "asn_name", "tls_issuer", "tls_subject",
                "http_title", "http_server", "http_status"):
        val = ctx.get(key)
        if val:
            parts.append(f"{key}={val}")
    tech = ctx.get("http_tech")
    if tech and isinstance(tech, list):
        parts.append(f"tech={','.join(str(t) for t in tech[:10])}")
    return " ".join(parts)


def _capture_scope_decisions(targets: list, from_scope: str, to_scope: str, cur):
    """Record scope decisions with recon context and embeddings for future classification."""
    import requests as _req
    embedder_url = os.environ.get("EMBEDDER_URL", "https://embedder:8030")

    for t in targets:
        t = t.strip()
        if not t:
            continue
        ctx = _gather_target_context(t, cur)
        ctx_text = _build_context_text(ctx)

        # Embed context (optional — graceful failure)
        embedding = None
        try:
            resp = _req.post(f"{embedder_url}/embed", json={"text": ctx_text}, timeout=5)
            if resp.status_code == 200:
                embedding = resp.json().get("embedding")
        except Exception:
            pass

        target_type = "ip" if t.replace(".", "").isdigit() or ":" in t else "domain"
        cur.execute("""
            INSERT INTO scope_decisions (id, target, target_type, from_scope, to_scope, context, context_text, embedding)
            VALUES (gen_random_uuid(), %s, %s, %s, %s, %s, %s, %s)
        """, (t, target_type, from_scope, to_scope,
              json.dumps(ctx), ctx_text,
              embedding if embedding else None))


def _move_target_to_scope(cur, target: str, scope: str, engagement_id=None):
    """Move one target out of unknown_scope into `scope`, keeping engagement_id.

    Uses the current unique index (engagement_id, name, target) — the legacy
    (name, target) constraint every older INSERT still names was dropped by the
    schema migration, so those ON CONFLICTs now raise. When engagement_id is
    unknown, inherit it from the row we are moving so the Recon Agent can see it.
    """
    from scope_classifier import target_type_of
    if not engagement_id:
        cur.execute("SELECT engagement_id FROM scope_targets WHERE target = %s "
                    "AND engagement_id IS NOT NULL LIMIT 1", (target,))
        row = cur.fetchone()
        engagement_id = (row["engagement_id"] if isinstance(row, dict) else row[0]) if row else None
    cur.execute("DELETE FROM scope_targets WHERE name = 'unknown_scope' AND target = %s "
                "AND (engagement_id = %s::uuid OR %s IS NULL)",
                (target, engagement_id, engagement_id))
    cur.execute(
        """INSERT INTO scope_targets (id, engagement_id, name, target, target_type, source)
           VALUES (gen_random_uuid(), %s::uuid, %s, %s, %s, 'auto-classified')
           ON CONFLICT (engagement_id, name, target) DO NOTHING""",
        (engagement_id, scope, target, target_type_of(target)))


def _distill(cur, target: str, scope: str, engagement_id=None, method="manual"):
    """Best-effort rule distillation; never raises into the request path."""
    try:
        from scope_classifier import distill_rule_from_decision
        return distill_rule_from_decision(cur, target, scope, engagement_id, method)
    except Exception as e:
        logging.warning(f"rule distillation failed for {target}->{scope}: {e}")
        return None


@app.post("/scope/move", tags=["Scope"])
def move_scope_targets(body: dict, authorized: bool = Depends(auth)):
    """Move targets from one scope to another. Body: {from_scope, to_scope, targets: [str]}
    Matches exact targets AND targets that are in the source scope that the given items are subdomains of.
    E.g. moving ['testdw.convio.com'] from unknown_scope will also move 'convio.com' if it's in unknown_scope.
    """
    from_scope = body.get("from_scope")
    to_scope = body.get("to_scope")
    targets = body.get("targets", [])
    if not from_scope or not to_scope or not targets:
        raise HTTPException(400, "Provide from_scope, to_scope, and targets")
    removed = 0
    added = 0
    with get_db() as conn, conn.cursor() as cur:
        # Build the full set of scope targets to move:
        # 1. Exact matches from the targets list
        # 2. Targets in the source scope that the given items are subdomains of
        to_move = set(t.strip() for t in targets if t.strip())

        # Get all targets currently in the source scope
        cur.execute("SELECT target FROM scope_targets WHERE name = %s", [from_scope])
        source_targets = [r[0] for r in cur.fetchall()]

        # For each selected item, find any source scope targets it's a subdomain of
        for item in list(to_move):
            for st in source_targets:
                # If source scope has 'convio.com' and we're moving 'testdw.convio.com'
                # then also move 'convio.com'
                if item.endswith('.' + st) or item == st:
                    to_move.add(st)

        # Remove all matched targets from source scope
        move_list = list(to_move)
        # Capture each row's engagement BEFORE deleting it: a move must not drop
        # attribution, and re-deriving it afterwards is guesswork.
        cur.execute("""SELECT target, engagement_id::text AS eid FROM scope_targets
                        WHERE name = %s AND target = ANY(%s)""", [from_scope, move_list])
        moved_eid = {r["target"]: r["eid"] for r in cur.fetchall()}
        dest_eid = _scope_engagement(cur, to_scope)
        cur.execute("DELETE FROM scope_targets WHERE name = %s AND target = ANY(%s)", [from_scope, move_list])
        removed = cur.rowcount
        # Add to destination scope
        for t in move_list:
            t = t.strip()
            if not t:
                continue
            target_type = "domain"
            if t.replace(".", "").isdigit() or ":" in t:
                target_type = "ip"
            # ON CONFLICT must name the real unique index
            # (engagement_id, name, target); (name, target) matched none, so this
            # insert raised and the move deleted the rows without re-adding them.
            cur.execute("""
                INSERT INTO scope_targets (id, engagement_id, name, target, target_type, source)
                VALUES (gen_random_uuid(), %s::uuid, %s, %s, %s, 'moved')
                ON CONFLICT (engagement_id, name, target) DO NOTHING
            """, [moved_eid.get(t) or dest_eid, to_scope, t, target_type])
            added += cur.rowcount

        # Capture decisions for auto-classification learning
        try:
            _capture_scope_decisions(targets, from_scope, to_scope, cur)
        except Exception as e:
            logging.warning(f"scope decision capture failed: {e}")

        conn.commit()
    return {"ok": True, "from_scope": from_scope, "to_scope": to_scope,
            "removed": removed, "added": added, "decisions_captured": len(targets)}


@app.post("/scope/cleanup-unknown", tags=["Scope"])
def cleanup_unknown_scope(authorized: bool = Depends(auth)):
    """Remove targets from unknown_scope if the exact same target already exists in any other named scope.
    Only removes exact matches — blog.example.com in a named scope does NOT remove example.com from unknown_scope.
    """
    with get_db() as conn, conn.cursor() as cur:
        # Remove exact duplicates only: targets in unknown_scope that also exist in another scope
        cur.execute("""
            DELETE FROM scope_targets
            WHERE name = 'unknown_scope'
            AND target IN (
                SELECT target FROM scope_targets WHERE name != 'unknown_scope'
            )
        """)
        removed = cur.rowcount
        conn.commit()

    return {
        "ok": True,
        "exact_duplicates_removed": removed,
        "total_removed": removed,
    }


# ── Scope Auto-Classification ─────────────────────────────────────────────

@app.get("/scope/classify/{target}", tags=["Scope Classification"])
def classify_single_target(target: str, authorized: bool = Depends(auth)):
    """Classify a single target — returns suggested scope with confidence and reasoning."""
    from scope_classifier import get_classifier
    classifier = get_classifier()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        classifier.load_rules(cur)
        ctx = _gather_target_context(target, cur)
        result = classifier.classify_target(target, ctx, cur)
    if not result:
        return {"target": target, "suggestion": None, "context": ctx}
    return {
        "target": target,
        "suggestion": {
            "scope": result.scope, "confidence": result.confidence,
            "reasoning": result.reasoning, "method": result.method,
        },
        "context": ctx,
    }


@app.post("/scope/classify-unknown", tags=["Scope Classification"])
def classify_unknown_scope(
    body: dict = None,
    authorized: bool = Depends(auth),
):
    """Run classifier on all unknown_scope items. Creates suggestions for user review.
    Body (optional): {auto_apply_threshold: 0.95, limit: 500}
    """
    body = body or {}
    auto_threshold = float(body.get("auto_apply_threshold", 0.95))
    limit = int(body.get("limit", 500))

    from scope_classifier import get_classifier
    classifier = get_classifier()

    auto_assigned = 0
    suggested = 0
    unclassified = 0

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        classifier.load_rules(cur)

        # Get unknown_scope targets
        cur.execute("SELECT target FROM scope_targets WHERE name = 'unknown_scope' LIMIT %s", (limit,))
        targets = [r["target"] for r in cur.fetchall()]

        for target in targets:
            ctx = _gather_target_context(target, cur)
            result = classifier.classify_target(target, ctx, cur)

            if not result or result.confidence < 0.5:
                unclassified += 1
                continue

            # Auto-apply if high confidence and rule allows it
            if result.method == "rule" and result.confidence >= auto_threshold:
                # Check if rule has auto_apply
                if result.rule_id:
                    cur.execute("SELECT auto_apply FROM scope_classification_rules WHERE id = %s", (result.rule_id,))
                    row = cur.fetchone()
                    if row and row["auto_apply"]:
                        # Auto-move. Mirrors _apply_scope_classification above:
                        # keep the row's engagement across the move, and name the
                        # real unique index in ON CONFLICT — (name, target)
                        # matched no index, so this raised every time.
                        cur.execute("""SELECT engagement_id::text AS eid FROM scope_targets
                                        WHERE name = 'unknown_scope' AND target = %s""",
                                    (target,))
                        _row = cur.fetchone()
                        _eid = ((_row or {}).get("eid")
                                or _scope_engagement(cur, result.scope))
                        cur.execute("DELETE FROM scope_targets WHERE name = 'unknown_scope' AND target = %s", (target,))
                        cur.execute("""
                            INSERT INTO scope_targets (id, engagement_id, name, target, target_type, source)
                            VALUES (gen_random_uuid(), %s::uuid, %s, %s, 'domain', 'auto-classified')
                            ON CONFLICT (engagement_id, name, target) DO NOTHING
                        """, (_eid, result.scope, target))
                        _capture_scope_decisions([target], "unknown_scope", result.scope, cur)
                        auto_assigned += 1
                        continue

            # Create suggestion for user review
            cur.execute("""
                INSERT INTO scope_suggestions (id, target, suggested_scope, confidence, reasoning, method, rule_id, similar_decisions, status)
                VALUES (gen_random_uuid(), %s, %s, %s, %s, %s, %s, %s, 'pending')
                ON CONFLICT (target) DO UPDATE SET
                    suggested_scope = EXCLUDED.suggested_scope,
                    confidence = EXCLUDED.confidence,
                    reasoning = EXCLUDED.reasoning,
                    method = EXCLUDED.method,
                    status = 'pending',
                    created_at = now()
            """, (target, result.scope, result.confidence, result.reasoning, result.method,
                  result.rule_id,
                  result.similar_decision_ids if result.similar_decision_ids else None))
            suggested += 1

        conn.commit()

    return {
        "ok": True, "total_processed": len(targets),
        "auto_assigned": auto_assigned, "suggested": suggested,
        "unclassified": unclassified,
    }


@app.get("/scope/suggestions", tags=["Scope Classification"])
def list_suggestions(
    status: str = Query("pending"),
    limit: int = Query(100, ge=1, le=1000),
    authorized: bool = Depends(auth),
):
    """List scope classification suggestions."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        if status == "all":
            cur.execute("SELECT * FROM scope_suggestions ORDER BY confidence DESC LIMIT %s", (limit,))
        else:
            cur.execute("SELECT * FROM scope_suggestions WHERE status = %s ORDER BY confidence DESC LIMIT %s", (status, limit))
        rows = cur.fetchall()
    return {"suggestions": [{k: str(v) if k == "id" else v for k, v in r.items()} for r in rows], "total": len(rows)}


@app.post("/scope/suggestions/{suggestion_id}/accept", tags=["Scope Classification"])
def accept_suggestion(suggestion_id: str, authorized: bool = Depends(auth)):
    """Accept a suggestion: move target to suggested scope and record decision."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM scope_suggestions WHERE id = %s", (suggestion_id,))
        sug = cur.fetchone()
        if not sug:
            raise HTTPException(404, "Suggestion not found")
        if sug["status"] != "pending":
            raise HTTPException(400, f"Suggestion already {sug['status']}")

        target = sug["target"]
        scope = sug["suggested_scope"]
        eid = sug.get("engagement_id")

        # Move target within THIS engagement (engagement_id is what makes the
        # Recon Agent see it; the old name-only conflict target no longer exists).
        _move_target_to_scope(cur, target, scope, eid)

        # Record decision, and distil a reusable rule so the next host under this
        # domain is a deterministic hit — the model is not asked twice.
        _capture_scope_decisions([target], "unknown_scope", scope, cur)
        learned = _distill(cur, target, scope, eid, sug.get("method") or "similarity")

        # Mark suggestion accepted
        cur.execute("UPDATE scope_suggestions SET status = 'accepted', reviewed_at = now() WHERE id = %s", (suggestion_id,))
        conn.commit()

    return {"ok": True, "target": target, "scope": scope, "learned_rule": learned}


@app.post("/scope/suggestions/{suggestion_id}/reject", tags=["Scope Classification"])
def reject_suggestion(suggestion_id: str, body: dict = None, authorized: bool = Depends(auth)):
    """Reject a suggestion. Optionally provide {correct_scope} to record the right answer."""
    body = body or {}
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM scope_suggestions WHERE id = %s", (suggestion_id,))
        sug = cur.fetchone()
        if not sug:
            raise HTTPException(404, "Suggestion not found")

        cur.execute("UPDATE scope_suggestions SET status = 'rejected', reviewed_at = now() WHERE id = %s", (suggestion_id,))

        # If user provided correct scope, record decision for learning
        correct_scope = body.get("correct_scope")
        if correct_scope:
            _capture_scope_decisions([sug["target"]], "unknown_scope", correct_scope, cur)

        conn.commit()
    return {"ok": True, "target": sug["target"]}


@app.post("/scope/suggestions/bulk-accept", tags=["Scope Classification"])
def bulk_accept_suggestions(body: dict, authorized: bool = Depends(auth)):
    """Accept all pending suggestions above a confidence threshold.
    Body: {min_confidence: 0.85}
    """
    min_conf = float(body.get("min_confidence", 0.85))
    accepted = 0
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM scope_suggestions WHERE status = 'pending' AND confidence >= %s", (min_conf,))
        for sug in cur.fetchall():
            target = sug["target"]
            scope = sug["suggested_scope"]
            _move_target_to_scope(cur, target, scope, sug.get("engagement_id"))
            _capture_scope_decisions([target], "unknown_scope", scope, cur)
            _distill(cur, target, scope, sug.get("engagement_id"), sug.get("method") or "similarity")
            cur.execute("UPDATE scope_suggestions SET status = 'accepted', reviewed_at = now() WHERE id = %s", (sug["id"],))
            accepted += 1
        conn.commit()
    return {"ok": True, "accepted": accepted, "min_confidence": min_conf}


class AutoClassifyBody(BaseModel):
    generate_rules: bool = True
    limit: Optional[int] = None
    unknown_scope: str = "unknown_scope"


@app.post("/engagements/{engagement_id}/scope/auto-classify", tags=["Scope Classification"])
def engagement_auto_classify(engagement_id: str, body: AutoClassifyBody = None,
                             authorized: bool = Depends(auth)):
    """Assign every discovered host to a scope UNDER this engagement, deterministically.

    Two steps, both LLM-free:
      1. generate_seed_rules — turns each operator-entered domain seed into a
         `*.{domain}` auto_apply rule (self-learning: the seed you typed becomes
         a reusable classifier).
      2. classify_and_assign_engagement — matches every discovered host against
         those rules. In-scope hosts land in the matched scope; the rest land in
         `unknown_scope`. BOTH carry engagement_id, so the Recon Agent scans the
         in-scope set and the unknown bucket is there for triage.

    Reusable across every recon tool — it reads recon_findings/assets, not any
    single tool's output.
    """
    from scope_classifier import generate_seed_rules, classify_and_assign_engagement
    body = body or AutoClassifyBody()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT id, name FROM engagements WHERE id = %s::uuid", (engagement_id,))
        eng = cur.fetchone()
        if not eng:
            raise HTTPException(404, f"engagement {engagement_id} not found")
        rules_created = generate_seed_rules(cur, engagement_id) if body.generate_rules else 0
        result = classify_and_assign_engagement(
            cur, engagement_id, unknown_scope=body.unknown_scope, limit=body.limit)
        conn.commit()
    try:
        from webhooks import emit_webhook
        emit_webhook("scope_auto_classified", "scope_classifier", {
            "engagement_id": engagement_id, "rules_created": rules_created, **result})
    except Exception:
        pass
    return {"ok": True, "engagement_id": engagement_id,
            "rules_created": rules_created, **result}


