@app.post("/scope-pivot/typosquat/{engagement_id}", tags=["Scope"])
def run_typosquat_pivot(
    engagement_id: str,
    check_resolution: bool = True,
    auto_block_at: float = 0.85,
    authorized: bool = Depends(auth),
):
    """Run the typosquat detector against this engagement's apex scope.

    For each in-scope domain / url target, generates ~200 lookalike
    candidates (edit-1/2, QWERTY, homoglyph, bitsquat, IDN, TLD swap),
    scores each, writes `scope_suggestions` rows with `method='typosquat'`,
    and auto-adds high-confidence hits to the GLOBAL `not_in_scope`
    deny-list (where the scope-gate short-circuit refuses dispatch for
    every engagement).

    Query params:
      * check_resolution — DNS A/AAAA resolution check per candidate
        (slower, but much better signal). Default True.
      * auto_block_at — score threshold for auto-adding to the deny-list.
        Default 0.85 — operator-confirmed in the OSINT scope-expansion plan.

    Returns the summary dict from `flag_typosquats_for_engagement`:
      {seeds, total_candidates, suggestions_written, denylist_added, errors}
    """
    try:
        eid = _validate_engagement_uuid(engagement_id)
    except Exception:
        raise HTTPException(status_code=400,
                            detail="invalid engagement_id uuid")
    if not eid:
        raise HTTPException(status_code=400,
                            detail="engagement_id required")
    try:
        from typosquat_agent import flag_typosquats_for_engagement
    except ImportError as e:
        logging.exception("typosquat_agent import failed")
        raise HTTPException(status_code=500,
                            detail=f"typosquat_agent unavailable: {e}")
    summary = flag_typosquats_for_engagement(
        get_db, eid,
        check_resolution=check_resolution,
        auto_block_at=auto_block_at,
    )
    return {"ok": True, "engagement_id": eid, "summary": summary}


@app.post("/scope-pivot/cert/{engagement_id}", tags=["Scope"])
def run_cert_pivot_endpoint(
    engagement_id: str,
    limit: int = 500,
    authorized: bool = Depends(auth),
):
    """Cert-pivot pass for this engagement.

    Reads TLS certificates already collected on the engagement's in-scope
    hosts (tlsx / crtsh / certspotter in `recon_findings`) and flags any
    SAN that names a DIFFERENT registrable domain — a "same owner, new
    surface" signal. Writes `scope_suggestions` rows with
    `method='cert_pivot'`, `suggested_scope='new_for_review'`.

    Passive: sends NO traffic to any host. If no certs have been collected
    yet, the summary says so (run recon first).
    """
    try:
        eid = _validate_engagement_uuid(engagement_id)
    except Exception:
        raise HTTPException(status_code=400, detail="invalid engagement_id uuid")
    if not eid:
        raise HTTPException(status_code=400, detail="engagement_id required")
    try:
        from scope_pivot_agent import run_cert_pivot
    except ImportError as e:
        logging.exception("scope_pivot_agent import failed")
        raise HTTPException(status_code=500,
                            detail=f"scope_pivot_agent unavailable: {e}")
    summary = run_cert_pivot(get_db, eid, limit=limit)
    try:
        from webhooks import emit_webhook
        emit_webhook("scope_cert_pivot_completed", "scope_pivot", {
            "engagement_id": eid,
            "seeds": summary.get("seeds"),
            "certs_examined": summary.get("certs_examined"),
            "candidates": summary.get("candidates"),
            "suggestions_written": summary.get("suggestions_written"),
        })
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, "engagement_id": eid, "summary": summary}


@app.post("/scope-pivot/asn/{engagement_id}", tags=["Scope"])
def run_asn_pivot_endpoint(
    engagement_id: str,
    limit: int = 500,
    authorized: bool = Depends(auth),
):
    """ASN-pivot pass for this engagement.

    Reads the ASN mappings already collected (asnmap in `recon_findings`)
    for the engagement's in-scope hosts and suggests the CIDR ranges of
    those ASNs, dropping cloud/CDN AS names unless the AS name matches an
    in-scope org token. Writes `scope_suggestions` rows with
    `method='asn_pivot'`, `suggested_scope='new_for_review'`.

    Passive: sends NO traffic to any host. If no asnmap results have been
    collected yet, the summary says so (run asnmap first).
    """
    try:
        eid = _validate_engagement_uuid(engagement_id)
    except Exception:
        raise HTTPException(status_code=400, detail="invalid engagement_id uuid")
    if not eid:
        raise HTTPException(status_code=400, detail="engagement_id required")
    try:
        from scope_pivot_agent import run_asn_pivot
    except ImportError as e:
        logging.exception("scope_pivot_agent import failed")
        raise HTTPException(status_code=500,
                            detail=f"scope_pivot_agent unavailable: {e}")
    summary = run_asn_pivot(get_db, eid, limit=limit)
    try:
        from webhooks import emit_webhook
        emit_webhook("scope_asn_pivot_completed", "scope_pivot", {
            "engagement_id": eid,
            "seeds": summary.get("seeds"),
            "asns_matched": summary.get("asns_matched"),
            "candidates": summary.get("candidates"),
            "suggestions_written": summary.get("suggestions_written"),
        })
    except Exception:  # noqa: BLE001
        pass
    return {"ok": True, "engagement_id": eid, "summary": summary}


@app.get("/scope-pivot/suggestions", tags=["Scope"])
def list_scope_suggestions(
    status: Optional[str] = None,
    method: Optional[str] = None,
    limit: int = 500,
    authorized: bool = Depends(auth),
):
    """List rows from `scope_suggestions` — the review workflow for the
    typosquat detector + cert-pivot + ASN-pivot pass.

    Filters:
      * status=pending|accepted|rejected  (default: all)
      * method=typosquat|cert_pivot|asn_pivot|rule|similarity|llm
    """
    where, args = [], []
    if status:
        where.append("status = %s"); args.append(status)
    if method:
        where.append("method = %s"); args.append(method)
    sql = ("SELECT id::text, target, suggested_scope, confidence, "
           "reasoning, method, status, created_at, reviewed_at "
           "FROM public.scope_suggestions ")
    if where:
        sql += "WHERE " + " AND ".join(where) + " "
    sql += "ORDER BY confidence DESC NULLS LAST, created_at DESC LIMIT %s"
    args.append(int(limit))
    with get_db() as c, c.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(sql, tuple(args))
        rows = [dict(r) for r in cur.fetchall()]
    for r in rows:
        if r.get("created_at"):
            r["created_at"] = r["created_at"].isoformat()
        if r.get("reviewed_at"):
            r["reviewed_at"] = r["reviewed_at"].isoformat()
    return {"ok": True, "suggestions": rows, "total": len(rows)}


def _pivot_target_type(target: str) -> str:
    """Classify an accepted pivot target so the scope_targets row carries
    the right target_type. cert_pivot yields domains; asn_pivot yields
    CIDRs; a bare IP is possible too."""
    t = (target or "").strip()
    try:
        import ipaddress as _ip
        if "/" in t:
            _ip.ip_network(t, strict=False)
            return "cidr"
        _ip.ip_address(t)
        return "ip"
    except Exception:  # noqa: BLE001
        return "domain"


@app.post("/scope-pivot/suggestions/{suggestion_id}/review", tags=["Scope"])
def review_scope_suggestion(
    suggestion_id: str,
    body: dict,
    authorized: bool = Depends(auth),
):
    """Operator review action on a scope_suggestions row.
    Body: {action: "accept"|"reject"}.

    For method='typosquat' AND action='accept': the target is ALSO added
    to the global not_in_scope deny-list (if not already) via the same
    pathway as exclude_from_scope — the deny-list is the belt-and-braces
    for the scope-gate short-circuit, so operator confirmation of a
    typosquat is what pins it there even when the score was below the
    auto-block threshold.

    For method IN ('cert_pivot','asn_pivot') AND action='accept': the
    target is promoted into the engagement's `new_for_review` STAGING
    scope. The scope gate refuses dispatch to that scope (like
    `typosquats`), so the pivot is visible under the engagement but is
    NOT scannable until the operator moves it to a live scope.
    """
    action = (body or {}).get("action", "").lower().strip()
    if action not in ("accept", "reject"):
        raise HTTPException(status_code=400,
                            detail="action must be 'accept' or 'reject'")
    new_status = "accepted" if action == "accept" else "rejected"
    with get_db() as c, c.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT target, method, suggested_scope FROM public.scope_suggestions "
                    "WHERE id = %s::uuid", (suggestion_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404,
                                detail="scope_suggestion not found")
        cur.execute("UPDATE public.scope_suggestions "
                    "SET status = %s, reviewed_at = now() "
                    "WHERE id = %s::uuid", (new_status, suggestion_id))
        # Post-review action depending on method
        if action == "accept":
            method = row["method"]
            target = row["target"]
            if method == "typosquat":
                # Add to the engagement's `typosquats` scope. The scope
                # gate's deny-list loader reads every engagement's
                # typosquats scope, so block semantics are preserved
                # cross-engagement while visibility is grouped per
                # engagement. REFUSE the write (not fall back to global
                # not_in_scope) when no active engagement — operator
                # tightening so a confirmed typosquat is never recorded
                # under the wrong engagement.
                eid = _resolve_engagement_id(None)
                if not eid:
                    raise HTTPException(
                        status_code=409,
                        detail=("Cannot confirm typosquat without an active "
                                "engagement. Select an engagement in the "
                                "header before confirming."),
                    )
                cur.execute(
                    "INSERT INTO public.scope_targets "
                    "(name, target, target_type, source, engagement_id) "
                    "VALUES ('typosquats', %s, 'domain', 'typosquat_review', %s::uuid) "
                    "ON CONFLICT DO NOTHING",
                    (target, eid),
                )
            elif method in ("cert_pivot", "asn_pivot"):
                # Promote into the engagement's `new_for_review` STAGING
                # scope — NOT the live in-scope list. The scope gate's
                # deny-list loader reads `new_for_review`, so the pivot is
                # visible under the engagement but dispatch is refused
                # until the operator moves it to a live scope. REFUSE the
                # write with no active engagement (same rule as typosquat)
                # so a pivot is never recorded under the wrong engagement.
                eid = _resolve_engagement_id(None)
                if not eid:
                    raise HTTPException(
                        status_code=409,
                        detail=("Cannot confirm pivot without an active "
                                "engagement. Select an engagement in the "
                                "header before confirming."),
                    )
                cur.execute(
                    "INSERT INTO public.scope_targets "
                    "(name, target, target_type, source, engagement_id) "
                    "VALUES ('new_for_review', %s, %s, %s, %s::uuid) "
                    "ON CONFLICT DO NOTHING",
                    (target, _pivot_target_type(target),
                     f"{method}_review", eid),
                )
        c.commit()
    return {"ok": True, "suggestion_id": suggestion_id,
            "new_status": new_status, "action": action}


@app.post("/scope-pivot/suggestions/review-bulk", tags=["Scope"])
def review_scope_suggestions_bulk(
    body: dict,
    authorized: bool = Depends(auth),
):
    """Operator bulk-review action on scope_suggestions rows.

    Body: {ids: [uuid, ...], action: "accept"|"reject"}.

    Runs ONE transaction over the whole batch — all-or-nothing per the
    scope-gate's fail-closed principle, so a mid-batch rejection on one
    row (e.g. a typosquat insert that races a duplicate) can't leave
    half the batch half-committed. Returns per-id outcomes
    (processed / not_found / error-reason) so the UI can show which
    rows landed and which did not.

    Each accepted row runs the same post-review side-effect as the
    single-row endpoint (typosquat → per-engagement `typosquats` scope;
    cert_pivot / asn_pivot → per-engagement `new_for_review` staging
    scope, which the gate refuses dispatch to until promoted).
    """
    ids = body.get("ids") or []
    action = (body.get("action") or "").lower().strip()
    if action not in ("accept", "reject"):
        raise HTTPException(status_code=400,
                            detail="action must be 'accept' or 'reject'")
    if not isinstance(ids, list) or not ids:
        raise HTTPException(status_code=400,
                            detail="ids must be a non-empty list of UUIDs")
    # Hard upper bound — the UI never has more than a page of pending rows
    # visible at once, and a 1 000-id batch is almost certainly a mis-call.
    if len(ids) > 500:
        raise HTTPException(status_code=400,
                            detail="batch size limited to 500 ids")
    new_status = "accepted" if action == "accept" else "rejected"
    results: dict = {}
    processed = 0
    with get_db() as c, c.cursor(cursor_factory=RealDictCursor) as cur:
        # Resolve the active engagement once; cert_pivot/asn_pivot accepts
        # all land on the same engagement for the batch (operator chose
        # which engagement is active before clicking). When any accept
        # is of a typosquat, the engagement is REQUIRED — refuse the
        # whole batch rather than scatter rows under a mix of engagement
        # attributions.
        eid = _resolve_engagement_id(None) if action == "accept" else None
        if action == "accept" and not eid:
            # Pre-flight: if any accepted row would be a typosquat, we
            # cannot proceed without engagement attribution.
            cur.execute(
                "SELECT COUNT(*) FROM public.scope_suggestions "
                "WHERE id = ANY(%s::uuid[]) AND method = 'typosquat'",
                ([str(x) for x in ids if x],),
            )
            n_typo = (cur.fetchone() or {}).get("count", 0)
            if n_typo:
                raise HTTPException(
                    status_code=409,
                    detail=(f"Cannot confirm {n_typo} typosquat(s) without "
                            f"an active engagement. Select an engagement "
                            f"in the header before bulk-confirming."),
                )
        for sid in ids:
            sid_s = str(sid).strip()
            if not sid_s:
                results[sid_s or "(empty)"] = "invalid_id"
                continue
            try:
                cur.execute(
                    "SELECT target, method FROM public.scope_suggestions "
                    "WHERE id = %s::uuid", (sid_s,))
            except Exception:  # noqa: BLE001 — malformed uuid
                results[sid_s] = "invalid_uuid"
                continue
            row = cur.fetchone()
            if not row:
                results[sid_s] = "not_found"
                continue
            cur.execute(
                "UPDATE public.scope_suggestions "
                "SET status = %s, reviewed_at = now() "
                "WHERE id = %s::uuid", (new_status, sid_s))
            if action == "accept":
                target = row["target"]
                method = row["method"]
                if method == "typosquat":
                    # Per-engagement `typosquats` scope. The pre-flight
                    # above ensures eid is set when a typosquat is in
                    # the batch, so this write never silently drops.
                    cur.execute(
                        "INSERT INTO public.scope_targets "
                        "(name, target, target_type, source, engagement_id) "
                        "VALUES ('typosquats', %s, 'domain', "
                        "'typosquat_review_bulk', %s::uuid) "
                        "ON CONFLICT DO NOTHING",
                        (target, eid),
                    )
                elif method in ("cert_pivot", "asn_pivot") and eid:
                    # Staging `new_for_review` scope — gate-blocked until
                    # the operator promotes it (see single-review note).
                    cur.execute(
                        "INSERT INTO public.scope_targets "
                        "(name, target, target_type, source, engagement_id) "
                        "VALUES ('new_for_review', %s, %s, %s, %s::uuid) "
                        "ON CONFLICT DO NOTHING",
                        (target, _pivot_target_type(target),
                         f"{method}_review_bulk", eid),
                    )
            results[sid_s] = "processed"
            processed += 1
        c.commit()
    return {
        "ok": True,
        "action": action,
        "requested": len(ids),
        "processed": processed,
        "new_status": new_status,
        "results": results,
    }


@app.post("/scope/exclude", tags=["Scope"])
def exclude_from_scope(
    body: dict,
    authorized: bool = Depends(auth),
):
    """Mark domains/targets as out of scope. Adds to 'not_in_scope' list.

    Body: {targets: ["domain1.com", "domain2.com"], source?: "manual"}
    """
    targets = body.get("targets", [])
    source = body.get("source", "manual")
    if not targets:
        raise HTTPException(status_code=400, detail="No targets provided")

    added = 0
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        for t in targets:
            target_val = t.strip() if isinstance(t, str) else ""
            if not target_val:
                continue
            # Idempotent insert into the global not_in_scope list. The legacy
            # UNIQUE(name,target) is gone (now UNIQUE(engagement_id,name,target)),
            # so guard on the NULL-engagement row set rather than ON CONFLICT.
            cur.execute(
                """INSERT INTO scope_targets (name, target, target_type, source)
                   SELECT 'not_in_scope', %s, 'domain', %s
                   WHERE NOT EXISTS (
                       SELECT 1 FROM scope_targets
                       WHERE engagement_id IS NULL AND name = 'not_in_scope' AND target = %s
                   )""",
                [target_val, source, target_val],
            )
            added += cur.rowcount
        conn.commit()
    return {"ok": True, "added": added, "scope": "not_in_scope"}


@app.delete("/scope/exclude", tags=["Scope"])
def remove_exclusion(
    body: dict,
    authorized: bool = Depends(auth),
):
    """Remove domains from the not_in_scope list (restore to scope).

    Body: {targets: ["domain1.com"]}
    """
    targets = body.get("targets", [])
    if not targets:
        raise HTTPException(status_code=400, detail="No targets provided")

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            "DELETE FROM scope_targets WHERE name = 'not_in_scope' AND target = ANY(%s)",
            [targets],
        )
        removed = cur.rowcount
        conn.commit()
    return {"ok": True, "removed": removed}


@app.get("/scope/excluded", tags=["Scope"])
def list_excluded(authorized: bool = Depends(auth)):
    """List all domains/targets marked as not_in_scope."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            "SELECT target, source, added_at FROM scope_targets WHERE name = 'not_in_scope' ORDER BY added_at DESC"
        )
        rows = [dict(r) for r in cur.fetchall()]
    return {"targets": rows, "total": len(rows)}


# ── Wordlist Management ──────────────────────────────────────────────────────

WORDLISTS_DIR = "/wordlists"
WORDLIST_EXTENSIONS = {".txt", ".lst", ".dict", ".wordlist"}

def _count_lines(path: str) -> int:
    try:
        with open(path, "rb") as f:
            return sum(1 for _ in f)
    except Exception:
        return 0

def _auto_register_host_files(conn):
    """Scan /wordlists/ directory and register any unregistered files."""
    if not os.path.isdir(WORDLISTS_DIR):
        return
    cur = conn.cursor(cursor_factory=RealDictCursor)
    cur.execute("SELECT path FROM wordlists")
    known_paths = {row["path"] for row in cur.fetchall()}
    for fname in os.listdir(WORDLISTS_DIR):
        fpath = os.path.join(WORDLISTS_DIR, fname)
        if not os.path.isfile(fpath):
            continue
        ext = os.path.splitext(fname)[1].lower()
        if ext not in WORDLIST_EXTENSIONS:
            continue
        if fpath in known_paths:
            continue
        size = os.path.getsize(fpath)
        lines = _count_lines(fpath)
        cur.execute(
            """INSERT INTO wordlists (name, path, source, list_type, line_count, size_bytes)
               VALUES (%s, %s, 'host', 'passwords', %s, %s)
               ON CONFLICT (name) DO NOTHING""",
            [fname, fpath, lines, size],
        )
    conn.commit()

@app.get("/wordlists", tags=["Wordlists"])
def list_wordlists(authorized: bool = Depends(auth)):
    """List all registered wordlists, auto-registering host files."""
    with get_db() as conn:
        _auto_register_host_files(conn)
        cur = conn.cursor(cursor_factory=RealDictCursor)
        cur.execute("SELECT * FROM wordlists ORDER BY created_at DESC")
        rows = cur.fetchall()
    for r in rows:
        r["id"] = str(r["id"])
        r["created_at"] = r["created_at"].isoformat() if r.get("created_at") else None
    return {"ok": True, "wordlists": rows}

@app.post("/wordlists/resolve-command", tags=["Wordlists"])
def resolve_command_wordlists(body: dict, _: bool = Depends(auth)):
    """Fill {user_list}/{password_list} in a command with readable paths.

    The BFF cannot import `etl/` (no such mount on pentest-dashboard) and has no
    database, so rather than duplicate this logic there — and need an agreement
    test to keep two copies honest — the dispatcher asks here.

    Falls back to the STATIC short lists if building fails: 17 x 25 = 425
    candidates, never rockyou's 243,854,783, and never a leftover placeholder for
    the listener to refuse. `source` reports which path was taken, because a
    silent fallback would hide that the discovered usernames were not used.
    """
    command = (body or {}).get("command") or ""
    target = (body or {}).get("target") or ""
    port = (body or {}).get("port")
    service = (body or {}).get("service") or ""
    if not command:
        raise HTTPException(400, "command is required")

    import sys as _sys
    if "/app" not in _sys.path:
        _sys.path.insert(0, "/app")
    import target_wordlists as tw

    if not tw.needs_lists(command):
        return {"ok": True, "command": command, "changed": False,
                "source": "not_needed"}
    if not target:
        raise HTTPException(400, "target is required to build per-target lists")

    from etl.scope_gate import check_dispatch, load_dispatch_scope
    with get_db() as conn, conn.cursor() as cur:
        scope_rows, scope_source = load_dispatch_scope(cur, None)
        if scope_source == "unavailable":
            raise HTTPException(503, "scope could not be loaded — refusing")
        refusal = check_dispatch(target, scope_rows)
        if refusal:
            raise HTTPException(403, f"Out of scope — {refusal}")
        result = tw.resolve_command(cur, command, target, port=port,
                                    service_hint=service)
    return {"ok": True, **result}


@app.post("/wordlists/build-target", tags=["Wordlists"])
def build_target_wordlists(target: str = Query(...),
                           port: int = Query(None),
                           service: str = Query(""),
                           include_curated: bool = Query(True),
                           write: bool = Query(True),
                           _: bool = Depends(auth)):
    """Build the candidate lists for one target/service, ordered by priority.

    Composition, cheapest and most likely first:
      1. usernames discovered ON THIS HOST — enum4linux-ng found 35
      2. the documented default pair for the SERVICE
      3. the username as its own password — how msfadmin:msfadmin works, and a
         pair the generic 25-entry shortlist could never produce
      4. the generic curated shortlist, as the tail

    Order is priority because hydra reads the file top to bottom: a pair that is
    going to be found is found in the first few hundred attempts rather than
    after the generic tail. Every entry carries its provenance so a recovered
    credential can be traced back to the evidence that suggested it.

    Scope-gated: building a list for a host names that host, and an
    out-of-scope target must not be prepared for attack any more than scanned.
    """
    import sys as _sys
    if "/app" not in _sys.path:
        _sys.path.insert(0, "/app")
    from etl.scope_gate import check_dispatch, load_dispatch_scope
    import target_wordlists as tw

    with get_db() as conn, conn.cursor() as cur:
        scope_rows, scope_source = load_dispatch_scope(cur, None)
        if scope_source == "unavailable":
            raise HTTPException(503, "scope could not be loaded — refusing")
        refusal = check_dispatch(target, scope_rows)
        if refusal:
            raise HTTPException(403, f"Out of scope — {refusal}")
        built = tw.build_lists(cur, target, port=port, service_hint=service,
                               include_curated=include_curated)

    paths = {}
    if write:
        try:
            paths = tw.write_lists(built)
        except OSError as e:
            raise HTTPException(500, f"could not write lists: {e}")
        # Register so the lists appear alongside every other selectable option.
        with get_db() as conn, conn.cursor() as cur:
            for kind in ("users", "passwords"):
                path = paths.get(kind)
                if not path:
                    continue
                cur.execute("""
                    INSERT INTO wordlists (name, path, source, list_type,
                                           line_count, size_bytes, description)
                    VALUES (%s,%s,'generated',%s,%s,%s,%s)
                    ON CONFLICT (path) DO UPDATE
                       SET line_count = EXCLUDED.line_count,
                           size_bytes = EXCLUDED.size_bytes,
                           description = EXCLUDED.description
                """, (os.path.basename(path), path,
                      "usernames" if kind == "users" else "passwords",
                      paths.get(f"{kind}_lines"),
                      os.path.getsize(path) if os.path.exists(path) else None,
                      f"generated for {target}"
                      f"{'/' + (built.get('service') or '') if built.get('service') else ''}"
                      f" — {built['counts']['discovered_usernames']} discovered usernames"))
            conn.commit()

    try:
        from webhooks import emit_webhook
        emit_webhook("target_wordlists_built", "wordlists", {
            "target": target, "service": built.get("service"), "port": port,
            **built["counts"], "paths": paths})
    except Exception:
        pass

    # The candidate count is reported so the operator sees what the listener's
    # guard will judge BEFORE dispatching, rather than after a refusal.
    return {"ok": True, **{k: v for k, v in built.items()
                           if k not in ("user_provenance", "password_provenance")},
            "provenance": {"users": built["user_provenance"],
                           "passwords": built["password_provenance"]},
            "paths": paths}


@app.post("/wordlists/discover", tags=["Wordlists"])
def discover_image_wordlists(curated_only: bool = Query(False),
                             min_lines: int = Query(2, ge=1),
                             _: bool = Depends(auth)):
    """Register the wordlists that exist inside kali-listener.

    The registry held TWO rows because `_auto_register_host_files` only ever
    looked at rag-api's host-mounted /wordlists — while every brute-force
    command in the catalogue names /usr/share/wordlists/..., which exists only
    in the listener image. So the operator could not select from the lists
    actually in use, and the one they were given by default was rockyou.

    Line counts come from the listener, the same source the candidate-space
    guard enforces on, so an advertised size and an enforced size cannot differ.
    """
    import httpx as _hx
    base = os.environ.get("KALI_LISTENER_URL", "https://kali-listener:8019")
    try:
        with _hx.Client(verify=False, timeout=120) as c:
            resp = c.get(f"{base}/wordlists/inventory",
                         params={"curated_only": curated_only,
                                 "min_lines": min_lines, "max_files": 2000})
            resp.raise_for_status()
            body = resp.json()
    except Exception as e:
        raise HTTPException(502, f"could not read listener wordlist inventory: {e}")

    rows = body.get("wordlists") or []
    # `name` is UNIQUE and seclists ships the same basename in several
    # directories, so a bare basename would raise on the second one. Only the
    # colliding names are qualified, and by parent directory, so the common case
    # stays readable and the result is deterministic.
    from collections import Counter
    basename_counts = Counter(w["name"] for w in rows)
    for w in rows:
        if basename_counts[w["name"]] > 1:
            parent = os.path.basename(os.path.dirname(w["path"]))
            w["_store_name"] = f"{parent}/{w['name']}"
        else:
            w["_store_name"] = w["name"]

    added = updated = failed = 0
    problems = []
    with get_db() as conn, conn.cursor() as cur:
        for w in rows:
            # A savepoint per row: one name collision with a pre-existing host
            # row must not abort the whole batch.
            cur.execute("SAVEPOINT wl")
            try:
                cur.execute("""
                INSERT INTO wordlists (name, path, source, list_type,
                                       line_count, size_bytes, description)
                VALUES (%s,%s,'image:kali-listener',%s,%s,%s,%s)
                ON CONFLICT (path) DO UPDATE
                   SET line_count = EXCLUDED.line_count,
                       size_bytes = EXCLUDED.size_bytes,
                       list_type  = EXCLUDED.list_type,
                       description = EXCLUDED.description
                    RETURNING (xmax = 0) AS inserted
                """, (w["_store_name"], w["path"], w["list_type"],
                      w["line_count"], w.get("size_bytes"),
                      f"size_verdict={w['size_verdict']}"
                      + (" curated" if w.get("curated") else "")))
                got = cur.fetchone()
                cur.execute("RELEASE SAVEPOINT wl")
                if got is not None:
                    was_new = got["inserted"] if isinstance(got, dict) else got[0]
                    if was_new:
                        added += 1
                    else:
                        updated += 1
            except Exception as e:
                cur.execute("ROLLBACK TO SAVEPOINT wl")
                # The batch-level disambiguation cannot see PRE-EXISTING rows:
                # rockyou.txt was already registered from the host mount at a
                # different path, so the image copy collided on `name`. Retry
                # once, parent-qualified.
                parent = os.path.basename(os.path.dirname(w["path"]))
                retry_name = f"{parent}/{w['name']}"
                if retry_name == w["_store_name"]:
                    failed += 1
                    if len(problems) < 10:
                        problems.append(f"{w['path']}: {type(e).__name__}: {e}")
                    continue
                cur.execute("SAVEPOINT wl2")
                try:
                    cur.execute("""
                        INSERT INTO wordlists (name, path, source, list_type,
                                               line_count, size_bytes, description)
                        VALUES (%s,%s,'image:kali-listener',%s,%s,%s,%s)
                        ON CONFLICT (path) DO UPDATE
                           SET line_count = EXCLUDED.line_count,
                               size_bytes = EXCLUDED.size_bytes,
                               list_type  = EXCLUDED.list_type
                        RETURNING (xmax = 0) AS inserted
                    """, (retry_name, w["path"], w["list_type"], w["line_count"],
                          w.get("size_bytes"),
                          f"size_verdict={w['size_verdict']}"))
                    got = cur.fetchone()
                    cur.execute("RELEASE SAVEPOINT wl2")
                    if got is not None:
                        was_new = got["inserted"] if isinstance(got, dict) else got[0]
                        added += 1 if was_new else 0
                        updated += 0 if was_new else 1
                except Exception as e2:
                    cur.execute("ROLLBACK TO SAVEPOINT wl2")
                    failed += 1
                    if len(problems) < 10:
                        problems.append(f"{w['path']}: {type(e2).__name__}: {e2}")
        conn.commit()
    try:
        from webhooks import emit_webhook
        emit_webhook("wordlists_discovered", "wordlists", {
            "seen": len(rows), "added": added, "updated": updated,
            "curated_only": curated_only})
    except Exception:
        pass
    return {"ok": True, "seen": len(rows), "added": added, "updated": updated,
            "failed": failed, "problems": problems,
            "thresholds": body.get("thresholds")}


@app.post("/wordlists/upload", tags=["Wordlists"])
def upload_wordlist(
    file: UploadFile = File(...),
    list_type: str = "passwords",
    description: str = None,
    authorized: bool = Depends(auth),
):
    """Upload a wordlist file, save to /wordlists/, register in DB."""
    os.makedirs(WORDLISTS_DIR, exist_ok=True)
    fname = file.filename or "uploaded_wordlist.txt"
    dest = os.path.join(WORDLISTS_DIR, fname)
    with open(dest, "wb") as f:
        data = file.file.read()
        f.write(data)
    size = len(data)
    lines = _count_lines(dest)
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            """INSERT INTO wordlists (name, path, source, list_type, line_count, size_bytes, description)
               VALUES (%s, %s, 'upload', %s, %s, %s, %s)
               ON CONFLICT (name) DO UPDATE SET
                 path = EXCLUDED.path, line_count = EXCLUDED.line_count,
                 size_bytes = EXCLUDED.size_bytes, description = EXCLUDED.description
               RETURNING id""",
            [fname, dest, list_type, lines, size, description],
        )
        row = cur.fetchone()
        conn.commit()
    return {"ok": True, "id": str(row["id"]), "name": fname, "line_count": lines, "size_bytes": size}

@app.get("/wordlists/{wordlist_id}", tags=["Wordlists"])
def get_wordlist(wordlist_id: str, authorized: bool = Depends(auth)):
    """Get single wordlist metadata."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM wordlists WHERE id = %s", [wordlist_id])
        row = cur.fetchone()
    if not row:
        raise HTTPException(status_code=404, detail="Wordlist not found")
    row["id"] = str(row["id"])
    row["created_at"] = row["created_at"].isoformat() if row.get("created_at") else None
    return {"ok": True, "wordlist": row}

@app.delete("/wordlists/{wordlist_id}", tags=["Wordlists"])
def delete_wordlist(wordlist_id: str, authorized: bool = Depends(auth)):
    """Remove wordlist record (and file if source='upload')."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM wordlists WHERE id = %s", [wordlist_id])
        row = cur.fetchone()
        if not row:
            raise HTTPException(status_code=404, detail="Wordlist not found")
        if row["source"] == "upload" and os.path.exists(row["path"]):
            os.remove(row["path"])
        cur.execute("DELETE FROM wordlists WHERE id = %s", [wordlist_id])
        conn.commit()
    return {"ok": True, "deleted": str(row["id"])}


## --- Content Extractions + Wordlist Generation endpoints ---

@app.get("/content-extractions", tags=["Content Intel"])
def list_content_extractions(
    asset_id: str = None,
    scan_id: str = None,
    search: str = None,
    limit: int = 100,
    authorized: bool = Depends(auth),
):
    """List content extractions with optional filters. search matches IP or hostname."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        conditions = []
        params = []
        # Scope to the active engagement via the linked asset (content_extractions
        # has no engagement_id) so the list isn't cross-engagement.
        _eid = _validate_engagement_uuid(_resolve_engagement_id())
        if _eid:
            conditions.append("ce.asset_id IN (SELECT id FROM assets WHERE engagement_id = %s::uuid)")
            params.append(_eid)
        if asset_id:
            conditions.append("ce.asset_id = %s")
            params.append(asset_id)
        if scan_id:
            conditions.append("ce.scan_id = %s")
            params.append(scan_id)
        if search:
            conditions.append(
                "(ce.asset_id IN (SELECT id FROM assets WHERE hostname ILIKE %s OR host(ip)::text ILIKE %s)"
                " OR ce.url ILIKE %s)"
            )
            like = f"%{search}%"
            params.extend([like, like, like])
        where = f"WHERE {' AND '.join(conditions)}" if conditions else ""
        params.append(limit)
        cur.execute(
            f"SELECT ce.* FROM content_extractions ce {where} ORDER BY ce.created_at DESC LIMIT %s",
            params,
        )
        rows = cur.fetchall()
    for r in rows:
        r["id"] = str(r["id"])
        if r.get("scan_id"):
            r["scan_id"] = str(r["scan_id"])
        if r.get("asset_id"):
            r["asset_id"] = str(r["asset_id"])
        r["created_at"] = r["created_at"].isoformat() if r.get("created_at") else None
        # Truncate word_corpus in list view
        if r.get("word_corpus") and len(r["word_corpus"]) > 500:
            r["word_corpus"] = r["word_corpus"][:500] + "..."
    return {"ok": True, "extractions": rows, "count": len(rows)}


@app.get("/content-extractions/summary", tags=["Content Intel"])
def content_extraction_summary(
    asset_id: str = None,
    search: str = None,
    scope: str = None,
    engagement_id: str = None,
    authorized: bool = Depends(auth),
):
    """Aggregated counts of extracted content intelligence.

    Counts are calculated for the active ENGAGEMENT and (optional) SCOPE, so the
    summary matches the scope-filtered list rather than showing global totals.
    content_extractions has no engagement_id column, so engagement is applied via
    the linked asset; scope is a URL substring match on the scope's targets, the
    same rule the Content Intel list uses client-side.
    """
    eid = _validate_engagement_uuid(_resolve_engagement_id(engagement_id))
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        conditions = []
        params = []
        if asset_id:
            conditions.append("asset_id = %s")
            params.append(asset_id)
        if eid:
            conditions.append(
                "asset_id IN (SELECT id FROM assets WHERE engagement_id = %s::uuid)")
            params.append(eid)
        if scope:
            cur.execute(
                "SELECT target FROM scope_targets WHERE lower(name) = lower(%s)", (scope,))
            pats = []
            for (t,) in cur.fetchall():
                tv = (t or "").strip()
                if not tv:  # blank target = %% wildcard trap — skip
                    continue
                pats.append(f"%{tv}%")
                if "://" in tv:  # url target → also match its bare host
                    host = tv.split("://", 1)[1].split("/", 1)[0].split(":")[0]
                    if host:
                        pats.append(f"%{host}%")
            # A selected scope with no concrete target matches nothing (not
            # everything) — otherwise the counts would silently show all rows.
            conditions.append("url ILIKE ANY(%s)" if pats else "false")
            if pats:
                params.append(pats)
        if search:
            like = f"%{search}%"
            conditions.append(
                "(asset_id IN (SELECT id FROM assets WHERE hostname ILIKE %s OR host(ip)::text ILIKE %s)"
                " OR url ILIKE %s)"
            )
            params.extend([like, like, like])
        condition = f"WHERE {' AND '.join(conditions)}" if conditions else ""
        cur.execute(
            f"""SELECT
                count(*) as total_extractions,
                coalesce(sum(jsonb_array_length(emails)), 0) as total_emails,
                coalesce(sum(jsonb_array_length(names)), 0) as total_names,
                coalesce(sum(jsonb_array_length(internal_paths)), 0) as total_paths,
                coalesce(sum(jsonb_array_length(api_endpoints)), 0) as total_api_endpoints,
                coalesce(sum(jsonb_array_length(exposed_keys)), 0) as total_exposed_keys,
                coalesce(sum(jsonb_array_length(tech_indicators)), 0) as total_tech_indicators,
                coalesce(sum(jsonb_array_length(comments)), 0) as total_comments,
                coalesce(sum(jsonb_array_length(hidden_inputs)), 0) as total_hidden_inputs,
                coalesce(sum(jsonb_array_length(interesting_files)), 0) as total_interesting_files,
                coalesce(sum(jsonb_array_length(file_metadata)), 0) as total_file_metadata,
                coalesce(sum(jsonb_array_length(login_pages)), 0) as total_login_pages
            FROM content_extractions {condition}""",
            params,
        )
        row = cur.fetchone()
    return {"ok": True, "summary": {k: int(v) for k, v in row.items()}}


## --- Sitemap / URL inventory ---

@app.get("/content-intel/sitemap", tags=["Content Intel"])
def content_intel_sitemap(
    domain: str = None,
    asset_id: str = None,
    search: str = None,
    authorized: bool = Depends(auth),
):
    """Unified sitemap: all discovered URLs for a domain from every source.

    Merges URLs from web_findings, content_extractions (internal_paths, api_endpoints),
    discovered_params, playwright_scans, and dom_analysis into a deduplicated list
    with source attribution, method, status code, and finding counts.
    """
    # Resolve search to domain if provided
    if search and not domain:
        domain = search
    if not domain and not asset_id:
        raise HTTPException(400, "Provide 'domain', 'search', or 'asset_id' parameter")

    like = f"%{domain}%" if domain else None

    urls: dict = {}  # path -> {methods, sources, status_codes, findings, params}

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # 1. web_findings
        if like:
            cur.execute("""
                SELECT url, source, method, status_code, severity, name
                FROM web_findings WHERE url ILIKE %s
                ORDER BY url""", [like])
        else:
            cur.execute("""
                SELECT wf.url, wf.source, wf.method, wf.status_code, wf.severity, wf.name
                FROM web_findings wf
                WHERE wf.asset_id = %s ORDER BY wf.url""", [asset_id])
        for r in cur.fetchall():
            u = r["url"] or ""
            if u not in urls:
                urls[u] = {"url": u, "methods": set(), "sources": set(),
                           "status_codes": set(), "findings": 0, "params": [],
                           "severities": set()}
            if r["method"]:
                urls[u]["methods"].add(r["method"])
            urls[u]["sources"].add(r["source"] or "unknown")
            if r["status_code"]:
                urls[u]["status_codes"].add(r["status_code"])
            urls[u]["findings"] += 1
            if r["severity"]:
                urls[u]["severities"].add(r["severity"])

        # 2. content_extractions — internal_paths and api_endpoints
        if like:
            cur.execute("""
                SELECT url, internal_paths, api_endpoints
                FROM content_extractions WHERE url ILIKE %s""", [like])
        else:
            cur.execute("""
                SELECT url, internal_paths, api_endpoints
                FROM content_extractions WHERE asset_id = %s""", [asset_id])
        for r in cur.fetchall():
            base = r["url"] or ""
            from urllib.parse import urlparse as _up
            parsed = _up(base)
            base_prefix = f"{parsed.scheme}://{parsed.netloc}" if parsed.scheme else ""
            for path in (r.get("internal_paths") or []):
                full = f"{base_prefix}{path}" if path.startswith("/") else path
                if full not in urls:
                    urls[full] = {"url": full, "methods": set(), "sources": set(),
                                  "status_codes": set(), "findings": 0, "params": [],
                                  "severities": set()}
                urls[full]["sources"].add("content-extraction")
            for ep in (r.get("api_endpoints") or []):
                full = f"{base_prefix}{ep}" if ep.startswith("/") else ep
                if full not in urls:
                    urls[full] = {"url": full, "methods": set(), "sources": set(),
                                  "status_codes": set(), "findings": 0, "params": [],
                                  "severities": set()}
                urls[full]["sources"].add("content-extraction")

        # 3. discovered_params
        if like:
            cur.execute("""
                SELECT url_pattern, param_name, http_method, param_location, param_type
                FROM discovered_params WHERE url_pattern ILIKE %s""", [like])
        else:
            cur.execute("""
                SELECT url_pattern, param_name, http_method, param_location, param_type
                FROM discovered_params WHERE asset_id = %s""", [asset_id])
        for r in cur.fetchall():
            u = r["url_pattern"]
            if u not in urls:
                urls[u] = {"url": u, "methods": set(), "sources": set(),
                           "status_codes": set(), "findings": 0, "params": [],
                           "severities": set()}
            urls[u]["methods"].add(r["http_method"])
            urls[u]["sources"].add("param-discovery")
            urls[u]["params"].append({
                "name": r["param_name"],
                "type": r["param_type"],
                "location": r["param_location"],
            })

        # 4. playwright_scans
        if like:
            cur.execute("SELECT DISTINCT url FROM playwright_scans WHERE url ILIKE %s", [like])
        else:
            cur.execute("SELECT DISTINCT url FROM playwright_scans WHERE asset_id = %s", [asset_id])
        for r in cur.fetchall():
            u = r["url"]
            if u not in urls:
                urls[u] = {"url": u, "methods": {"GET"}, "sources": set(),
                           "status_codes": set(), "findings": 0, "params": [],
                           "severities": set()}
            urls[u]["sources"].add("playwright")

    # Serialize sets to lists
    result = []
    for u, data in sorted(urls.items()):
        result.append({
            "url": data["url"],
            "methods": sorted(data["methods"]),
            "sources": sorted(data["sources"]),
            "status_codes": sorted(data["status_codes"]),
            "findings": data["findings"],
            "params": data["params"],
            "severities": sorted(data["severities"]),
        })

    return {"ok": True, "urls": result, "total": len(result), "domain": domain}


@app.get("/content-intel/sitemap/export/burp", tags=["Content Intel"])
def export_sitemap_burp_xml(
    domain: str = None,
    asset_id: str = None,
    authorized: bool = Depends(auth),
):
    """Export sitemap as Burp Suite-compatible XML for import."""
    data = content_intel_sitemap(domain=domain, asset_id=asset_id, authorized=True)
    urls_list = data.get("urls", [])

    from xml.sax.saxutils import escape as xml_escape
    import base64

    lines = ['<?xml version="1.0"?>', '<items burpVersion="2024.0" exportTime="">']
    for entry in urls_list:
        url = entry["url"]
        method = entry["methods"][0] if entry["methods"] else "GET"
        from urllib.parse import urlparse as _up2
        p = _up2(url)
        host = p.hostname or p.netloc or domain or ""
        port = p.port or (443 if p.scheme == "https" else 80)
        protocol = p.scheme or "https"
        path = p.path or "/"
        if p.query:
            path += f"?{p.query}"

        req_str = f"{method} {path} HTTP/1.1\r\nHost: {host}\r\n\r\n"
        req_b64 = base64.b64encode(req_str.encode()).decode()

        comment_parts = []
        if entry["sources"]:
            comment_parts.append(f"Sources: {', '.join(entry['sources'])}")
        if entry["findings"]:
            comment_parts.append(f"Findings: {entry['findings']}")
        if entry["params"]:
            param_names = [pr["name"] for pr in entry["params"]]
            comment_parts.append(f"Params: {', '.join(param_names)}")
        comment = " | ".join(comment_parts)

        lines.append("  <item>")
        lines.append(f"    <url>{xml_escape(url)}</url>")
        lines.append(f"    <host ip=\"\">{xml_escape(host)}</host>")
        lines.append(f"    <port>{port}</port>")
        lines.append(f"    <protocol>{protocol}</protocol>")
        lines.append(f"    <method>{xml_escape(method)}</method>")
        lines.append(f"    <path>{xml_escape(path)}</path>")
        lines.append(f"    <request base64=\"true\">{req_b64}</request>")
        lines.append(f"    <status>200</status>")
        lines.append(f"    <responselength>0</responselength>")
        lines.append(f"    <mimetype>text/html</mimetype>")
        lines.append(f"    <comment>{xml_escape(comment)}</comment>")
        lines.append("  </item>")
    lines.append("</items>")

    xml_content = "\n".join(lines)
    fname = f"sitemap_{domain or 'export'}.xml"
    return Response(
        content=xml_content,
        media_type="application/xml",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


@app.get("/content-intel/sitemap/export/urls", tags=["Content Intel"])
def export_sitemap_urls_txt(
    domain: str = None,
    asset_id: str = None,
    authorized: bool = Depends(auth),
):
    """Export sitemap as plain text URL list (one per line) for ZAP/tools import."""
    data = content_intel_sitemap(domain=domain, asset_id=asset_id, authorized=True)
    urls_list = data.get("urls", [])
    text = "\n".join(entry["url"] for entry in urls_list)
    fname = f"urls_{domain or 'export'}.txt"
    return Response(
        content=text,
        media_type="text/plain",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


