@app.get("/content-intel/patterns", tags=["Content Intel"])
def list_patterns(category: str = None, authorized: bool = Depends(auth)):
    """List content intel extraction patterns."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        if category:
            cur.execute(
                "SELECT * FROM content_intel_patterns WHERE category = %s ORDER BY category, name",
                [category],
            )
        else:
            cur.execute("SELECT * FROM content_intel_patterns ORDER BY category, name")
        rows = cur.fetchall()
    for r in rows:
        r["id"] = str(r["id"])
        r["created_at"] = r["created_at"].isoformat() if r.get("created_at") else None
        r["updated_at"] = r["updated_at"].isoformat() if r.get("updated_at") else None
    return {"ok": True, "patterns": rows}


@app.post("/content-intel/patterns", tags=["Content Intel"])
def create_pattern(body: dict, authorized: bool = Depends(auth)):
    """Create a custom content extraction pattern."""
    category = body.get("category")
    name = body.get("name")
    pattern = body.get("pattern")
    if not all([category, name, pattern]):
        raise HTTPException(400, "category, name, and pattern are required")
    # Validate regex
    try:
        import re as _re
        _re.compile(pattern)
    except _re.error as e:
        raise HTTPException(400, f"Invalid regex pattern: {e}")
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            """INSERT INTO content_intel_patterns
               (category, name, pattern, label, enabled, description)
               VALUES (%s, %s, %s, %s, %s, %s) RETURNING id""",
            (category, name, pattern,
             body.get("label", name),
             body.get("enabled", True),
             body.get("description")),
        )
        row = cur.fetchone()
        conn.commit()
    return {"ok": True, "id": str(row["id"])}


@app.put("/content-intel/patterns/{pattern_id}", tags=["Content Intel"])
def update_pattern(pattern_id: str, body: dict, authorized: bool = Depends(auth)):
    """Update a content extraction pattern."""
    if body.get("pattern"):
        try:
            import re as _re
            _re.compile(body["pattern"])
        except _re.error as e:
            raise HTTPException(400, f"Invalid regex pattern: {e}")
    updates = []
    params = []
    for field in ("category", "name", "pattern", "label", "enabled", "description"):
        if field in body:
            updates.append(f"{field} = %s")
            params.append(body[field])
    if not updates:
        raise HTTPException(400, "No fields to update")
    updates.append("updated_at = now()")
    params.append(pattern_id)
    with get_db() as conn, conn.cursor() as cur:
        cur.execute(
            f"UPDATE content_intel_patterns SET {', '.join(updates)} WHERE id = %s",
            params,
        )
        if cur.rowcount == 0:
            raise HTTPException(404, "Pattern not found")
        conn.commit()
    return {"ok": True}


@app.delete("/content-intel/patterns/{pattern_id}", tags=["Content Intel"])
def delete_pattern(pattern_id: str, authorized: bool = Depends(auth)):
    """Delete a content extraction pattern."""
    with get_db() as conn, conn.cursor() as cur:
        cur.execute("DELETE FROM content_intel_patterns WHERE id = %s", [pattern_id])
        if cur.rowcount == 0:
            raise HTTPException(404, "Pattern not found")
        conn.commit()
    return {"ok": True}


## --- Content Extraction manual editing ---

@app.patch("/content-extractions/{extraction_id}", tags=["Content Intel"])
def update_extraction(extraction_id: str, body: dict, authorized: bool = Depends(auth)):
    """Manually edit a content extraction's data fields."""
    allowed = ("emails", "names", "internal_paths", "api_endpoints",
               "exposed_keys", "tech_indicators", "comments", "hidden_inputs",
               "interesting_files", "file_metadata", "js_configs")
    updates = []
    params = []
    for field in allowed:
        if field in body:
            updates.append(f"{field} = %s")
            params.append(Json(body[field]))
    if not updates:
        raise HTTPException(400, f"No editable fields provided. Allowed: {', '.join(allowed)}")
    params.append(extraction_id)
    with get_db() as conn, conn.cursor() as cur:
        cur.execute(
            f"UPDATE content_extractions SET {', '.join(updates)} WHERE id = %s",
            params,
        )
        if cur.rowcount == 0:
            raise HTTPException(404, "Extraction not found")
        conn.commit()
    return {"ok": True}


@app.delete("/content-extractions/{extraction_id}", tags=["Content Intel"])
def delete_extraction(extraction_id: str, authorized: bool = Depends(auth)):
    """Delete a content extraction."""
    with get_db() as conn, conn.cursor() as cur:
        cur.execute("DELETE FROM content_extractions WHERE id = %s", [extraction_id])
        if cur.rowcount == 0:
            raise HTTPException(404, "Extraction not found")
        conn.commit()
    return {"ok": True}


@app.post("/wordlists/generate", tags=["Wordlists"])
def generate_wordlist_endpoint(
    body: dict,
    authorized: bool = Depends(auth),
):
    """Generate CeWL-style wordlist from content extractions."""
    from wordlist_generator import generate_wordlist

    try:
        result = generate_wordlist(
            asset_id=body.get("asset_id"),
            scan_id=body.get("scan_id"),
            list_type=body.get("list_type", "passwords"),
            min_word_length=body.get("min_word_length", 5),
            max_lines=body.get("max_lines", 50000),
            enable_mutations=body.get("enable_mutations", True),
            mutations=body.get("mutations"),
            include_sources=body.get("include_sources"),
        )
    except ValueError as e:
        raise HTTPException(404, str(e))
    except Exception as e:
        raise HTTPException(500, f"Generation failed: {e}")

    return {"ok": True, **result}


## --- Data Export / Import endpoints ---

import csv
import io
import zipfile
import hashlib

# Category → table mapping for export
EXPORT_CATEGORIES = {
    "assets":      ["assets", "ports"],
    "findings":    ["vulns", "web_findings", "playwright_findings"],
    # The infrastructure rollup: one row per shared problem rather than one per
    # virtual host. Until now nothing but a test read this view, so a report of
    # 778 web findings gave no way to see that they collapse to 13 problems.
    "infrastructure": ["v_infrastructure_findings"],
    "recon":       ["recon_findings"],
    "credentials": ["credential_findings"],
    "params":      ["discovered_params"],
    "exploits":    ["pending_exploits", "exploit_results"],
    "screenshots": ["screenshot_metadata"],
}


def _severity_to_nessus(sev: str) -> int:
    """Map severity string to Nessus numeric risk level."""
    return {"info": 0, "low": 1, "medium": 2, "high": 3, "critical": 4}.get(
        (sev or "info").lower(), 0
    )


def _serialize_value(val):
    """Serialize a single value for JSON export (handles datetimes, inet, etc.)."""
    if val is None:
        return None
    if isinstance(val, datetime):
        return val.isoformat()
    if hasattr(val, "__str__") and type(val).__name__ in ("IPv4Address", "IPv6Address"):
        return str(val)
    if isinstance(val, (dict, list)):
        return val
    if isinstance(val, (int, float, bool, str)):
        return val
    # psycopg2 inet type, UUID, Decimal, etc.
    return str(val)


# Views and a few tables have no created_at, and an unconditional
# `ORDER BY created_at` turns adding one to an export category into a 500.
# Resolved from the catalog rather than hard-coded per table.
_EXPORT_ORDER_PREFERENCE = ("created_at", "last_seen", "discovered_at",
                            "first_seen", "updated_at")


def _export_order_column(cur, table: str) -> Optional[str]:
    cur.execute("""
        SELECT column_name FROM information_schema.columns
         WHERE table_schema = 'public' AND table_name = %s
    """, (table,))
    have = {r[0] if not isinstance(r, dict) else r["column_name"]
            for r in cur.fetchall()}
    for col in _EXPORT_ORDER_PREFERENCE:
        if col in have:
            return col
    return None


def _export_web_findings(cur, include_inventory: bool,
                         collapse_problems: bool, limit: int = 50000,
                         engagement_id: str = None) -> list:
    """web_findings for /export/data, honouring the same two switches the
    findings search and the SARIF export honour.

    DISTINCT ON keys on COALESCE(infrastructure_fingerprint, id::text), never on
    the fingerprint alone: it is NULL for every ungroupable row, and in Postgres
    a DISTINCT ON over a NULL key folds ALL of them into one row — which would
    silently drop hundreds of unrelated findings from the export.
    """
    where = "WHERE 1=1"
    eng_params: list = []
    if engagement_id:  # scope the export to the active engagement
        where += " AND engagement_id = %s::uuid"
        eng_params.append(engagement_id)
    if not include_inventory:
        where += " AND COALESCE(record_kind, 'finding') = 'finding'"
    if collapse_problems:
        sql = f"""
            SELECT * FROM (
                SELECT DISTINCT ON (COALESCE(infrastructure_fingerprint, id::text)) *
                  FROM public.web_findings
                  {where}
                 ORDER BY COALESCE(infrastructure_fingerprint, id::text),
                          public.severity_rank(severity) DESC, last_seen DESC
            ) collapsed
            ORDER BY public.severity_rank(severity) DESC, last_seen DESC
            LIMIT %s
        """
    else:
        sql = f"""
            SELECT * FROM public.web_findings
            {where}
            ORDER BY last_seen DESC
            LIMIT %s
        """
    cur.execute(sql, eng_params + [limit])
    cols = [d[0] for d in cur.description]
    return [{c: _serialize_value(r[c]) for c in cols} for r in cur.fetchall()]


def _export_table_rows(cur, table: str, limit: int = 50000,
                       engagement_id: str = None) -> list:
    """Generic SELECT * from a table or view, with safe serialization.

    When engagement_id is given, scope collected-data tables to it: filter by the
    table's own engagement_id, or (for tables that only carry asset_id) via the
    linked asset. A table with neither column is cross-engagement config/technique
    data and is exported unscoped."""
    where_sql, eng_params = "", []
    if engagement_id:
        cur.execute(
            "SELECT column_name FROM information_schema.columns WHERE table_name = %s",
            (table,))
        cols_present = {(r["column_name"] if isinstance(r, dict) else r[0])
                        for r in cur.fetchall()}
        if "engagement_id" in cols_present:
            where_sql = "WHERE engagement_id = %s::uuid"
            eng_params.append(engagement_id)
        elif "asset_id" in cols_present:
            where_sql = "WHERE asset_id IN (SELECT id FROM assets WHERE engagement_id = %s::uuid)"
            eng_params.append(engagement_id)
    order_col = _export_order_column(cur, table)
    order_sql = f"ORDER BY {order_col} DESC" if order_col else ""
    cur.execute(f"SELECT * FROM {table} {where_sql} {order_sql} LIMIT %s",
                eng_params + [limit])
    cols = [desc[0] for desc in cur.description]
    rows = []
    for row in cur.fetchall():
        rows.append({col: _serialize_value(row[col]) for col in cols})
    return rows


def _build_nessus_xml(data: dict) -> str:
    """Build a .nessus XML document from findings tables."""
    root = ET.Element("NessusClientData_v2")
    report = ET.SubElement(root, "Report")
    report.set("name", "pentest-export")

    # Group findings by IP
    host_findings: Dict[str, list] = {}
    finding_tables = ["vulns", "web_findings", "playwright_findings", "credential_findings"]
    for tbl in finding_tables:
        for row in data.get(tbl, []):
            ip = None
            if tbl == "vulns":
                ip = row.get("metadata", {}).get("ip") if isinstance(row.get("metadata"), dict) else None
            elif tbl == "credential_findings":
                ip = str(row.get("ip", "")) if row.get("ip") else None
            if not ip:
                ip = str(row.get("ip", "unknown"))
            host_findings.setdefault(ip, []).append((tbl, row))

    for ip, items in host_findings.items():
        host_el = ET.SubElement(report, "ReportHost")
        host_el.set("name", ip)
        props = ET.SubElement(host_el, "HostProperties")
        tag = ET.SubElement(props, "tag")
        tag.set("name", "host-ip")
        tag.text = ip

        for tbl, row in items:
            sev = _severity_to_nessus(row.get("severity", "info"))
            title = row.get("script") or row.get("name") or row.get("title") or row.get("exploit_title") or "Finding"
            rid = row.get("id", "")
            plugin_id = str(abs(int(hashlib.md5(rid.encode()).hexdigest()[:8], 16)) % 900000 + 100000)

            item = ET.SubElement(host_el, "ReportItem")
            item.set("port", str(row.get("port", 0) or 0))
            item.set("svc_name", row.get("service", "") or row.get("protocol", "") or "")
            item.set("protocol", row.get("proto", "tcp") or "tcp")
            item.set("severity", str(sev))
            item.set("pluginID", plugin_id)
            item.set("pluginName", title[:200])
            item.set("pluginFamily", "Pentest Export")

            def _sub(tag_name, text):
                el = ET.SubElement(item, tag_name)
                el.text = str(text) if text else ""
                return el

            _sub("description", row.get("output") or row.get("evidence") or row.get("description") or "")
            _sub("solution", row.get("solution", "N/A"))
            risk_map = {0: "None", 1: "Low", 2: "Medium", 3: "High", 4: "Critical"}
            _sub("risk_factor", risk_map.get(sev, "None"))

            cves = row.get("cve", [])
            if isinstance(cves, list):
                for c in cves:
                    _sub("cve", c)

            cvss = row.get("cvss")
            if cvss is not None:
                _sub("cvss_base_score", str(cvss))

    return '<?xml version="1.0" ?>\n' + ET.tostring(root, encoding="unicode")


@app.get("/export/sarif", tags=["Export"])
def export_sarif(
    severity: Optional[List[str]] = Query(None),
    source: Optional[List[str]] = Query(None),
    collapse_problems: bool = Query(False, description="Emit one SARIF result per underlying problem, with a location per affected virtual host, instead of one result per host"),
    include_inventory: bool = Query(False, description="Include crawl inventory (record_kind='inventory') as SARIF results. Off by default: it was 746 of 787 results, drowning the 41 real findings"),
    limit: int = Query(5000, ge=1, le=50000),
    authorized: bool = Depends(auth),
):
    """
    Export findings in SARIF v2.1.0 format (Static Analysis Results Interchange Format).

    Maps vulnerability and web findings to SARIF results with:
    - tool/driver per source (nmap, nuclei, zap, nessus, etc.)
    - rules from scripts/templates
    - results with severity levels, messages, locations, and fingerprints
    """
    sarif = {
        "$schema": "https://raw.githubusercontent.com/oasis-tcs/sarif-spec/main/sarif-2.1/schema/sarif-schema-2.1.0.json",
        "version": "2.1.0",
        "runs": [],
    }

    # SARIF severity mapping
    sev_map = {
        "critical": "error",
        "high": "error",
        "medium": "warning",
        "low": "note",
        "info": "note",
        # Explicit rather than relying on sev_map.get(..., "note"). It landed on
        # "note" by fallthrough, so changing that default would have silently
        # moved every one of these. Kept for pre-migration rows.
        "recon": "note",
    }

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # --- Collect vuln findings ---
        vuln_sql = """
            SELECT v.id, v.script, v.output, v.severity, v.cve, v.cvss, v.fingerprint,
                   v.metadata, v.created_at,
                   host(a.ip)::text as ip, a.hostname, p.port, p.proto
            FROM vulns v
            LEFT JOIN assets a ON v.asset_id = a.id
            LEFT JOIN ports p ON v.port_id = p.id
            WHERE 1=1
        """
        params = []
        # Scope the export to the active engagement (X-Engagement-Id header).
        _eid = _validate_engagement_uuid(_resolve_engagement_id())
        if _eid:
            vuln_sql += " AND v.engagement_id = %s::uuid"
            params.append(_eid)
        if severity:
            vuln_sql += " AND v.severity = ANY(%s)"
            params.append(severity)
        if source:
            # Match source prefix in script field (e.g., 'nmap:', 'nessus:', 'nuclei:')
            patterns = [f"{s}:%" for s in source]
            vuln_sql += " AND (" + " OR ".join(["v.script LIKE %s"] * len(patterns)) + ")"
            params.extend(patterns)
        vuln_sql += f" ORDER BY v.created_at DESC LIMIT {int(limit)}"
        cur.execute(vuln_sql, params)
        vuln_rows = cur.fetchall()

        # --- Collect web findings ---
        web_sql = """
            SELECT id, url, source, name, severity, issue_type, evidence,
                   description, cwe, fingerprint, first_seen,
                   infrastructure_fingerprint
            FROM web_findings WHERE 1=1
        """
        web_params = []
        if _eid:
            web_sql += " AND engagement_id = %s::uuid"
            web_params.append(_eid)
        if not include_inventory:
            # 746 of 787 SARIF results were katana crawl rows — the inventory the
            # record_kind column exists to separate. /findings/search filters them
            # and reported 94 findings while this export emitted 787, so the same
            # engagement looked like two different engagements depending on which
            # artefact the reader opened.
            web_sql += " AND COALESCE(record_kind, 'finding') = 'finding'"
        if severity:
            web_sql += " AND severity = ANY(%s)"
            web_params.append(severity)
        if source:
            web_sql += " AND source = ANY(%s)"
            web_params.append(source)
        web_sql += f" ORDER BY first_seen DESC LIMIT {int(limit)}"
        cur.execute(web_sql, web_params)
        web_rows = cur.fetchall()

        # --- Collect credential findings ---
        # Omitted entirely until now: there was no `brutus` run in the output, so
        # a verified credential — arguably the most actionable thing a pentest
        # produces — never appeared in a SARIF report at all.
        cred_sql = """
            SELECT id, host(ip)::text AS ip, port, protocol, username,
                   secret_type, severity, source, fingerprint, discovered_at,
                   secret_value IS NOT NULL AS has_secret
              FROM credential_findings WHERE valid_cred IS TRUE
        """
        cred_params: list = []
        if severity:
            cred_sql += " AND severity = ANY(%s)"
            cred_params.append(severity)
        if source:
            cred_sql += " AND COALESCE(source, 'brutus') = ANY(%s)"
            cred_params.append(source)
        cred_sql += f" ORDER BY discovered_at DESC NULLS LAST LIMIT {int(limit)}"
        cur.execute(cred_sql, cred_params)
        cred_rows = cur.fetchall()

        # --- Collect playwright findings ---
        cur.execute(f"""
            SELECT id, url, finding_type, severity, description, evidence,
                   created_at
              FROM playwright_findings
             ORDER BY created_at DESC LIMIT {int(limit)}
        """)
        pw_rows = cur.fetchall()

    # Group by tool for SARIF runs
    tool_results: dict = {}

    # Process vulns
    for row in vuln_rows:
        script = row.get("script") or "unknown"
        tool_name = script.split(":")[0] if ":" in script else script
        if tool_name not in tool_results:
            tool_results[tool_name] = {"rules": {}, "results": []}

        rule_id = script
        if rule_id not in tool_results[tool_name]["rules"]:
            tool_results[tool_name]["rules"][rule_id] = {
                "id": rule_id,
                "shortDescription": {"text": script},
            }

        result = {
            "ruleId": rule_id,
            "level": sev_map.get(row.get("severity", "info"), "note"),
            "message": {"text": (row.get("output") or script)[:2000]},
            "locations": [],
            "properties": {
                "severity": row.get("severity"),
                "created_at": str(row.get("created_at")),
            },
        }

        # Physical location
        ip = row.get("ip") or "unknown"
        port = row.get("port")
        uri = f"tcp://{ip}:{port}" if port else f"tcp://{ip}"
        result["locations"].append({
            "physicalLocation": {
                "artifactLocation": {"uri": uri},
            }
        })

        # Fingerprint
        if row.get("fingerprint"):
            result["fingerprints"] = {"finding/v1": row["fingerprint"]}

        # CVEs as partial fingerprints
        cves = row.get("cve") or []
        if cves:
            result["properties"]["cve"] = cves

        if row.get("cvss") is not None:
            result["properties"]["cvss"] = float(row["cvss"])

        tool_results[tool_name]["results"].append(result)

    # Process web findings
    # SARIF represents "one problem, several places" natively: a result carries a
    # LIST of locations. So a server-level problem on shared hosting should be
    # one result with a location per affected virtual host — not N near-identical
    # results, which is what a report consumer would otherwise have to dedupe by
    # hand.
    #
    # Grouped on COALESCE(infrastructure_fingerprint, id): keying on the
    # fingerprint alone would fold every ungroupable row into one bucket, since
    # they all share a NULL.
    if collapse_problems:
        merged: Dict[str, Dict[str, Any]] = {}
        for row in web_rows:
            key = row.get("infrastructure_fingerprint") or f"row:{row['id']}"
            if key in merged:
                merged[key]["_urls"].append(row.get("url") or "")
                continue
            head = dict(row)
            head["_urls"] = [row.get("url") or ""]
            merged[key] = head
        web_rows = list(merged.values())

    for row in web_rows:
        tool_name = row.get("source") or "web"
        if tool_name not in tool_results:
            tool_results[tool_name] = {"rules": {}, "results": []}

        rule_id = f"{tool_name}:{row.get('issue_type') or 'finding'}"
        name = row.get("name") or rule_id
        if rule_id not in tool_results[tool_name]["rules"]:
            tool_results[tool_name]["rules"][rule_id] = {
                "id": rule_id,
                "shortDescription": {"text": name},
            }

        result = {
            "ruleId": rule_id,
            "level": sev_map.get(row.get("severity", "info"), "note"),
            "message": {"text": (row.get("description") or name)[:2000]},
            "locations": [
                {"physicalLocation": {"artifactLocation": {"uri": u}}}
                for u in (row.get("_urls") or [row.get("url") or ""])
            ],
            "properties": {
                "severity": row.get("severity"),
                "created_at": str(row.get("first_seen")),
            },
        }

        # Only meaningful when collapsed; a consumer reading affects_hosts=1 on
        # every result would learn nothing.
        if collapse_problems:
            urls = row.get("_urls") or []
            result["properties"]["affects_locations"] = len(urls)
            if row.get("infrastructure_fingerprint"):
                result["properties"]["problem_id"] = row["infrastructure_fingerprint"]

        if row.get("fingerprint"):
            result["fingerprints"] = {"finding/v1": row["fingerprint"]}

        cwes = row.get("cwe") or []
        if cwes:
            result["properties"]["cwe"] = cwes

        tool_results[tool_name]["results"].append(result)

    # Process credential findings
    for row in cred_rows:
        tool_name = row.get("source") or "brutus"
        tool_results.setdefault(tool_name, {"rules": {}, "results": []})
        rule_id = f"credential/{row.get('secret_type') or 'password'}"
        tool_results[tool_name]["rules"].setdefault(rule_id, {
            "id": rule_id,
            "shortDescription": {"text": "Valid credential accepted by a service"},
        })
        # The secret itself is deliberately NOT in the message. A SARIF file is
        # made to be handed to other tooling and CI, which is a wider audience
        # than the database; has_secret says whether one is stored to look up.
        result = {
            "ruleId": rule_id,
            "level": sev_map.get((row.get("severity") or "").lower(), "note"),
            "message": {"text": (f"Valid credential: {row.get('username')} on "
                                 f"{row.get('protocol')}://{row.get('ip')}:{row.get('port')}")},
            "locations": [{
                "physicalLocation": {
                    "artifactLocation": {
                        "uri": f"{row.get('protocol')}://{row.get('ip')}:{row.get('port')}"},
                }
            }],
            "properties": {
                "username": row.get("username"),
                "service": row.get("protocol"),
                "port": row.get("port"),
                "secret_stored": bool(row.get("has_secret")),
            },
        }
        if row.get("fingerprint"):
            result["fingerprints"] = {"finding/v1": row["fingerprint"]}
        tool_results[tool_name]["results"].append(result)

    # Process playwright findings
    for row in pw_rows:
        tool_name = "playwright"
        tool_results.setdefault(tool_name, {"rules": {}, "results": []})
        rule_id = row.get("finding_type") or "playwright/finding"
        tool_results[tool_name]["rules"].setdefault(rule_id, {
            "id": rule_id, "shortDescription": {"text": rule_id},
        })
        tool_results[tool_name]["results"].append({
            "ruleId": rule_id,
            "level": sev_map.get((row.get("severity") or "").lower(), "note"),
            "message": {"text": row.get("description") or rule_id},
            "locations": [{"physicalLocation": {
                "artifactLocation": {"uri": row.get("url") or "unknown"}}}],
            "properties": {"evidence": row.get("evidence")},
        })

    # Build SARIF runs
    for tool_name, data in tool_results.items():
        run = {
            "tool": {
                "driver": {
                    "name": tool_name,
                    "informationUri": "https://github.com/raptordoug/rag_scan_stack",
                    "rules": list(data["rules"].values()),
                }
            },
            "results": data["results"],
        }
        sarif["runs"].append(run)

    return Response(
        content=json.dumps(sarif, default=str, indent=2),
        media_type="application/json",
        headers={"Content-Disposition": 'attachment; filename="pentest_findings.sarif"'},
    )


@app.get("/export/data", tags=["Export"])
def export_data(
    format: str = Query("json", description="Export format: json, csv, nessus"),
    categories: str = Query(
        "assets,findings,infrastructure,recon,credentials,params,exploits,screenshots",
        description="Comma-separated categories"),
    include_inventory: bool = Query(False, description="Include crawl inventory (record_kind='inventory') in web_findings. Off by default, matching /findings/search and /export/sarif"),
    collapse_problems: bool = Query(False, description="One web_findings row per underlying problem instead of one per virtual host"),
    authorized: bool = Depends(auth),
):
    """
    Export collected pentest data.

    Formats:
    - json: Full data envelope with all selected categories
    - csv: ZIP file with one CSV per table
    - nessus: Nessus-compatible XML (findings tables only)
    """
    selected = [c.strip() for c in categories.split(",") if c.strip() in EXPORT_CATEGORIES]
    if not selected:
        raise HTTPException(400, "No valid categories selected")

    # Collect tables to query
    tables_to_query = []
    for cat in selected:
        tables_to_query.extend(EXPORT_CATEGORIES[cat])

    # Query all data — scoped to the active engagement (X-Engagement-Id header)
    # so a bulk export never bundles another engagement's data. Config/technique
    # tables with no engagement attribution are exported unscoped by the helpers.
    _eid = _validate_engagement_uuid(_resolve_engagement_id())
    data: Dict[str, list] = {}
    counts: Dict[str, int] = {}
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        for tbl in tables_to_query:
            try:
                # web_findings is the only table where inventory and virtual-host
                # duplication apply. Until now /export/data had neither control,
                # so the same engagement read as 779 rows here and 94 in
                # /findings/search — three export paths, three different answers.
                if tbl == "web_findings":
                    rows = _export_web_findings(cur, include_inventory,
                                                collapse_problems, engagement_id=_eid)
                else:
                    rows = _export_table_rows(cur, tbl, engagement_id=_eid)
                data[tbl] = rows
                counts[tbl] = len(rows)
            except Exception:
                conn.rollback()
                data[tbl] = []
                counts[tbl] = 0

    if format == "nessus":
        xml_str = _build_nessus_xml(data)
        return Response(
            content=xml_str,
            media_type="application/xml",
            headers={"Content-Disposition": 'attachment; filename="pentest_export.nessus"'},
        )

    if format == "csv":
        buf = io.BytesIO()
        with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
            for tbl, rows in data.items():
                if not rows:
                    continue
                csv_buf = io.StringIO()
                cols = list(rows[0].keys())
                writer = csv.DictWriter(csv_buf, fieldnames=cols)
                writer.writeheader()
                for row in rows:
                    safe_row = {}
                    for k, v in row.items():
                        if isinstance(v, (dict, list)):
                            safe_row[k] = json.dumps(v)
                        else:
                            safe_row[k] = v
                    writer.writerow(safe_row)
                zf.writestr(f"{tbl}.csv", csv_buf.getvalue())
        buf.seek(0)
        return Response(
            content=buf.getvalue(),
            media_type="application/zip",
            headers={"Content-Disposition": 'attachment; filename="pentest_export_csv.zip"'},
        )

    # Default: JSON
    envelope = {
        "schema_version": "1.1",
        "exported_at": datetime.now(timezone.utc).isoformat(),
        "categories": selected,
        "data": data,
        "counts": counts,
    }
    return Response(
        content=json.dumps(envelope, default=str),
        media_type="application/json",
        headers={"Content-Disposition": 'attachment; filename="pentest_export.json"'},
    )


@app.post("/import/data", tags=["Import"])
def import_data(file: UploadFile = File(...), authorized: bool = Depends(auth)):
    """
    Import pentest data from a previous JSON export.

    Inserts records in dependency order. Existing records (by id) are skipped.
    """
    try:
        raw = file.file.read()
        payload = json.loads(raw)
    except Exception as e:
        raise HTTPException(400, f"Invalid JSON file: {e}")

    if payload.get("schema_version") not in ("1.0", "1.1"):
        raise HTTPException(400, "Unsupported schema_version (expected '1.0')")

    data = payload.get("data", {})
    if not data:
        raise HTTPException(400, "No data found in export file")

    # Insert order (respects FK dependencies)
    insert_order = [
        "assets", "ports",
        "vulns", "web_findings", "playwright_findings",
        "recon_findings", "credential_findings", "discovered_params",
        "pending_exploits", "exploit_results",
        "screenshot_metadata",
    ]

    inserted: Dict[str, int] = {}

    with get_db() as conn, conn.cursor() as cur:
        for tbl in insert_order:
            rows = data.get(tbl, [])
            if not rows:
                continue
            count = 0
            cols = list(rows[0].keys())
            col_list = ", ".join(cols)
            placeholders = ", ".join(["%s"] * len(cols))
            sql = f"INSERT INTO {tbl} ({col_list}) VALUES ({placeholders}) ON CONFLICT (id) DO NOTHING"

            for row in rows:
                vals = []
                for c in cols:
                    v = row.get(c)
                    if isinstance(v, (dict, list)):
                        vals.append(Json(v))
                    else:
                        vals.append(v)
                try:
                    cur.execute(sql, vals)
                    if cur.rowcount > 0:
                        count += 1
                except Exception:
                    conn.rollback()
                    continue
            inserted[tbl] = count
        conn.commit()

    return {"ok": True, "inserted": inserted, "total": sum(inserted.values())}


