class EngagementCreate(BaseModel):
    name: str
    client: Optional[str] = None
    engagement_type: str = "external_pentest"
    methodology: str = "custom"
    status: str = "planning"
    start_date: Optional[str] = None
    end_date: Optional[str] = None
    scope_name: Optional[str] = None
    rules_of_engagement: Optional[str] = None
    notes: Optional[str] = None
    metadata: Optional[Dict[str, Any]] = None

class EngagementUpdate(BaseModel):
    name: Optional[str] = None
    client: Optional[str] = None
    engagement_type: Optional[str] = None
    methodology: Optional[str] = None
    status: Optional[str] = None
    start_date: Optional[str] = None
    end_date: Optional[str] = None
    scope_name: Optional[str] = None
    rules_of_engagement: Optional[str] = None
    notes: Optional[str] = None
    metadata: Optional[Dict[str, Any]] = None

@app.post("/engagements", tags=["Engagements"])
def create_engagement(body: EngagementCreate, _: bool = Depends(auth)):
    """Create a new engagement."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            """INSERT INTO engagements (name, client, engagement_type, methodology, status,
                start_date, end_date, scope_name, rules_of_engagement, notes, metadata)
               VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s) RETURNING *""",
            (body.name, body.client, body.engagement_type, body.methodology, body.status,
             body.start_date, body.end_date, body.scope_name, body.rules_of_engagement,
             body.notes or '', Json(body.metadata or {})),
        )
        row = cur.fetchone()
        conn.commit()
    return row

@app.get("/engagements", tags=["Engagements"])
def list_engagements(
    status: Optional[str] = Query(None),
    _: bool = Depends(auth),
):
    """List engagements with optional status filter."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        if status:
            cur.execute("SELECT * FROM engagements WHERE status = %s ORDER BY created_at DESC", (status,))
        else:
            cur.execute("SELECT * FROM engagements ORDER BY created_at DESC")
        rows = cur.fetchall()
        # Add scopes to each engagement
        for eng in rows:
            try:
                cur.execute("""
                    SELECT name, COUNT(*) as target_count
                    FROM scope_targets WHERE engagement_id = %s
                    GROUP BY name ORDER BY name
                """, (str(eng["id"]),))
                eng["scopes"] = [dict(r) for r in cur.fetchall()]
            except Exception:
                eng["scopes"] = []
    return {"engagements": rows}

@app.get("/engagements/{eid}", tags=["Engagements"])
def get_engagement(eid: str, _: bool = Depends(auth)):
    """Get engagement detail with summary stats."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT * FROM engagements WHERE id = %s", (eid,))
        eng = cur.fetchone()
        if not eng:
            raise HTTPException(404, "Engagement not found")
        # Summary stats
        stats = {"findings_by_severity": {}, "asset_count": 0, "scan_count": 0}
        try:
            cur.execute(
                """SELECT severity, COUNT(*) as cnt FROM vulns WHERE engagement_id = %s
                   GROUP BY severity""", (eid,))
            for r in cur.fetchall():
                stats["findings_by_severity"][r["severity"] or "unknown"] = r["cnt"]
            cur.execute("SELECT COUNT(*) as cnt FROM assets WHERE engagement_id = %s", (eid,))
            stats["asset_count"] = cur.fetchone()["cnt"]
        except Exception:
            pass
        eng["stats"] = stats
        # Scopes under this engagement
        try:
            cur.execute("""
                SELECT name, COUNT(*) as target_count
                FROM scope_targets WHERE engagement_id = %s
                GROUP BY name ORDER BY name
            """, (eid,))
            eng["scopes"] = [dict(r) for r in cur.fetchall()]
        except Exception:
            eng["scopes"] = []
    return eng

class ExploitPreapprovalBody(BaseModel):
    enabled: bool
    approved_by: Optional[str] = None
    note: Optional[str] = None


@app.get("/engagements/{eid}/exploit-preapproval", tags=["Engagements"])
def get_exploit_preapproval(eid: str, _: bool = Depends(auth)):
    """Whether exploit execution is pre-approved for this engagement."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            """SELECT COALESCE((metadata->>'exploit_preapproved')::boolean, false) AS enabled,
                      metadata->'exploit_preapproval_meta' AS meta
                 FROM engagements WHERE id = %s::uuid""", (eid,))
        row = cur.fetchone()
    if not row:
        raise HTTPException(404, f"no engagement {eid}")
    return {"engagement_id": eid, "enabled": bool(row["enabled"]),
            "meta": row["meta"] or {}}


@app.put("/engagements/{eid}/exploit-preapproval", tags=["Engagements"])
def set_exploit_preapproval(eid: str, body: ExploitPreapprovalBody,
                            x_operator: str = Header("operator", alias="X-Operator"),
                            _: bool = Depends(auth)):
    """Pre-approve exploit execution for ONE engagement.

    With this on, a LangGraph session does not pause at the exploit gate: the
    operator has already authorised this engagement, so there is nobody to wait
    for. That is authorization given in advance, not an override of it — see
    langgraph_engine._engagement_preapproval.

    Deliberately its own endpoint rather than PUT /engagements/{eid}: that one
    REPLACES `metadata` wholesale, so setting one key through it would silently
    drop every other key the engagement holds. This merges.

    Scope is untouched. execute_approved_exploit still fails closed on scope, so
    pre-approval can never make an out-of-scope target runnable.
    """
    meta = {"enabled": bool(body.enabled), "approved_by": body.approved_by or x_operator,
            "note": body.note, "set_at": datetime.now(timezone.utc).isoformat()}
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(
            """UPDATE engagements
                  SET metadata = COALESCE(metadata, '{}'::jsonb)
                                 || jsonb_build_object('exploit_preapproved', %s::boolean,
                                                       'exploit_preapproval_meta', %s::jsonb)
                WHERE id = %s::uuid
            RETURNING id, name,
                      COALESCE((metadata->>'exploit_preapproved')::boolean, false) AS enabled""",
            (bool(body.enabled), Json(meta), eid))
        row = cur.fetchone()
        conn.commit()
    if not row:
        raise HTTPException(404, f"no engagement {eid}")
    try:
        from webhooks import emit_webhook
        emit_webhook("engagement_exploit_preapproval_changed", "engagements",
                     {"engagement_id": eid, "name": row["name"],
                      "enabled": bool(row["enabled"]), "actor": meta["approved_by"]},
                     severity="high")
    except Exception as e:  # noqa: BLE001
        log.warning("preapproval webhook failed: %s", e)
    return {"ok": True, "engagement_id": eid, "name": row["name"],
            "enabled": bool(row["enabled"]), "meta": meta}


@app.put("/engagements/{eid}", tags=["Engagements"])
def update_engagement(eid: str, body: EngagementUpdate, _: bool = Depends(auth)):
    """Update an engagement."""
    updates, vals = [], []
    for field in ["name","client","engagement_type","methodology","status","start_date",
                  "end_date","scope_name","rules_of_engagement","notes"]:
        v = getattr(body, field, None)
        if v is not None:
            updates.append(f"{field} = %s")
            vals.append(v)
    if body.metadata is not None:
        updates.append("metadata = %s")
        vals.append(Json(body.metadata))
    if not updates:
        raise HTTPException(400, "No fields to update")
    vals.append(eid)
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(f"UPDATE engagements SET {', '.join(updates)} WHERE id = %s RETURNING *", vals)
        row = cur.fetchone()
        conn.commit()
    if not row:
        raise HTTPException(404, "Engagement not found")
    return row

# _purge_engagement_data now discovers engagement_id / asset_id tables dynamically
# (so a new table is covered automatically) and adds IP / scan_id / pending_exploit
# keyed deletes for rows with a NULL engagement_id. Operator config (scope,
# schedules, rules, prompts) is listed in that function's CONFIG_KEEP set and kept
# on a data purge, removed only on a full delete.


def _sp_delete(cur, sql: str, params) -> int:
    """DELETE inside a SAVEPOINT so a missing table/column does not abort the
    whole purge transaction. Returns rows deleted (0 on any failure)."""
    cur.execute("SAVEPOINT purge_sp")
    try:
        cur.execute(sql, params)
        n = cur.rowcount
        cur.execute("RELEASE SAVEPOINT purge_sp")
        return n
    except Exception as e:  # noqa: BLE001
        cur.execute("ROLLBACK TO SAVEPOINT purge_sp")
        log.warning("purge step failed (%s): %s", sql.split()[2] if len(sql.split()) > 2 else sql, e)
        return 0


def _purge_engagement_data(cur, eid: str, keep_engagement: bool = False) -> Dict[str, int]:
    """Delete an engagement's collected DATA — its assets and every row hanging
    off them (ports, vulns, findings, web/recon/credential/playwright findings,
    exploits, recommendations, …), plus engagement-attributed orphan findings.

    An asset carries exactly one engagement_id, so this never touches another
    engagement's inventory. `keep_engagement=True` KEEPS the engagement row and
    its scope/schedule (so it can be re-run); False also removes the scope and the
    engagement itself. Returns per-table deleted counts."""
    counts: Dict[str, int] = {}

    def _scalars(sql, params):
        cur.execute(sql, params)
        out = []
        for r in cur.fetchall():
            v = (list(r.values())[0] if isinstance(r, dict) else r[0])
            if v:
                out.append(str(v))
        return out

    # Gather the engagement's target IPs BEFORE deleting assets. A lot of data —
    # cracked creds (credential_findings src=hashcat_crack), exploits, held access,
    # security tests — is keyed ONLY by IP with a NULL engagement_id/asset_id, so an
    # engagement/asset-scoped delete misses it and it keeps showing after a purge.
    ips = set(_scalars("SELECT host(ip) FROM assets WHERE engagement_id = %s::uuid", (eid,)))
    ips |= {x.split('/')[0] for x in _scalars(
        "SELECT target FROM scope_targets WHERE engagement_id = %s::uuid "
        "AND target_type = 'ip'", (eid,))}
    ips = [i for i in ips if i]

    cur.execute("SELECT id FROM assets WHERE engagement_id = %s::uuid", (eid,))
    asset_ids = [str(r["id"] if isinstance(r, dict) else r[0]) for r in cur.fetchall()]

    # The engagement's scan ids (via asset-linked scan_id rows) and pending-exploit
    # ids — gathered before their parents are deleted so scan_id / pending_exploit_id
    # children can be cleaned too.
    scan_ids = pe_ids = []
    if asset_ids:
        scan_ids = _scalars("SELECT DISTINCT scan_id FROM public.port_observation "
                            "WHERE asset_id = ANY(%s::uuid[]) AND scan_id IS NOT NULL", (asset_ids,))
    if ips:
        pe_ids = _scalars("SELECT id FROM public.pending_exploits WHERE host(target_ip) = ANY(%s)", (ips,))

    # Config the operator OWNS (scope, schedules, rules, prompts) — kept on a
    # data purge so the engagement can be re-run, removed only on a full delete.
    CONFIG_KEEP = {"scope_targets", "scheduled_scans", "exploit_approval_rules",
                   "custom_enumeration_rules", "scope_classification_rules",
                   "service_prompts", "scan_parameters", "target_tool_settings",
                   "chat_presets"}

    def _tables_with(col):
        cur.execute(
            "SELECT c.table_name FROM information_schema.columns c "
            "JOIN information_schema.tables t ON t.table_name = c.table_name "
            "  AND t.table_schema = c.table_schema "
            "WHERE c.table_schema = 'public' AND c.column_name = %s "
            "  AND t.table_type = 'BASE TABLE'", (col,))
        return [(r["table_name"] if isinstance(r, dict) else r[0]) for r in cur.fetchall()]

    def _del(tbl, sql, params):
        counts[tbl] = counts.get(tbl, 0) + _sp_delete(cur, sql, params)

    # 1) pending-exploit children (no cascade) — before pending_exploits itself.
    if pe_ids:
        for tbl in ("exploit_results", "exploit_callbacks", "active_listeners", "vector_coverage"):
            _del(tbl, f"DELETE FROM public.{tbl} WHERE pending_exploit_id = ANY(%s::uuid[])", (pe_ids,))

    # 2) IP / target-keyed data — the class with a NULL engagement_id/asset_id
    #    (cracked creds src=hashcat_crack, exploits, held access, tests, recs).
    if ips:
        for tbl, col in (("credential_findings", "ip"), ("pending_exploits", "target_ip"),
                         ("security_tests", "target_ip"), ("credential_spray_attempts", "target_ip"),
                         ("detected_software", "ip"), ("pending_scan_recommendations", "ip"),
                         ("scan_recommendations", "ip"), ("port_observation", "ip")):
            # Per-row CASE guard: some of these columns are TEXT and hold non-IP
            # values (e.g. detected_software.ip), so a table-wide `col::inet` cast
            # would error and skip the whole delete. Cast only rows that look like IPs.
            _del(tbl, f"DELETE FROM public.{tbl} WHERE CASE WHEN {col}::text ~ "
                      f"'^[0-9]{{1,3}}(\\.[0-9]{{1,3}}){{3}}' "
                      f"THEN host({col}::inet) = ANY(%s) ELSE false END", (ips,))
        for tbl, col in (("obtained_access", "target"), ("attack_vectors", "target"),
                         ("recon_findings", "target"), ("follow_up_items", "target"),
                         ("tool_attempts", "target"), ("tool_executions", "target"),
                         ("scan_runs", "target"), ("raw_artifacts", "target"),
                         ("burp_followup_queue", "target"), ("port_access_advice", "target"),
                         ("enumeration_observations", "target"), ("vector_coverage", "target"),
                         ("scope_coverage", "target"), ("scope_decisions", "target"),
                         ("scope_suggestions", "target"), ("scope_conflicts", "target"),
                         ("attack_path_edges", "target"),
                         ("scan_pipeline_jobs", "host")):
            _del(tbl, f"DELETE FROM public.{tbl} WHERE "
                      f"split_part(regexp_replace({col}, '^.*@', ''), ':', 1) = ANY(%s)", (ips,))
        # web_findings are keyed by URL — extract the host (strip scheme, path, port).
        _del("web_findings", "DELETE FROM public.web_findings WHERE "
             "split_part(split_part(regexp_replace(url, '^[a-z]+://', ''), '/', 1), ':', 1) "
             "= ANY(%s)", (ips,))

    # 3) scan_id-keyed children (for scans tied to this engagement's assets).
    if scan_ids:
        for tbl in _tables_with("scan_id"):
            _del(tbl, f"DELETE FROM public.{tbl} WHERE scan_id = ANY(%s::uuid[])", (scan_ids,))

    # 4) asset_id-keyed — EVERY table with asset_id, for this engagement's assets.
    if asset_ids:
        for tbl in _tables_with("asset_id"):
            _del(tbl, f"DELETE FROM public.{tbl} WHERE asset_id = ANY(%s::uuid[])", (asset_ids,))

    # 5) engagement_id-keyed — EVERY table with engagement_id (dynamic, so a new
    #    table is covered automatically), minus operator config on a data purge.
    for tbl in _tables_with("engagement_id"):
        if tbl == "engagements":
            continue
        if keep_engagement and tbl in CONFIG_KEEP:
            continue
        _del(tbl, f"DELETE FROM public.{tbl} WHERE engagement_id = %s::uuid", (eid,))

    # 6) the assets themselves.
    #
    # ADDITIVE, not assignment. `assets` carries an engagement_id, so step 5's
    # dynamic sweep has ALREADY deleted these rows and recorded the real count.
    # This pass then deletes 0 rows, and assigning `counts["assets"] = cur.rowcount`
    # overwrote the true figure with 0 — a purge that had just removed an asset
    # reported "assets: 0" to the operator. Measured: 1 asset in, 0 assets left
    # afterwards, `deleted.assets` reported as 0.
    #
    # The delete stays: step 5 skips CONFIG_KEEP tables on a data purge, and this
    # is the backstop if `assets` ever joins that set or the sweep misses it.
    # `.get(...) + rowcount` is the same shape _del uses for every other table.
    if asset_ids:
        cur.execute("DELETE FROM public.assets WHERE engagement_id = %s::uuid", (eid,))
        counts["assets"] = counts.get("assets", 0) + cur.rowcount
    else:
        counts["assets"] = counts.get("assets", 0)

    if keep_engagement:
        return counts
    # Full delete: config is gone with the engagement (CONFIG_KEEP tables were
    # already deleted above since keep_engagement is False), then the row itself.
    cur.execute("DELETE FROM public.engagements WHERE id = %s::uuid", (eid,))
    counts["engagements"] = cur.rowcount
    return counts


def _purge_dry_run(cur, eid: str) -> Dict[str, Any]:
    """Counts of what a purge would remove, without deleting anything. Counts by
    engagement AND by target IP, so IP-keyed rows with a NULL engagement_id
    (cracked creds, exploits, held access) are shown — the real purge deletes them."""
    cur.execute("SELECT COUNT(*) AS n FROM assets WHERE engagement_id = %s::uuid", (eid,))
    asset_n = cur.fetchone()["n"]

    def _col(sql, params):
        cur.execute(sql, params)
        return [(r[list(r.keys())[0]] if isinstance(r, dict) else r[0]) for r in cur.fetchall()]

    ips = set(x for x in _col("SELECT host(ip) FROM assets WHERE engagement_id = %s::uuid", (eid,)) if x)
    ips |= {str(x).split('/')[0] for x in _col(
        "SELECT target FROM scope_targets WHERE engagement_id = %s::uuid AND target_type = 'ip'", (eid,)) if x}
    ips = [i for i in ips if i]
    counts: Dict[str, int] = {}

    def _count(tbl, where, params):
        cur.execute("SAVEPOINT dr_sp")
        try:
            cur.execute(f"SELECT COUNT(*) AS n FROM public.{tbl} WHERE {where}", params)
            counts[tbl] = cur.fetchone()["n"]
            cur.execute("RELEASE SAVEPOINT dr_sp")
        except Exception:  # noqa: BLE001
            cur.execute("ROLLBACK TO SAVEPOINT dr_sp")

    sub = "asset_id IN (SELECT id FROM public.assets WHERE engagement_id = %s::uuid)"
    for tbl in ("ports", "vulns", "findings", "web_findings"):
        _count(tbl, sub, (eid,))
    for tbl in ("recon_findings", "pending_exploits", "playwright_findings"):
        _count(tbl, "engagement_id = %s::uuid", (eid,))
    if ips:
        _count("credential_findings", "host(ip::inet) = ANY(%s)", (ips,))
        _count("pending_exploits", "host(target_ip::inet) = ANY(%s)", (ips,))
        _count("obtained_access",
               "split_part(regexp_replace(target,'^.*@',''),':',1) = ANY(%s)", (ips,))
        _count("security_tests", "host(target_ip::inet) = ANY(%s)", (ips,))
        _count("exploit_results",
               "pending_exploit_id IN (SELECT id FROM public.pending_exploits "
               "WHERE host(target_ip) = ANY(%s))", (ips,))
        _count("web_findings",
               "split_part(split_part(regexp_replace(url,'^[a-z]+://',''),'/',1),':',1) = ANY(%s)", (ips,))
    return {"assets": asset_n, "target_ips": ips, "would_delete": counts}


@app.post("/engagements/{eid}/purge-data", tags=["Engagements"])
def purge_engagement_data_endpoint(eid: str, dry_run: bool = Query(False),
                                   x_operator: str = Header("operator", alias="X-Operator"),
                                   _: bool = Depends(auth)):
    """Delete the engagement's collected DATA but KEEP the engagement.

    Removes its assets and everything hanging off them (ports, vulns, findings,
    recon, credentials, exploits, recommendations), so the engagement is emptied
    and can be re-run — its scope and schedule are preserved. Irreversible; pass
    dry_run=true to preview the counts first."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT id, name FROM engagements WHERE id = %s::uuid", (eid,))
        eng = cur.fetchone()
        if not eng:
            raise HTTPException(404, "Engagement not found")
        if dry_run:
            out = _purge_dry_run(cur, eid)
            return {"ok": True, "id": eid, "dry_run": True, "action": "purge_data", **out}
        counts = _purge_engagement_data(cur, eid, keep_engagement=True)
        conn.commit()
    try:
        from webhooks import emit_webhook
        emit_webhook("engagement_data_purged", "engagements", {
            "engagement_id": eid, "name": eng["name"], "actor": x_operator,
            "assets_deleted": counts.get("assets", 0)})
    except Exception:
        log.warning("engagement data-purge webhook emit failed", exc_info=True)
    return {"ok": True, "id": eid, "action": "data_purged", "kept_engagement": True,
            "deleted": counts}


@app.delete("/engagements/{eid}", tags=["Engagements"])
def delete_engagement(eid: str, purge: bool = Query(False), dry_run: bool = Query(False),
                      x_operator: str = Header("operator", alias="X-Operator"),
                      _: bool = Depends(auth)):
    """Remove an engagement.

    Default (purge=false): ARCHIVE — sets status='archived', deletes nothing, so
    the engagement's assets and findings are preserved (the historical behaviour).

    purge=true: HARD DELETE — removes the engagement AND its assets and every row
    hanging off them, plus its scope and schedule. Irreversible; pass dry_run=true
    to preview. To keep the engagement and wipe only its data, use
    POST /engagements/{eid}/purge-data instead. An asset belongs to one
    engagement, so this never deletes another engagement's hosts."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("SELECT id, name, status FROM engagements WHERE id = %s::uuid", (eid,))
        eng = cur.fetchone()
        if not eng:
            raise HTTPException(404, "Engagement not found")

        if not purge:
            cur.execute("UPDATE engagements SET status = 'archived' WHERE id = %s::uuid "
                        "RETURNING id", (eid,))
            conn.commit()
            return {"ok": True, "id": eid, "action": "archived"}

        if dry_run:
            out = _purge_dry_run(cur, eid)
            return {"ok": True, "id": eid, "dry_run": True, "action": "purge", **out}

        counts = _purge_engagement_data(cur, eid, keep_engagement=False)
        conn.commit()
    try:
        from webhooks import emit_webhook
        emit_webhook("engagement_purged", "engagements", {
            "engagement_id": eid, "name": eng["name"], "actor": x_operator,
            "assets_deleted": counts.get("assets", 0)})
    except Exception:
        log.warning("engagement purge webhook emit failed", exc_info=True)
    return {"ok": True, "id": eid, "action": "purged", "deleted": counts}


# ── Engagement-Scoped Scopes ────────────────────────────────────────────

_SCOPE_PLACEHOLDER_TARGET = ""  # sentinel marker so an empty scope can exist
_SCOPE_PLACEHOLDER_SOURCE = "__placeholder__"


def _classify_target(target_val: str) -> str:
    """Return one of: 'ip', 'cidr', 'url', 'domain' for a free-text target."""
    if not target_val:
        return "domain"
    if "/" in target_val and target_val.split("/", 1)[0].replace(".", "").replace(":", "").isalnum():
        # Heuristic: looks like CIDR (contains slash, leading is dotted/colon-numeric)
        try:
            ipaddress.ip_network(target_val, strict=False)
            return "cidr"
        except ValueError:
            pass
    if target_val.startswith("http://") or target_val.startswith("https://"):
        return "url"
    try:
        ipaddress.ip_address(target_val)
        return "ip"
    except ValueError:
        return "domain"


@app.get("/engagements/{eid}/scopes", tags=["Engagements"])
def list_engagement_scopes(eid: str, _: bool = Depends(auth)):
    """List all scopes under an engagement with target counts.

    Sentinel placeholder rows (target='') are excluded from target_count but
    still surface the scope itself, so empty-but-named scopes are visible.
    """
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("""
            SELECT name,
                   COUNT(*) FILTER (WHERE target <> '' AND source IS DISTINCT FROM %s) AS target_count,
                   MAX(added_at) AS last_updated
            FROM scope_targets
            WHERE engagement_id = %s::uuid
            GROUP BY name
            ORDER BY name
        """, (_SCOPE_PLACEHOLDER_SOURCE, eid))
        return {"scopes": [dict(r) for r in cur.fetchall()]}


@app.get("/engagements/{eid}/scopes/{scope_name}", tags=["Engagements"])
def get_engagement_scope(eid: str, scope_name: str, limit: int = Query(500, le=5000), _: bool = Depends(auth)):
    """Get targets for a scope under an engagement (sentinel rows excluded)."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("""
            SELECT id, name, target, target_type, source, added_at, engagement_id::text
            FROM scope_targets
            WHERE engagement_id = %s::uuid AND name = %s
              AND target <> '' AND source IS DISTINCT FROM %s
            ORDER BY added_at DESC LIMIT %s
        """, (eid, scope_name, _SCOPE_PLACEHOLDER_SOURCE, limit))
        targets = [dict(r) for r in cur.fetchall()]
    return {"name": scope_name, "engagement_id": eid, "total": len(targets), "targets": targets}


class ScopeTargetsAdd(BaseModel):
    targets: list
    source: Optional[str] = "manual"


@app.post("/engagements/{eid}/scopes/{scope_name}/targets", tags=["Engagements"])
def add_engagement_scope_targets(eid: str, scope_name: str, body: ScopeTargetsAdd, _: bool = Depends(auth)):
    """Add targets to a scope under an engagement.

    - Empty `targets` list → creates the scope (sentinel placeholder row),
      enabling an "empty scope" to be visible in the UI.
    - Each target insert is wrapped in its own SAVEPOINT so a duplicate or
      validation error doesn't poison the whole batch.
    """
    added = 0
    skipped = 0
    errors: list[str] = []
    with get_db() as conn, conn.cursor() as cur:
        # Always ensure a placeholder row so the scope exists even with 0 targets
        try:
            cur.execute("SAVEPOINT sp_placeholder")
            cur.execute("""
                INSERT INTO scope_targets (engagement_id, name, target, target_type, source)
                VALUES (%s::uuid, %s, %s, 'domain', %s)
                ON CONFLICT (engagement_id, name, target) DO NOTHING
            """, (eid, scope_name, _SCOPE_PLACEHOLDER_TARGET, _SCOPE_PLACEHOLDER_SOURCE))
            cur.execute("RELEASE SAVEPOINT sp_placeholder")
        except Exception as e:
            cur.execute("ROLLBACK TO SAVEPOINT sp_placeholder")
            cur.execute("RELEASE SAVEPOINT sp_placeholder")
            errors.append(f"placeholder: {type(e).__name__}: {e}")

        for t in body.targets:
            if isinstance(t, dict):
                target_val = str(t.get("target", "")).strip()
                target_type = t.get("target_type") or _classify_target(target_val)
                source = t.get("source") or body.source
            else:
                target_val = str(t).strip()
                if not target_val:
                    continue
                target_type = _classify_target(target_val)
                source = body.source

            if not target_val:
                continue

            try:
                cur.execute("SAVEPOINT sp_t")
                cur.execute("""
                    INSERT INTO scope_targets (engagement_id, name, target, target_type, source)
                    VALUES (%s::uuid, %s, %s, %s, %s)
                    ON CONFLICT (engagement_id, name, target) DO NOTHING
                """, (eid, scope_name, target_val, target_type, source))
                if cur.rowcount > 0:
                    added += 1
                else:
                    skipped += 1
                cur.execute("RELEASE SAVEPOINT sp_t")
            except Exception as e:
                cur.execute("ROLLBACK TO SAVEPOINT sp_t")
                cur.execute("RELEASE SAVEPOINT sp_t")
                errors.append(f"{target_val}: {type(e).__name__}: {e}")
        conn.commit()

    resp = {"ok": True, "added": added, "skipped": skipped,
            "scope": scope_name, "engagement_id": eid}
    if errors:
        resp["errors"] = errors
    return resp


@app.delete("/engagements/{eid}/scopes/{scope_name}", tags=["Engagements"])
def delete_engagement_scope(eid: str, scope_name: str, _: bool = Depends(auth)):
    """Delete an entire scope and all its targets from an engagement."""
    with get_db() as conn, conn.cursor() as cur:
        cur.execute(
            "DELETE FROM scope_targets WHERE engagement_id = %s::uuid AND name = %s",
            (eid, scope_name)
        )
        deleted = cur.rowcount
        conn.commit()
    return {"ok": True, "deleted": deleted, "scope": scope_name}


class MarkCustomerSitesBody(BaseModel):
    targets: List[str] = []
    scope_name: str = "customer_scope"


# Reserved buckets that are NOT part of the scanned scope; mirrored in the recon
# agent's RESERVED_NONSCANNABLE (dashboard/bff/services/recon_agent.py).
_RESERVED_SCOPES = ("customer_scope", "excluded", "not_in_scope")


def _bg_capture_customer_decisions(targets: list, scope_name: str):
    """Best-effort scope_decisions capture (embeds per-host recon context). Runs
    AFTER the response as a background task — it is ~0.16s/host, so a large
    selection would otherwise block the request past the client timeout and look
    like a hang. Learning-only; the scope move already committed."""
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            for t in targets:
                try:
                    _capture_scope_decisions([t], "customer-site", scope_name, cur)
                except Exception:
                    pass
            conn.commit()
    except Exception as e:
        logging.warning(f"bg customer scope decisions failed: {e}")


@app.post("/engagements/{eid}/scope/mark-customer-sites", tags=["Engagements"])
def mark_customer_sites(eid: str, body: MarkCustomerSitesBody,
                        background_tasks: BackgroundTasks, _: bool = Depends(auth)):
    """Move hosts into the engagement's `customer_scope` (out of the scanned scope).

    Per-host BY DESIGN: we host customers on SHARED domains (e.g. convio.net), so a
    domain-pattern rule would wrongly exclude our own infra. All DB work is done in
    BULK (single statements over the whole target list) so marking a whole group of
    hundreds of hosts returns in ~a second instead of looping per host:
      1. removes them from the scanned engagement scopes (e.g. `blackbaud`);
      2. files them under `customer_scope` (engagement-scoped, UI-visible);
      3. records them in the global `not_in_scope` list (dispatch-gate safety);
      4. resolves the matching customer-site follow-ups + tags the assets.
    The per-host scope_decisions (learning; embeds recon context, ~0.16s each) are
    captured in a BACKGROUND task so they never block the request — and deliberately
    NOT distilled into a `*.domain` rule (that would nuke the shared domain). The
    recon agent skips `customer_scope`, so scanning of these hosts stops.
    """
    from psycopg2.extras import execute_values
    scope_name = (body.scope_name or "customer_scope").strip() or "customer_scope"
    seen: set = set()
    targets = [t for t in (str(x).strip() for x in (body.targets or []))
               if t and not (t in seen or seen.add(t))]
    if not targets:
        raise HTTPException(400, "no targets provided")
    tt = {t: _classify_target(t) for t in targets}

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # Ensure the bucket exists so it shows in the engagement's scope list.
        cur.execute("""
            INSERT INTO scope_targets (engagement_id, name, target, target_type, source)
            VALUES (%s::uuid, %s, %s, 'domain', %s)
            ON CONFLICT (engagement_id, name, target) DO NOTHING
        """, (eid, scope_name, _SCOPE_PLACEHOLDER_TARGET, _SCOPE_PLACEHOLDER_SOURCE))

        # 1. bulk remove from the scanned engagement scopes
        cur.execute("""
            DELETE FROM scope_targets
             WHERE engagement_id = %s::uuid AND target = ANY(%s) AND name NOT IN %s
        """, (eid, targets, _RESERVED_SCOPES))
        # 2. bulk file under customer_scope
        execute_values(cur,
            "INSERT INTO scope_targets (engagement_id, name, target, target_type, source) "
            "VALUES %s ON CONFLICT (engagement_id, name, target) DO NOTHING",
            [(eid, scope_name, t, tt[t], 'customer-site-exclude') for t in targets],
            template="(%s::uuid, %s, %s, %s, %s)")
        moved = len(targets)
        # 3. secondary safety: global not_in_scope. Delete-then-insert because a
        #    unique index does not dedupe NULL-engagement rows.
        cur.execute("""DELETE FROM scope_targets
                        WHERE engagement_id IS NULL AND name = 'not_in_scope'
                          AND target = ANY(%s)""", (targets,))
        execute_values(cur,
            "INSERT INTO scope_targets (name, target, target_type, source) VALUES %s",
            [(t, tt[t]) for t in targets],
            template="('not_in_scope', %s, %s, 'customer-site-exclude')")
        # 4. bulk resolve matching customer-site follow-ups
        cur.execute("""
            UPDATE follow_up_items
               SET status = 'resolved', resolved_at = now(), updated_at = now()
             WHERE target = ANY(%s)
               AND rule_id IN ('customer_hosted_site', 'customer_hosted_site_cname')
               AND status NOT IN ('resolved', 'dismissed')
        """, (targets,))
        resolved = cur.rowcount
        # 5. durable 'customer-site' tag on the assets (badge source).
        try:
            cur.execute("""
                UPDATE assets SET tags = (
                    SELECT array_agg(DISTINCT x)
                      FROM unnest(COALESCE(tags,'{}'::text[]) || ARRAY['customer-site']) x)
                 WHERE lower(hostname) = ANY(%s)
            """, ([t.lower() for t in targets],))
        except Exception as e:
            logging.warning(f"customer-site asset tag failed: {e}")
        conn.commit()

    # Learning decisions run after the response (slow per-host embed).
    background_tasks.add_task(_bg_capture_customer_decisions, targets, scope_name)

    try:
        from webhooks import emit_webhook
        emit_webhook("customer_scope_excluded", "scope", {
            "engagement_id": eid, "scope": scope_name, "moved": moved,
            "resolved_follow_ups": resolved, "targets": targets[:50]})
    except Exception:
        pass
    return {"ok": True, "engagement_id": eid, "scope": scope_name,
            "moved": moved, "resolved_follow_ups": resolved}


class WhoisAgentBody(BaseModel):
    engagement_id: Optional[str] = None
    stale_days: int = 90
    limit: int = 1000
    dispatch: bool = True


def _gather_whois_domains(cur, engagement_id: Optional[str] = None) -> set:
    """Distinct registrable domains worth a WHOIS across ALL scopes + discovered
    owner domains. IPs are dropped (registrable_domain returns None)."""
    from scope_classifier import registrable_domain
    doms: set = set()
    if engagement_id:
        cur.execute("SELECT DISTINCT target FROM scope_targets "
                    "WHERE target <> '' AND engagement_id = %s::uuid", (engagement_id,))
    else:
        cur.execute("SELECT DISTINCT target FROM scope_targets WHERE target <> ''")
    for r in cur.fetchall():
        rd = registrable_domain((r["target"] or "").strip())
        if rd:
            doms.add(rd)
    # discovered customer owner domains (from the customer-site follow-ups)
    cur.execute("""SELECT DISTINCT metadata->>'owner_domain' od FROM follow_up_items
                    WHERE rule_id IN ('customer_hosted_site','customer_hosted_site_cname')
                      AND metadata->>'owner_domain' IS NOT NULL
                      AND metadata->>'owner_domain' <> ''""")
    for r in cur.fetchall():
        if r["od"]:
            doms.add(r["od"].strip().lower())
    return doms


@app.post("/whois-agent/run", tags=["ReconAgent"])
def whois_agent_run(body: WhoisAgentBody = None, _: bool = Depends(auth)):
    """Standing WHOIS collector — passive registrant lookup for EVERY scope +
    discovered owner domain, not just in-scope hosts.

    WHOIS is a public-registry lookup with no traffic to the target host, so it is
    safe (host-scan authorisation rules do not apply) for the out-of-scope
    customer/owner domains that the recon agent's scope-gated whois never reaches.
    Two idempotent phases:
      1. dispatch WHOIS (via osint-runner, passive) for domains with no fresh
         record (older than `stale_days` or missing);
      2. copy registrant org/country from the whois recon_finding into each
         customer-site follow-up's metadata (what the report renders).
    """
    import httpx as _hx
    from datetime import timedelta as _timedelta
    from scope_classifier import registrable_domain
    body = body or WhoisAgentBody()
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        domains = _gather_whois_domains(cur, body.engagement_id)
        # existing whois coverage, keyed by registrable domain (keep the newest)
        cur.execute("SELECT target, created_at FROM recon_findings WHERE source = 'whois'")
        have: dict = {}
        for r in cur.fetchall():
            reg = registrable_domain((r["target"] or "").strip()) or (r["target"] or "").strip().lower()
            if reg and (reg not in have or (r["created_at"] and have[reg] and r["created_at"] > have[reg])):
                have[reg] = r["created_at"]
        cutoff = datetime.now(timezone.utc) - _timedelta(days=max(1, body.stale_days))
        missing = sorted(d for d in domains
                         if d not in have or (have[d] and have[d] < cutoff))
        missing = missing[:max(1, body.limit)]

        dispatched = 0
        if body.dispatch and missing:
            osint_url = os.environ.get("OSINT_RUNNER_URL", "https://osint-runner:8024")
            try:
                rr = _hx.post(f"{osint_url}/jobs/whois", json={"targets": missing},
                              headers={"x-api-key": API_KEY}, verify=False, timeout=30)
                if rr.status_code < 400:
                    dispatched = len(missing)
                else:
                    log.warning("whois dispatch HTTP %s: %s", rr.status_code, rr.text[:200])
            except Exception as e:
                log.warning("whois dispatch failed: %s", e)

        # Enrich customer follow-ups from whatever whois we already have.
        cur.execute("SELECT target, data FROM recon_findings WHERE source = 'whois'")
        wmap: dict = {}
        for r in cur.fetchall():
            d = r["data"] if isinstance(r["data"], dict) else {}
            reg = registrable_domain((r["target"] or "").strip()) or (r["target"] or "").strip().lower()
            org = (d.get("org") or d.get("registrant_org") or d.get("registrant_organization") or "").strip()
            country = (d.get("registrant_country") or d.get("country") or "").strip()
            registrar = (d.get("registrar") or "").strip()
            created = (d.get("creation_date") or d.get("created") or "").strip()
            # WHOIS registrant org is often GDPR-redacted; registrar + created are
            # usually present, so capture them too for attribution context.
            if reg and (org or country or registrar or created):
                wmap[reg] = {"registrant_org": org, "registrant_country": country,
                             "registrar": registrar, "whois_created": created,
                             "whois_enriched": "1"}
        enriched = 0
        for od, w in wmap.items():
            cur.execute("""
                UPDATE follow_up_items
                   SET metadata = COALESCE(metadata, '{}'::jsonb) || %s::jsonb, updated_at = now()
                 WHERE rule_id IN ('customer_hosted_site','customer_hosted_site_cname')
                   AND metadata->>'owner_domain' = %s
                   AND COALESCE(metadata->>'whois_enriched','') = ''
            """, (Json(w), od))
            enriched += cur.rowcount
        conn.commit()

    try:
        from webhooks import emit_webhook
        emit_webhook("whois_agent_run", "whois-agent", {
            "domains": len(domains), "dispatched": dispatched,
            "enriched_follow_ups": enriched})
    except Exception:
        pass
    return {"ok": True, "domains": len(domains), "with_whois": len(have),
            "dispatched": dispatched, "enriched_follow_ups": enriched}


class ScopeRename(BaseModel):
    new_name: str


@app.put("/engagements/{eid}/scopes/{scope_name}", tags=["Engagements"])
def rename_engagement_scope(eid: str, scope_name: str, body: ScopeRename, _: bool = Depends(auth)):
    """Rename a scope under an engagement."""
    with get_db() as conn, conn.cursor() as cur:
        cur.execute(
            "UPDATE scope_targets SET name = %s WHERE engagement_id = %s::uuid AND name = %s",
            (body.new_name, eid, scope_name)
        )
        updated = cur.rowcount
        conn.commit()
    return {"ok": True, "updated": updated, "old_name": scope_name, "new_name": body.new_name}


class ScopeMoveTargets(BaseModel):
    targets: List[str]
    to_engagement_id: str
    to_scope_name: str


@app.post("/engagements/{eid}/scopes/{scope_name}/move", tags=["Engagements"])
def move_scope_targets(eid: str, scope_name: str, body: ScopeMoveTargets, _: bool = Depends(auth)):
    """Move specific targets to a different scope/engagement."""
    moved = 0
    with get_db() as conn, conn.cursor() as cur:
        for target in body.targets:
            try:
                # Delete from source
                cur.execute(
                    "DELETE FROM scope_targets WHERE engagement_id = %s::uuid AND name = %s AND target = %s RETURNING id",
                    (eid, scope_name, target)
                )
                if cur.rowcount > 0:
                    # Insert into destination
                    cur.execute("""
                        INSERT INTO scope_targets (engagement_id, name, target, target_type, source)
                        VALUES (%s::uuid, %s, %s, 'domain', 'moved')
                        ON CONFLICT (engagement_id, name, target) DO NOTHING
                    """, (body.to_engagement_id, body.to_scope_name, target))
                    moved += 1
            except Exception:
                conn.rollback()
        conn.commit()
    return {"ok": True, "moved": moved, "from": f"{eid}/{scope_name}", "to": f"{body.to_engagement_id}/{body.to_scope_name}"}


class ScopeMoveAll(BaseModel):
    to_engagement_id: str


@app.post("/engagements/{eid}/scopes/{scope_name}/move-all", tags=["Engagements"])
def move_entire_scope(eid: str, scope_name: str, body: ScopeMoveAll, _: bool = Depends(auth)):
    """Move an entire scope (all targets) to a different engagement."""
    with get_db() as conn, conn.cursor() as cur:
        cur.execute(
            "UPDATE scope_targets SET engagement_id = %s::uuid WHERE engagement_id = %s::uuid AND name = %s",
            (body.to_engagement_id, eid, scope_name)
        )
        moved = cur.rowcount
        conn.commit()
    return {"ok": True, "moved": moved, "scope": scope_name, "from_engagement": eid, "to_engagement": body.to_engagement_id}


# ============================================================================
# FINDING WORKFLOW (C1)
# ============================================================================

_WORKFLOW_TABLES = {"vuln": "vulns", "web": "web_findings", "playwright": "playwright_findings"}

class WorkflowUpdate(BaseModel):
    workflow_status: Optional[str] = None
    assigned_to: Optional[str] = None
    verified_by: Optional[str] = None
    tester_notes: Optional[str] = None
    original_severity: Optional[str] = None
    report_ready: Optional[bool] = None

@app.patch("/findings/{source}/{fid}/workflow", tags=["Findings"])
def update_finding_workflow(source: str, fid: str, body: WorkflowUpdate, _: bool = Depends(auth)):
    """Update workflow status for a finding."""
    table = _WORKFLOW_TABLES.get(source)
    if not table:
        raise HTTPException(400, f"Invalid source: {source}. Use: vuln, web, playwright")
    updates, vals = [], []
    if body.workflow_status is not None:
        updates.append("workflow_status = %s")
        vals.append(body.workflow_status)
    if body.assigned_to is not None:
        updates.append("assigned_to = %s")
        vals.append(body.assigned_to)
    if body.verified_by is not None:
        updates.append("verified_by = %s")
        vals.append(body.verified_by)
        updates.append("verified_at = now()")
    if body.tester_notes is not None:
        updates.append("tester_notes = %s")
        vals.append(body.tester_notes)
    if body.original_severity is not None:
        updates.append("original_severity = %s")
        vals.append(body.original_severity)
    if body.report_ready is not None:
        updates.append("report_ready = %s")
        vals.append(body.report_ready)
    if not updates:
        raise HTTPException(400, "No fields to update")
    vals.append(fid)
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(f"UPDATE {table} SET {', '.join(updates)} WHERE id = %s RETURNING id", vals)
        row = cur.fetchone()
        if not row:
            conn.rollback()
            raise HTTPException(404, "Finding not found")
        # Auto-create activity records for status/severity changes
        if body.workflow_status is not None:
            cur.execute(
                """INSERT INTO finding_activity (finding_source, finding_id, activity_type, actor, new_value)
                   VALUES (%s, %s, 'status_change', %s, %s)""",
                (source, fid, body.verified_by or body.assigned_to, body.workflow_status))
        if body.original_severity is not None:
            cur.execute(
                """INSERT INTO finding_activity (finding_source, finding_id, activity_type, actor, new_value)
                   VALUES (%s, %s, 'severity_change', %s, %s)""",
                (source, fid, body.verified_by or body.assigned_to, body.original_severity))
        if body.assigned_to is not None:
            cur.execute(
                """INSERT INTO finding_activity (finding_source, finding_id, activity_type, new_value)
                   VALUES (%s, %s, 'assignment', %s)""",
                (source, fid, body.assigned_to))
        conn.commit()
    return {"ok": True, "id": fid}


