# ============================================================================
# EXPLOIT MATCHING (J2)
# ============================================================================

@app.get("/findings/{source}/{fid}/exploit-matches", tags=["Findings"])
def get_finding_exploit_matches(source: str, fid: str, _: bool = Depends(auth)):
    """Find exploits matching a finding's CVE, title, and service info."""
    table = _WORKFLOW_TABLES.get(source)
    if not table:
        raise HTTPException(400, f"Invalid source: {source}. Use: vuln, web, playwright")
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # Get finding details
        if table == "vulns":
            cur.execute(
                """SELECT v.script as title, v.cve, v.severity, v.output,
                          p.port, p.service, p.product, p.version
                   FROM vulns v LEFT JOIN ports p ON p.id = v.port_id
                   WHERE v.id = %s""", (fid,))
        elif table == "web_findings":
            cur.execute(
                "SELECT name as title, url, severity, issue_type, cwe, description, evidence "
                "FROM web_findings WHERE id = %s", (fid,))
        else:
            cur.execute(
                "SELECT title, url, severity, finding_type as issue_type, cwe, description "
                "FROM playwright_findings WHERE id = %s", (fid,))
        finding = cur.fetchone()
        if not finding:
            raise HTTPException(404, "Finding not found")
    # Query exploit search
    params = {"top_k": 5, "min_confidence": 0.2}
    cves = finding.get("cve") or []
    if cves and len(cves) > 0:
        params["cve"] = cves[0]
    # For web findings, also check CWE array
    cwes = finding.get("cwe") or []
    if isinstance(cwes, list) and cwes:
        # CWE values like "CWE-79" — pass as search context
        cwe_str = cwes[0] if isinstance(cwes[0], str) else str(cwes[0])
        if cwe_str and not params.get("cve"):
            params["cve"] = cwe_str  # RAG search can match on CWE too
    if finding.get("service"):
        params["service"] = finding["service"]
    if finding.get("version"):
        params["version"] = finding["version"]
    # Build richer query for web findings: include issue_type and description
    query_parts = []
    if finding.get("title"):
        query_parts.append(finding["title"])
    if finding.get("issue_type") and finding["issue_type"] not in ("zap-alert", "scan_execution", "scan-note"):
        query_parts.append(finding["issue_type"])
    if finding.get("description"):
        query_parts.append(finding["description"][:200])
    if query_parts:
        params["query"] = " ".join(query_parts)[:500]
    if finding.get("port"):
        params["port"] = finding["port"]
    # ── Stored exploit_store rows that match this finding's CVE+target ──
    # These rank above generic exploitdb/metasploit hits because they are
    # curated for this engagement, often already verified, and runnable with
    # one click via POST /exploit-store/{id}/run. A VERIFIED row is the
    # strongest match — put it first.
    stored_matches: list[dict] = []
    try:
        with get_db() as conn2, conn2.cursor(cursor_factory=RealDictCursor) as cur2:
            # Resolve target IP from the finding's asset (vuln -> ports.asset_id,
            # web/playwright -> asset_id or URL host).
            target_ip = None
            if table == "vulns":
                cur2.execute("""SELECT host(a.ip) AS ip FROM vulns v
                                 JOIN ports p ON p.id = v.port_id
                                 JOIN assets a ON a.id = p.asset_id
                                WHERE v.id = %s""", (fid,))
                r = cur2.fetchone()
                target_ip = r["ip"] if r else None
            elif table == "web_findings":
                cur2.execute("""SELECT host(a.ip) AS ip FROM web_findings w
                                 JOIN assets a ON a.id = w.asset_id
                                WHERE w.id = %s""", (fid,))
                r = cur2.fetchone()
                target_ip = r["ip"] if r else None
            # Build the where clause: match CVE OR same target host
            where_bits, where_args = [], []
            if cves:
                where_bits.append("upper(es.cve) = ANY(%s::text[])")
                where_args.append([c.upper() for c in cves if c])
            if target_ip:
                where_bits.append("es.target_host = %s")
                where_args.append(target_ip)
            if where_bits:
                cur2.execute(f"""
                    SELECT es.id, es.name, es.cve, es.target_host, es.target_port,
                           es.verified, es.command, es.rationale, es.built_at,
                           es.llm_model, es.engagement_id
                      FROM exploit_store es
                     WHERE ({' OR '.join(where_bits)})
                     ORDER BY es.verified DESC, es.updated_at DESC
                     LIMIT 10
                """, where_args)
                for r in cur2.fetchall():
                    stored_matches.append({
                        "source": "exploit_store",
                        "exploit_store_id": str(r["id"]),
                        "title": r["name"],
                        "cve": r["cve"],
                        "target_host": r["target_host"],
                        "target_port": r["target_port"],
                        "verified": bool(r["verified"]),
                        "command_preview": (r["command"] or "")[:400],
                        "rationale": (r["rationale"] or "")[:500],
                        "built_at": r["built_at"].isoformat() if r["built_at"] else None,
                        "llm_model": r["llm_model"],
                        "runnable": True,  # UI: show a Run button
                        "match_confidence": 1.0 if r["verified"] else 0.7,
                    })
    except Exception as e:  # noqa: BLE001
        logging.debug("exploit_store match lookup failed: %s", e)

    try:
        resp = requests.get(f"{SCAN_RECOMMENDER_URL}/rag/search/enhanced", params=params, verify=False, timeout=15)
        if resp.status_code == 200:
            data = resp.json()
            rag_matches = data.get("exploitdb", [])[:5] + data.get("metasploit", [])[:5]
            # Stored exploits first; RAG matches after.
            return {"matches": stored_matches + rag_matches, "finding": finding}
    except Exception:
        pass
    return {"matches": stored_matches, "finding": finding}


@app.get("/findings/{source}/{fid}/auto-evidence", tags=["Findings"])
def get_finding_auto_evidence(source: str, fid: str, _: bool = Depends(auth)):
    """Already-collected material related to this finding — what the operator
    sees under "Add Evidence" BEFORE they upload anything. Three source types:

      (1) finding_evidence: the finding's own `evidence`/`output` text column
      (2) stored_exploits: every exploit_store row matching the finding's
          CVE or target_host. Includes command + rationale + verified flag
          so the operator can see the proven technique without digging.
      (3) target_artifacts: raw_artifacts rows for the finding's target_ip
          (last 10, newest first) — nmap/nuclei/zap/cve_poc_builder output
          already captured against this host.

    Each item has a shared shape {kind, title, body/preview, created_at,
    link{type,id}} so the UI can render them uniformly as evidence cards."""
    table = _WORKFLOW_TABLES.get(source)
    if not table:
        raise HTTPException(400, f"Invalid source: {source}. Use: vuln, web, playwright")
    items: list[dict] = []
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # (1) finding's own evidence/output column — tier-by-source
        target_ip = None
        cves: list[str] = []
        if table == "vulns":
            cur.execute("""SELECT v.cve, v.output, v.script,
                                 host(a.ip) AS ip
                            FROM vulns v
                            LEFT JOIN ports p ON p.id = v.port_id
                            LEFT JOIN assets a ON a.id = p.asset_id
                           WHERE v.id = %s""", (fid,))
            r = cur.fetchone()
            if r:
                target_ip = r.get("ip")
                cves = list(r.get("cve") or [])
                if r.get("output"):
                    items.append({"kind": "finding_output", "title": r.get("script") or "scanner output",
                                  "body": r["output"][:4000], "created_at": None,
                                  "link": {"type": "vuln", "id": fid}})
        elif table == "web_findings":
            cur.execute("""SELECT w.name, w.evidence, w.description, w.url,
                                 host(a.ip) AS ip
                            FROM web_findings w
                            LEFT JOIN assets a ON a.id = w.asset_id
                           WHERE w.id = %s""", (fid,))
            r = cur.fetchone()
            if r:
                target_ip = r.get("ip")
                if r.get("evidence"):
                    items.append({"kind": "finding_evidence", "title": r.get("name") or "web evidence",
                                  "body": r["evidence"][:4000], "created_at": None,
                                  "link": {"type": "web_finding", "id": fid}})
        else:
            cur.execute("""SELECT title, description, url FROM playwright_findings WHERE id = %s""", (fid,))
            r = cur.fetchone()
            if r and r.get("description"):
                items.append({"kind": "finding_description", "title": r.get("title") or "playwright finding",
                              "body": r["description"][:4000], "created_at": None,
                              "link": {"type": "playwright_finding", "id": fid}})

        # (2) stored exploit_store rows matching CVE or target host
        where_bits, where_args = [], []
        if cves:
            where_bits.append("upper(es.cve) = ANY(%s::text[])")
            where_args.append([c.upper() for c in cves if c])
        if target_ip:
            where_bits.append("es.target_host = %s")
            where_args.append(target_ip)
        if where_bits:
            cur.execute(f"""
                SELECT id, name, cve, target_host, target_port, verified,
                       command, rationale, built_at
                  FROM exploit_store es
                 WHERE ({' OR '.join(where_bits)})
                 ORDER BY verified DESC, updated_at DESC LIMIT 10
            """, where_args)
            for e in cur.fetchall():
                items.append({
                    "kind": "stored_exploit",
                    "title": f"{'✓ VERIFIED' if e['verified'] else 'unverified'} — {e['name']}",
                    "body": (f"CVE: {e['cve']}\n"
                             f"Target: {e['target_host']}:{e['target_port']}\n"
                             f"Verified: {e['verified']}\n\n"
                             f"RATIONALE:\n{(e['rationale'] or '(none)')[:600]}\n\n"
                             f"COMMAND:\n{(e['command'] or '')[:1200]}"),
                    "created_at": e["built_at"].isoformat() if e["built_at"] else None,
                    "link": {"type": "exploit_store", "id": str(e["id"])},
                    "verified": bool(e["verified"]),
                    "runnable": True,
                })

        # (3) raw_artifacts rows for this target — scans the operator ran
        if target_ip:
            cur.execute("""SELECT id, tool, source, note, byte_size, first_seen,
                                 substring(content, 1, 600) AS preview
                            FROM raw_artifacts
                           WHERE target = %s
                           ORDER BY first_seen DESC LIMIT 10""", (target_ip,))
            for a in cur.fetchall():
                items.append({
                    "kind": "target_artifact",
                    "title": f"[{a['tool']}] {a.get('note') or ''}".strip(),
                    "body": (a["preview"] or "")[:1800],
                    "created_at": a["first_seen"].isoformat() if a["first_seen"] else None,
                    "link": {"type": "artifact", "id": str(a["id"])},
                    "byte_size": a["byte_size"],
                })
    return {"items": items, "count": len(items), "target_ip": target_ip, "cves": cves}


# ── Web PoC Generation + Queueing ─────────────────────────────────────────

class GeneratePocsRequest(BaseModel):
    max_payloads: int = Field(5, description="Maximum payloads to return")
    use_llm: bool = Field(True, description="Augment templates with LLM-generated payloads")
    knowledge_source: str = Field("all", description="skill | rag | yaml | all")


@app.post("/findings/{source}/{fid}/generate-pocs", tags=["Findings"])
def generate_pocs_for_finding(
    source: str, fid: str, body: GeneratePocsRequest = None,
    _: bool = Depends(auth),
):
    """
    Generate PoC payloads for a web finding using templates + LLM.

    Calls the exploit-runner's web_payload_generator to produce a list of
    targeted payloads the user can review and select.
    """
    if body is None:
        body = GeneratePocsRequest()

    table = _WORKFLOW_TABLES.get(source)
    if not table:
        raise HTTPException(400, f"Invalid source: {source}")

    # Fetch finding details
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        if table == "web_findings":
            cur.execute(
                "SELECT id, name, url, issue_type, severity, evidence, method, payload, parameter "
                "FROM web_findings WHERE id = %s", (fid,))
        elif table == "playwright_findings":
            cur.execute(
                "SELECT id, title as name, url, finding_type as issue_type, severity, "
                "description as evidence, location as parameter "
                "FROM playwright_findings WHERE id = %s", (fid,))
        else:
            raise HTTPException(400, "PoC generation only supports web/playwright findings")
        finding = cur.fetchone()
        if not finding:
            raise HTTPException(404, "Finding not found")

    # Call exploit-runner payload generation endpoint
    try:
        resp = requests.post(
            f"{EXPLOIT_RUNNER_URL}/generate-payloads",
            json={
                "issue_type": finding.get("issue_type", ""),
                "url": finding.get("url", ""),
                "parameter": finding.get("parameter", ""),
                "evidence": finding.get("evidence", ""),
                "name": finding.get("name", ""),
                "max_payloads": body.max_payloads,
                "use_llm": body.use_llm,
                "knowledge_source": body.knowledge_source,
            },
            timeout=120,
        )
        if resp.status_code >= 400:
            raise HTTPException(resp.status_code, resp.text)
        payloads = resp.json().get("payloads", [])
    except requests.exceptions.ConnectionError:
        # Fallback: return empty if exploit-runner not reachable
        payloads = []
    except requests.exceptions.Timeout:
        payloads = []

    return {"payloads": payloads, "finding": dict(finding)}


class QueuePocRequest(BaseModel):
    payloads: List[Dict[str, Any]] = Field(..., description="Selected payloads to queue")


@app.post("/findings/{source}/{fid}/deepen", tags=["Findings"])
def deepen_finding_endpoint(source: str, fid: str, request: dict = None,
                            authorized: bool = Depends(auth)):
    """Operator-initiated "Deepen this finding": synthesize ONE confirmation probe
    for the finding (router deepen role, force=True), scope-gate it, and queue it.
    METHOD-AWARE: a GET finding gets a read-only probe queued to the safe lane
    (tier='safe'); a state-changing (POST/PUT/PATCH/DELETE) finding — e.g. a
    POST-body SQLi — gets an impactful POST/sqlmap confirmation queued to the
    APPROVAL lane (tier='impactful', requires_approval=true, pending_exploit_id).
    Web findings only. Body/query: {engagement_id?}."""
    if source not in ("web", "web_findings"):
        raise HTTPException(400, "deepen currently supports web findings only")
    try:
        from etl.post_enumeration import deepen_web_finding
    except ImportError:  # pragma: no cover
        from post_enumeration import deepen_web_finding
    eid = (request or {}).get("engagement_id")
    res = deepen_web_finding(fid, engagement_id=eid)
    if not res.get("ok"):
        # 422 for "nothing proposed / out of scope", 404 for missing finding
        code = 404 if res.get("reason") == "finding not found" else 422
        raise HTTPException(code, res.get("reason") or "could not deepen finding")
    return res


@app.post("/followups/default-cred-check/{rec_id}/approve", tags=["Findings"])
def approve_default_cred_check(rec_id: str, authorized: bool = Depends(auth)):
    """Approve a default-credential check that exceeded max_auto_attempts and was
    queued for a human. Runs the bounded check with force=True (the approval path)
    against the queued login form, then marks the recommendation done."""
    try:
        from etl.default_cred_check import run_default_cred_check
        from etl.scope_gate import load_dispatch_scope, load_host_aliases
    except ImportError:  # pragma: no cover
        from default_cred_check import run_default_cred_check
        from scope_gate import load_dispatch_scope, load_host_aliases
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("""SELECT host(ip)::text AS host, engagement_id::text AS eid,
                              extra->>'login_url' AS login_url, status
                         FROM scan_recommendations
                        WHERE id = %s::uuid AND scanner = 'default_cred_check'""", (rec_id,))
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "default-cred-check recommendation not found")
        if not row.get("login_url"):
            raise HTTPException(409, "recommendation has no login_url")
        host, eid, login_url = row["host"], row["eid"], row["login_url"]
        scope_rows, src = load_dispatch_scope(cur, eid)
        if src == "unavailable":
            raise HTTPException(409, "no dispatch scope configured — cannot run (fail closed)")
        aliases = load_host_aliases(cur, host)
        res = run_default_cred_check(cur, host, login_url, engagement_id=eid,
                                     scope_rows=scope_rows, aliases=aliases, force=True)
        cur.execute("UPDATE scan_recommendations SET status='done' WHERE id=%s::uuid", (rec_id,))
        conn.commit()
    return res


@app.post("/findings/{source}/{fid}/queue-poc", tags=["Findings"])
def queue_poc_for_finding(
    source: str, fid: str, body: QueuePocRequest,
    _: bool = Depends(auth),
):
    """
    Queue selected PoC payloads as pending_exploits for approval.

    Each selected payload creates one pending_exploit with
    exploit_category='webapp' and the payload details in metadata.
    """
    table = _WORKFLOW_TABLES.get(source)
    if not table:
        raise HTTPException(400, f"Invalid source: {source}")

    # Fetch finding for context
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        if table == "web_findings":
            cur.execute(
                "SELECT id, name, url, issue_type, severity, asset_id "
                "FROM web_findings WHERE id = %s", (fid,))
        elif table == "playwright_findings":
            cur.execute(
                "SELECT id, title as name, url, finding_type as issue_type, severity, asset_id "
                "FROM playwright_findings WHERE id = %s", (fid,))
        else:
            raise HTTPException(400, "PoC queueing only supports web/playwright findings")
        finding = cur.fetchone()
        if not finding:
            raise HTTPException(404, "Finding not found")

        # Determine target IP from asset
        target_ip = "0.0.0.0"
        if finding.get("asset_id"):
            cur.execute("SELECT host(ip)::text as ip FROM assets WHERE id = %s", (finding["asset_id"],))
            asset_row = cur.fetchone()
            if asset_row:
                target_ip = asset_row["ip"]

        # Extract port from URL if possible
        from urllib.parse import urlparse
        parsed_url = urlparse(finding.get("url", ""))
        target_port = parsed_url.port or (443 if parsed_url.scheme == "https" else 80)

        # Map issue_type to exploit_type
        issue_type = (finding.get("issue_type") or "").lower()
        type_map = {
            "xss": "xss", "sqli": "sqli", "sql-injection": "sqli",
            "command-injection": "command_injection", "ssrf": "ssrf",
            "lfi": "lfi", "path-traversal": "lfi", "xxe": "xxe",
            # 'open_redirect' is NOT an allowed exploit_type — map web-app issues
            # with no dedicated enum to the 'webapp_other' catch-all.
            "csrf": "csrf", "open-redirect": "webapp_other",
        }
        exploit_type = type_map.get(issue_type, "other")

        queued_ids = []
        for payload_item in body.payloads:
            pending_id = str(uuid.uuid4())
            metadata = {
                "payload": payload_item.get("payload", ""),
                "injection_point": payload_item.get("injection_point", "query_param"),
                "parameter": payload_item.get("target_parameter", ""),
                "success_indicator": payload_item.get("success_indicator", "response_content"),
                "target_url": finding.get("url", ""),
                "finding_id": str(fid),
                "finding_source": source,
                "confidence": payload_item.get("confidence", 0.5),
                "auto_triggered": False,
            }

            # match_confidence is stored 0.0-1.0; an LLM/user value > 1 is a
            # percentage (95) and would render as 9500%. Normalize.
            _wc = payload_item.get("confidence", 0.5)
            try:
                _wc = float(_wc)
                _wc = _wc / 100.0 if _wc > 1 else _wc
                _wc = max(0.0, min(1.0, _wc))
            except (TypeError, ValueError):
                _wc = 0.5

            cur.execute("""
                INSERT INTO pending_exploits
                (id, source, exploit_id, exploit_title, exploit_type, exploit_category,
                 target_ip, target_port, target_service,
                 customized_command, parameters, match_confidence,
                 match_reasoning, status, requested_by, metadata)
                VALUES (%s, 'web_poc', %s, %s, %s, 'webapp',
                        %s::inet, %s, %s,
                        %s, %s, %s,
                        %s, 'pending', 'user', %s)
            """, (
                pending_id,
                f"poc-{fid[:8]}",
                payload_item.get("description", finding.get("name", "Web PoC")),
                exploit_type,
                target_ip,
                target_port,
                issue_type,
                payload_item.get("payload", "")[:500],
                Json({}),
                _wc,
                payload_item.get("description", "User-selected web PoC payload"),
                Json(metadata),
            ))
            queued_ids.append(pending_id)

        conn.commit()

    return {"queued": queued_ids, "count": len(queued_ids)}


