class RescopeRequest(BaseModel):
    dry_run: bool = True
    limit: int = 500


@app.post("/follow-ups/rescope", tags=["Follow-Ups"])
def rescope_follow_ups(req: RescopeRequest, authorized: bool = Depends(auth)):
    """Re-evaluate quarantined follow-ups against the CURRENT scope.

    Why this is needed: `_is_out_of_scope_target` fails closed, which is right at
    discovery time — but the quarantine was never revisited. Its own docstring
    says "the caller quarantines rather than deletes, so this is recoverable",
    and nothing recovered it.

    Two ways a row ends up wrongly quarantined:

      * it was discovered before the scope was configured (correct then, wrong
        now), or
      * its `target` was the literal string "unknown", because the rule engine's
        target resolver only looked at target/url/ip and rules like
        sensitive_parameter select `url_pattern`. Scope matching then treated
        "unknown" as a hostname and refused it, so "we do not know the target"
        became "the target is out of scope". Fixed in rule_engine._row_target;
        this repairs the rows already stored.

    The target is recovered from the SOURCE ROW where possible and only then from
    the title, because a title is display text and parsing it is a guess.
    Nothing is ever moved INTO quarantine here: a row that is genuinely
    out-of-scope keeps its label.
    """
    import re as _re
    from osint_agent import _is_out_of_scope_target

    label = "[OUT-OF-SCOPE] "
    fixed, checked, still_oos = [], 0, 0
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("""
            SELECT f.id, f.title, f.target, f.tags, f.finding_id, f.finding_source,
                   f.engagement_id,
                   dp.url_pattern              AS dp_url,
                   wf.url                      AS wf_url,
                   host(av.ip)                 AS vuln_ip
              FROM follow_up_items f
              LEFT JOIN discovered_params dp ON dp.id = f.finding_id
              LEFT JOIN web_findings wf      ON wf.id = f.finding_id
              LEFT JOIN vulns v              ON v.id  = f.finding_id
              LEFT JOIN assets av            ON av.id = v.asset_id
             WHERE f.title LIKE %s
             ORDER BY f.created_at
             LIMIT %s
        """, (label + "%", req.limit))
        rows = cur.fetchall()

        for r in rows:
            checked += 1
            bare = (r["target"] or "").strip()
            recovered = None
            for cand in (r["dp_url"], r["wf_url"], r["vuln_ip"]):
                if cand and str(cand).strip():
                    recovered = str(cand).strip()
                    break
            if not recovered and (not bare or bare.lower() == "unknown"):
                # Last resort: the row's own title. A URL first, then a bare IPv4.
                m = _re.search(r"https?://[^\s\"']+", r["title"] or "")
                if not m:
                    m = _re.search(r"\b\d{1,3}(?:\.\d{1,3}){3}\b", r["title"] or "")
                recovered = m.group(0) if m else None
            target = recovered or bare
            if not target or target.lower() == "unknown":
                still_oos += 1
                continue
            if _is_out_of_scope_target(target, cur, r["engagement_id"]):
                still_oos += 1
                continue

            new_title = r["title"][len(label):] if r["title"].startswith(label) else r["title"]
            new_tags = [t for t in (r["tags"] or [])
                        if t not in ("out-of-scope", "unknown-scope")]
            fixed.append({"id": str(r["id"]), "target": target,
                          "title": new_title, "was_target": r["target"]})
            if not req.dry_run:
                cur.execute("""
                    UPDATE follow_up_items
                       SET title = %s, target = %s, tags = %s::text[],
                           updated_at = now()
                     WHERE id = %s
                """, (new_title, target, new_tags, r["id"]))

    if not req.dry_run and fixed:
        try:
            from webhooks import emit_webhook
            emit_webhook("follow_ups_rescoped", "osint_agent", {
                "checked": checked, "corrected": len(fixed),
                "still_out_of_scope": still_oos,
            })
        except Exception:
            pass
    return {"ok": True, "dry_run": req.dry_run, "checked": checked,
            "corrected": len(fixed), "still_out_of_scope": still_oos,
            "items": fixed}


@app.get("/follow-ups/stats", tags=["Follow-Ups"])
def follow_up_stats(
    engagement_id: Optional[str] = Query(None),
    exclude_scope: Optional[str] = Query(
        None, description="Comma-separated scope list names whose hosts to omit"),
    _: bool = Depends(auth),
):
    """Aggregate counts by status, priority, and flagged_by.

    Takes the same exclude_scope as the list endpoint on purpose: a header that
    counted rows the table refuses to show would contradict the table under it.
    """
    stat_clauses = []
    params = []
    if engagement_id:
        stat_clauses.append("engagement_id = %s::uuid")
        params.append(engagement_id)
    _ex, _exp = _scope_exclusion_clause(HOST_EXPR_FOLLOWUP, exclude_scope)
    if _ex:
        stat_clauses.append(_ex)
        params.extend(_exp)
    eng_clause = ("WHERE " + " AND ".join(stat_clauses)) if stat_clauses else ""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(f"""
            SELECT
                count(*) FILTER (WHERE status = 'open')        AS open,
                count(*) FILTER (WHERE status = 'in_progress') AS in_progress,
                count(*) FILTER (WHERE status = 'resolved')    AS resolved,
                count(*) FILTER (WHERE status = 'dismissed')   AS dismissed,
                count(*) FILTER (WHERE priority = 'critical')  AS critical,
                count(*) FILTER (WHERE priority = 'high')      AS high,
                count(*) FILTER (WHERE priority = 'medium')    AS medium_pri,
                count(*) FILTER (WHERE priority = 'low')       AS low_pri,
                count(*) FILTER (WHERE flagged_by = 'manual')      AS manual,
                count(*) FILTER (WHERE flagged_by = 'osint_agent') AS agent,
                count(*) FILTER (WHERE flagged_by LIKE 'rule:%%')  AS rule_flagged,
                count(*) AS total
            FROM follow_up_items {eng_clause}
        """, params)
        row = cur.fetchone()
    return {"stats": row}


@app.get("/follow-ups/group-ids", tags=["Follow-Ups"])
def follow_up_group_ids(
    group_key: str = Query(...),
    group_by: str = Query("title"),
    status: Optional[str] = Query(None),
    exclude_status: Optional[str] = Query(None),
    engagement_id: Optional[str] = Query(None),
    _: bool = Depends(auth),
):
    """Get all follow-up IDs matching a group key (for bulk select)."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        clauses = []
        params = []
        if group_by == "title":
            clauses.append("title ILIKE %s")
            params.append(f"%{group_key}%")
        else:
            clauses.append("(target ILIKE %s OR target ILIKE %s)")
            params.extend([f"%{group_key}%", f"%://{group_key}%"])
        if status:
            clauses.append("status = %s"); params.append(status)
        if exclude_status:
            clauses.append("status != %s"); params.append(exclude_status)
        if engagement_id:
            clauses.append("engagement_id = %s::uuid"); params.append(engagement_id)
        where = f"WHERE {' AND '.join(clauses)}" if clauses else ""
        cur.execute(f"SELECT id::text FROM follow_up_items {where} LIMIT 5000", params)
        return {"ids": [r["id"] for r in cur.fetchall()]}


@app.get("/follow-ups/grouped", tags=["Follow-Ups"])
def follow_ups_grouped(
    group_by: str = Query("title", description="title or target"),
    status: Optional[str] = Query(None),
    exclude_status: Optional[str] = Query(None),
    engagement_id: Optional[str] = Query(None),
    exclude_scope: Optional[str] = Query(
        None, description="Comma-separated scope list names whose hosts to omit"),
    authorized: bool = Depends(auth),
):
    """Return follow-ups grouped by finding name or target host with counts."""
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        where_clauses = []
        params = []
        if status:
            where_clauses.append("status = %s")
            params.append(status)
        if exclude_status:
            where_clauses.append("status != %s")
            params.append(exclude_status)
        if engagement_id:
            where_clauses.append("engagement_id = %s::uuid")
            params.append(engagement_id)
        _ex, _exp = _scope_exclusion_clause(HOST_EXPR_FOLLOWUP, exclude_scope)
        if _ex:
            where_clauses.append(_ex)
            params.extend(_exp)
        where = f"WHERE {' AND '.join(where_clauses)}" if where_clauses else ""

        if group_by == "target":
            # Group by hostname extracted from target
            cur.execute(f"""
                SELECT
                    COALESCE(
                        CASE
                            WHEN target LIKE 'http%%' THEN split_part(split_part(target, '://', 2), '/', 1)
                            ELSE split_part(target, '/', 1)
                        END,
                        'No target'
                    ) AS group_key,
                    count(*) AS total,
                    count(*) FILTER (WHERE status = 'open') AS open_count,
                    count(*) FILTER (WHERE status = 'in_progress') AS in_progress_count,
                    count(*) FILTER (WHERE status = 'resolved') AS resolved_count,
                    count(*) FILTER (WHERE status = 'dismissed') AS dismissed_count,
                    array_agg(DISTINCT
                        CASE
                            WHEN title LIKE '%% \u2014 %%' THEN split_part(title, ' \u2014 ', 1)
                            WHEN title LIKE '%% -- %%' THEN split_part(title, ' -- ', 1)
                            ELSE title
                        END
                    ) AS finding_names
                FROM follow_up_items
                {where}
                GROUP BY group_key
                ORDER BY total DESC
            """, params)
        else:
            # Group by finding name (title prefix before separator)
            # For software CVE titles like "Vulnerable: IIS 10.0 on 1.2.3.4 — CVE-..."
            # group by the part before " on " to roll up all hosts under one finding
            cur.execute(f"""
                SELECT
                    CASE
                        WHEN title LIKE '%% on %%' THEN trim(split_part(title, ' on ', 1))
                        WHEN title LIKE '%% \u2014 %%' THEN trim(split_part(title, ' \u2014 ', 1))
                        WHEN title LIKE '%% -- %%' THEN trim(split_part(title, ' -- ', 1))
                        WHEN title LIKE '%% \u2013 %%' THEN trim(split_part(title, ' \u2013 ', 1))
                        ELSE trim(title)
                    END AS group_key,
                    count(*) AS total,
                    count(*) FILTER (WHERE status = 'open') AS open_count,
                    count(*) FILTER (WHERE status = 'in_progress') AS in_progress_count,
                    count(*) FILTER (WHERE status = 'resolved') AS resolved_count,
                    count(*) FILTER (WHERE status = 'dismissed') AS dismissed_count,
                    count(DISTINCT
                        CASE
                            WHEN target LIKE 'http%%' THEN split_part(split_part(target, '://', 2), '/', 1)
                            ELSE split_part(COALESCE(target, ''), '/', 1)
                        END
                    ) AS unique_hosts,
                    array_agg(DISTINCT
                        CASE
                            WHEN target LIKE 'http%%' THEN split_part(split_part(target, '://', 2), '/', 1)
                            ELSE split_part(COALESCE(target, ''), '/', 1)
                        END
                    ) AS host_samples
                FROM follow_up_items
                {where}
                GROUP BY group_key
                ORDER BY total DESC
            """, params)

        rows = cur.fetchall()
        # Trim host_samples to max 5
        for r in rows:
            if r.get("host_samples"):
                r["host_samples"] = [h for h in r["host_samples"] if h][:5]
            if r.get("finding_names"):
                r["finding_names"] = [f for f in r["finding_names"] if f][:5]

    return {"groups": rows, "group_by": group_by, "total_groups": len(rows)}


@app.get("/follow-ups", tags=["Follow-Ups"])
def list_follow_ups(
    status: Optional[str] = Query(None),
    exclude_status: Optional[str] = Query(None),
    severity: Optional[str] = Query(None),
    priority: Optional[str] = Query(None),
    flagged_by: Optional[str] = Query(None),
    engagement_id: Optional[str] = Query(None),
    rule_id: Optional[str] = Query(None),
    search: Optional[str] = Query(None),
    exclude_scope: Optional[str] = Query(
        None, description="Comma-separated scope list names whose hosts to omit, "
                          "e.g. 'customer_scope' to drop customer-hosted sites"),
    limit: int = Query(10000),
    offset: int = Query(0),
    _: bool = Depends(auth),
):
    """List follow-up items with filters."""
    clauses, params = [], []
    if status:
        clauses.append("status = %s"); params.append(status)
    if exclude_status:
        clauses.append("status != %s"); params.append(exclude_status)
    if severity:
        clauses.append("severity = %s"); params.append(severity)
    if priority:
        clauses.append("priority = %s"); params.append(priority)
    if flagged_by:
        clauses.append("flagged_by = %s"); params.append(flagged_by)
    if engagement_id:
        clauses.append("engagement_id = %s::uuid"); params.append(engagement_id)
    if rule_id:
        clauses.append("rule_id = %s"); params.append(rule_id)
    if search:
        clauses.append("(title ILIKE %s OR target ILIKE %s OR reason ILIKE %s OR rule_id ILIKE %s)")
        params.extend([f"%{search}%", f"%{search}%", f"%{search}%", f"%{search}%"])
    _ex, _exp = _scope_exclusion_clause(HOST_EXPR_FOLLOWUP, exclude_scope)
    if _ex:
        clauses.append(_ex)
        params.extend(_exp)
    where = ("WHERE " + " AND ".join(clauses)) if clauses else ""
    params.extend([limit, offset])
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(f"""
            SELECT * FROM follow_up_items {where}
            ORDER BY
                CASE priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1
                              WHEN 'medium' THEN 2 ELSE 3 END,
                created_at DESC
            LIMIT %s OFFSET %s
        """, params)
        rows = cur.fetchall()
    return {"follow_ups": rows}


def _derive_follow_up_url(target: Optional[str], detail: dict) -> str:
    """Best-effort URL for a follow-up host. Generic across rules: honours an
    already-URL target, otherwise builds from host + the linked finding's port."""
    t = (target or "").strip()
    if not t:
        return ""
    if t.lower().startswith(("http://", "https://")):
        return t
    host = t.split("/")[0]
    port = str((detail or {}).get("port") or "").strip()
    if port in ("80", ""):
        return f"http://{host}" if port == "80" else f"https://{host}"
    if port == "443":
        return f"https://{host}"
    return f"https://{host}:{port}"


@app.get("/follow-ups/export", tags=["Follow-Ups"])
def export_follow_ups(
    format: str = Query("csv", description="csv | json | md | urls"),
    status: Optional[str] = Query(None),
    exclude_status: Optional[str] = Query(None),
    severity: Optional[str] = Query(None),
    priority: Optional[str] = Query(None),
    flagged_by: Optional[str] = Query(None),
    engagement_id: Optional[str] = Query(None),
    rule_id: Optional[str] = Query(None),
    search: Optional[str] = Query(None),
    _: bool = Depends(auth),
):
    """Export follow-up items in a chosen format, enriched with the linked
    finding's detail. Filters mirror GET /follow-ups exactly, so any view an
    operator can build in the UI can be exported. Generic across rules — cert,
    CVE, exposed-admin all flow through the same path; rule-specific detail rides
    along in `detail_json` (CSV/JSON) rather than in bespoke columns.

    Formats: csv (flat rows), json (enriched objects), md (grouped report),
    urls (one derived URL per line, de-duplicated)."""
    from fastapi import Response
    fmt = (format or "csv").lower()
    if fmt not in ("csv", "json", "md", "urls"):
        raise HTTPException(400, "format must be csv | json | md | urls")

    clauses, params = [], []
    for col, val in (("status", status), ("severity", severity), ("priority", priority),
                     ("flagged_by", flagged_by), ("rule_id", rule_id)):
        if val:
            clauses.append(f"{col} = %s"); params.append(val)
    if exclude_status:
        clauses.append("status != %s"); params.append(exclude_status)
    if engagement_id:
        clauses.append("engagement_id = %s::uuid"); params.append(engagement_id)
    if search:
        clauses.append("(title ILIKE %s OR target ILIKE %s OR reason ILIKE %s OR rule_id ILIKE %s)")
        params.extend([f"%{search}%"] * 4)
    where = ("WHERE " + " AND ".join(clauses)) if clauses else ""

    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(f"""
            SELECT * FROM follow_up_items {where}
            ORDER BY rule_id,
                CASE priority WHEN 'critical' THEN 0 WHEN 'high' THEN 1
                              WHEN 'medium' THEN 2 ELSE 3 END,
                target
        """, params)
        rows = [dict(r) for r in cur.fetchall()]

        # Enrich recon-sourced items with their tlsx/dns/etc finding detail.
        recon_ids = [r["finding_id"] for r in rows
                     if r.get("finding_source") == "recon" and r.get("finding_id")]
        detail_by_id = {}
        if recon_ids:
            cur.execute("SELECT id::text, data FROM recon_findings WHERE id = ANY(%s::uuid[])",
                        ([str(i) for i in recon_ids],))
            for r in cur.fetchall():
                d = r["data"]
                if isinstance(d, str):
                    try:
                        d = json.loads(d)
                    except Exception:
                        d = {}
                detail_by_id[r["id"]] = d or {}

    enriched = []
    for r in rows:
        detail = detail_by_id.get(str(r.get("finding_id")), {}) if r.get("finding_id") else {}
        enriched.append({
            "follow_up_id": str(r["id"]),
            "rule_id": r.get("rule_id") or "",
            "title": r.get("title") or "",
            "host": r.get("target") or "",
            "url": _derive_follow_up_url(r.get("target"), detail),
            "severity": r.get("severity") or "",
            "priority": r.get("priority") or "",
            "status": r.get("status") or "",
            "reason": r.get("reason") or "",
            "flagged_by": r.get("flagged_by") or "",
            "assigned_to": r.get("assigned_to") or "",
            "confidence": r.get("confidence"),
            "tags": r.get("tags") or [],
            "created_at": r["created_at"].isoformat() if r.get("created_at") else "",
            "finding_source": r.get("finding_source") or "",
            "finding_id": str(r["finding_id"]) if r.get("finding_id") else "",
            "detail": detail,
            "metadata": r.get("metadata") or {},
        })

    stamp = datetime.now(timezone.utc).strftime("%Y%m%d-%H%M%S")
    tag = (rule_id or "all").replace("/", "_")
    fname = f"follow-ups-{tag}-{stamp}"

    if fmt == "json":
        return Response(json.dumps({"count": len(enriched), "follow_ups": enriched}, default=str),
                        media_type="application/json",
                        headers={"Content-Disposition": f'attachment; filename="{fname}.json"'})

    if fmt == "urls":
        seen, lines = set(), []
        for e in enriched:
            u = e["url"]
            if u and u not in seen:
                seen.add(u); lines.append(u)
        return Response("\n".join(lines) + ("\n" if lines else ""),
                        media_type="text/plain",
                        headers={"Content-Disposition": f'attachment; filename="{fname}-urls.txt"'})

    if fmt == "csv":
        import csv as _csv
        import io as _io
        buf = _io.StringIO()
        cols = ["follow_up_id", "rule_id", "title", "host", "url", "severity",
                "priority", "status", "reason", "flagged_by", "assigned_to",
                "confidence", "tags", "created_at", "finding_source",
                "finding_id", "detail_json"]
        w = _csv.DictWriter(buf, fieldnames=cols, extrasaction="ignore")
        w.writeheader()
        for e in enriched:
            row = dict(e)
            row["tags"] = ",".join(e["tags"]) if isinstance(e["tags"], list) else (e["tags"] or "")
            _d = e["detail"] or e.get("metadata") or {}
            row["detail_json"] = json.dumps(_d, default=str) if _d else ""
            row.pop("detail", None)
            row.pop("metadata", None)
            w.writerow(row)
        return Response(buf.getvalue(), media_type="text/csv",
                        headers={"Content-Disposition": f'attachment; filename="{fname}.csv"'})

    # md — grouped by rule_id
    from collections import defaultdict
    groups = defaultdict(list)
    for e in enriched:
        groups[e["rule_id"] or "(no rule)"].append(e)
    lines = [f"# Follow-ups export ({len(enriched)} items)", "",
             f"Generated {stamp} UTC" + (f" · engagement {engagement_id}" if engagement_id else ""), ""]
    for rid in sorted(groups):
        g = groups[rid]
        lines.append(f"## {rid} — {len(g)} item(s)")
        lines.append("")
        lines.append("| Host | URL | Severity | Reason |")
        lines.append("|---|---|---|---|")
        for e in g:
            reason = (e["reason"] or "").replace("|", "\\|")
            lines.append(f"| {e['host']} | {e['url']} | {e['severity']} | {reason} |")
        lines.append("")
    return Response("\n".join(lines), media_type="text/markdown",
                    headers={"Content-Disposition": f'attachment; filename="{fname}.md"'})


@app.post("/follow-ups", tags=["Follow-Ups"])
def create_follow_up(body: FollowUpCreate, _: bool = Depends(auth)):
    """Create a follow-up item (manual or agent-created)."""
    import uuid as _uuid
    fid = str(_uuid.uuid4())
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute("""
            INSERT INTO follow_up_items
                (id, finding_source, finding_id, title, target, severity, reason,
                 priority, assigned_to, flagged_by, rule_id, confidence,
                 tags, notes, engagement_id)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING *
        """, (
            fid, body.finding_source,
            body.finding_id if body.finding_id else None,
            body.title, body.target, body.severity or "info",
            body.reason, body.priority or "medium", body.assigned_to,
            body.flagged_by or "manual", body.rule_id, body.confidence,
            body.tags or [], body.notes,
            body.engagement_id if body.engagement_id else None,
        ))
        row = cur.fetchone()
        conn.commit()
    return {"ok": True, "follow_up": row}


@app.patch("/follow-ups/{item_id}", tags=["Follow-Ups"])
def update_follow_up(item_id: str, body: FollowUpUpdate, _: bool = Depends(auth)):
    """Update a follow-up item's fields."""
    sets, params = [], []
    for field in ["title", "target", "severity", "reason", "status", "priority",
                  "assigned_to", "notes", "engagement_id"]:
        val = getattr(body, field, None)
        if val is not None:
            sets.append(f"{field} = %s"); params.append(val)
    if body.tags is not None:
        sets.append("tags = %s"); params.append(body.tags)
    if body.status == "resolved":
        sets.append("resolved_at = now()")
    if not sets:
        raise HTTPException(400, "No fields to update")
    params.append(item_id)
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        cur.execute(f"""
            UPDATE follow_up_items SET {', '.join(sets)}
            WHERE id = %s::uuid RETURNING *
        """, params)
        row = cur.fetchone()
        if not row:
            raise HTTPException(404, "Follow-up item not found")
        conn.commit()
    return {"ok": True, "follow_up": row}


@app.delete("/follow-ups/{item_id}", tags=["Follow-Ups"])
def delete_follow_up(item_id: str, _: bool = Depends(auth)):
    """Delete a follow-up item."""
    with get_db() as conn, conn.cursor() as cur:
        cur.execute("DELETE FROM follow_up_items WHERE id = %s::uuid", (item_id,))
        if cur.rowcount == 0:
            raise HTTPException(404, "Follow-up item not found")
        conn.commit()
    return {"ok": True, "deleted": item_id}


@app.post("/follow-ups/{item_id}/feedback", tags=["Follow-Ups"])
def submit_follow_up_feedback(item_id: str, body: FeedbackBody, _: bool = Depends(auth)):
    """Submit user feedback on an agent-flagged follow-up (for learning)."""
    import uuid as _uuid
    with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
        # Load the follow-up item
        cur.execute("SELECT * FROM follow_up_items WHERE id = %s::uuid", (item_id,))
        fu = cur.fetchone()
        if not fu:
            raise HTTPException(404, "Follow-up item not found")

        # Build finding context snapshot
        context = {
            "title": fu["title"], "target": fu["target"],
            "severity": fu["severity"], "reason": fu["reason"],
            "flagged_by": fu["flagged_by"], "rule_id": fu.get("rule_id"),
        }

        # Generate embedding for RAG retrieval
        embedding = None
        try:
            context_text = f"{fu['title']} {fu.get('target','')} {fu.get('reason','')} action={body.action}"
            embedding = _embed_text(context_text)
        except Exception:
            pass  # embedding is optional — feedback still saved

        cur.execute("""
            INSERT INTO osint_agent_feedback
                (id, follow_up_id, finding_context, agent_suggestion, agent_reasoning,
                 agent_confidence, user_action, user_notes, embedding)
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
            RETURNING id
        """, (
            str(_uuid.uuid4()), item_id, Json(context),
            fu.get("flagged_by"), fu.get("reason"), fu.get("confidence"),
            body.action, body.notes,
            embedding,
        ))
        fb_id = cur.fetchone()["id"]

        # Update the follow-up status based on feedback
        if body.action == "dismissed":
            cur.execute("UPDATE follow_up_items SET status = 'dismissed' WHERE id = %s::uuid", (item_id,))
        elif body.action == "accepted":
            cur.execute("UPDATE follow_up_items SET status = 'in_progress' WHERE id = %s::uuid", (item_id,))

        conn.commit()
    return {"ok": True, "feedback_id": fb_id}


