        cur.execute(f"SELECT id::text, flagging_agent, target_agent, engagement_id::text, "
                    f"flag_type, data, status, acted_by, created_at, acted_at FROM agent_flags "
                    f"{clause} ORDER BY created_at DESC LIMIT %s", params)
