@app.get("/agents/status", tags=["AI Agents"])
def get_agents_status(_: bool = Depends(auth)):
    """Aggregate status of all AI agents for the unified agents page."""
    import httpx as _hx

    print("[DEBUG] get_agents_status called")
    agents = []

    def _fast_get(url, timeout=2):
        """HTTP GET with a hard total timeout (not per-socket like requests)."""
        try:
            return _hx.get(url, timeout=timeout, verify=False)
        except Exception:
            return None

    # 1. Pentest Agent (autogen-agents)
    try:
        r = _fast_get("https://autogen-agents:8015/health")
        sessions_count = 0
        if r and r.status_code == 200:
            sr = _fast_get("https://autogen-agents:8015/pentest/sessions")
            if sr and sr.status_code == 200:
                sessions = sr.json().get("sessions", [])
                sessions_count = len([s for s in sessions if s.get("status") == "active"])
        agents.append({
            "id": "pentest-agent", "name": "Pentest Agent",
            "type": "session", "status": "running" if r and r.status_code == 200 else "unreachable",
            "description": "7-agent team for automated penetration testing",
            "active_sessions": sessions_count,
            "service_port": 8015,
        })
    except Exception:
        agents.append({
            "id": "pentest-agent", "name": "Pentest Agent",
            "type": "session", "status": "unreachable",
            "description": "7-agent team for automated penetration testing",
            "service_port": 8015,
        })

    # 2. OSINT Flagging Agent
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT count(*) as cnt, max(created_at) as last_run
                FROM follow_up_items WHERE flagged_by = 'osint_agent'
            """)
            row = cur.fetchone()
            agents.append({
                "id": "osint-agent", "name": "OSINT Flagging Agent",
                "type": "on-demand", "status": "idle",
                "description": "YAML rule engine — scans findings and flags follow-ups",
                "findings_created": row["cnt"] if row else 0,
                "last_run": row["last_run"].isoformat() if row and row["last_run"] else None,
            })
    except Exception:
        agents.append({
            "id": "osint-agent", "name": "OSINT Flagging Agent",
            "type": "on-demand", "status": "error",
            "description": "YAML rule engine — scans findings and flags follow-ups",
        })

    # 3. Scan Recommender
    try:
        r = _fast_get("https://scan-recommender:8013/health")
        last_run = None
        recommendations_count = 0

        # Check for recent scan recommendations activity
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT count(*) as cnt, max(created_at) as last_run
                FROM scan_recommendations
            """)
            row = cur.fetchone()
            if row:
                recommendations_count = row["cnt"] or 0
                last_run = row["last_run"].isoformat() if row["last_run"] else None

        agents.append({
            "id": "scan-recommender", "name": "Scan Recommender",
            "type": "continuous", "status": "running" if r and r.status_code == 200 else "unreachable",
            "description": "LLM-powered tool and scan recommendations",
            "service_port": 8013,
            "findings_created": recommendations_count,
            "last_run": last_run,
        })
    except Exception as e:
        print(f"[DEBUG] Scan recommender agent error: {e}")
        agents.append({
            "id": "scan-recommender", "name": "Scan Recommender",
            "type": "continuous", "status": "unreachable",
            "description": "LLM-powered tool and scan recommendations",
            "service_port": 8013,
        })

    # 4. Recon Agent
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            # Check how many engagements have the recon agent enabled
            cur.execute("""
                SELECT count(*) as enabled_count,
                       count(*) FILTER (WHERE last_run_at > now() - interval '10 minutes') as recently_active,
                       max(last_run_at) as last_run,
                       max(last_dispatch_at) as last_dispatch
                FROM recon_agent_state WHERE enabled = true
            """)
            agent_row = cur.fetchone()
            enabled_count = agent_row["enabled_count"] if agent_row else 0
            recently_active = agent_row["recently_active"] if agent_row else 0
            last_run = agent_row["last_run"] if agent_row else None
            last_dispatch = agent_row["last_dispatch"] if agent_row else None

            # Coverage stats
            cur.execute("""
                SELECT count(*) as total,
                       count(*) FILTER (WHERE status = 'completed') as completed,
                       count(*) FILTER (WHERE status = 'pending') as pending,
                       count(*) FILTER (WHERE status = 'running') as running
                FROM scope_coverage
            """)
            cov = cur.fetchone()

            status = "running" if recently_active > 0 else "idle" if enabled_count > 0 else "idle"
            agents.append({
                "id": "recon-agent", "name": "Recon Agent",
                "type": "continuous", "status": status,
                "description": "Auto-dispatches missing scans per engagement scope",
                "enabled_engagements": enabled_count,
                "coverage_total": cov["total"] if cov else 0,
                "coverage_completed": cov["completed"] if cov else 0,
                "coverage_pending": cov["pending"] if cov else 0,
                "coverage_running": cov["running"] if cov else 0,
                "last_run": last_run.isoformat() if last_run else None,
                "last_dispatch": last_dispatch.isoformat() if last_dispatch else None,
            })
    except Exception:
        agents.append({
            "id": "recon-agent", "name": "Recon Agent",
            "type": "continuous", "status": "error",
            "description": "Auto-dispatches missing scans per engagement scope",
        })

    # 5. Gap Analysis Agent
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT id, status, gaps_found, completed_at
                FROM gap_analysis_reports
                ORDER BY created_at DESC LIMIT 1
            """)
            row = cur.fetchone()
            agents.append({
                "id": "gap-agent", "name": "Recon Gap Analysis",
                "type": "on-demand", "status": "idle",
                "description": "Identifies missing recon data and recommends scans to fill gaps",
                "last_run": row["completed_at"].isoformat() if row and row["completed_at"] else None,
                "gaps_found": row["gaps_found"] if row else None,
            })
    except Exception:
        agents.append({
            "id": "gap-agent", "name": "Recon Gap Analysis",
            "type": "on-demand", "status": "error",
            "description": "Identifies missing recon data and recommends scans to fill gaps",
        })

    # 6. Cloud Triage Agent
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT id, open_recs_count, model, created_at, error
                FROM cloud_triage_runs
                ORDER BY created_at DESC LIMIT 1
            """)
            row = cur.fetchone()
            cur.execute("SELECT count(*) AS n FROM cloud_scan_recommendations WHERE status='open'")
            open_recs = (cur.fetchone() or {}).get("n", 0)
            agents.append({
                "id": "cloud-triage-agent", "name": "Cloud Triage Agent",
                "type": "on-demand", "status": "error" if row and row.get("error") else "idle",
                "description": "Re-ranks open cloud recommendations by attack-chain order and produces a top-3 next-actions plan",
                "last_run": row["created_at"].isoformat() if row and row.get("created_at") else None,
                "model": row["model"] if row else None,
                "open_recs": open_recs,
            })
    except Exception:
        agents.append({
            "id": "cloud-triage-agent", "name": "Cloud Triage Agent",
            "type": "on-demand", "status": "error",
            "description": "Re-ranks open cloud recommendations by attack-chain order and produces a top-3 next-actions plan",
        })

    # 7. Artifact LLM Review Agent — services the raw_artifacts LLM-review queue.
    #    The consumer + /artifacts/drain already exist; this surfaces the queue so
    #    an operator can see the backlog and process it from the AI Agents page.
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT count(*) FILTER (WHERE llm_status = 'pending')    AS pending,
                       count(*) FILTER (WHERE llm_status = 'processing') AS processing,
                       count(*) FILTER (WHERE llm_status = 'done')       AS done,
                       count(*) FILTER (WHERE llm_status = 'failed')     AS failed,
                       count(*)                                          AS total,
                       max(llm_processed_at)                             AS last_run
                  FROM raw_artifacts
            """)
            a = cur.fetchone() or {}
            pending = int(a.get("pending") or 0)
            processing = int(a.get("processing") or 0)
            agents.append({
                "id": "artifact-review", "name": "Artifact LLM Review",
                "type": "on-demand",
                "status": "running" if processing > 0 else "idle",
                "description": "Runs the LLM enrichment pass over raw scan output pending review, then extracts follow-on actions",
                "queue_pending": pending,
                "queue_processing": processing,
                "queue_done": int(a.get("done") or 0),
                "queue_failed": int(a.get("failed") or 0),
                "queue_total": int(a.get("total") or 0),
                "last_run": a["last_run"].isoformat() if a.get("last_run") else None,
            })
    except Exception:
        agents.append({
            "id": "artifact-review", "name": "Artifact LLM Review",
            "type": "on-demand", "status": "error",
            "description": "Runs the LLM enrichment pass over raw scan output pending review, then extracts follow-on actions",
        })

    # 8. Pre-Validation Agent — verifies agent/LLM factual claims (ports, CVEs,
    #    services, hosts) against what the scans actually recorded, BEFORE those
    #    claims are trusted. Deterministic (regex + SQL) via scan-recommender
    #    /kb/agent-output/verify; autogen runs it per-session and persists the
    #    outcome to agent_sessions.metadata->'claim_validation'.
    try:
        r = _fast_get("https://scan-recommender:8013/health")
        reachable = bool(r and r.status_code == 200)
        validated = unsupported = 0
        last_val = None
        try:
            with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
                cur.execute("""
                    SELECT count(*) FILTER (WHERE metadata ? 'claim_validation') AS validated,
                           COALESCE(SUM((metadata->'claim_validation'->>'unsupported_count')::int)
                                    FILTER (WHERE metadata ? 'claim_validation'), 0) AS unsupported,
                           MAX(updated_at) FILTER (WHERE metadata ? 'claim_validation') AS last_run
                      FROM agent_sessions
                """)
                v = cur.fetchone() or {}
                validated = int(v.get("validated") or 0)
                unsupported = int(v.get("unsupported") or 0)
                last_val = v.get("last_run")
        except Exception:
            pass
        agents.append({
            "id": "pre-validation", "name": "Pre-Validation Agent",
            "type": "continuous", "status": "running" if reachable else "unreachable",
            "description": "Verifies agent/LLM claims (ports, CVEs, services, hosts) against recorded scan data before findings are trusted",
            "service_port": 8013,
            "sessions_validated": validated,
            "unsupported_claims": unsupported,
            "last_run": last_val.isoformat() if last_val else None,
        })
    except Exception:
        agents.append({
            "id": "pre-validation", "name": "Pre-Validation Agent",
            "type": "continuous", "status": "error",
            "description": "Verifies agent/LLM claims against recorded scan data before findings are trusted",
            "service_port": 8013,
        })

    # 9. WHOIS Collection Agent — passive registrant lookup across ALL scopes +
    #    discovered owner domains (not just in-scope hosts, since whois is public).
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            domains = _gather_whois_domains(cur)
            cur.execute("SELECT DISTINCT target, max(created_at) last FROM recon_findings "
                        "WHERE source = 'whois' GROUP BY target")
            from scope_classifier import registrable_domain as _rd
            have = set()
            last_run = None
            for r in cur.fetchall():
                reg = _rd((r["target"] or "").strip()) or (r["target"] or "").strip().lower()
                if reg:
                    have.add(reg)
                if r["last"] and (last_run is None or r["last"] > last_run):
                    last_run = r["last"]
            covered = len(domains & have)
            agents.append({
                "id": "whois-agent", "name": "WHOIS Collection",
                "type": "on-demand", "status": "idle",
                "description": "Passive WHOIS/registrant lookup for every scope + discovered owner domain (identifies who owns customer sites)",
                "coverage_total": len(domains),
                "coverage_completed": covered,
                "coverage_pending": max(0, len(domains) - covered),
                "last_run": last_run.isoformat() if last_run else None,
            })
    except Exception:
        agents.append({
            "id": "whois-agent", "name": "WHOIS Collection",
            "type": "on-demand", "status": "error",
            "description": "Passive WHOIS/registrant lookup for every scope + discovered owner domain",
        })

    # 10. Agent Feedback channel — one agent flags interesting things; approving a
    #     flag enqueues a scope-gated scan_recommendation.
    try:
        with get_db() as conn, conn.cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("SELECT count(*) FILTER (WHERE status='pending') pending, "
                        "count(*) FILTER (WHERE status='acted') acted, "
                        "max(created_at) last FROM agent_flags")
            a = cur.fetchone() or {}
            pend = int(a.get("pending") or 0)
            agents.append({
                "id": "agent-feedback", "name": "Agent Feedback",
                "type": "on-demand", "status": "running" if pend > 0 else "idle",
                "description": "Inter-agent channel: flags interesting findings for review; approving one queues a scope-gated follow-up scan",
                "queue_pending": pend,
                "queue_done": int(a.get("acted") or 0),
                "last_run": a["last"].isoformat() if a.get("last") else None,
            })
    except Exception:
        agents.append({
            "id": "agent-feedback", "name": "Agent Feedback",
            "type": "on-demand", "status": "error",
            "description": "Inter-agent channel for flagging interesting findings",
        })

    return {"agents": agents}


# API Collections + Test Sessions (Swagger/OpenAPI Ingestion)
# ============================================================================

SWAGGER_DIR = os.environ.get("SWAGGER_DIR", "/app/swagger_files")


class ApiTestSessionCreate(BaseModel):
    name: Optional[str] = None
